-- =====================================================================================
-- EscudoSST · esquema de la base PRINCIPAL `escudo_main`
-- GENERADO por tools/db/generar.py desde tools/db/modelo_main.txt — no editar a mano.
-- PostgreSQL 16 y 17. Requiere un rol con permiso para crear roles (la primera vez) y extensión citext no requerida.
-- =====================================================================================

SET client_min_messages = warning;
SET search_path = public;

-- ---------- Roles ----------------------------------------------------------------
-- owner: dueño de los objetos (migraciones). NO tiene BYPASSRLS: FORCE ROW LEVEL SECURITY también lo alcanza.
-- app:   rol de la aplicación (las credenciales LOGIN se crean en despliegue con IN ROLE). Sin BYPASSRLS.
-- platform: panel del dueño del SaaS (SUS). Solo catálogos globales, cuentas, suscripciones y facturación.
-- definer:  solo es dueño de funciones SECURITY DEFINER acotadas (endpoints públicos, cadena de auditoría).
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'escudo_owner') THEN CREATE ROLE escudo_owner NOLOGIN NOBYPASSRLS; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'escudo_app') THEN CREATE ROLE escudo_app NOLOGIN NOBYPASSRLS; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'escudo_platform') THEN CREATE ROLE escudo_platform NOLOGIN NOBYPASSRLS; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'escudo_definer') THEN CREATE ROLE escudo_definer NOLOGIN BYPASSRLS; END IF;
END $$;
ALTER ROLE escudo_owner NOLOGIN NOBYPASSRLS;
ALTER ROLE escudo_app NOLOGIN NOBYPASSRLS;
ALTER ROLE escudo_platform NOLOGIN NOBYPASSRLS;
ALTER ROLE escudo_definer NOLOGIN BYPASSRLS;
GRANT USAGE ON SCHEMA public TO escudo_app; GRANT USAGE ON SCHEMA public TO escudo_platform, escudo_definer;
GRANT CREATE ON SCHEMA public TO escudo_owner;

-- ---------- Funciones base ---------------------------------------------------------
-- UUID v7 (RFC 9562): 48 bits de milisegundos Unix + aleatorio. En PostgreSQL 18 existe pg_catalog.uuidv7();
-- esta versión en public mantiene compatibilidad con 16 y 17.
CREATE OR REPLACE FUNCTION public.uuidv7() RETURNS uuid
LANGUAGE plpgsql VOLATILE PARALLEL SAFE AS $$
DECLARE
  ms bigint := floor(extract(epoch FROM clock_timestamp()) * 1000);
  b bytea := uuid_send(gen_random_uuid());
BEGIN
  b := overlay(b PLACING substring(int8send(ms) FROM 3 FOR 6) FROM 1 FOR 6);
  b := set_byte(b, 6, (get_byte(b, 6) & 15) | 112);   -- versión 7
  b := set_byte(b, 8, (get_byte(b, 8) & 63) | 128);   -- variante RFC
  RETURN encode(b, 'hex')::uuid;
END $$;

-- Contexto de la petición (fijado con SET LOCAL por el middleware SetTenantContext).
-- Si no está fijado devuelve NULL y ninguna política deja pasar filas (no hay valor por defecto permisivo).
CREATE OR REPLACE FUNCTION public.app_company_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$ SELECT NULLIF(current_setting('app.company_id', true), '')::uuid $$;
CREATE OR REPLACE FUNCTION public.app_account_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$ SELECT NULLIF(current_setting('app.account_id', true), '')::uuid $$;
CREATE OR REPLACE FUNCTION public.app_user_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$ SELECT NULLIF(current_setting('app.user_id', true), '')::uuid $$;
CREATE OR REPLACE FUNCTION public.app_contractor_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE AS $$ SELECT NULLIF(current_setting('app.contractor_id', true), '')::uuid $$;

CREATE OR REPLACE FUNCTION public.trg_set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION public.trg_bump_version() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.version IS NOT DISTINCT FROM OLD.version THEN
    NEW.version := OLD.version + 1;
  ELSIF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'conflicto de versión en %.%: esperado %, recibido %', TG_TABLE_NAME, OLD.id, OLD.version + 1, NEW.version
      USING ERRCODE = '40001';
  END IF;
  RETURN NEW;
END $$;

-- Tablas inalterables: solo INSERT. Rechaza UPDATE, DELETE y TRUNCATE para cualquier rol (incluido el dueño).
CREATE OR REPLACE FUNCTION public.trg_forbid_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'La tabla % es inalterable: % no permitido', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'insufficient_privilege', HINT = 'Registre una nueva fila (corrección o anulación) en lugar de modificar.';
END $$;

-- Verifica que una referencia desde una tabla de empresa hacia un catálogo mixto (company_id NULL = global)
-- apunte a una fila global o de la misma empresa. Corre como escudo_definer porque la fila de otra empresa no es visible por RLS.
CREATE OR REPLACE FUNCTION public.trg_check_hybrid_ref() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  col text := TG_ARGV[0];
  tgt text := TG_ARGV[1];
  ref_id uuid;
  ref_company uuid;
  child_company uuid;
BEGIN
  EXECUTE format('SELECT ($1).%I::uuid, ($1).company_id::uuid', col) INTO ref_id, child_company USING NEW;
  IF ref_id IS NULL THEN RETURN NEW; END IF;
  EXECUTE format('SELECT company_id FROM %I WHERE id = $1', tgt) INTO ref_company USING ref_id;
  IF ref_company IS NOT NULL AND ref_company IS DISTINCT FROM child_company THEN
    RAISE EXCEPTION '%.% referencia una fila de %.id de otra empresa', TG_TABLE_NAME, col, tgt
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  RETURN NEW;
END $$;


-- ---------- Tablas -----------------------------------------------------------------
-- TEN · accounts (special)
CREATE TABLE IF NOT EXISTS accounts (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  account_type text NOT NULL DEFAULT 'direct' CHECK (account_type IN ('direct', 'consultancy', 'group')),
  tax_id_type text DEFAULT 'RUC' CHECK (tax_id_type IN ('RUC', 'DNI', 'CE', 'OTHER')),
  tax_id text,
  legal_name text,
  billing_email text,
  billing_phone text,
  billing_address text,
  country_code char(2) NOT NULL DEFAULT 'PE',
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'cancelled', 'archived')),
  white_label_enabled boolean NOT NULL DEFAULT false,
  trial_used_at timestamptz,
  cancelled_at timestamptz,
  data_retention_until date,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE accounts IS '[TEN] Cuenta suscriptora (empresa directa, grupo o consultora); agrupa empresas y paga suscripciones';
COMMENT ON COLUMN accounts.trial_used_at IS 'una prueba gratuita por RUC';
COMMENT ON COLUMN accounts.data_retention_until IS 'fin de la retención tras la cancelación (parámetro)';

-- TEN · companies (special, definer)
CREATE TABLE IF NOT EXISTS companies (
  id uuid NOT NULL DEFAULT uuidv7(),
  account_id uuid NOT NULL,
  managed_by_account_id uuid,
  ruc char(11) NOT NULL,
  legal_name text NOT NULL,
  trade_name text,
  ciiu_code text,
  economic_sector text CHECK (economic_sector IN ('construction', 'mining', 'agroindustry', 'manufacturing', 'retail', 'services', 'office', 'health', 'education', 'transport', 'energy', 'other')),
  risk_level text CHECK (risk_level IN ('low', 'medium', 'high', 'very_high')),
  headcount_declared integer,
  headcount_active integer NOT NULL DEFAULT 0,
  sst_model text NOT NULL DEFAULT 'supervisor' CHECK (sst_model IN ('committee', 'supervisor')),
  fiscal_address text,
  ubigeo char(6),
  district text,
  province text,
  department text,
  phone text,
  email text,
  legal_rep_name text,
  legal_rep_document text,
  timezone text NOT NULL DEFAULT 'America/Lima',
  currency char(3) NOT NULL DEFAULT 'PEN',
  logo_file_id uuid,
  catalog_slug text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'archived')),
  onboarding_completed_at timestamptz,
  data_retention_until date,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_companies_1 CHECK (ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_companies_2 CHECK (headcount_declared IS NULL OR headcount_declared >= 0),
  CONSTRAINT ck_companies_3 CHECK (catalog_slug IS NULL OR catalog_slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);
COMMENT ON TABLE companies IS '[TEN] Empresa empleadora con RUC; unidad de aislamiento (company_id = companies.id)';
COMMENT ON COLUMN companies.managed_by_account_id IS 'cuenta consultora que la gestiona (CON)';
COMMENT ON COLUMN companies.headcount_active IS 'recalculado a diario desde workers';
COMMENT ON COLUMN companies.sst_model IS 'propuesto según el parámetro committee_threshold_workers';
COMMENT ON COLUMN companies.legal_rep_document IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN companies.catalog_slug IS 'identificador del catálogo público de cursos a la venta (VTA)';

-- TEN · sites (company)
CREATE TABLE IF NOT EXISTS sites (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  site_type text NOT NULL DEFAULT 'plant' CHECK (site_type IN ('plant', 'office', 'project', 'store', 'warehouse', 'mine', 'field', 'clinic', 'other')),
  address text,
  ubigeo char(6),
  district text,
  province text,
  department text,
  latitude numeric(9,6),
  longitude numeric(9,6),
  is_main boolean NOT NULL DEFAULT false,
  is_temporary boolean NOT NULL DEFAULT false,
  starts_on date,
  ends_on date,
  headcount_estimated integer,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'closed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_sites_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_sites_1 CHECK (NOT is_temporary OR starts_on IS NOT NULL),
  CONSTRAINT ck_sites_2 CHECK (ends_on IS NULL OR starts_on IS NULL OR ends_on >= starts_on),
  CONSTRAINT ck_sites_3 CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
  CONSTRAINT ck_sites_4 CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180)
);
COMMENT ON TABLE sites IS '[TEN] Sede, planta, obra, tienda o almacén de la empresa';

-- TEN · areas (company)
CREATE TABLE IF NOT EXISTS areas (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  site_id uuid NOT NULL,
  parent_area_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  manager_worker_id uuid,
  depth smallint NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_areas_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_areas_1 CHECK (parent_area_id IS NULL OR parent_area_id <> id)
);
COMMENT ON TABLE areas IS '[TEN] Área o línea dentro de una sede (árbol jerárquico)';

-- TEN · positions (company)
CREATE TABLE IF NOT EXISTS positions (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  area_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  functions text,
  occupational_group text,
  is_critical boolean NOT NULL DEFAULT false,
  requires_emo boolean NOT NULL DEFAULT true,
  emo_protocol_code text,
  emo_periodicity_param text NOT NULL DEFAULT 'emo_periodic_months',
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_positions_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE positions IS '[TEN] Puesto de trabajo: unidad para IPERC, EPP, EMO y capacitaciones';
COMMENT ON COLUMN positions.emo_protocol_code IS 'perfil de exámenes del puesto (sin resultados)';
COMMENT ON COLUMN positions.emo_periodicity_param IS 'clave en legal_parameters';

-- TEN · work_shifts (company)
CREATE TABLE IF NOT EXISTS work_shifts (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  site_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  start_time time NOT NULL,
  end_time time NOT NULL,
  hours_per_day numeric(4,2) NOT NULL,
  days_pattern text NOT NULL DEFAULT 'MON-FRI',
  is_night boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_work_shifts_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_work_shifts_1 CHECK (hours_per_day > 0 AND hours_per_day <= 24)
);
COMMENT ON TABLE work_shifts IS '[TEN] Turnos de trabajo para horas-hombre y programación';
COMMENT ON COLUMN work_shifts.days_pattern IS 'p. ej. MON-SAT, 4x3, 14x7';

-- USR · users (special, definer)
CREATE TABLE IF NOT EXISTS users (
  id uuid NOT NULL DEFAULT uuidv7(),
  email text NOT NULL,
  email_verified_at timestamptz,
  phone_e164 text,
  full_name text NOT NULL,
  password_hash text,
  document_type text CHECK (document_type IN ('DNI', 'CE', 'PTP', 'PASSPORT', 'OTHER')),
  document_number text,
  document_number_hash bytea,
  locale text NOT NULL DEFAULT 'es-PE',
  timezone text NOT NULL DEFAULT 'America/Lima',
  status text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited', 'active', 'locked', 'disabled')),
  last_login_at timestamptz,
  failed_login_count integer NOT NULL DEFAULT 0,
  locked_until timestamptz,
  mfa_enabled boolean NOT NULL DEFAULT false,
  mfa_secret text,
  mfa_recovery_codes text,
  reauth_secret_hash text,
  password_changed_at timestamptz,
  is_platform_staff boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE users IS '[USR] Identidad global de una persona; puede tener membresías en varias empresas';
COMMENT ON COLUMN users.phone_e164 IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN users.password_hash IS 'Argon2id';
COMMENT ON COLUMN users.document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN users.document_number_hash IS 'HMAC del número para búsqueda exacta';
COMMENT ON COLUMN users.mfa_secret IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN users.mfa_recovery_codes IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN users.reauth_secret_hash IS 'clave adicional para datos médicos (Argon2id)';

-- USR · roles (special)
CREATE TABLE IF NOT EXISTS roles (
  id uuid NOT NULL DEFAULT uuidv7(),
  account_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  base_role_code text CHECK (base_role_code IN ('platform_owner', 'platform_support', 'account_admin', 'consultant', 'sst_manager', 'sst_supervisor', 'committee_member', 'management', 'area_lead', 'occupational_doctor', 'health_staff', 'hr', 'trainer', 'external_learner', 'worker', 'contractor_admin', 'external_auditor')),
  scope_level text NOT NULL DEFAULT 'company' CHECK (scope_level IN ('platform', 'account', 'company', 'scoped', 'own')),
  is_system boolean NOT NULL DEFAULT false,
  is_medical boolean NOT NULL DEFAULT false,
  requires_mfa boolean NOT NULL DEFAULT false,
  is_temporary boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE roles IS '[USR] Roles: 17 del sistema (account_id NULL) y personalizados por cuenta';

-- SUS · modules (global, added)
CREATE TABLE IF NOT EXISTS modules (
  id uuid NOT NULL DEFAULT uuidv7(),
  code char(3) NOT NULL,
  number text NOT NULL,
  name text NOT NULL,
  group_number smallint NOT NULL,
  plan_code text NOT NULL CHECK (plan_code IN ('E', 'P', 'C', '+', 'K', 'I')),
  phase smallint NOT NULL,
  origin text,
  solves text,
  is_addon boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE modules IS '[SUS] Catálogo de los 60 módulos (código, grupo, plan, fase) para planes, permisos y feature flags · Tabla de soporte agregada (fuera del catálogo).';

-- USR · permissions (global)
CREATE TABLE IF NOT EXISTS permissions (
  id uuid NOT NULL DEFAULT uuidv7(),
  code text NOT NULL,
  module_code char(3) NOT NULL,
  resource text NOT NULL,
  action text NOT NULL CHECK (action IN ('read', 'create', 'update', 'delete', 'approve', 'sign', 'export', 'close', 'vote', 'verify', 'generate', 'share', 'sync', 'read_sensitive', 'publish', 'revoke', 'import', 'respond', 'track', 'assign', 'send', 'confirm', 'manage')),
  is_sensitive boolean NOT NULL DEFAULT false,
  is_special boolean NOT NULL DEFAULT false,
  description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_permissions_1 CHECK (code = lower(module_code) || '.' || resource || '.' || action)
);
COMMENT ON TABLE permissions IS '[USR] Catálogo de permisos module.resource.action';

-- USR · role_permissions (special, hard_delete)
CREATE TABLE IF NOT EXISTS role_permissions (
  id uuid NOT NULL DEFAULT uuidv7(),
  account_id uuid,
  role_id uuid NOT NULL,
  permission_id uuid NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE role_permissions IS '[USR] Permisos asignados a un rol (account_id NULL en roles del sistema)';

-- USR · memberships (company)
CREATE TABLE IF NOT EXISTS memberships (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  user_id uuid NOT NULL,
  role_id uuid NOT NULL,
  worker_id uuid,
  status text NOT NULL DEFAULT 'invited' CHECK (status IN ('invited', 'active', 'suspended', 'expired', 'revoked')),
  invited_by uuid,
  invited_at timestamptz,
  accepted_at timestamptz,
  valid_from timestamptz,
  expires_at timestamptz,
  is_support_session boolean NOT NULL DEFAULT false,
  support_access_grant_id uuid,
  audit_period_from date,
  audit_period_to date,
  allowed_modules text[],
  last_access_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_memberships_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_memberships_1 CHECK (NOT is_support_session OR (expires_at IS NOT NULL AND support_access_grant_id IS NOT NULL)),
  CONSTRAINT ck_memberships_2 CHECK (audit_period_to IS NULL OR audit_period_from IS NULL OR audit_period_to >= audit_period_from)
);
COMMENT ON TABLE memberships IS '[USR] Pertenencia usuario–empresa con un rol; temporal para auditor externo y soporte';
COMMENT ON COLUMN memberships.expires_at IS 'obligatorio para auditor externo y soporte';
COMMENT ON COLUMN memberships.audit_period_from IS 'auditor externo: registros visibles desde';
COMMENT ON COLUMN memberships.allowed_modules IS 'auditor externo: módulos habilitados';

-- USR · membership_scopes (company, hard_delete)
CREATE TABLE IF NOT EXISTS membership_scopes (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  membership_id uuid NOT NULL,
  scope_type text NOT NULL CHECK (scope_type IN ('site', 'area', 'module', 'contractor')),
  site_id uuid,
  area_id uuid,
  contractor_id uuid,
  module_code char(3),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_membership_scopes_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_membership_scopes_1 CHECK ((scope_type = 'site' AND site_id IS NOT NULL) OR (scope_type = 'area' AND area_id IS NOT NULL) OR (scope_type = 'module' AND module_code IS NOT NULL) OR (scope_type = 'contractor' AND contractor_id IS NOT NULL))
);
COMMENT ON TABLE membership_scopes IS '[USR] Limita una membresía a sedes, áreas, módulos o una contratista';

-- USR · sessions_mfa (special)
CREATE TABLE IF NOT EXISTS sessions_mfa (
  id uuid NOT NULL DEFAULT uuidv7(),
  user_id uuid NOT NULL,
  token_hash bytea NOT NULL,
  device_label text,
  ip inet,
  user_agent text,
  mfa_method text CHECK (mfa_method IN ('totp', 'email_otp', 'recovery_code', 'pin', 'none')),
  mfa_verified_at timestamptz,
  reauth_at timestamptz,
  reauth_expires_at timestamptz,
  reauth_purpose text CHECK (reauth_purpose IN ('medical', 'sensitive_export', 'signature', 'security_change')),
  last_seen_at timestamptz,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  revoked_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT ck_sessions_mfa_1 CHECK (reauth_expires_at IS NULL OR reauth_at IS NOT NULL)
);
COMMENT ON TABLE sessions_mfa IS '[USR] Sesiones, factores MFA y re-autenticaciones (token médico de corta vida)';

-- USR · support_access_grants (company, added)
CREATE TABLE IF NOT EXISTS support_access_grants (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  support_user_id uuid NOT NULL,
  requested_by uuid,
  authorized_by uuid,
  reason text NOT NULL,
  ticket_reference text,
  access_level text NOT NULL DEFAULT 'read_only' CHECK (access_level IN ('read_only', 'read_write')),
  includes_medical boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested', 'authorized', 'rejected', 'active', 'expired', 'revoked')),
  requested_at timestamptz NOT NULL DEFAULT now(),
  authorized_at timestamptz,
  starts_at timestamptz,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  revoked_by uuid,
  membership_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_support_access_grants_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_support_access_grants_1 CHECK (includes_medical = false),
  CONSTRAINT ck_support_access_grants_2 CHECK (starts_at IS NULL OR expires_at > starts_at),
  CONSTRAINT ck_support_access_grants_3 CHECK (status NOT IN ('authorized','active') OR authorized_by IS NOT NULL)
);
COMMENT ON TABLE support_access_grants IS '[USR] Autorización temporal del administrador de cuenta para que soporte de plataforma acceda a la empresa · Tabla de soporte agregada (fuera del catálogo).';
COMMENT ON COLUMN support_access_grants.includes_medical IS 'siempre false: soporte nunca ve datos médicos';

-- TRB · workers (company, definer)
CREATE TABLE IF NOT EXISTS workers (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  user_id uuid,
  document_type text NOT NULL DEFAULT 'DNI' CHECK (document_type IN ('DNI', 'CE', 'PTP', 'PASSPORT', 'OTHER')),
  document_number text NOT NULL,
  document_number_hash bytea NOT NULL,
  document_last4 text,
  first_name text NOT NULL,
  paternal_last_name text NOT NULL,
  maternal_last_name text,
  full_name text GENERATED ALWAYS AS (first_name || ' ' || paternal_last_name || coalesce(' ' || maternal_last_name, '')) STORED,
  birth_on date,
  sex text CHECK (sex IN ('M', 'F', 'X')),
  nationality char(2) DEFAULT 'PE',
  phone_e164 text,
  personal_email text,
  address text,
  ubigeo char(6),
  emergency_contact_name text,
  emergency_contact_phone text,
  employee_code text,
  hire_on date,
  termination_on date,
  termination_reason text,
  employment_type text NOT NULL DEFAULT 'own' CHECK (employment_type IN ('own', 'intermediated', 'outsourced', 'intern', 'trainee', 'other')),
  contract_type text,
  current_site_id uuid,
  current_area_id uuid,
  current_position_id uuid,
  photo_file_id uuid,
  whatsapp_opt_in boolean NOT NULL DEFAULT false,
  whatsapp_opt_in_at timestamptz,
  activation_code_hash text,
  activated_at timestamptz,
  pin_hash text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'on_leave', 'terminated', 'inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_workers_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_workers_1 CHECK (termination_on IS NULL OR hire_on IS NULL OR termination_on >= hire_on),
  CONSTRAINT ck_workers_2 CHECK (status <> 'terminated' OR termination_on IS NOT NULL)
);
COMMENT ON TABLE workers IS '[TRB] Ficha única del trabajador (legajo SST)';
COMMENT ON COLUMN workers.document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN workers.document_number_hash IS 'HMAC del número para búsqueda y unicidad';
COMMENT ON COLUMN workers.document_last4 IS 'para mostrar enmascarado';
COMMENT ON COLUMN workers.phone_e164 IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN workers.personal_email IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN workers.address IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN workers.emergency_contact_name IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN workers.emergency_contact_phone IS '[CIFRADO EN APLICACIÓN]';

