-- ACT · substandard_reports (company, sync)
CREATE TABLE IF NOT EXISTS substandard_reports (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text,
  report_type text NOT NULL CHECK (report_type IN ('unsafe_act', 'unsafe_condition', 'near_miss', 'suggestion')),
  origin text NOT NULL CHECK (origin IN ('qr', 'whatsapp', 'app', 'web')),
  report_point_id uuid,
  site_id uuid,
  area_id uuid,
  contractor_id uuid,
  description text NOT NULL,
  location_text text,
  latitude numeric(9,6),
  longitude numeric(9,6),
  photo_file_id uuid,
  occurred_at timestamptz,
  reported_at timestamptz NOT NULL DEFAULT now(),
  is_anonymous boolean NOT NULL DEFAULT false,
  reporter_worker_id uuid,
  reporter_user_id uuid,
  reporter_contact text,
  whatsapp_conversation_id text,
  ip_hash bytea,
  classification text,
  risk_level text CHECK (risk_level IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL DEFAULT 'received' CHECK (status IN ('received', 'triaged', 'rejected', 'action_assigned', 'closed')),
  triaged_by uuid,
  triaged_at timestamptz,
  rejection_reason text,
  corrective_action_id uuid,
  feedback_sent_at timestamptz,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  idempotency_key text,
  device_id uuid,
  client_created_at timestamptz,
  sync_batch_id uuid,
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  CONSTRAINT uq_substandard_reports_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_substandard_reports_1 CHECK (NOT is_anonymous OR (reporter_worker_id IS NULL AND reporter_user_id IS NULL AND reporter_contact IS NULL)),
  CONSTRAINT ck_substandard_reports_2 CHECK (origin <> 'qr' OR report_point_id IS NOT NULL),
  CONSTRAINT ck_substandard_reports_3 CHECK (status <> 'rejected' OR rejection_reason IS NOT NULL)
);
COMMENT ON TABLE substandard_reports IS '[ACT] Reporte de acto o condición subestándar (origen QR, WhatsApp, app o web)';
COMMENT ON COLUMN substandard_reports.reporter_contact IS '[CIFRADO EN APLICACIÓN] teléfono de WhatsApp para dar respuesta';
COMMENT ON COLUMN substandard_reports.ip_hash IS 'solo para límites de uso; no se muestra al cliente';
COMMENT ON COLUMN substandard_reports.idempotency_key IS 'clave idempotente generada por el cliente (offline)';
COMMENT ON COLUMN substandard_reports.client_created_at IS 'instante de captura en el dispositivo';
COMMENT ON COLUMN substandard_reports.version IS 'versión para control optimista y conflictos offline';

