  site_id uuid NOT NULL,
  area_id uuid,
  work_description text NOT NULL,
  location_text text,
  latitude numeric(9,6),
  longitude numeric(9,6),
  contractor_id uuid,
  executor_leader_worker_id uuid,
  executor_leader_contractor_worker_id uuid,
  crew jsonb,
  requested_by uuid,
  valid_from timestamptz NOT NULL,
  valid_until timestamptz NOT NULL,
  ats_form_id uuid,
  procedure_id uuid,
  gas_measurements jsonb,
  isolation_points jsonb,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'pending_approval', 'approved', 'rejected', 'active', 'suspended', 'closed', 'expired')),
  activated_at timestamptz,
  suspended_reason text,
  extension_count integer NOT NULL DEFAULT 0,
  closed_at timestamptz,
  closed_by uuid,
  closure_notes text,
  area_left_safe boolean,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
