  PRIMARY KEY (id),
  CONSTRAINT uq_work_permits_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_work_permits_1 CHECK (valid_until > valid_from),
  CONSTRAINT ck_work_permits_2 CHECK (status <> 'suspended' OR suspended_reason IS NOT NULL),
  CONSTRAINT ck_work_permits_3 CHECK (status <> 'closed' OR (closed_at IS NOT NULL AND area_left_safe IS NOT NULL))
);
COMMENT ON TABLE work_permits IS '[PTR] PETAR / permiso de trabajo de alto riesgo con aprobaciones y cierre';
