-- CAP · training_certificates (company)
CREATE TABLE IF NOT EXISTS training_certificates (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  training_id uuid,
  course_id uuid,
  course_enrollment_id uuid,
  worker_id uuid,
  contractor_worker_id uuid,
  external_learner_id uuid,
  certificate_template_id uuid,
  certificate_code text NOT NULL,
  verification_code text NOT NULL,
  holder_name text NOT NULL,
  holder_document_masked text,
  course_title text NOT NULL,
  issued_on date NOT NULL,
  expires_on date,
  hours numeric(6,2),
  score numeric(6,2),
  score_label text,
  grading_scale_id uuid,
  file_id uuid,
  public_verification_enabled boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'pending_validation' CHECK (status IN ('pending_validation', 'validated', 'voided', 'expired')),
  validated_by uuid,
  validated_at timestamptz,
  voided_by uuid,
  voided_at timestamptz,
  void_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_training_certificates_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_training_certificates_1 CHECK (training_id IS NOT NULL OR course_id IS NOT NULL),
  CONSTRAINT ck_training_certificates_2 CHECK (((worker_id IS NOT NULL)::int + (contractor_worker_id IS NOT NULL)::int + (external_learner_id IS NOT NULL)::int) = 1),
  CONSTRAINT ck_training_certificates_3 CHECK (certificate_code ~ '^[A-Z0-9]{2,12}-[0-9]{4}-[0-9]{6}$'),
  CONSTRAINT ck_training_certificates_4 CHECK (verification_code ~ '^[A-Z0-9]{12,32}$'),
  CONSTRAINT ck_training_certificates_5 CHECK (status <> 'validated' OR (validated_by IS NOT NULL AND validated_at IS NOT NULL)),
  CONSTRAINT ck_training_certificates_6 CHECK (status <> 'voided' OR (voided_by IS NOT NULL AND voided_at IS NOT NULL AND void_reason IS NOT NULL)),
  CONSTRAINT ck_training_certificates_7 CHECK (expires_on IS NULL OR expires_on >= issued_on),
  CONSTRAINT ck_training_certificates_8 CHECK (score IS NULL OR score >= 0)
);
COMMENT ON TABLE training_certificates IS '[CAP] Certificado o constancia de una capacitación (CAP) o de un curso del aula (AUL), con validación, anulación y verificación pública por código';
COMMENT ON COLUMN training_certificates.certificate_code IS 'código único legible por empresa, p. ej. CERT-2026-000142 (prefijo de la plantilla + año + correlativo)';
COMMENT ON COLUMN training_certificates.verification_code IS 'código aleatorio no secuencial (QR y consulta pública); evita enumerar certificados';
COMMENT ON COLUMN training_certificates.holder_name IS 'instantánea del nombre al emitir';
COMMENT ON COLUMN training_certificates.holder_document_masked IS 'solo los últimos dígitos (p. ej. ****5678)';
COMMENT ON COLUMN training_certificates.course_title IS 'instantánea del título de la capacitación o curso';
COMMENT ON COLUMN training_certificates.score_label IS 'nota literal cuando la escala es de letras (AD, A, B, C…)';
COMMENT ON COLUMN training_certificates.public_verification_enabled IS 'se hereda del curso; si es falso la consulta pública responde «no público»';

-- CAP · certificate_templates (hybrid)
CREATE TABLE IF NOT EXISTS certificate_templates (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  orientation text NOT NULL DEFAULT 'landscape' CHECK (orientation IN ('landscape', 'portrait')),
  paper_size text NOT NULL DEFAULT 'A4' CHECK (paper_size IN ('A4', 'letter')),
  layout jsonb NOT NULL DEFAULT '{}'::jsonb,
  body_template text NOT NULL,
  variable_fields text[] NOT NULL DEFAULT '{holder_name,holder_document_masked,course_title,hours,score,grade_label,issued_on,expires_on,certificate_number,verification_url}',
  logo_file_id uuid,
  background_file_id uuid,
  signatory_name text,
  signatory_title text,
  signature_file_id uuid,
  second_signatory_name text,
  second_signatory_title text,
  second_signature_file_id uuid,
  code_prefix text NOT NULL DEFAULT 'CERT',
  shows_qr boolean NOT NULL DEFAULT true,
  shows_hours boolean NOT NULL DEFAULT true,
  shows_score boolean NOT NULL DEFAULT false,
  is_default boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft', 'active', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_certificate_templates_1 CHECK (code_prefix ~ '^[A-Z0-9]{2,12}$'),
  CONSTRAINT ck_certificate_templates_2 CHECK (NOT is_default OR status = 'active')
);
COMMENT ON TABLE certificate_templates IS '[CAP] Plantilla de certificado: global por defecto de la plataforma (company_id NULL) o diseño propio de la empresa';
COMMENT ON COLUMN certificate_templates.company_id IS 'NULL = fila global de la plataforma';
COMMENT ON COLUMN certificate_templates.layout IS 'posiciones, tipografías y colores de cada bloque';
COMMENT ON COLUMN certificate_templates.body_template IS 'texto con campos variables entre llaves dobles, p. ej. {{holder_name}}';
COMMENT ON COLUMN certificate_templates.signature_file_id IS 'imagen de la firma del responsable';
COMMENT ON COLUMN certificate_templates.code_prefix IS 'prefijo del código legible del certificado';

-- CAP · certificate_verifications (imm)
CREATE TABLE IF NOT EXISTS certificate_verifications (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  certificate_id uuid NOT NULL,
  queried_code text NOT NULL,
  verified_at timestamptz NOT NULL DEFAULT now(),
  channel text NOT NULL DEFAULT 'public_web' CHECK (channel IN ('public_web', 'public_qr', 'app')),
  result text NOT NULL CHECK (result IN ('valid', 'expired', 'voided', 'pending_validation', 'not_public')),
  response_snapshot jsonb,
  ip_hash bytea,
  user_agent text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT uq_certificate_verifications_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE certificate_verifications IS '[CAP] Consulta pública de un certificado por código (sin sesión), inalterable · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN certificate_verifications.queried_code IS 'código consultado tal como llegó (normalizado a mayúsculas)';
COMMENT ON COLUMN certificate_verifications.response_snapshot IS 'lo que se mostró: nombre, curso, horas, fechas y estado (sin documento completo ni datos de contacto)';

-- CAP · position_training_requirements (company)
CREATE TABLE IF NOT EXISTS position_training_requirements (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  position_id uuid NOT NULL,
  training_id uuid,
  course_id uuid,
  requirement_level text NOT NULL DEFAULT 'mandatory' CHECK (requirement_level IN ('mandatory', 'suggested')),
  renewal_months integer,
  due_within_days integer,
  applies_to_contractors boolean NOT NULL DEFAULT false,
  auto_enroll boolean NOT NULL DEFAULT true,
  legal_parameter_key text,
  notes text,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_position_training_requirements_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_position_training_requirements_1 CHECK ((training_id IS NOT NULL) <> (course_id IS NOT NULL)),
  CONSTRAINT ck_position_training_requirements_2 CHECK (renewal_months IS NULL OR renewal_months > 0),
  CONSTRAINT ck_position_training_requirements_3 CHECK (due_within_days IS NULL OR due_within_days >= 0)
);
COMMENT ON TABLE position_training_requirements IS '[CAP] Matriz de capacitación por cargo: capacitación o curso obligatorio o sugerido por puesto, con renovación';
COMMENT ON COLUMN position_training_requirements.renewal_months IS 'NULL = no se renueva; si hay vencimiento, se reprograma al vencer el certificado';
COMMENT ON COLUMN position_training_requirements.due_within_days IS 'plazo interno de la empresa desde la asignación al puesto (configuración de la empresa)';
COMMENT ON COLUMN position_training_requirements.auto_enroll IS 'al asignar un trabajador al puesto se matricula en el curso (origen position_assignment)';
COMMENT ON COLUMN position_training_requirements.legal_parameter_key IS 'si la exigencia viene de un parámetro legal con vigencia';

-- AUL · courses (hybrid, module=AUL)
CREATE TABLE IF NOT EXISTS courses (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid,
  code text NOT NULL,
  title text NOT NULL,
  summary text,
  description text,
  objectives text,
  target_audience text,
  category text,
  source text NOT NULL DEFAULT 'internal' CHECK (source IN ('internal', 'external', 'catalog')),
  lms_connection_id uuid,
  external_course_id text,
  catalog_course_code text,
  cover_file_id uuid,
  promo_video_provider text CHECK (promo_video_provider IN ('vimeo')),
  promo_video_id text,
  sector_pack_id uuid,
  modality text NOT NULL DEFAULT 'internal' CHECK (modality IN ('internal', 'for_sale', 'both')),
  delivery_mode text NOT NULL DEFAULT 'self_paced' CHECK (delivery_mode IN ('self_paced', 'instructor_led', 'blended')),
  sequential boolean NOT NULL DEFAULT false,
  grading_scale_id uuid,
  passing_score numeric(6,2),
  max_attempts integer,
  randomize_questions boolean NOT NULL DEFAULT false,
  randomize_options boolean NOT NULL DEFAULT false,
  completion_commitment text NOT NULL DEFAULT 'none' CHECK (completion_commitment IN ('none', 'optional', 'mandatory')),
  commitment_text text,
  hours numeric(6,2),
  min_active_time_pct numeric(5,2),
  certificate_enabled boolean NOT NULL DEFAULT true,
  certificate_template_id uuid,
  certificate_validity_months integer,
  public_verification_enabled boolean NOT NULL DEFAULT false,
  is_mandatory_induction boolean NOT NULL DEFAULT false,
  published_at timestamptz,
  published_by uuid,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_courses_1 CHECK ((source = 'catalog') = (company_id IS NULL)),
  CONSTRAINT ck_courses_2 CHECK (source <> 'external' OR (lms_connection_id IS NOT NULL AND external_course_id IS NOT NULL)),
  CONSTRAINT ck_courses_3 CHECK (source <> 'catalog' OR catalog_course_code IS NOT NULL),
  CONSTRAINT ck_courses_4 CHECK (max_attempts IS NULL OR max_attempts > 0),
  CONSTRAINT ck_courses_5 CHECK (hours IS NULL OR hours > 0),
  CONSTRAINT ck_courses_6 CHECK (certificate_validity_months IS NULL OR certificate_validity_months > 0),
  CONSTRAINT ck_courses_7 CHECK (min_active_time_pct IS NULL OR min_active_time_pct BETWEEN 0 AND 100),
  CONSTRAINT ck_courses_8 CHECK (completion_commitment = 'none' OR commitment_text IS NOT NULL),
  CONSTRAINT ck_courses_9 CHECK (promo_video_provider IS NULL OR promo_video_id IS NOT NULL),
  CONSTRAINT ck_courses_10 CHECK (status <> 'published' OR published_at IS NOT NULL)
);
COMMENT ON TABLE courses IS '[AUL] Curso del portal propio de cursos: interno o a la venta, enlazado a Moodle (opcional) o del catálogo SST estándar de EscudoSST (company_id NULL)';
COMMENT ON COLUMN courses.company_id IS 'NULL = fila global de la plataforma';
COMMENT ON COLUMN courses.external_course_id IS 'id del curso en Moodle cuando source = external';
COMMENT ON COLUMN courses.catalog_course_code IS 'código del curso del catálogo global (en el curso de catálogo y en las copias de empresa)';
COMMENT ON COLUMN courses.modality IS 'interno (personal propio), a la venta (VTA) o ambos';
COMMENT ON COLUMN courses.sequential IS 'recorrido secuencial: una lección se habilita al completar la anterior';
COMMENT ON COLUMN courses.passing_score IS 'nota mínima aprobatoria en la escala del curso';
COMMENT ON COLUMN courses.hours IS 'horas acreditables en el certificado';
COMMENT ON COLUMN courses.min_active_time_pct IS '% mínimo de tiempo de permanencia real sobre las horas para certificar';
COMMENT ON COLUMN courses.certificate_validity_months IS 'vigencia del certificado; NULL = sin vencimiento';

-- AUL · course_sections (hybrid, module=AUL)
CREATE TABLE IF NOT EXISTS course_sections (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid,
  course_id uuid NOT NULL,
  section_number integer NOT NULL,
  title text NOT NULL,
  description text,
  sort_order integer NOT NULL DEFAULT 0,
  is_visible boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE course_sections IS '[AUL] Sección (unidad o módulo) de un curso que agrupa lecciones';
COMMENT ON COLUMN course_sections.company_id IS 'NULL = fila global de la plataforma';

-- AUL · course_lessons (hybrid, module=AUL)
CREATE TABLE IF NOT EXISTS course_lessons (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid,
  course_id uuid NOT NULL,
  section_id uuid,
  lesson_number integer NOT NULL,
  title text NOT NULL,
  lesson_type text NOT NULL CHECK (lesson_type IN ('text', 'video', 'document', 'link', 'exam')),
  content_html text,
  file_id uuid,
  video_provider text CHECK (video_provider IN ('vimeo')),
  video_external_id text,
  external_url text,
  duration_minutes integer,
  is_required boolean NOT NULL DEFAULT true,
  min_view_pct numeric(5,2),
  question_bank_id uuid,
  exam_config jsonb,
  passing_score numeric(6,2),
  max_attempts integer,
  time_limit_minutes integer,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_course_lessons_1 CHECK (lesson_type <> 'video' OR (video_provider IS NOT NULL AND video_external_id IS NOT NULL)),
  CONSTRAINT ck_course_lessons_2 CHECK (lesson_type <> 'link' OR (external_url IS NOT NULL AND external_url ~ '^https://')),
  CONSTRAINT ck_course_lessons_3 CHECK (lesson_type <> 'document' OR file_id IS NOT NULL),
  CONSTRAINT ck_course_lessons_4 CHECK (lesson_type <> 'text' OR content_html IS NOT NULL),
  CONSTRAINT ck_course_lessons_5 CHECK (min_view_pct IS NULL OR min_view_pct BETWEEN 0 AND 100),
  CONSTRAINT ck_course_lessons_6 CHECK (max_attempts IS NULL OR max_attempts > 0),
  CONSTRAINT ck_course_lessons_7 CHECK (time_limit_minutes IS NULL OR time_limit_minutes > 0)
);
COMMENT ON TABLE course_lessons IS '[AUL] Lección del curso: texto, video en Vimeo, documento, enlace o evaluación (company_id NULL en cursos del catálogo)';
COMMENT ON COLUMN course_lessons.company_id IS 'NULL = fila global de la plataforma';
COMMENT ON COLUMN course_lessons.content_html IS 'contenido de texto (HTML saneado)';
COMMENT ON COLUMN course_lessons.video_external_id IS 'id del video en Vimeo';
COMMENT ON COLUMN course_lessons.min_view_pct IS '% mínimo de visualización del video para darlo por visto';
COMMENT ON COLUMN course_lessons.question_bank_id IS 'banco del que se sortea el examen';
COMMENT ON COLUMN course_lessons.exam_config IS 'número de preguntas por banco o dificultad, orden aleatorio, mostrar retroalimentación';

-- AUL · course_enrollments (company)
CREATE TABLE IF NOT EXISTS course_enrollments (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  course_id uuid NOT NULL,
  worker_id uuid,
  contractor_worker_id uuid,
  external_learner_id uuid,
  user_id uuid,
  source text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'position_assignment', 'purchase', 'license', 'self_enrollment', 'lms_sync')),
  order_item_id uuid,
  license_assignment_id uuid,
  position_training_requirement_id uuid,
  enrolled_by uuid,
  enrolled_at timestamptz NOT NULL DEFAULT now(),
  access_until timestamptz,
  due_on date,
  started_at timestamptz,
  completed_at timestamptz,
  progress_pct numeric(5,2) NOT NULL DEFAULT 0,
  final_score numeric(6,2),
  final_score_label text,
  passed boolean,
  active_seconds_total bigint NOT NULL DEFAULT 0,
  last_activity_at timestamptz,
  lesson_progress jsonb,
  commitment_accepted_at timestamptz,
  certificate_id uuid,
  external_enrollment_id text,
  last_synced_at timestamptz,
  status text NOT NULL DEFAULT 'enrolled' CHECK (status IN ('enrolled', 'in_progress', 'completed', 'failed', 'expired', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_course_enrollments_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_course_enrollments_1 CHECK (((worker_id IS NOT NULL)::int + (contractor_worker_id IS NOT NULL)::int + (external_learner_id IS NOT NULL)::int) = 1),
  CONSTRAINT ck_course_enrollments_2 CHECK (source <> 'purchase' OR order_item_id IS NOT NULL),
  CONSTRAINT ck_course_enrollments_3 CHECK (source <> 'license' OR license_assignment_id IS NOT NULL),
  CONSTRAINT ck_course_enrollments_4 CHECK (source <> 'position_assignment' OR position_training_requirement_id IS NOT NULL),
  CONSTRAINT ck_course_enrollments_5 CHECK (progress_pct BETWEEN 0 AND 100),
  CONSTRAINT ck_course_enrollments_6 CHECK (active_seconds_total >= 0),
  CONSTRAINT ck_course_enrollments_7 CHECK (status <> 'completed' OR completed_at IS NOT NULL)
);
COMMENT ON TABLE course_enrollments IS '[AUL] Matrícula en un curso de un trabajador, trabajador de contratista o participante externo';
COMMENT ON COLUMN course_enrollments.access_until IS 'fin del acceso (cursos comprados con vigencia en días)';
COMMENT ON COLUMN course_enrollments.active_seconds_total IS 'tiempo activo acumulado (suma de learning_activity_sessions)';
COMMENT ON COLUMN course_enrollments.lesson_progress IS 'avance por lección (vista, % de video, completada)';

-- AUL · quiz_attempts (company, sync)
CREATE TABLE IF NOT EXISTS quiz_attempts (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  enrollment_id uuid NOT NULL,
  lesson_id uuid,
  source text NOT NULL DEFAULT 'internal' CHECK (source IN ('internal', 'external')),
  external_attempt_id text,
  attempt_number integer NOT NULL,
  question_set jsonb,
  started_at timestamptz NOT NULL DEFAULT now(),
  submitted_at timestamptz,
  expires_at timestamptz,
  time_spent_seconds integer,
  score numeric(6,2),
  max_score numeric(6,2),
  grade_label text,
  passed boolean,
  answers jsonb,
  graded_by uuid,
  graded_at timestamptz,
  feedback text,
  status text NOT NULL DEFAULT 'in_progress' CHECK (status IN ('in_progress', 'submitted', 'graded', 'expired')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  idempotency_key text,
  device_id uuid,
  client_created_at timestamptz,
  sync_batch_id uuid,
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  CONSTRAINT uq_quiz_attempts_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_quiz_attempts_1 CHECK (attempt_number > 0),
  CONSTRAINT ck_quiz_attempts_2 CHECK (score IS NULL OR max_score IS NULL OR score <= max_score)
);
COMMENT ON TABLE quiz_attempts IS '[AUL] Intento de evaluación en línea (propio, sorteado desde bancos, o nota importada de Moodle)';
COMMENT ON COLUMN quiz_attempts.question_set IS 'preguntas sorteadas (ids y orden de opciones) para este intento';
COMMENT ON COLUMN quiz_attempts.expires_at IS 'límite según time_limit_minutes';
COMMENT ON COLUMN quiz_attempts.graded_by IS 'calificación manual (respuesta corta)';
COMMENT ON COLUMN quiz_attempts.idempotency_key IS 'clave idempotente generada por el cliente (offline)';
COMMENT ON COLUMN quiz_attempts.client_created_at IS 'instante de captura en el dispositivo';
COMMENT ON COLUMN quiz_attempts.version IS 'versión para control optimista y conflictos offline';

-- AUL · question_banks (company)
CREATE TABLE IF NOT EXISTS question_banks (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  course_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  topic text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_question_banks_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE question_banks IS '[AUL] Banco de preguntas: general de la empresa (course_id NULL) o propio de un curso';

-- AUL · questions (company)
CREATE TABLE IF NOT EXISTS questions (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  question_bank_id uuid NOT NULL,
  code text,
  question_type text NOT NULL CHECK (question_type IN ('single_choice', 'multiple_choice', 'true_false', 'short_answer')),
  statement text NOT NULL,
  statement_file_id uuid,
  options jsonb,
  accepted_answers jsonb,
  points numeric(6,2) NOT NULL DEFAULT 1,
  difficulty text CHECK (difficulty IN ('easy', 'medium', 'hard')),
  feedback_correct text,
  feedback_incorrect text,
  shuffle_options boolean NOT NULL DEFAULT true,
  bulk_import_id uuid,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft', 'active', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_questions_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_questions_1 CHECK (points > 0),
  CONSTRAINT ck_questions_2 CHECK (question_type = 'short_answer' OR options IS NOT NULL),
  CONSTRAINT ck_questions_3 CHECK (question_type <> 'short_answer' OR accepted_answers IS NOT NULL)
);
COMMENT ON TABLE questions IS '[AUL] Pregunta de un banco (opción única, múltiple, verdadero/falso o respuesta corta) con puntaje y retroalimentación';
COMMENT ON COLUMN questions.statement_file_id IS 'imagen opcional del enunciado';
COMMENT ON COLUMN questions.options IS '[{key, text, is_correct, feedback}]';
COMMENT ON COLUMN questions.accepted_answers IS 'respuesta corta: respuestas aceptadas (normalizadas)';
COMMENT ON COLUMN questions.bulk_import_id IS 'importada desde Excel';

-- AUL · grading_scales (hybrid, module=AUL)
CREATE TABLE IF NOT EXISTS grading_scales (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid,
  code text NOT NULL,
  name text NOT NULL,
  scale_type text NOT NULL CHECK (scale_type IN ('numeric', 'letter')),
  min_value numeric(6,2),
  max_value numeric(6,2),
  passing_value numeric(6,2),
  passing_label text,
  bands jsonb NOT NULL DEFAULT '[]'::jsonb,
  decimals smallint NOT NULL DEFAULT 0,
  is_default boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_grading_scales_1 CHECK (scale_type <> 'numeric' OR (min_value IS NOT NULL AND max_value IS NOT NULL AND passing_value IS NOT NULL AND max_value > min_value AND passing_value BETWEEN min_value AND max_value)),
  CONSTRAINT ck_grading_scales_2 CHECK (scale_type <> 'letter' OR (passing_label IS NOT NULL AND jsonb_array_length(bands) > 0)),
  CONSTRAINT ck_grading_scales_3 CHECK (decimals BETWEEN 0 AND 2)
);
COMMENT ON TABLE grading_scales IS '[AUL] Escala de calificación: numérica (0-20, 0-10, 0-100) o de letras (AD/A/B/C, A/B/C/D), global por defecto o propia';
COMMENT ON COLUMN grading_scales.company_id IS 'NULL = fila global de la plataforma';
COMMENT ON COLUMN grading_scales.passing_value IS 'nota mínima aprobatoria (escala numérica)';
COMMENT ON COLUMN grading_scales.passing_label IS 'letra mínima aprobatoria (escala de letras)';
COMMENT ON COLUMN grading_scales.bands IS 'tramos [{label, from, to, description}] sobre el porcentaje obtenido';

-- AUL · trainer_permissions (company)
CREATE TABLE IF NOT EXISTS trainer_permissions (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  trainer_user_id uuid NOT NULL,
  course_id uuid,
  can_upload_materials boolean NOT NULL DEFAULT true,
  can_edit_content boolean NOT NULL DEFAULT false,
  can_edit_assessments boolean NOT NULL DEFAULT false,
  can_manage_question_banks boolean NOT NULL DEFAULT false,
  can_grade boolean NOT NULL DEFAULT false,
  can_enroll boolean NOT NULL DEFAULT false,
  can_view_reports boolean NOT NULL DEFAULT true,
  valid_from date,
  valid_until date,
  granted_by uuid,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_trainer_permissions_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_trainer_permissions_1 CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_until >= valid_from)
);
COMMENT ON TABLE trainer_permissions IS '[AUL] Permisos del capacitador, globales en la empresa (course_id NULL) o por curso; los configura el administrador';

-- AUL · trainer_availability (company)
CREATE TABLE IF NOT EXISTS trainer_availability (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  trainer_user_id uuid NOT NULL,
  kind text NOT NULL DEFAULT 'weekly' CHECK (kind IN ('weekly', 'blocked', 'extra')),
  weekday smallint,
  start_time time,
  end_time time,
  date_from date,
  date_to date,
  site_id uuid,
  modality text CHECK (modality IN ('in_person', 'virtual', 'both')),
  reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_trainer_availability_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_trainer_availability_1 CHECK (kind <> 'weekly' OR (weekday BETWEEN 1 AND 7 AND start_time IS NOT NULL AND end_time IS NOT NULL)),
  CONSTRAINT ck_trainer_availability_2 CHECK (kind = 'weekly' OR date_from IS NOT NULL),
  CONSTRAINT ck_trainer_availability_3 CHECK (end_time IS NULL OR start_time IS NULL OR end_time > start_time),
  CONSTRAINT ck_trainer_availability_4 CHECK (date_to IS NULL OR date_from IS NULL OR date_to >= date_from)
);
COMMENT ON TABLE trainer_availability IS '[AUL] Horario semanal de disponibilidad del capacitador y fechas bloqueadas';
COMMENT ON COLUMN trainer_availability.weekday IS '1 = lunes … 7 = domingo';

-- AUL · learning_activity_sessions (company)
CREATE TABLE IF NOT EXISTS learning_activity_sessions (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  enrollment_id uuid NOT NULL,
  lesson_id uuid,
  client_session_id text NOT NULL,
  started_at timestamptz NOT NULL,
  last_heartbeat_at timestamptz NOT NULL,
  ended_at timestamptz,
  active_seconds integer NOT NULL DEFAULT 0,
  video_seconds integer NOT NULL DEFAULT 0,
  video_max_position_seconds integer,
  interactions_count integer NOT NULL DEFAULT 0,
  heartbeats_count integer NOT NULL DEFAULT 0,
  last_heartbeat_seq integer NOT NULL DEFAULT 0,
  device_type text CHECK (device_type IN ('desktop', 'mobile', 'tablet', 'other')),
  user_agent text,
  ip_hash bytea,
  end_reason text CHECK (end_reason IN ('closed', 'idle_timeout', 'completed', 'superseded')),
  is_flagged boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_learning_activity_sessions_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_learning_activity_sessions_1 CHECK (active_seconds >= 0 AND video_seconds >= 0 AND interactions_count >= 0 AND heartbeats_count >= 0),
  CONSTRAINT ck_learning_activity_sessions_2 CHECK (last_heartbeat_at >= started_at),
  CONSTRAINT ck_learning_activity_sessions_3 CHECK (ended_at IS NULL OR ended_at >= started_at),
  CONSTRAINT ck_learning_activity_sessions_4 CHECK (active_seconds <= extract(epoch FROM (last_heartbeat_at - started_at)) + 120)
);
COMMENT ON TABLE learning_activity_sessions IS '[AUL] Sesión de actividad real en el aula (latidos con interacción y video), base del tiempo de permanencia acreditable';
COMMENT ON COLUMN learning_activity_sessions.client_session_id IS 'id generado por el cliente; el latido es idempotente por (matrícula, client_session_id, secuencia)';
COMMENT ON COLUMN learning_activity_sessions.active_seconds IS 'solo segundos con interacción o video en reproducción con la pestaña visible';
COMMENT ON COLUMN learning_activity_sessions.last_heartbeat_seq IS 'secuencia del último latido aplicado (un latido repetido no suma)';
COMMENT ON COLUMN learning_activity_sessions.is_flagged IS 'actividad anómala (p. ej. segundos activos mayores que el tiempo transcurrido)';

-- AUL · completion_commitments (company)
CREATE TABLE IF NOT EXISTS completion_commitments (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  enrollment_id uuid NOT NULL,
  course_id uuid NOT NULL,
  commitment_text_snapshot text NOT NULL,
  text_version integer NOT NULL DEFAULT 1,
  accepted_at timestamptz NOT NULL DEFAULT now(),
  accepted_by_user_id uuid,
  signature_id uuid,
  ip_hash bytea,
  user_agent text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_completion_commitments_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE completion_commitments IS '[AUL] Compromiso de culminación aceptado por el participante (obligatorio si el curso lo activa)';
COMMENT ON COLUMN completion_commitments.commitment_text_snapshot IS 'texto exacto aceptado';

-- AUL · lms_connections (company)
CREATE TABLE IF NOT EXISTS lms_connections (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  provider text NOT NULL DEFAULT 'moodle' CHECK (provider IN ('moodle')),
  name text NOT NULL,
  base_url text NOT NULL,
  credentials_secret_ref text NOT NULL,
  moodle_service_name text,
  sync_direction text NOT NULL DEFAULT 'import' CHECK (sync_direction IN ('import', 'export', 'both')),
  sync_enrollments boolean NOT NULL DEFAULT true,
  sync_grades boolean NOT NULL DEFAULT true,
  sso_enabled boolean NOT NULL DEFAULT false,
  settings jsonb NOT NULL DEFAULT '{}'::jsonb,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'error', 'disabled')),
  last_tested_at timestamptz,
  last_sync_at timestamptz,
  last_sync_status text CHECK (last_sync_status IN ('ok', 'partial', 'failed')),
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_lms_connections_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_lms_connections_1 CHECK (base_url ~ '^https://'),
  CONSTRAINT ck_lms_connections_2 CHECK (credentials_secret_ref ~ '^[a-z][a-z0-9+.-]*://')
);
COMMENT ON TABLE lms_connections IS '[AUL] Conexión opcional con el Moodle del cliente por API (única implementación de LmsProvider); credenciales solo como referencia al gestor de secretos';
COMMENT ON COLUMN lms_connections.credentials_secret_ref IS 'referencia al token del servicio web de Moodle en el gestor de secretos (nunca el secreto en claro)';

-- AUL · recommendation_rules (company)
CREATE TABLE IF NOT EXISTS recommendation_rules (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  rule_type text NOT NULL CHECK (rule_type IN ('matrix_gap', 'certificate_expiring', 'learning_path_next', 'complementary', 'inspection_finding', 'incident_related', 'similar_buyers', 'manual')),
  parameters jsonb NOT NULL DEFAULT '{}'::jsonb,
  audience text NOT NULL CHECK (audience IN ('workers', 'external_learners', 'buyer_companies')),
  course_ids uuid[],
  channels text[] NOT NULL DEFAULT '{in_app}',
  max_sends_per_person integer NOT NULL DEFAULT 1,
  send_period_days integer NOT NULL DEFAULT 30,
  requires_consent boolean NOT NULL DEFAULT true,
  priority smallint NOT NULL DEFAULT 100,
  is_active boolean NOT NULL DEFAULT false,
  last_run_at timestamptz,
  last_run_status text CHECK (last_run_status IN ('ok', 'partial', 'failed')),
  last_run_count integer,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_recommendation_rules_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_recommendation_rules_1 CHECK (channels <@ ARRAY['in_app','email','whatsapp']::text[] AND cardinality(channels) > 0),
  CONSTRAINT ck_recommendation_rules_2 CHECK (max_sends_per_person > 0 AND send_period_days > 0),
  CONSTRAINT ck_recommendation_rules_3 CHECK (rule_type <> 'similar_buyers' OR audience <> 'workers')
);
COMMENT ON TABLE recommendation_rules IS '[AUL] Regla automática de recomendación de cursos configurable por la empresa (nunca usa datos médicos)';
COMMENT ON COLUMN recommendation_rules.parameters IS 'p. ej. días de anticipación, cursos origen y destino, tipos de hallazgo; validado contra el esquema del tipo';
COMMENT ON COLUMN recommendation_rules.course_ids IS 'cursos que puede recomendar (NULL = los que resuelva la regla); se valida en la aplicación';
COMMENT ON COLUMN recommendation_rules.max_sends_per_person IS 'límite de envíos por persona en el periodo';
COMMENT ON COLUMN recommendation_rules.requires_consent IS 'correo y WhatsApp solo con consentimiento vigente';

-- AUL · course_recommendations (company)
CREATE TABLE IF NOT EXISTS course_recommendations (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  course_id uuid NOT NULL,
  course_offer_id uuid,
  worker_id uuid,
  external_learner_id uuid,
  buyer_company_ruc char(11),
  buyer_company_name text,
  rule_id uuid,
  source text NOT NULL CHECK (source IN ('rule', 'manual', 'ai')),
  recommended_by uuid,
  target_scope text NOT NULL DEFAULT 'person' CHECK (target_scope IN ('person', 'position', 'area', 'buyer_company')),
  target_position_id uuid,
  target_area_id uuid,
  reason_code text,
  message text,
  ai_suggestion_id uuid,
  channel text CHECK (channel IN ('in_app', 'email', 'whatsapp')),
  status text NOT NULL DEFAULT 'suggested' CHECK (status IN ('suggested', 'sent', 'viewed', 'clicked', 'converted', 'dismissed', 'expired')),
  sent_at timestamptz,
  viewed_at timestamptz,
  clicked_at timestamptz,
  converted_at timestamptz,
  dismissed_at timestamptz,
  dismiss_reason text,
  expires_at timestamptz,
  converted_enrollment_id uuid,
  converted_order_id uuid,
  dedupe_key text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_course_recommendations_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_course_recommendations_1 CHECK (((worker_id IS NOT NULL)::int + (external_learner_id IS NOT NULL)::int + (buyer_company_ruc IS NOT NULL)::int) = 1),
  CONSTRAINT ck_course_recommendations_2 CHECK (buyer_company_ruc IS NULL OR buyer_company_ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_course_recommendations_3 CHECK (source <> 'rule' OR rule_id IS NOT NULL),
  CONSTRAINT ck_course_recommendations_4 CHECK (source <> 'ai' OR (ai_suggestion_id IS NOT NULL AND recommended_by IS NOT NULL)),
  CONSTRAINT ck_course_recommendations_5 CHECK (source <> 'manual' OR recommended_by IS NOT NULL),
  CONSTRAINT ck_course_recommendations_6 CHECK (status <> 'converted' OR (converted_at IS NOT NULL AND (converted_enrollment_id IS NOT NULL OR converted_order_id IS NOT NULL))),
  CONSTRAINT ck_course_recommendations_7 CHECK (status <> 'sent' OR sent_at IS NOT NULL),
  CONSTRAINT ck_course_recommendations_8 CHECK (status <> 'dismissed' OR dismissed_at IS NOT NULL),
  CONSTRAINT ck_course_recommendations_9 CHECK (target_scope <> 'position' OR target_position_id IS NOT NULL),
  CONSTRAINT ck_course_recommendations_10 CHECK (target_scope <> 'area' OR target_area_id IS NOT NULL)
);
COMMENT ON TABLE course_recommendations IS '[AUL] Recomendación de un curso a un trabajador, participante externo o empresa compradora, con su embudo de conversión';
COMMENT ON COLUMN course_recommendations.course_offer_id IS 'oferta de venta cuando el destinatario es externo';
COMMENT ON COLUMN course_recommendations.buyer_company_ruc IS 'empresa compradora destinataria';
COMMENT ON COLUMN course_recommendations.recommended_by IS 'autor de la recomendación manual o aprobador de la sugerencia de IA';
COMMENT ON COLUMN course_recommendations.target_scope IS 'alcance con que se creó (una fila por destinatario)';
COMMENT ON COLUMN course_recommendations.reason_code IS 'motivo de la regla (p. ej. matrix_gap, certificate_expiring) sin datos sensibles';
COMMENT ON COLUMN course_recommendations.converted_enrollment_id IS 'conversión: matrícula';
COMMENT ON COLUMN course_recommendations.converted_order_id IS 'conversión: compra';
COMMENT ON COLUMN course_recommendations.dedupe_key IS 'destinatario + curso + motivo: no se repite mientras haya una activa (el enfriamiento tras descartar lo aplica la app con recommendation_dismiss_cooldown_days)';

-- FOT · credential_types (company, definer)
CREATE TABLE IF NOT EXISTS credential_types (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  description text,
  validity_months integer,
  design_template jsonb,
  shows_photo boolean NOT NULL DEFAULT true,
  shows_position boolean NOT NULL DEFAULT true,
  applies_to text NOT NULL DEFAULT 'both' CHECK (applies_to IN ('workers', 'contractor_workers', 'both')),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_credential_types_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE credential_types IS '[FOT] Tipo de fotocheck SST (diseño, vigencia, a quién aplica)';

-- FOT · credential_requirements (company, definer)
CREATE TABLE IF NOT EXISTS credential_requirements (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  credential_type_id uuid NOT NULL,
  requirement_type text NOT NULL CHECK (requirement_type IN ('training', 'emo_fitness', 'sctr', 'induction', 'document', 'ppe_delivery', 'accreditation')),
  training_id uuid,
  worker_document_kind text,
  position_id uuid,
  description text NOT NULL,
  is_blocking boolean NOT NULL DEFAULT true,
  grace_days integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_credential_requirements_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE credential_requirements IS '[FOT] Requisito para que la credencial esté habilitada (capacitación, aptitud vigente, SCTR, inducción…)';

-- FOT · credentials (company, definer)
CREATE TABLE IF NOT EXISTS credentials (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  credential_type_id uuid NOT NULL,
  worker_id uuid,
  contractor_worker_id uuid,
  credential_number text NOT NULL,
  token_hash bytea NOT NULL,
  token_last4 text,
  qr_payload_version smallint NOT NULL DEFAULT 1,
  issued_at timestamptz,
  issued_by uuid,
  valid_from date,
  expires_on date,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'issued', 'active', 'blocked', 'expired', 'revoked')),
  blocking_reasons jsonb,
  last_evaluated_at timestamptz,
  revoked_at timestamptz,
  revoked_reason text,
  pdf_file_id uuid,
  printed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_credentials_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_credentials_1 CHECK ((worker_id IS NOT NULL) <> (contractor_worker_id IS NOT NULL)),
  CONSTRAINT ck_credentials_2 CHECK (status <> 'revoked' OR revoked_reason IS NOT NULL)
);
COMMENT ON TABLE credentials IS '[FOT] Fotocheck SST con token QR verificable (estado calculado)';
COMMENT ON COLUMN credentials.token_hash IS 'sha256 del token opaco del QR';
COMMENT ON COLUMN credentials.blocking_reasons IS 'solo códigos de requisito, nunca datos médicos';

-- FOT · credential_verifications (imm, sync)
CREATE TABLE IF NOT EXISTS credential_verifications (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  credential_id uuid NOT NULL,
  verified_at timestamptz NOT NULL DEFAULT now(),
  channel text NOT NULL CHECK (channel IN ('public_qr', 'app_scan', 'access_point')),
  access_point_id uuid,
  verifier_user_id uuid,
  result text NOT NULL CHECK (result IN ('enabled', 'not_enabled', 'invalid', 'revoked', 'expired')),
  response_snapshot jsonb,
  ip_hash bytea,
  user_agent text,
  latitude numeric(9,6),
  longitude numeric(9,6),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  idempotency_key text,
  device_id uuid,
  client_created_at timestamptz,
  sync_batch_id uuid,
  PRIMARY KEY (id),
  CONSTRAINT uq_credential_verifications_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE credential_verifications IS '[FOT] Verificación de un fotocheck (pública por QR, app o portería), inalterable · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN credential_verifications.response_snapshot IS 'lo que se mostró (sin datos médicos)';
COMMENT ON COLUMN credential_verifications.idempotency_key IS 'clave idempotente generada por el cliente (offline)';
COMMENT ON COLUMN credential_verifications.client_created_at IS 'instante de captura en el dispositivo';

-- EMO · medical_exam_orders (company)
CREATE TABLE IF NOT EXISTS medical_exam_orders (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  worker_id uuid NOT NULL,
  exam_type text NOT NULL CHECK (exam_type IN ('pre_employment', 'periodic', 'exit', 'return_to_work', 'position_change', 'other')),
  position_id uuid,
  protocol_code text,
  clinic_name text,
  clinic_ruc char(11),
  scheduled_at timestamptz,
  attended_at timestamptz,
  status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'attended', 'no_show', 'results_received', 'fitness_issued', 'cancelled')),
  cancel_reason text,
  requested_by uuid,
  order_file_id uuid,
  medical_exam_ref uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_medical_exam_orders_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_medical_exam_orders_1 CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL)
);
COMMENT ON TABLE medical_exam_orders IS '[EMO] Orden y programación de EMO (sin resultados; los resultados viven en la base médica)';
COMMENT ON COLUMN medical_exam_orders.order_file_id IS 'orden de atención (no médica)';
COMMENT ON COLUMN medical_exam_orders.medical_exam_ref IS 'id en escudo_medical.medical_exams (sin FK entre bases)';

-- EMO · fitness_status (company, definer)
CREATE TABLE IF NOT EXISTS fitness_status (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  worker_id uuid NOT NULL,
  medical_exam_order_id uuid,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'fit', 'fit_with_restrictions', 'unfit', 'expired')),
  valid_from date,
  valid_until date,
  work_restrictions text,
  issued_by uuid,
  issued_at timestamptz,
  is_current boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_fitness_status_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_fitness_status_1 CHECK (status <> 'fit_with_restrictions' OR work_restrictions IS NOT NULL),
  CONSTRAINT ck_fitness_status_2 CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_until >= valid_from)
);
COMMENT ON TABLE fitness_status IS '[EMO] Aptitud vigente del trabajador (apto / con restricciones / no apto / pendiente); nunca diagnósticos';
COMMENT ON COLUMN fitness_status.work_restrictions IS 'redactada en términos laborales por el médico, sin diagnóstico';

-- DES · absences (company)
CREATE TABLE IF NOT EXISTS absences (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  worker_id uuid NOT NULL,
  absence_type text NOT NULL CHECK (absence_type IN ('medical_leave', 'occupational_accident', 'occupational_disease', 'maternity', 'paternity', 'permission', 'unjustified', 'other')),
  starts_on date NOT NULL,
  ends_on date NOT NULL,
  days integer GENERATED ALWAYS AS ((ends_on - starts_on) + 1) STORED,
  is_work_related boolean NOT NULL DEFAULT false,
  sst_event_id uuid,
  certificate_received boolean NOT NULL DEFAULT false,
  medical_leave_ref uuid,
  registered_by uuid,
  status text NOT NULL DEFAULT 'registered' CHECK (status IN ('registered', 'validated', 'closed', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_absences_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_absences_1 CHECK (ends_on >= starts_on)
);
COMMENT ON TABLE absences IS '[DES] Ausencia o descanso médico (solo fechas, días y tipo general; el detalle va a la base médica)';
COMMENT ON COLUMN absences.medical_leave_ref IS 'id en escudo_medical.medical_leave_details';

-- VUL · work_adjustments (company)
CREATE TABLE IF NOT EXISTS work_adjustments (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  worker_id uuid NOT NULL,
  vulnerability_ref uuid,
  adjustment_category text NOT NULL CHECK (adjustment_category IN ('workload', 'schedule', 'position_change', 'ergonomic', 'environment', 'equipment', 'other')),
  description text NOT NULL,
  new_position_id uuid,
  starts_on date NOT NULL,
  ends_on date,
  approved_by uuid,
  status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'active', 'ended', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_work_adjustments_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_work_adjustments_1 CHECK (ends_on IS NULL OR ends_on >= starts_on)
);
COMMENT ON TABLE work_adjustments IS '[VUL] Adecuación del puesto por condición de vulnerabilidad (sin la condición; esta vive en la base médica)';
COMMENT ON COLUMN work_adjustments.vulnerability_ref IS 'id en escudo_medical.vulnerability_records';
COMMENT ON COLUMN work_adjustments.description IS 'en términos laborales';

-- VTA · external_learners (company)
CREATE TABLE IF NOT EXISTS external_learners (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  user_id uuid,
  document_type text NOT NULL DEFAULT 'DNI' CHECK (document_type IN ('DNI', 'CE', 'PTP', 'PASSPORT', 'OTHER')),
  document_number text NOT NULL,
  document_number_hash bytea NOT NULL,
  document_last4 text,
  first_name text NOT NULL,
  last_name text NOT NULL,
  email text NOT NULL,
  phone_e164 text,
  buyer_company_ruc char(11),
  buyer_company_name text,
  data_consent_at timestamptz NOT NULL,
  consent_text_version text NOT NULL,
  marketing_consent boolean NOT NULL DEFAULT false,
  marketing_consent_at timestamptz,
  source text NOT NULL DEFAULT 'purchase' CHECK (source IN ('purchase', 'manual', 'import', 'license')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'blocked', 'anonymized')),
  anonymized_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_external_learners_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_external_learners_1 CHECK (buyer_company_ruc IS NULL OR buyer_company_ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_external_learners_2 CHECK (NOT marketing_consent OR marketing_consent_at IS NOT NULL)
);
COMMENT ON TABLE external_learners IS '[VTA] Participante externo (no trabajador): compra cursos o recibe un cupo de una empresa compradora';
COMMENT ON COLUMN external_learners.user_id IS 'cuenta para ingresar al aula (rol external_learner)';
COMMENT ON COLUMN external_learners.document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN external_learners.document_number_hash IS 'HMAC del número para búsqueda exacta y unicidad';
COMMENT ON COLUMN external_learners.phone_e164 IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN external_learners.buyer_company_ruc IS 'empresa compradora (opcional) que le asignó el cupo';
COMMENT ON COLUMN external_learners.data_consent_at IS 'consentimiento de tratamiento de datos (Ley 29733)';

-- VTA · course_offers (company, definer)
CREATE TABLE IF NOT EXISTS course_offers (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  course_id uuid NOT NULL,
  slug text NOT NULL,
  title text NOT NULL,
  short_description text,
  currency char(3) NOT NULL DEFAULT 'PEN',
  list_price numeric(12,2) NOT NULL,
  sale_price numeric(12,2),
  price_includes_igv boolean NOT NULL DEFAULT true,
  igv_affectation text NOT NULL DEFAULT 'taxed' CHECK (igv_affectation IN ('taxed', 'exempt', 'unaffected')),
  sale_starts_at timestamptz,
  sale_ends_at timestamptz,
  access_days integer,
  seats_total integer,
  seats_sold integer NOT NULL DEFAULT 0,
  allows_company_purchase boolean NOT NULL DEFAULT true,
  min_company_seats integer,
  is_public boolean NOT NULL DEFAULT false,
  published_at timestamptz,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'paused', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_course_offers_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_course_offers_1 CHECK (currency = 'PEN'),
  CONSTRAINT ck_course_offers_2 CHECK (list_price >= 0 AND (sale_price IS NULL OR (sale_price >= 0 AND sale_price <= list_price))),
  CONSTRAINT ck_course_offers_3 CHECK (seats_total IS NULL OR (seats_total > 0 AND seats_sold <= seats_total)),
  CONSTRAINT ck_course_offers_4 CHECK (seats_sold >= 0),
  CONSTRAINT ck_course_offers_5 CHECK (access_days IS NULL OR access_days > 0),
  CONSTRAINT ck_course_offers_6 CHECK (min_company_seats IS NULL OR min_company_seats > 0),
  CONSTRAINT ck_course_offers_7 CHECK (sale_ends_at IS NULL OR sale_starts_at IS NULL OR sale_ends_at > sale_starts_at),
  CONSTRAINT ck_course_offers_8 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);
COMMENT ON TABLE course_offers IS '[VTA] Curso a la venta: precio en soles (lo define la empresa), vigencia del acceso, cupo y visibilidad en el catálogo público';
COMMENT ON COLUMN course_offers.slug IS 'identificador en la URL del catálogo público';
COMMENT ON COLUMN course_offers.title IS 'título comercial';
COMMENT ON COLUMN course_offers.list_price IS 'precio de lista con IGV (dato de la empresa)';
COMMENT ON COLUMN course_offers.sale_price IS 'precio de oferta con IGV';
COMMENT ON COLUMN course_offers.access_days IS 'días de acceso desde la compra; NULL = mientras el curso esté publicado';
COMMENT ON COLUMN course_offers.seats_total IS 'cupo de la oferta; NULL = sin límite';
COMMENT ON COLUMN course_offers.allows_company_purchase IS 'se puede comprar como cupos (licencias) por una empresa';
COMMENT ON COLUMN course_offers.is_public IS 'visible en el catálogo público sin sesión';

-- VTA · coupons (company)
CREATE TABLE IF NOT EXISTS coupons (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text NOT NULL,
  description text,
  discount_type text NOT NULL CHECK (discount_type IN ('percent', 'fixed')),
  discount_value numeric(12,2) NOT NULL,
  currency char(3) NOT NULL DEFAULT 'PEN',
  applies_to text NOT NULL DEFAULT 'all' CHECK (applies_to IN ('all', 'offers')),
  course_offer_ids uuid[],
  min_order_total numeric(12,2),
  max_redemptions integer,
  max_redemptions_per_buyer integer NOT NULL DEFAULT 1,
  redemptions_count integer NOT NULL DEFAULT 0,
  valid_from timestamptz,
  valid_until timestamptz,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_coupons_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_coupons_1 CHECK (discount_value > 0 AND (discount_type <> 'percent' OR discount_value <= 100)),
  CONSTRAINT ck_coupons_2 CHECK (currency = 'PEN'),
  CONSTRAINT ck_coupons_3 CHECK (max_redemptions IS NULL OR (max_redemptions > 0 AND redemptions_count <= max_redemptions)),
  CONSTRAINT ck_coupons_4 CHECK (applies_to = 'all' OR course_offer_ids IS NOT NULL),
  CONSTRAINT ck_coupons_5 CHECK (valid_until IS NULL OR valid_from IS NULL OR valid_until > valid_from)
);
COMMENT ON TABLE coupons IS '[VTA] Cupón de descuento (porcentaje o monto fijo) con vigencia y límite de usos';
COMMENT ON COLUMN coupons.course_offer_ids IS 'ofertas a las que aplica cuando applies_to = offers (se valida en la aplicación)';

-- VTA · orders (company)
CREATE TABLE IF NOT EXISTS orders (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  order_number text NOT NULL,
  buyer_type text NOT NULL CHECK (buyer_type IN ('person', 'company')),
  external_learner_id uuid,
  buyer_document_type text NOT NULL CHECK (buyer_document_type IN ('DNI', 'CE', 'PTP', 'PASSPORT', 'RUC', 'OTHER')),
  buyer_document_number text NOT NULL,
  buyer_name text NOT NULL,
  buyer_email text NOT NULL,
  buyer_phone text,
  buyer_ruc char(11),
  buyer_legal_name text,
  buyer_fiscal_address text,
  billing_document_type text NOT NULL DEFAULT 'receipt' CHECK (billing_document_type IN ('receipt', 'invoice')),
  coupon_id uuid,
  payment_gateway_id uuid,
  currency char(3) NOT NULL DEFAULT 'PEN',
  subtotal numeric(12,2) NOT NULL DEFAULT 0,
  discount_total numeric(12,2) NOT NULL DEFAULT 0,
  igv_rate numeric(5,4),
  igv_total numeric(12,2) NOT NULL DEFAULT 0,
  total numeric(12,2) NOT NULL DEFAULT 0,
  idempotency_key text NOT NULL,
  source text NOT NULL DEFAULT 'public_catalog' CHECK (source IN ('public_catalog', 'admin', 'api')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'paid', 'failed', 'voided', 'refunded')),
  expires_at timestamptz,
  paid_at timestamptz,
  voided_at timestamptz,
  void_reason text,
  refunded_at timestamptz,
  customer_ip_hash bytea,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_orders_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_orders_1 CHECK (currency = 'PEN'),
  CONSTRAINT ck_orders_2 CHECK (subtotal >= 0 AND discount_total >= 0 AND igv_total >= 0),
  CONSTRAINT ck_orders_3 CHECK (total = subtotal + igv_total),
  CONSTRAINT ck_orders_4 CHECK (buyer_type <> 'person' OR external_learner_id IS NOT NULL),
  CONSTRAINT ck_orders_5 CHECK (buyer_type <> 'company' OR (buyer_ruc IS NOT NULL AND buyer_legal_name IS NOT NULL)),
  CONSTRAINT ck_orders_6 CHECK (billing_document_type <> 'invoice' OR buyer_ruc IS NOT NULL),
  CONSTRAINT ck_orders_7 CHECK (buyer_ruc IS NULL OR buyer_ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_orders_8 CHECK (status <> 'paid' OR paid_at IS NOT NULL),
  CONSTRAINT ck_orders_9 CHECK (status <> 'voided' OR void_reason IS NOT NULL)
);
COMMENT ON TABLE orders IS '[VTA] Pedido de compra de cursos (persona o empresa compradora con RUC), totales con IGV e idempotencia';
COMMENT ON COLUMN orders.order_number IS 'correlativo legible, p. ej. PED-2026-000031';
COMMENT ON COLUMN orders.buyer_document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN orders.buyer_phone IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN orders.subtotal IS 'base imponible después de descuentos';
COMMENT ON COLUMN orders.igv_rate IS 'tasa aplicada (instantánea del parámetro legal igv_rate)';
COMMENT ON COLUMN orders.idempotency_key IS 'clave del cliente al crear el pedido (un doble clic no crea dos pedidos)';
COMMENT ON COLUMN orders.expires_at IS 'un pedido pendiente caduca y libera el cupo';

-- VTA · order_items (company)
CREATE TABLE IF NOT EXISTS order_items (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  order_id uuid NOT NULL,
  course_offer_id uuid NOT NULL,
  course_id uuid NOT NULL,
  description text NOT NULL,
  item_type text NOT NULL DEFAULT 'individual' CHECK (item_type IN ('individual', 'license')),
  quantity integer NOT NULL DEFAULT 1,
  unit_price numeric(12,2) NOT NULL,
  discount_amount numeric(12,2) NOT NULL DEFAULT 0,
  subtotal numeric(12,2) NOT NULL,
  igv_amount numeric(12,2) NOT NULL DEFAULT 0,
  total numeric(12,2) NOT NULL,
  course_license_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_order_items_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_order_items_1 CHECK (quantity > 0),
  CONSTRAINT ck_order_items_2 CHECK (item_type = 'license' OR quantity = 1),
  CONSTRAINT ck_order_items_3 CHECK (unit_price >= 0 AND discount_amount >= 0 AND subtotal >= 0 AND igv_amount >= 0),
  CONSTRAINT ck_order_items_4 CHECK (total = subtotal + igv_amount)
);
COMMENT ON TABLE order_items IS '[VTA] Línea del pedido: curso individual o cupos (licencias) para una empresa';
COMMENT ON COLUMN order_items.unit_price IS 'precio unitario con IGV al momento de la compra';
COMMENT ON COLUMN order_items.subtotal IS 'base imponible';
COMMENT ON COLUMN order_items.course_license_id IS 'cupos generados al pagarse (item_type = license)';

-- VTA · payment_gateways (company, definer)
CREATE TABLE IF NOT EXISTS payment_gateways (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  provider text NOT NULL CHECK (provider IN ('culqi', 'niubiz', 'izipay', 'mercadopago')),
  name text NOT NULL,
  mode text NOT NULL DEFAULT 'test' CHECK (mode IN ('test', 'production')),
  public_key text,
  secret_key_ref text NOT NULL,
  webhook_secret_ref text NOT NULL,
  merchant_id text,
  allowed_methods text[] NOT NULL DEFAULT '{card,yape}',
  settings jsonb NOT NULL DEFAULT '{}'::jsonb,
  is_active boolean NOT NULL DEFAULT false,
  is_default boolean NOT NULL DEFAULT false,
  last_tested_at timestamptz,
  last_test_status text CHECK (last_test_status IN ('ok', 'failed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_payment_gateways_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_payment_gateways_1 CHECK (secret_key_ref ~ '^[a-z][a-z0-9+.-]*://'),
  CONSTRAINT ck_payment_gateways_2 CHECK (webhook_secret_ref ~ '^[a-z][a-z0-9+.-]*://'),
  CONSTRAINT ck_payment_gateways_3 CHECK (allowed_methods <@ ARRAY['card','yape','plin','pagoefectivo','transfer']::text[]),
  CONSTRAINT ck_payment_gateways_4 CHECK (NOT is_default OR is_active)
);
COMMENT ON TABLE payment_gateways IS '[VTA] Pasarela de pagos de la empresa (Culqi, Niubiz, Izipay o Mercado Pago); llaves y secreto de webhook solo como referencia al gestor de secretos';
COMMENT ON COLUMN payment_gateways.public_key IS 'llave pública publicable (la usa el formulario de pago del navegador)';
COMMENT ON COLUMN payment_gateways.secret_key_ref IS 'referencia a la llave privada en el gestor de secretos (nunca en claro)';
COMMENT ON COLUMN payment_gateways.webhook_secret_ref IS 'referencia al secreto de firma del webhook';

-- VTA · payment_transactions (imm)
CREATE TABLE IF NOT EXISTS payment_transactions (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  order_id uuid NOT NULL,
  payment_gateway_id uuid NOT NULL,
  provider text NOT NULL CHECK (provider IN ('culqi', 'niubiz', 'izipay', 'mercadopago')),
  external_id text NOT NULL,
  provider_reference text,
  kind text NOT NULL DEFAULT 'charge' CHECK (kind IN ('charge', 'refund', 'chargeback')),
  status text NOT NULL CHECK (status IN ('pending', 'succeeded', 'failed', 'refunded', 'cancelled')),
  amount numeric(12,2) NOT NULL,
  currency char(3) NOT NULL DEFAULT 'PEN',
  method text CHECK (method IN ('card', 'yape', 'plin', 'pagoefectivo', 'transfer', 'other')),
  card_brand text,
  card_last4 char(4),
  idempotency_key text,
  gateway_token_ref text,
  cip_code text,
  payload jsonb,
  payload_sha256 bytea NOT NULL,
  signature_verified boolean NOT NULL DEFAULT false,
  source text NOT NULL DEFAULT 'webhook' CHECK (source IN ('webhook', 'api_response', 'reconciliation')),
  received_at timestamptz NOT NULL DEFAULT now(),
  ip_hash bytea,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT uq_payment_transactions_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_payment_transactions_1 CHECK (amount >= 0),
  CONSTRAINT ck_payment_transactions_2 CHECK (currency = 'PEN'),
  CONSTRAINT ck_payment_transactions_3 CHECK (card_last4 IS NULL OR card_last4 ~ '^[0-9]{4}$'),
  CONSTRAINT ck_payment_transactions_4 CHECK (source <> 'webhook' OR signature_verified),
  CONSTRAINT ck_payment_transactions_5 CHECK (payload IS NULL OR NOT (payload ?| ARRAY['card_number','pan','cvv','cvc','cvv2','security_code']))
);
COMMENT ON TABLE payment_transactions IS '[VTA] Evento de pago recibido de la pasarela (webhook firmado o respuesta de la API), inalterable; único por (pasarela, id externo) · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN payment_transactions.external_id IS 'id del evento o cargo en la pasarela; idempotencia: el mismo evento no se procesa dos veces';
COMMENT ON COLUMN payment_transactions.card_last4 IS 'solo si la pasarela lo devuelve; jamás el número de tarjeta';
COMMENT ON COLUMN payment_transactions.idempotency_key IS 'clave con que se creó el cargo en la pasarela (por pedido e intento)';
COMMENT ON COLUMN payment_transactions.gateway_token_ref IS 'token o id de la tarjeta en la pasarela (nunca PAN ni CVV)';
COMMENT ON COLUMN payment_transactions.cip_code IS 'código CIP de PagoEfectivo';
COMMENT ON COLUMN payment_transactions.payload IS 'carga útil recibida, sin datos de tarjeta';

-- VTA · course_licenses (company)
CREATE TABLE IF NOT EXISTS course_licenses (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  order_item_id uuid,
  course_id uuid NOT NULL,
  course_offer_id uuid,
  buyer_ruc char(11) NOT NULL,
  buyer_legal_name text NOT NULL,
  buyer_contact_email text,
  manager_user_id uuid,
  license_code text NOT NULL,
  seats_purchased integer NOT NULL,
  seats_used integer NOT NULL DEFAULT 0,
  access_days integer,
  expires_at timestamptz,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'exhausted', 'expired', 'voided')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_course_licenses_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_course_licenses_1 CHECK (buyer_ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_course_licenses_2 CHECK (seats_purchased > 0 AND seats_used >= 0 AND seats_used <= seats_purchased),
  CONSTRAINT ck_course_licenses_3 CHECK (access_days IS NULL OR access_days > 0)
);
COMMENT ON TABLE course_licenses IS '[VTA] Cupos (licencias) de un curso comprados por una empresa para asignarlos a su personal';
COMMENT ON COLUMN course_licenses.manager_user_id IS 'usuario de la empresa compradora que asigna los cupos';
COMMENT ON COLUMN course_licenses.license_code IS 'código de la licencia para su gestión';

-- VTA · license_assignments (company)
CREATE TABLE IF NOT EXISTS license_assignments (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  course_license_id uuid NOT NULL,
  external_learner_id uuid NOT NULL,
  assigned_by uuid,
  assigned_at timestamptz NOT NULL DEFAULT now(),
  enrollment_id uuid,
  status text NOT NULL DEFAULT 'assigned' CHECK (status IN ('assigned', 'consumed', 'revoked')),
  revoked_at timestamptz,
  revoke_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_license_assignments_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_license_assignments_1 CHECK (status <> 'revoked' OR (revoked_at IS NOT NULL AND revoke_reason IS NOT NULL))
);
COMMENT ON TABLE license_assignments IS '[VTA] Asignación de un cupo de licencia a un participante externo (genera su matrícula)';

-- VTA · sales_documents (company)
CREATE TABLE IF NOT EXISTS sales_documents (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  order_id uuid NOT NULL,
  document_type text NOT NULL CHECK (document_type IN ('receipt', 'invoice', 'credit_note', 'debit_note')),
  series text NOT NULL,
  number integer NOT NULL,
  issue_date date NOT NULL,
  related_document_id uuid,
  note_reason_code text,
  customer_document_type text NOT NULL CHECK (customer_document_type IN ('DNI', 'CE', 'RUC', 'PASSPORT', 'OTHER')),
  customer_document_number text NOT NULL,
  customer_name text NOT NULL,
  customer_address text,
  currency char(3) NOT NULL DEFAULT 'PEN',
  taxable_amount numeric(12,2) NOT NULL DEFAULT 0,
  igv_amount numeric(12,2) NOT NULL DEFAULT 0,
  total numeric(12,2) NOT NULL DEFAULT 0,
  lines jsonb NOT NULL DEFAULT '[]'::jsonb,
  provider text,
  provider_document_id text,
  sunat_status text NOT NULL DEFAULT 'pending' CHECK (sunat_status IN ('pending', 'sent', 'accepted', 'observed', 'rejected', 'voided', 'not_sent')),
  sunat_response_code text,
  sunat_description text,
  sent_at timestamptz,
  accepted_at timestamptz,
  hash_code text,
  xml_file_id uuid,
  cdr_file_id uuid,
  pdf_file_id uuid,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'issued', 'voided')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_sales_documents_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_sales_documents_1 CHECK (currency = 'PEN'),
  CONSTRAINT ck_sales_documents_2 CHECK (total = taxable_amount + igv_amount),
  CONSTRAINT ck_sales_documents_3 CHECK (number > 0),
  CONSTRAINT ck_sales_documents_4 CHECK (series ~ '^[BF][A-Z0-9]{3}$'),
  CONSTRAINT ck_sales_documents_5 CHECK (document_type NOT IN ('credit_note','debit_note') OR related_document_id IS NOT NULL),
  CONSTRAINT ck_sales_documents_6 CHECK (document_type <> 'invoice' OR customer_document_type = 'RUC')
);
COMMENT ON TABLE sales_documents IS '[VTA] Comprobante electrónico de la venta (boleta, factura, nota de crédito o débito); proveedor de emisión por definir';
COMMENT ON COLUMN sales_documents.series IS 'p. ej. B001, F001';
COMMENT ON COLUMN sales_documents.related_document_id IS 'comprobante que modifica la nota de crédito o débito';
COMMENT ON COLUMN sales_documents.customer_document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN sales_documents.provider IS 'proveedor de emisión electrónica (por definir; detrás de la interfaz ElectronicInvoicing)';
COMMENT ON COLUMN sales_documents.hash_code IS 'resumen de la firma digital del XML';

-- ACC · sst_events (company, sync)
CREATE TABLE IF NOT EXISTS sst_events (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text NOT NULL,
  event_type text NOT NULL CHECK (event_type IN ('fatal_accident', 'disabling_accident', 'minor_accident', 'dangerous_incident', 'incident', 'occupational_disease')),
  origin text NOT NULL DEFAULT 'web' CHECK (origin IN ('app', 'web', 'whatsapp', 'qr')),
  occurred_at timestamptz NOT NULL,
  reported_at timestamptz NOT NULL DEFAULT now(),
  site_id uuid NOT NULL,
  area_id uuid,
  work_shift_id uuid,
  exact_location text,
  latitude numeric(9,6),
  longitude numeric(9,6),
  description text NOT NULL,
  activity_at_time text,
  hours_worked_before numeric(5,2),
  is_contractor_event boolean NOT NULL DEFAULT false,
  contractor_id uuid,
  severity text CHECK (severity IN ('none', 'minor', 'disabling', 'fatal')),
  disability_type text CHECK (disability_type IN ('none', 'total_temporary', 'partial_temporary', 'partial_permanent', 'total_permanent')),
  lost_days integer NOT NULL DEFAULT 0,
  injured_count integer NOT NULL DEFAULT 0,
  material_damage text,
  witnesses jsonb,
  immediate_actions text,
  reporter_user_id uuid,
  register_number text,
  notification_deadline_at timestamptz,
  notification_overdue boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'reported' CHECK (status IN ('reported', 'registered', 'notified', 'under_investigation', 'closed', 'discarded')),
  discarded_reason text,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  idempotency_key text,
  device_id uuid,
  client_created_at timestamptz,
  sync_batch_id uuid,
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  CONSTRAINT uq_sst_events_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_sst_events_1 CHECK (reported_at >= occurred_at - interval '1 day'),
  CONSTRAINT ck_sst_events_2 CHECK (status <> 'discarded' OR discarded_reason IS NOT NULL),
  CONSTRAINT ck_sst_events_3 CHECK (NOT is_contractor_event OR contractor_id IS NOT NULL)
);
COMMENT ON TABLE sst_events IS '[ACC] Accidente, incidente peligroso, incidente o enfermedad ocupacional (registro y notificación en plazo)';
COMMENT ON COLUMN sst_events.notification_deadline_at IS 'calculado con legal_parameters';
COMMENT ON COLUMN sst_events.idempotency_key IS 'clave idempotente generada por el cliente (offline)';
COMMENT ON COLUMN sst_events.client_created_at IS 'instante de captura en el dispositivo';
COMMENT ON COLUMN sst_events.version IS 'versión para control optimista y conflictos offline';

-- ACC · event_people (company, sync)
CREATE TABLE IF NOT EXISTS event_people (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  event_id uuid NOT NULL,
  worker_id uuid,
  contractor_worker_id uuid,
  external_person_name text,
  person_role text NOT NULL CHECK (person_role IN ('injured', 'affected', 'ill', 'witness', 'involved')),
  age_at_event integer,
  seniority_months integer,
  position_text text,
  injury_type text,
  body_part text,
  injury_nature text,
  lost_days integer NOT NULL DEFAULT 0,
  citt_days integer,
  disability_type text CHECK (disability_type IN ('none', 'total_temporary', 'partial_temporary', 'partial_permanent', 'total_permanent')),
  medical_attention_place text,
  is_fatal boolean NOT NULL DEFAULT false,
  disease_agent_type text,
  medical_record_ref uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  idempotency_key text,
  device_id uuid,
  client_created_at timestamptz,
  sync_batch_id uuid,
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  CONSTRAINT uq_event_people_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_event_people_1 CHECK (worker_id IS NOT NULL OR contractor_worker_id IS NOT NULL OR external_person_name IS NOT NULL)
);
COMMENT ON TABLE event_people IS '[ACC] Persona afectada, involucrada o testigo del evento con datos del registro R.M. 050-2013-TR';
COMMENT ON COLUMN event_people.disease_agent_type IS 'enfermedad ocupacional: agente causante';
COMMENT ON COLUMN event_people.medical_record_ref IS 'enfermedad ocupacional: id del caso/EMO en escudo_medical (el nombre de la enfermedad nunca se guarda aquí)';
COMMENT ON COLUMN event_people.idempotency_key IS 'clave idempotente generada por el cliente (offline)';
COMMENT ON COLUMN event_people.client_created_at IS 'instante de captura en el dispositivo';
COMMENT ON COLUMN event_people.version IS 'versión para control optimista y conflictos offline';

-- ACC · event_notifications (company)
CREATE TABLE IF NOT EXISTS event_notifications (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  event_id uuid NOT NULL,
  authority text NOT NULL CHECK (authority IN ('mtpe_sat', 'sunafil', 'essalud', 'eps', 'insurer_sctr', 'osinergmin', 'other')),
  notification_type text NOT NULL DEFAULT 'initial' CHECK (notification_type IN ('initial', 'update', 'final')),
  legal_parameter_key text,
  deadline_at timestamptz,
  notified_at timestamptz,
  notification_number text,
  channel text CHECK (channel IN ('sat_online', 'in_person', 'email', 'other')),
  receipt_file_id uuid,
  notified_by uuid,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'acknowledged', 'not_required')),
  notification_overdue boolean NOT NULL DEFAULT false,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_event_notifications_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_event_notifications_1 CHECK (status NOT IN ('sent','acknowledged') OR notified_at IS NOT NULL)
);
COMMENT ON TABLE event_notifications IS '[ACC] Notificación a la autoridad (MTPE/SAT, SUNAFIL, aseguradora) con plazo y alerta de vencimiento';

-- INV · investigations (company)
CREATE TABLE IF NOT EXISTS investigations (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  event_id uuid NOT NULL,
  code text,
  method text NOT NULL CHECK (method IN ('cause_tree', 'scat', 'five_whys', 'fishbone', 'other')),
  started_on date,
  due_on date,
  summary text,
  immediate_causes text,
  basic_causes text,
  conclusions text,
  lessons_learned text,
  report_file_id uuid,
  committee_meeting_id uuid,
  approved_by uuid,
  approved_at timestamptz,
  ai_assisted boolean NOT NULL DEFAULT false,
  ai_suggestion_id uuid,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'analysis', 'committee_review', 'approved', 'actions_in_progress', 'closed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_investigations_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_investigations_1 CHECK (NOT ai_assisted OR ai_suggestion_id IS NOT NULL)
);
COMMENT ON TABLE investigations IS '[INV] Investigación del evento (árbol de causas, SCAT…) con aprobación del comité';

-- INV · investigation_team (company)
CREATE TABLE IF NOT EXISTS investigation_team (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  investigation_id uuid NOT NULL,
  worker_id uuid,
  user_id uuid,
  external_name text,
  role text NOT NULL CHECK (role IN ('leader', 'member', 'committee_representative', 'worker_representative', 'expert', 'witness')),
  signature_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_investigation_team_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_investigation_team_1 CHECK (worker_id IS NOT NULL OR user_id IS NOT NULL OR external_name IS NOT NULL)
);
COMMENT ON TABLE investigation_team IS '[INV] Integrante del equipo investigador';

-- INV · investigation_causes (company)
CREATE TABLE IF NOT EXISTS investigation_causes (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  investigation_id uuid NOT NULL,
  parent_cause_id uuid,
  cause_level text NOT NULL CHECK (cause_level IN ('immediate', 'basic', 'root', 'lack_of_control')),
  cause_category text CHECK (cause_category IN ('unsafe_act', 'unsafe_condition', 'personal_factor', 'job_factor', 'management_system')),
  scat_code text,
  description text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  corrective_action_id uuid,
  ai_suggestion_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_investigation_causes_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE investigation_causes IS '[INV] Causa identificada (árbol: inmediata, básica, raíz, falta de control)';

-- ACR · corrective_actions (company)
CREATE TABLE IF NOT EXISTS corrective_actions (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text NOT NULL,
  source_type text NOT NULL CHECK (source_type IN ('inspection', 'finding', 'audit', 'event', 'investigation', 'report', 'baseline', 'legal_requirement', 'committee_agreement', 'management_review', 'monitoring', 'iperc', 'drill', 'observation', 'change', 'environmental_aspect', 'other')),
  source_id uuid,
  action_type text NOT NULL DEFAULT 'corrective' CHECK (action_type IN ('corrective', 'preventive', 'improvement')),
  control_hierarchy text CHECK (control_hierarchy IN ('elimination', 'substitution', 'engineering', 'administrative', 'signage', 'ppe')),
  title text NOT NULL,
  description text,
  site_id uuid,
  area_id uuid,
  responsible_user_id uuid,
  responsible_worker_id uuid,
  contractor_id uuid,
  due_on date NOT NULL,
  priority text NOT NULL DEFAULT 'medium' CHECK (priority IN ('low', 'medium', 'high', 'critical')),
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'pending_verification', 'verified', 'overdue', 'cancelled')),
  completed_at timestamptz,
  verified_by uuid,
  verified_at timestamptz,
  verification_notes text,
  effectiveness text CHECK (effectiveness IN ('effective', 'not_effective', 'pending')),
  cancel_reason text,
  reopened_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_corrective_actions_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_corrective_actions_1 CHECK (responsible_user_id IS NOT NULL OR responsible_worker_id IS NOT NULL OR contractor_id IS NOT NULL),
  CONSTRAINT ck_corrective_actions_2 CHECK (verified_by IS NULL OR responsible_user_id IS NULL OR verified_by <> responsible_user_id),
  CONSTRAINT ck_corrective_actions_3 CHECK (status <> 'verified' OR (verified_by IS NOT NULL AND verified_at IS NOT NULL)),
  CONSTRAINT ck_corrective_actions_4 CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL)
);
COMMENT ON TABLE corrective_actions IS '[ACR] Acción correctiva o preventiva con responsable, plazo y verificación de cierre';

-- ACR · action_evidences (company, sync)
CREATE TABLE IF NOT EXISTS action_evidences (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  corrective_action_id uuid NOT NULL,
  evidence_type text NOT NULL DEFAULT 'photo' CHECK (evidence_type IN ('photo', 'document', 'record', 'other')),
  description text,
  file_id uuid,
  submitted_by uuid,
  submitted_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  idempotency_key text,
  device_id uuid,
  client_created_at timestamptz,
  sync_batch_id uuid,
  version integer NOT NULL DEFAULT 1,
  PRIMARY KEY (id),
  CONSTRAINT uq_action_evidences_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE action_evidences IS '[ACR] Evidencia de ejecución de una acción correctiva';
COMMENT ON COLUMN action_evidences.idempotency_key IS 'clave idempotente generada por el cliente (offline)';
COMMENT ON COLUMN action_evidences.client_created_at IS 'instante de captura en el dispositivo';
COMMENT ON COLUMN action_evidences.version IS 'versión para control optimista y conflictos offline';

-- AUI · audits (company)
CREATE TABLE IF NOT EXISTS audits (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  code text,
  audit_type text NOT NULL CHECK (audit_type IN ('internal', 'external', 'legal_mandatory', 'certification', 'client', 'supplier')),
  standard text NOT NULL DEFAULT 'ley_29783' CHECK (standard IN ('ley_29783', 'iso_45001', 'iso_9001', 'iso_14001', 'integrated', 'other')),
  scope text,
  criteria text,
  site_id uuid,
  starts_on date,
  ends_on date,
  lead_auditor_name text,
  auditor_registration text,
  audit_firm text,
  team jsonb,
  external_auditor_membership_id uuid,
  report_file_id uuid,
  conclusions text,
  status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'in_progress', 'report_draft', 'completed', 'closed', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_audits_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE audits IS '[AUI] Auditoría interna o externa del SG-SST (registro obligatorio)';
COMMENT ON COLUMN audits.auditor_registration IS 'registro de auditores autorizados';

-- AUI · audit_checklist_items (company)
CREATE TABLE IF NOT EXISTS audit_checklist_items (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  audit_id uuid NOT NULL,
  clause_code text,
  requirement text NOT NULL,
  result text NOT NULL DEFAULT 'pending' CHECK (result IN ('conforming', 'minor_nc', 'major_nc', 'observation', 'opportunity', 'not_applicable', 'pending')),
  evidence text,
  file_id uuid,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_audit_checklist_items_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE audit_checklist_items IS '[AUI] Ítem verificado en la auditoría';

-- AUI · audit_findings (company)
CREATE TABLE IF NOT EXISTS audit_findings (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  audit_id uuid NOT NULL,
  checklist_item_id uuid,
  finding_type text NOT NULL CHECK (finding_type IN ('major_nc', 'minor_nc', 'observation', 'opportunity')),
  clause_code text,
  description text NOT NULL,
  root_cause text,
  due_on date,
  corrective_action_id uuid,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'action_assigned', 'resolved', 'dismissed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_audit_findings_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE audit_findings IS '[AUI] Hallazgo de auditoría (no conformidad, observación, oportunidad)';

-- EST · man_hours (company)
CREATE TABLE IF NOT EXISTS man_hours (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  period_year smallint NOT NULL,
  period_month smallint NOT NULL,
  site_id uuid,
  worker_count numeric(10,2) NOT NULL DEFAULT 0,
  contractor_worker_count numeric(10,2) NOT NULL DEFAULT 0,
  hours_worked numeric(14,2) NOT NULL,
  contractor_hours numeric(14,2) NOT NULL DEFAULT 0,
  source text NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'import', 'payroll_api', 'calculated')),
  bulk_import_id uuid,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_man_hours_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_man_hours_1 CHECK (period_month BETWEEN 1 AND 12),
  CONSTRAINT ck_man_hours_2 CHECK (hours_worked >= 0)
);
COMMENT ON TABLE man_hours IS '[EST] Horas-hombre trabajadas por mes y sede (base de los índices)';

-- EST · monthly_statistics (company)
CREATE TABLE IF NOT EXISTS monthly_statistics (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  period_year smallint NOT NULL,
  period_month smallint NOT NULL,
  site_id uuid,
  worker_count numeric(10,2),
  hours_worked numeric(14,2),
  accidents_fatal integer NOT NULL DEFAULT 0,
  accidents_disabling integer NOT NULL DEFAULT 0,
  accidents_minor integer NOT NULL DEFAULT 0,
  dangerous_incidents integer NOT NULL DEFAULT 0,
  incidents integer NOT NULL DEFAULT 0,
  occupational_diseases integer NOT NULL DEFAULT 0,
  lost_days integer NOT NULL DEFAULT 0,
  frequency_index numeric(14,4),
  severity_index numeric(14,4),
  accident_rate_index numeric(14,4),
  frequency_factor numeric(14,2),
  severity_factor numeric(14,2),
  accident_rate_divisor numeric(14,2),
  parameters_snapshot jsonb,
  computed_at timestamptz,
  is_closed boolean NOT NULL DEFAULT false,
  closed_by uuid,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_monthly_statistics_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_monthly_statistics_1 CHECK (period_month BETWEEN 1 AND 12)
);
COMMENT ON TABLE monthly_statistics IS '[EST] Estadística mensual: índices de frecuencia, gravedad y accidentabilidad (factor por parámetro)';
COMMENT ON COLUMN monthly_statistics.frequency_factor IS 'valor de legal_parameters usado en el cálculo';

-- RVD · management_reviews (company)
CREATE TABLE IF NOT EXISTS management_reviews (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  year smallint NOT NULL,
  review_on date,
  title text NOT NULL,
  inputs jsonb,
  participants jsonb,
  conclusions text,
  policy_changes_needed boolean NOT NULL DEFAULT false,
  report_file_id uuid,
  approved_by uuid,
  approved_at timestamptz,
  status text NOT NULL DEFAULT 'planned' CHECK (status IN ('planned', 'in_progress', 'completed', 'closed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_management_reviews_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE management_reviews IS '[RVD] Revisión por la dirección (informe anual a gerencia)';

-- RVD · management_review_outputs (company)
CREATE TABLE IF NOT EXISTS management_review_outputs (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  review_id uuid NOT NULL,
  output_type text NOT NULL CHECK (output_type IN ('decision', 'improvement', 'resource', 'objective_change', 'policy_change', 'other')),
  description text NOT NULL,
  responsible_user_id uuid,
  due_on date,
  corrective_action_id uuid,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'in_progress', 'done', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_management_review_outputs_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE management_review_outputs IS '[RVD] Decisión o salida de la revisión por la dirección';

-- REG · register_exports (company)
CREATE TABLE IF NOT EXISTS register_exports (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  register_type text NOT NULL CHECK (register_type IN ('accidents', 'occupational_diseases', 'incidents', 'emo', 'monitoring', 'inspections', 'statistics', 'emergency_equipment', 'training', 'audits')),
  period_from date NOT NULL,
  period_to date NOT NULL,
  site_id uuid,
  format text NOT NULL DEFAULT 'pdf' CHECK (format IN ('pdf', 'xlsx', 'zip')),
  template_version text,
  filters jsonb,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'generating', 'ready', 'failed', 'expired')),
  file_id uuid,
  sha256 bytea,
  rows_count integer,
  requested_by uuid,
  requested_at timestamptz NOT NULL DEFAULT now(),
  generated_at timestamptz,
  error_message text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_register_exports_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_register_exports_1 CHECK (period_to >= period_from)
);
COMMENT ON TABLE register_exports IS '[REG] Exportación de los registros obligatorios en formato R.M. 050-2013-TR';

-- CTR · contractors (company, contractor)
CREATE TABLE IF NOT EXISTS contractors (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  ruc char(11) NOT NULL,
  legal_name text NOT NULL,
  trade_name text,
  contact_name text,
  contact_email text,
  contact_phone text,
  services_description text,
  risk_level text CHECK (risk_level IN ('low', 'medium', 'high', 'very_high')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'blocked', 'inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_contractors_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_contractors_1 CHECK (ruc ~ '^(10|15|17|20)[0-9]{9}$')
);
COMMENT ON TABLE contractors IS '[CTR] Empresa contratista o proveedora';
COMMENT ON COLUMN contractors.contact_email IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN contractors.contact_phone IS '[CIFRADO EN APLICACIÓN]';

-- CTR · contractor_workers (company, contractor, definer)
CREATE TABLE IF NOT EXISTS contractor_workers (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  contractor_id uuid NOT NULL,
  document_type text NOT NULL DEFAULT 'DNI' CHECK (document_type IN ('DNI', 'CE', 'PTP', 'PASSPORT', 'OTHER')),
  document_number text NOT NULL,
  document_number_hash bytea NOT NULL,
  document_last4 text,
  first_name text NOT NULL,
  paternal_last_name text NOT NULL,
  maternal_last_name text,
  position_text text,
  phone_e164 text,
  photo_file_id uuid,
  emo_fitness text NOT NULL DEFAULT 'unknown' CHECK (emo_fitness IN ('fit', 'fit_with_restrictions', 'unfit', 'pending', 'unknown')),
  emo_valid_until date,
  access_enabled boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive', 'blocked')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_contractor_workers_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE contractor_workers IS '[CTR] Trabajador de contratista';
COMMENT ON COLUMN contractor_workers.document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN contractor_workers.phone_e164 IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN contractor_workers.emo_fitness IS 'según constancia presentada, sin diagnóstico';

-- CTR · contractor_requirements (company)
CREATE TABLE IF NOT EXISTS contractor_requirements (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  applies_to text NOT NULL CHECK (applies_to IN ('company', 'worker')),
  requirement_code text NOT NULL,
  name text NOT NULL,
  description text,
  document_kind text,
  is_mandatory boolean NOT NULL DEFAULT true,
  validity_months integer,
  risk_levels text[],
  service_types text[],
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_contractor_requirements_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE contractor_requirements IS '[CTR] Requisito documental exigido a contratistas o a sus trabajadores';

-- CTR · contractor_documents (company, contractor)
CREATE TABLE IF NOT EXISTS contractor_documents (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  contractor_id uuid NOT NULL,
  contractor_worker_id uuid,
  requirement_id uuid,
  document_kind text,
  file_id uuid,
  issued_on date,
  expires_on date,
  uploaded_by uuid,
  reviewed_by uuid,
  reviewed_at timestamptz,
  review_comments text,
  status text NOT NULL DEFAULT 'submitted' CHECK (status IN ('pending', 'submitted', 'approved', 'observed', 'rejected', 'expired')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_contractor_documents_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE contractor_documents IS '[CTR] Documento presentado por la contratista con revisión y vigencia';

-- CTR · contractor_accreditations (company, contractor)
CREATE TABLE IF NOT EXISTS contractor_accreditations (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  contractor_id uuid NOT NULL,
  contract_reference text,
  service_description text,
  site_id uuid,
  starts_on date,
  ends_on date,
  expires_on date,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'submitted', 'under_review', 'observed', 'accredited', 'expiring', 'expired', 'suspended', 'rejected')),
  submitted_at timestamptz,
  reviewed_by uuid,
  reviewed_at timestamptz,
  approved_by uuid,
  approved_at timestamptz,
  observations text,
  rejection_reason text,
  suspended_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_contractor_accreditations_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_contractor_accreditations_1 CHECK (approved_by IS NULL OR reviewed_by IS NULL OR approved_by <> reviewed_by)
);
COMMENT ON TABLE contractor_accreditations IS '[CTR] Acreditación de la contratista para un servicio y sede';

-- SCT · sctr_policies (company, contractor)
CREATE TABLE IF NOT EXISTS sctr_policies (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  contractor_id uuid,
  coverage_kind text NOT NULL CHECK (coverage_kind IN ('health', 'pension')),
  insurer_type text NOT NULL CHECK (insurer_type IN ('essalud', 'eps', 'private_insurer', 'onp')),
  insurer_name text NOT NULL,
  insurer_ruc char(11),
  policy_number text NOT NULL,
  starts_on date NOT NULL,
  ends_on date NOT NULL,
  file_id uuid,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'expiring', 'expired', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_sctr_policies_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_sctr_policies_1 CHECK (ends_on >= starts_on)
);
COMMENT ON TABLE sctr_policies IS '[SCT] Póliza SCTR (salud y pensión) propia o de contratista';
COMMENT ON COLUMN sctr_policies.contractor_id IS 'NULL = póliza de la propia empresa';

-- SCT · sctr_coverages (company)
CREATE TABLE IF NOT EXISTS sctr_coverages (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  sctr_policy_id uuid NOT NULL,
  worker_id uuid,
  contractor_worker_id uuid,
  covered_from date NOT NULL,
  covered_until date NOT NULL,
  constancy_number text,
  file_id uuid,
  status text NOT NULL DEFAULT 'covered' CHECK (status IN ('covered', 'not_covered', 'expired')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_sctr_coverages_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_sctr_coverages_1 CHECK ((worker_id IS NOT NULL) <> (contractor_worker_id IS NOT NULL)),
  CONSTRAINT ck_sctr_coverages_2 CHECK (covered_until >= covered_from)
);
COMMENT ON TABLE sctr_coverages IS '[SCT] Cobertura SCTR de un trabajador en una póliza';

-- ING · access_points (company)
CREATE TABLE IF NOT EXISTS access_points (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  site_id uuid NOT NULL,
  code text NOT NULL,
  name text NOT NULL,
  point_type text NOT NULL DEFAULT 'main_gate' CHECK (point_type IN ('main_gate', 'vehicle_gate', 'turnstile', 'area_access', 'other')),
  device_id uuid,
  requires_credential boolean NOT NULL DEFAULT true,
  allows_visitors boolean NOT NULL DEFAULT true,
  latitude numeric(9,6),
  longitude numeric(9,6),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_access_points_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE access_points IS '[ING] Punto de control de acceso (portería, torniquete)';

-- ING · access_events (imm, sync)
CREATE TABLE IF NOT EXISTS access_events (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  access_point_id uuid NOT NULL,
  occurred_at timestamptz NOT NULL,
  direction text NOT NULL CHECK (direction IN ('in', 'out')),
  subject_type text NOT NULL CHECK (subject_type IN ('worker', 'contractor_worker', 'visitor', 'vehicle')),
  worker_id uuid,
  contractor_worker_id uuid,
  credential_id uuid,
  visitor_name text,
  visitor_document_masked text,
  result text NOT NULL CHECK (result IN ('granted', 'denied', 'overridden')),
  deny_reasons jsonb,
  guard_user_id uuid,
  override_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  idempotency_key text,
  device_id uuid,
  client_created_at timestamptz,
  sync_batch_id uuid,
  PRIMARY KEY (id),
  CONSTRAINT uq_access_events_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_access_events_1 CHECK (result <> 'overridden' OR override_reason IS NOT NULL)
);
COMMENT ON TABLE access_events IS '[ING] Evento de ingreso o salida (habilitado / no habilitado), inalterable · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN access_events.idempotency_key IS 'clave idempotente generada por el cliente (offline)';
COMMENT ON COLUMN access_events.client_created_at IS 'instante de captura en el dispositivo';

-- HOM · vendor_evaluation_templates (hybrid)
