);
COMMENT ON TABLE self_diagnostics IS '[SUN] Autodiagnóstico frente a los criterios de inspección de SUNAFIL';

-- SUN · inspection_dossiers (company, definer)
CREATE TABLE IF NOT EXISTS inspection_dossiers (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  title text NOT NULL,
  request_type text NOT NULL DEFAULT 'sunafil_inspection' CHECK (request_type IN ('sunafil_inspection', 'self_review', 'client_audit', 'other')),
  inspection_order_number text,
  inspector_name text,
  requirement_file_id uuid,
  appearance_at timestamptz,
  period_from date NOT NULL,
  period_to date NOT NULL,
  site_id uuid,
  scope_modules text[],
  scope jsonb,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'building', 'ready', 'ready_with_gaps', 'failed', 'archived')),
  gaps jsonb,
  built_at timestamptz,
  zip_file_id uuid,
  index_file_id uuid,
  requested_by uuid,
  error_message text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_inspection_dossiers_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_inspection_dossiers_1 CHECK (period_to >= period_from)
);
COMMENT ON TABLE inspection_dossiers IS '[SUN] Expediente para inspección SUNAFIL por trabajador y periodo';
COMMENT ON COLUMN inspection_dossiers.appearance_at IS 'fecha de comparecencia';
COMMENT ON COLUMN inspection_dossiers.scope IS 'trabajadores y criterios incluidos';

-- SUN · dossier_items (company, definer)
CREATE TABLE IF NOT EXISTS dossier_items (
