-- OFF · sync_batches (company)
CREATE TABLE IF NOT EXISTS sync_batches (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  device_id uuid NOT NULL,
  user_id uuid,
  batch_uuid uuid NOT NULL,
  idempotency_key text NOT NULL,
  client_created_at timestamptz,
  received_at timestamptz NOT NULL DEFAULT now(),
  processed_at timestamptz,
  app_version text,
  payload_sha256 bytea,
  payload_file_id uuid,
  operations_count integer NOT NULL DEFAULT 0,
  applied_count integer NOT NULL DEFAULT 0,
  conflict_count integer NOT NULL DEFAULT 0,
  rejected_count integer NOT NULL DEFAULT 0,
  error_summary jsonb,
  status text NOT NULL DEFAULT 'received' CHECK (status IN ('received', 'processing', 'applied', 'partially_applied', 'rejected')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_sync_batches_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE sync_batches IS '[OFF] Lote de sincronización recibido desde un dispositivo (idempotente)';
COMMENT ON COLUMN sync_batches.batch_uuid IS 'generado por el cliente';

-- OFF · sync_conflicts (company)
CREATE TABLE IF NOT EXISTS sync_conflicts (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  sync_batch_id uuid NOT NULL,
  operation_idempotency_key text NOT NULL,
  entity_type text NOT NULL,
  entity_id uuid,
  operation text NOT NULL CHECK (operation IN ('create', 'update', 'delete')),
  client_version integer,
  server_version integer,
  client_payload jsonb NOT NULL,
  server_snapshot jsonb,
  conflict_type text NOT NULL CHECK (conflict_type IN ('version_mismatch', 'deleted_on_server', 'validation_failed', 'permission_denied', 'duplicate', 'state_transition')),
  resolution text NOT NULL DEFAULT 'pending' CHECK (resolution IN ('pending', 'client_wins', 'server_wins', 'merged', 'discarded')),
  resolved_by uuid,
  resolved_at timestamptz,
  resolution_notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_sync_conflicts_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_sync_conflicts_1 CHECK (resolution = 'pending' OR resolved_at IS NOT NULL)
);
COMMENT ON TABLE sync_conflicts IS '[OFF] Conflicto de sincronización registrado (no se pisa; se resuelve)';

-- IAA · ai_requests (company)
CREATE TABLE IF NOT EXISTS ai_requests (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  user_id uuid NOT NULL,
  feature text NOT NULL CHECK (feature IN ('iperc_suggestion', 'investigation_guide', 'document_reading', 'training_quiz', 'report_classification', 'other')),
