  subject_type text,
  subject_id uuid,
  provider text NOT NULL,
  model text NOT NULL,
  prompt_template_code text,
  prompt_version text,
  input_redacted boolean NOT NULL DEFAULT true,
  contains_medical_data boolean NOT NULL DEFAULT false,
  input_summary text,
  input_tokens integer,
  output_tokens integer,
  latency_ms integer,
  quota_period text,
  idempotency_key text,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'completed', 'failed', 'blocked')),
  error_code text,
  completed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_ai_requests_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_ai_requests_1 CHECK (contains_medical_data = false)
);
COMMENT ON TABLE ai_requests IS '[IAA] Solicitud al asistente IA (entrada redactada, sin datos médicos)';
