-- IAA · ai_suggestions (company)
CREATE TABLE IF NOT EXISTS ai_suggestions (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  ai_request_id uuid NOT NULL,
  suggestion_type text NOT NULL,
  target_type text NOT NULL,
  target_id uuid,
  payload jsonb NOT NULL,
  rationale text,
  confidence numeric(4,3),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'partially_accepted', 'rejected', 'expired')),
  reviewed_by uuid,
  reviewed_at timestamptz,
  review_notes text,
  applied_entity_type text,
  applied_entity_ids uuid[],
  expires_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_ai_suggestions_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_ai_suggestions_1 CHECK (status IN ('pending','expired') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CONSTRAINT ck_ai_suggestions_2 CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1)
);
COMMENT ON TABLE ai_suggestions IS '[IAA] Sugerencia de la IA pendiente de revisión humana (la IA nunca aplica cambios)';

