-- AMB · environmental_aspects (company)
CREATE TABLE IF NOT EXISTS environmental_aspects (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  site_id uuid,
  area_id uuid,
  activity text NOT NULL,
  aspect text NOT NULL,
  impact text NOT NULL,
  condition text NOT NULL DEFAULT 'normal' CHECK (condition IN ('normal', 'abnormal', 'emergency')),
  legal_requirement_id uuid,
  severity_value integer,
  probability_value integer,
  significance_score integer GENERATED ALWAYS AS (severity_value * probability_value) STORED,
  is_significant boolean NOT NULL DEFAULT false,
  controls text,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'obsolete')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_environmental_aspects_company_id_id UNIQUE (company_id, id)
);
COMMENT ON TABLE environmental_aspects IS '[AMB] Aspecto e impacto ambiental (matriz de aspectos)';

-- AMB · waste_records (company)
CREATE TABLE IF NOT EXISTS waste_records (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  site_id uuid NOT NULL,
  waste_type text NOT NULL CHECK (waste_type IN ('municipal', 'non_hazardous', 'hazardous', 'recyclable', 'electronic', 'biocontaminated', 'other')),
  description text,
  quantity numeric(14,3) NOT NULL,
  unit text NOT NULL DEFAULT 'kg' CHECK (unit IN ('kg', 't', 'm3', 'l', 'units')),
  generated_on date NOT NULL,
  disposal_method text,
  eo_rs_name text,
  eo_rs_ruc char(11),
  manifest_number text,
  manifest_file_id uuid,
  status text NOT NULL DEFAULT 'stored' CHECK (status IN ('stored', 'transferred', 'disposed')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT uq_waste_records_company_id_id UNIQUE (company_id, id),
  CONSTRAINT ck_waste_records_1 CHECK (quantity > 0)
);
COMMENT ON TABLE waste_records IS '[AMB] Registro de generación y disposición de residuos';
COMMENT ON COLUMN waste_records.eo_rs_name IS 'empresa operadora de residuos sólidos';

-- API · api_clients (company)
CREATE TABLE IF NOT EXISTS api_clients (
