COMMENT ON TABLE webhooks IS '[API] Suscripción de webhook saliente a eventos';
COMMENT ON COLUMN webhooks.secret IS '[CIFRADO EN APLICACIÓN]';

-- API · webhook_deliveries (company)
CREATE TABLE IF NOT EXISTS webhook_deliveries (
  id uuid NOT NULL DEFAULT uuidv7(),
  company_id uuid NOT NULL,
  webhook_id uuid NOT NULL,
  event_code text NOT NULL,
  event_id uuid NOT NULL,
  payload_sha256 bytea,
  request_body jsonb,
  attempt integer NOT NULL DEFAULT 1,
  response_status integer,
  response_ms integer,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'delivered', 'failed', 'abandoned')),
  next_retry_at timestamptz,
  delivered_at timestamptz,
  error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
