);
COMMENT ON TABLE webhook_deliveries IS '[API] Intento de entrega de un webhook (sin datos sensibles en el cuerpo)';

-- WEB · site_settings (platform, definer)
CREATE TABLE IF NOT EXISTS site_settings (
  id uuid NOT NULL DEFAULT uuidv7(),
  singleton boolean NOT NULL DEFAULT true,
  legal_name text NOT NULL,
  trade_name text NOT NULL DEFAULT 'EscudoSST',
  ruc char(11) NOT NULL,
  legal_address text,
  primary_domain text DEFAULT 'escudosst.com',
  contact_email text,
  sales_email text,
  support_email text,
  privacy_email text,
  contact_phone text,
  whatsapp_number text,
  whatsapp_default_message text,
  blog_url text,
  show_latest_blog_posts boolean NOT NULL DEFAULT false,
  latest_blog_posts_count smallint NOT NULL DEFAULT 3,
  hero_video_urls jsonb NOT NULL DEFAULT '[]'::jsonb,
  announcement_bar jsonb,
  trust_badges_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  interactive_demo_url text,
  complaints_officer_name text,
  complaints_officer_email text,
  complaints_officer_phone text,
  social_links jsonb NOT NULL DEFAULT '{}'::jsonb,
  analytics_ids jsonb NOT NULL DEFAULT '{}'::jsonb,
  search_console_verification text,
  logo_file_id uuid,
  logo_dark_file_id uuid,
  favicon_file_id uuid,
  default_og_image_file_id uuid,
  brand_colors jsonb NOT NULL DEFAULT '{}'::jsonb,
  default_locale text NOT NULL DEFAULT 'es-PE',
  timezone text NOT NULL DEFAULT 'America/Lima',
  maintenance_mode boolean NOT NULL DEFAULT false,
  content_blocked_terms jsonb NOT NULL DEFAULT '[]'::jsonb,
  comparison_blocked_terms jsonb NOT NULL DEFAULT '[]'::jsonb,
  assessment_level_thresholds jsonb NOT NULL DEFAULT '{"low_max": 40, "medium_max": 70}'::jsonb,
  newsletter_confirm_token_validity integer NOT NULL DEFAULT 72,
  status_history_days integer NOT NULL DEFAULT 90,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_settings_1 CHECK (singleton),
  CONSTRAINT ck_site_settings_2 CHECK (jsonb_typeof(content_blocked_terms) = 'array' AND jsonb_typeof(comparison_blocked_terms) = 'array' AND jsonb_typeof(assessment_level_thresholds) = 'object'),
  CONSTRAINT ck_site_settings_3 CHECK (newsletter_confirm_token_validity BETWEEN 1 AND 720),
  CONSTRAINT ck_site_settings_4 CHECK (status_history_days BETWEEN 1 AND 730),
  CONSTRAINT ck_site_settings_5 CHECK (ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_site_settings_6 CHECK (primary_domain IS NULL OR primary_domain ~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$'),
  CONSTRAINT ck_site_settings_7 CHECK (jsonb_typeof(social_links) = 'object' AND jsonb_typeof(analytics_ids) = 'object'),
  CONSTRAINT ck_site_settings_8 CHECK (jsonb_typeof(hero_video_urls) = 'array' AND jsonb_typeof(trust_badges_json) = 'array'),
  CONSTRAINT ck_site_settings_9 CHECK (whatsapp_number IS NULL OR whatsapp_number ~ '^[0-9]{8,15}$'),
  CONSTRAINT ck_site_settings_10 CHECK (interactive_demo_url IS NULL OR interactive_demo_url ~ '^https://'),
  CONSTRAINT ck_site_settings_11 CHECK (blog_url IS NULL OR blog_url ~ '^https://'),
  CONSTRAINT ck_site_settings_12 CHECK (latest_blog_posts_count BETWEEN 1 AND 12)
);
COMMENT ON TABLE site_settings IS '[WEB] Configuración única del sitio público: titular y datos legales editables, contacto, responsable del Libro de Reclamaciones, redes, analítica y marca';
COMMENT ON COLUMN site_settings.singleton IS 'garantiza una sola fila';
COMMENT ON COLUMN site_settings.legal_name IS 'razón social del titular (valor inicial GRUPO DE SOLUCIONES CREATIVAS SAC; editable)';
COMMENT ON COLUMN site_settings.legal_address IS 'domicilio legal (por completar)';
COMMENT ON COLUMN site_settings.primary_domain IS 'dominio principal (editable desde el panel)';
COMMENT ON COLUMN site_settings.privacy_email IS 'canal para derechos ARCO (Ley 29733)';
COMMENT ON COLUMN site_settings.whatsapp_number IS 'número del botón flotante de WhatsApp (formato internacional, solo dígitos)';
COMMENT ON COLUMN site_settings.whatsapp_default_message IS 'mensaje predefinido general (cada página puede tener el suyo en site_pages.whatsapp_message)';
COMMENT ON COLUMN site_settings.blog_url IS 'URL del blog en WordPress (externo)';
COMMENT ON COLUMN site_settings.show_latest_blog_posts IS 'la portada muestra los últimos artículos leídos de la API REST pública de WordPress';
COMMENT ON COLUMN site_settings.hero_video_urls IS '[{kind: presentation|tutorial, provider: youtube|vimeo, url}]; también pueden ir como bloques de site_pages';
COMMENT ON COLUMN site_settings.announcement_bar IS 'barra superior de anuncio {text, url, is_active}';
COMMENT ON COLUMN site_settings.trust_badges_json IS 'sellos de confianza [{label, icon_file_id, url}] (solo los que se tengan de verdad)';
COMMENT ON COLUMN site_settings.interactive_demo_url IS 'demo interactiva en línea';
COMMENT ON COLUMN site_settings.complaints_officer_name IS 'responsable del Libro de Reclamaciones';
COMMENT ON COLUMN site_settings.social_links IS '{linkedin, facebook, instagram, youtube, tiktok, x}';
COMMENT ON COLUMN site_settings.analytics_ids IS '{ga4, gtm, meta_pixel, clarity}; se cargan solo con consentimiento de cookies';
COMMENT ON COLUMN site_settings.logo_file_id IS 'files.id del logo (B2)';
COMMENT ON COLUMN site_settings.brand_colors IS 'tokens de color de la versión marketing';
COMMENT ON COLUMN site_settings.content_blocked_terms IS 'expresiones no veraces que el panel impide publicar (RN-WEB-58): «homologada», «ISO 27001», «cero multas»…';
COMMENT ON COLUMN site_settings.comparison_blocked_terms IS 'términos prohibidos además en la página comparativa (marcas de terceros, precios) (RN-WEB-42)';
COMMENT ON COLUMN site_settings.assessment_level_thresholds IS 'umbrales por defecto de un cuestionario nuevo (cada versión guarda los suyos en level_thresholds_json)';
COMMENT ON COLUMN site_settings.newsletter_confirm_token_validity IS 'horas de validez del enlace de confirmación del boletín (RN-WEB-49)';
COMMENT ON COLUMN site_settings.status_history_days IS 'días de historial de incidentes resueltos en /estado (RN-WEB-53)';

-- WEB · site_pages (platform, definer)
CREATE TABLE IF NOT EXISTS site_pages (
  id uuid NOT NULL DEFAULT uuidv7(),
  slug text NOT NULL,
  page_type text NOT NULL CHECK (page_type IN ('home', 'product', 'sector', 'pricing', 'about', 'contact', 'landing', 'legal', 'comparison', 'campaign')),
  title text NOT NULL,
  summary text,
  blocks jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  published_snapshot jsonb,
  published_at timestamptz,
  published_by uuid,
  archived_at timestamptz,
  meta_title text,
  meta_description text,
  canonical_url text,
  og_image_file_id uuid,
  noindex boolean NOT NULL DEFAULT false,
  structured_data jsonb,
  sector_code text,
  whatsapp_message text,
  legal_document_id uuid,
  sort_order integer NOT NULL DEFAULT 0,
  version integer NOT NULL DEFAULT 1,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_pages_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*$'),
  CONSTRAINT ck_site_pages_2 CHECK (jsonb_typeof(blocks) = 'array'),
  CONSTRAINT ck_site_pages_3 CHECK (status <> 'published' OR (published_at IS NOT NULL AND published_snapshot IS NOT NULL)),
  CONSTRAINT ck_site_pages_4 CHECK (meta_title IS NULL OR length(meta_title) <= 70),
  CONSTRAINT ck_site_pages_5 CHECK (meta_description IS NULL OR length(meta_description) <= 170),
  CONSTRAINT ck_site_pages_6 CHECK (canonical_url IS NULL OR canonical_url ~ '^(https://|/)')
);
COMMENT ON TABLE site_pages IS '[WEB] Página del sitio por bloques (portada, producto, sector, planes, nosotros, contacto, landing, legal) con SEO; borrador → publicada → archivada';
COMMENT ON COLUMN site_pages.slug IS 'URL amigable (sin barra inicial; segmentos kebab-case)';
COMMENT ON COLUMN site_pages.page_type IS 'comparison: «EscudoSST vs Excel y papel» (no nombra competidores); campaign: landing de campaña /l/{slug} (solo por public_campaign_page, noindex por defecto)';
COMMENT ON COLUMN site_pages.blocks IS 'bloques del editor (borrador de trabajo)';
COMMENT ON COLUMN site_pages.published_snapshot IS 'copia publicada (título, bloques, SEO); es lo único que sale por la web pública';
COMMENT ON COLUMN site_pages.structured_data IS 'JSON-LD adicional (Organization, Product/Offer, FAQPage, BreadcrumbList)';
COMMENT ON COLUMN site_pages.sector_code IS 'páginas por sector para SEO';
COMMENT ON COLUMN site_pages.whatsapp_message IS 'mensaje predefinido del botón de WhatsApp en esta página (NULL = el general)';
COMMENT ON COLUMN site_pages.legal_document_id IS 'page_type legal';
COMMENT ON COLUMN site_pages.version IS 'control optimista del editor';

-- WEB · site_menus (platform)
CREATE TABLE IF NOT EXISTS site_menus (
  id uuid NOT NULL DEFAULT uuidv7(),
  location text NOT NULL CHECK (location IN ('header', 'footer', 'footer_legal', 'mobile')),
  name text NOT NULL,
  items jsonb NOT NULL DEFAULT '[]'::jsonb,
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_menus_1 CHECK (jsonb_typeof(items) = 'array')
);
COMMENT ON TABLE site_menus IS '[WEB] Menú del sitio por ubicación (cabecera, pie, pie legal, móvil) con ítems ordenados';
COMMENT ON COLUMN site_menus.items IS '[{label, page_slug | url, children: [...]}]';

-- WEB · site_products (platform)
CREATE TABLE IF NOT EXISTS site_products (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  description text,
  logo_file_id uuid,
  url text,
  sort_order integer NOT NULL DEFAULT 0,
  is_visible boolean NOT NULL DEFAULT true,
  description_editable boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_products_1 CHECK (url IS NULL OR url ~ '^https://')
);
COMMENT ON TABLE site_products IS '[WEB] Otros productos de GRUPO DE SOLUCIONES CREATIVAS que se muestran en la web (nombre, descripción, logo, enlace)';
COMMENT ON COLUMN site_products.logo_file_id IS 'files.id del logo (B2)';
COMMENT ON COLUMN site_products.url IS 'enlace editable (vacío hasta que el dueño lo defina; sin URLs inventadas)';
COMMENT ON COLUMN site_products.description_editable IS 'descripción provisional: el panel la rotula «descripción editable» hasta que el dueño la revise';

-- WEB · site_testimonials (platform)
CREATE TABLE IF NOT EXISTS site_testimonials (
  id uuid NOT NULL DEFAULT uuidv7(),
  author_name text NOT NULL,
  author_role text,
  company_name text,
  quote text NOT NULL,
  rating smallint,
  photo_file_id uuid,
  publication_consent boolean NOT NULL DEFAULT false,
  consent_evidence text,
  is_example boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'hidden')),
  approved_by uuid,
  approved_at timestamptz,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_testimonials_1 CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  CONSTRAINT ck_site_testimonials_2 CHECK (status <> 'approved' OR ((publication_consent OR is_example) AND approved_at IS NOT NULL))
);
COMMENT ON TABLE site_testimonials IS '[WEB] Comentario o testimonio de cliente, con consentimiento de publicación y aprobación (pendiente → aprobado / oculto)';
COMMENT ON COLUMN site_testimonials.author_name IS 'nombre o iniciales';
COMMENT ON COLUMN site_testimonials.author_role IS 'cargo';
COMMENT ON COLUMN site_testimonials.rating IS 'calificación opcional de 1 a 5';
COMMENT ON COLUMN site_testimonials.photo_file_id IS 'foto opcional (files.id)';
COMMENT ON COLUMN site_testimonials.publication_consent IS 'consentimiento del autor para publicar (Ley 29733)';
COMMENT ON COLUMN site_testimonials.consent_evidence IS 'cómo se obtuvo (correo, formulario, contrato)';
COMMENT ON COLUMN site_testimonials.is_example IS 'testimonio de demostración: la web lo rotula «ejemplo»';

-- WEB · site_faqs (platform)
CREATE TABLE IF NOT EXISTS site_faqs (
  id uuid NOT NULL DEFAULT uuidv7(),
  page_id uuid,
  topic text NOT NULL DEFAULT 'general' CHECK (topic IN ('general', 'plans', 'security', 'data_protection', 'product', 'billing', 'support')),
  question text NOT NULL,
  answer text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE site_faqs IS '[WEB] Pregunta frecuente por tema (general o de una página); se publica en FAQPage';
COMMENT ON COLUMN site_faqs.page_id IS 'NULL = general';

-- WEB · site_redirects (platform)
CREATE TABLE IF NOT EXISTS site_redirects (
  id uuid NOT NULL DEFAULT uuidv7(),
  source_path text NOT NULL,
  target_url text NOT NULL,
  status_code smallint NOT NULL DEFAULT 301,
  is_active boolean NOT NULL DEFAULT true,
  hit_count integer NOT NULL DEFAULT 0,
  last_hit_at timestamptz,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_redirects_1 CHECK (status_code IN (301, 302)),
  CONSTRAINT ck_site_redirects_2 CHECK (source_path ~ '^/[^ ]*$'),
  CONSTRAINT ck_site_redirects_3 CHECK (target_url ~ '^(https://|/)'),
  CONSTRAINT ck_site_redirects_4 CHECK (source_path <> target_url)
);
COMMENT ON TABLE site_redirects IS '[WEB] Redirección del sitio: 301 permanente o 302 temporal';
COMMENT ON COLUMN site_redirects.source_path IS 'ruta de origen con barra inicial';
COMMENT ON COLUMN site_redirects.target_url IS 'ruta interna o URL https';

-- WEB · legal_documents (platform, definer)
CREATE TABLE IF NOT EXISTS legal_documents (
  id uuid NOT NULL DEFAULT uuidv7(),
  doc_type text NOT NULL CHECK (doc_type IN ('terms', 'privacy', 'cookies', 'dpa', 'sla', 'complaints_info')),
  title text NOT NULL,
  slug text NOT NULL,
  current_version_id uuid,
  requires_acceptance_on_signup boolean NOT NULL DEFAULT false,
  applies_to text NOT NULL DEFAULT 'all' CHECK (applies_to IN ('all', 'customers', 'visitors')),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_legal_documents_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);
COMMENT ON TABLE legal_documents IS '[WEB] Documento legal del sitio (términos, privacidad, cookies, encargo de tratamiento, SLA, información del Libro de Reclamaciones) y su versión vigente';
COMMENT ON COLUMN legal_documents.current_version_id IS 'versión vigente publicada (NULL = sin versión publicada)';

-- WEB · legal_document_versions (platform, definer)
CREATE TABLE IF NOT EXISTS legal_document_versions (
  id uuid NOT NULL DEFAULT uuidv7(),
  legal_document_id uuid NOT NULL,
  version_number integer NOT NULL,
  version_label text NOT NULL,
  content text NOT NULL,
  content_sha256 bytea,
  summary_of_changes text,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved', 'published', 'superseded')),
  effective_from timestamptz,
  requires_reacceptance boolean NOT NULL DEFAULT false,
  legal_reviewed_by text,
  approved_by uuid,
  approved_at timestamptz,
  published_at timestamptz,
  published_by uuid,
  superseded_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_legal_document_versions_1 CHECK (version_number >= 1),
  CONSTRAINT ck_legal_document_versions_2 CHECK (status IN ('draft') OR (approved_by IS NOT NULL AND approved_at IS NOT NULL)),
  CONSTRAINT ck_legal_document_versions_3 CHECK (status NOT IN ('published', 'superseded') OR (published_at IS NOT NULL AND effective_from IS NOT NULL AND content_sha256 IS NOT NULL))
);
COMMENT ON TABLE legal_document_versions IS '[WEB] Versión de un documento legal; una vez publicada no se edita (un cambio es otra versión)';
COMMENT ON COLUMN legal_document_versions.version_label IS 'p. ej. 1.0';
COMMENT ON COLUMN legal_document_versions.content IS 'Markdown; textos legales a validar con abogado';
COMMENT ON COLUMN legal_document_versions.content_sha256 IS 'hash del contenido publicado';
COMMENT ON COLUMN legal_document_versions.effective_from IS 'vigente desde';
COMMENT ON COLUMN legal_document_versions.requires_reacceptance IS 'obliga a los usuarios a aceptar de nuevo al publicarse';
COMMENT ON COLUMN legal_document_versions.legal_reviewed_by IS 'abogado que validó el texto';

-- WEB · legal_acceptances (platform, imm)
CREATE TABLE IF NOT EXISTS legal_acceptances (
  id uuid NOT NULL DEFAULT uuidv7(),
  legal_document_version_id uuid NOT NULL,
  legal_document_id uuid NOT NULL,
  doc_type text NOT NULL CHECK (doc_type IN ('terms', 'privacy', 'cookies', 'dpa', 'sla', 'complaints_info')),
  version_label text NOT NULL,
  user_id uuid,
  email text,
  email_hash bytea,
  account_id uuid,
  company_id uuid,
  context text NOT NULL CHECK (context IN ('signup', 'reacceptance', 'checkout')),
  accepted_at timestamptz NOT NULL DEFAULT now(),
  ip_hash bytea,
  user_agent text,
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT ck_legal_acceptances_1 CHECK (user_id IS NOT NULL OR email IS NOT NULL)
);
COMMENT ON TABLE legal_acceptances IS '[WEB] Aceptación de una versión de documento legal (registro, re-aceptación o checkout); inalterable · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN legal_acceptances.email IS '[CIFRADO EN APLICACIÓN] cuando aún no hay usuario (registro autoservicio, checkout)';
COMMENT ON COLUMN legal_acceptances.email_hash IS 'HMAC del correo normalizado (búsqueda sin descifrar)';
COMMENT ON COLUMN legal_acceptances.company_id IS 'empresa a cuyo nombre se acepta, si aplica (no es tabla de empresa: lo escribe la plataforma)';

-- WEB · cookie_consents (platform, imm)
CREATE TABLE IF NOT EXISTS cookie_consents (
  id uuid NOT NULL DEFAULT uuidv7(),
  visitor_id uuid NOT NULL,
  categories jsonb NOT NULL,
  action text NOT NULL CHECK (action IN ('accept_all', 'reject_all', 'custom', 'withdraw')),
  policy_version_id uuid,
  policy_version_label text NOT NULL,
  user_id uuid,
  consented_at timestamptz NOT NULL DEFAULT now(),
  ip_hash bytea,
  user_agent text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT ck_cookie_consents_1 CHECK (jsonb_typeof(categories) = 'object' AND (categories ->> 'necessary') = 'true')
);
COMMENT ON TABLE cookie_consents IS '[WEB] Preferencias de cookies de un visitante anónimo por categoría; cada cambio es una fila nueva (inalterable) · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN cookie_consents.visitor_id IS 'id anónimo generado en el navegador (no es dato de identificación)';
COMMENT ON COLUMN cookie_consents.categories IS '{necessary: true, preferences, analytics, marketing}';
COMMENT ON COLUMN cookie_consents.user_id IS 'si el visitante tenía sesión';

-- WEB · consumer_complaints (platform, definer, nodelete)
CREATE TABLE IF NOT EXISTS consumer_complaints (
  id uuid NOT NULL DEFAULT uuidv7(),
  complaint_code text NOT NULL,
  complaint_year smallint NOT NULL,
  sequence_number integer NOT NULL,
  filed_at timestamptz NOT NULL DEFAULT now(),
  tracking_key_hash bytea NOT NULL,
  provider_legal_name text NOT NULL,
  provider_ruc char(11) NOT NULL,
  provider_address text,
  provider_snapshot jsonb NOT NULL,
  consumer_full_name text NOT NULL,
  consumer_document_type text NOT NULL CHECK (consumer_document_type IN ('DNI', 'CE', 'PASSPORT', 'RUC', 'OTHER')),
  consumer_document_number text NOT NULL,
  consumer_address text,
  consumer_email text NOT NULL,
  consumer_phone text,
  is_minor boolean NOT NULL DEFAULT false,
  guardian_full_name text,
  guardian_document_type text CHECK (guardian_document_type IN ('DNI', 'CE', 'PASSPORT', 'OTHER')),
  guardian_document_number text,
  guardian_email text,
  guardian_phone text,
  item_type text NOT NULL CHECK (item_type IN ('product', 'service')),
  item_description text NOT NULL,
  related_account_id uuid,
  amount_claimed numeric(14,2),
  currency char(3) NOT NULL DEFAULT 'PEN',
  complaint_type text NOT NULL CHECK (complaint_type IN ('claim', 'complaint')),
  detail text NOT NULL,
  consumer_request text NOT NULL,
  status text NOT NULL DEFAULT 'received' CHECK (status IN ('received', 'in_progress', 'extended', 'answered', 'closed')),
  response_business_days integer NOT NULL,
  response_due_on date NOT NULL,
  extended_until date,
  extension_reason text,
  assigned_to uuid,
  response_text text,
  response_channel text CHECK (response_channel IN ('email', 'address', 'other')),
  answered_at timestamptz,
  answered_by uuid,
  closed_at timestamptz,
  closed_by uuid,
  acknowledgment_sent_at timestamptz,
  retention_years integer NOT NULL,
  retain_until date NOT NULL,
  consumer_ip_hash bytea,
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT ck_consumer_complaints_1 CHECK (complaint_code ~ '^LR-[0-9]{4}-[0-9]{6}$'),
  CONSTRAINT ck_consumer_complaints_2 CHECK (sequence_number >= 1),
  CONSTRAINT ck_consumer_complaints_3 CHECK (NOT is_minor OR (guardian_full_name IS NOT NULL AND guardian_document_number IS NOT NULL)),
  CONSTRAINT ck_consumer_complaints_4 CHECK (amount_claimed IS NULL OR amount_claimed >= 0),
  CONSTRAINT ck_consumer_complaints_5 CHECK (status <> 'extended' OR (extended_until IS NOT NULL AND extension_reason IS NOT NULL)),
  CONSTRAINT ck_consumer_complaints_6 CHECK (extended_until IS NULL OR extended_until > response_due_on),
  CONSTRAINT ck_consumer_complaints_7 CHECK (status NOT IN ('answered', 'closed') OR (response_text IS NOT NULL AND answered_at IS NOT NULL)),
  CONSTRAINT ck_consumer_complaints_8 CHECK (status <> 'closed' OR closed_at IS NOT NULL),
  CONSTRAINT ck_consumer_complaints_9 CHECK (retain_until > response_due_on)
);
COMMENT ON TABLE consumer_complaints IS '[WEB] Hoja del Libro de Reclamaciones virtual de EscudoSST (Ley 29571, D.S. 011-2011-PCM); no se elimina; distinto del de las empresas clientes';
COMMENT ON COLUMN consumer_complaints.complaint_code IS 'código legible y correlativo anual: LR-AAAA-NNNNNN';
COMMENT ON COLUMN consumer_complaints.filed_at IS 'fecha y hora de registro (America/Lima en pantalla)';
COMMENT ON COLUMN consumer_complaints.tracking_key_hash IS 'sha256 de la clave de seguimiento enviada en la constancia (el código solo no basta para consultar)';
COMMENT ON COLUMN consumer_complaints.provider_legal_name IS 'copia de site_settings al registrar';
COMMENT ON COLUMN consumer_complaints.provider_snapshot IS 'copia completa de los datos del proveedor al registrar';
COMMENT ON COLUMN consumer_complaints.consumer_full_name IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.consumer_document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.consumer_address IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.consumer_email IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.consumer_phone IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.guardian_full_name IS '[CIFRADO EN APLICACIÓN] padre, madre o apoderado si el consumidor es menor de edad';
COMMENT ON COLUMN consumer_complaints.guardian_document_number IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.guardian_email IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.guardian_phone IS '[CIFRADO EN APLICACIÓN]';
COMMENT ON COLUMN consumer_complaints.item_type IS 'bien contratado';
COMMENT ON COLUMN consumer_complaints.related_account_id IS 'cuenta suscriptora relacionada, si se identifica';
COMMENT ON COLUMN consumer_complaints.amount_claimed IS 'monto reclamado (opcional)';
COMMENT ON COLUMN consumer_complaints.complaint_type IS 'claim = reclamo (disconformidad con el bien); complaint = queja (atención)';
COMMENT ON COLUMN consumer_complaints.consumer_request IS 'pedido del consumidor';
COMMENT ON COLUMN consumer_complaints.response_business_days IS 'plazo aplicado (parámetro legal vigente al registrar)';
COMMENT ON COLUMN consumer_complaints.response_due_on IS 'fecha límite calculada en días hábiles';
COMMENT ON COLUMN consumer_complaints.acknowledgment_sent_at IS 'constancia enviada al consumidor y al responsable';
COMMENT ON COLUMN consumer_complaints.retention_years IS 'parámetro legal vigente al registrar';
COMMENT ON COLUMN consumer_complaints.retain_until IS 'conservar hasta (no se elimina antes ni después: se archiva)';

-- WEB · complaint_events (platform, imm)
CREATE TABLE IF NOT EXISTS complaint_events (
  id uuid NOT NULL DEFAULT uuidv7(),
  consumer_complaint_id uuid NOT NULL,
  event_type text NOT NULL CHECK (event_type IN ('registered', 'acknowledgment_sent', 'officer_notified', 'assigned', 'in_progress', 'extended', 'answered', 'response_sent', 'closed', 'note')),
  from_status text,
  to_status text,
  reason text,
  details jsonb,
  actor_type text NOT NULL DEFAULT 'user' CHECK (actor_type IN ('user', 'consumer', 'system')),
  actor_user_id uuid,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id),
  CONSTRAINT ck_complaint_events_1 CHECK (event_type <> 'extended' OR reason IS NOT NULL),
  CONSTRAINT ck_complaint_events_2 CHECK (actor_type <> 'user' OR actor_user_id IS NOT NULL)
);
COMMENT ON TABLE complaint_events IS '[WEB] Historial inalterable de cada hoja de reclamación (registro, constancia, asignación, prórroga, respuesta, cierre) · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN complaint_events.reason IS 'obligatorio en la prórroga';

-- WEB · demo_requests (platform)
CREATE TABLE IF NOT EXISTS demo_requests (
  id uuid NOT NULL DEFAULT uuidv7(),
  request_type text NOT NULL DEFAULT 'demo' CHECK (request_type IN ('demo', 'contact', 'quote')),
  full_name text NOT NULL,
  company_name text NOT NULL,
  ruc char(11),
  job_title text,
  email text NOT NULL,
  phone text,
  headcount integer,
  economic_sector text CHECK (economic_sector IN ('construction', 'mining', 'agroindustry', 'manufacturing', 'retail', 'services', 'office', 'health', 'education', 'transport', 'energy', 'other')),
  interest_plan_code text CHECK (interest_plan_code IN ('E', 'P', 'C', 'K')),
  message text,
  privacy_consent boolean NOT NULL,
  privacy_version_id uuid,
  marketing_consent boolean NOT NULL DEFAULT false,
  source_page text,
  utm jsonb NOT NULL DEFAULT '{}'::jsonb,
  referrer text,
  status text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'contacted', 'demo_scheduled', 'converted', 'discarded')),
  assigned_to uuid,
  contacted_at timestamptz,
  demo_scheduled_at timestamptz,
  converted_account_id uuid,
  discard_reason text,
  notes text,
  ip_hash bytea,
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_demo_requests_1 CHECK (privacy_consent),
  CONSTRAINT ck_demo_requests_2 CHECK (ruc IS NULL OR ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_demo_requests_3 CHECK (headcount IS NULL OR headcount >= 1),
  CONSTRAINT ck_demo_requests_4 CHECK (status <> 'demo_scheduled' OR demo_scheduled_at IS NOT NULL),
  CONSTRAINT ck_demo_requests_5 CHECK (status <> 'discarded' OR discard_reason IS NOT NULL),
  CONSTRAINT ck_demo_requests_6 CHECK (jsonb_typeof(utm) = 'object')
);
COMMENT ON TABLE demo_requests IS '[WEB] Solicitud desde los formularios del sitio («Agenda una demo», contacto, cotización) con estado y responsable comercial';
COMMENT ON COLUMN demo_requests.headcount IS 'número de trabajadores declarado';
COMMENT ON COLUMN demo_requests.privacy_consent IS 'aceptó la política de privacidad (obligatorio)';
COMMENT ON COLUMN demo_requests.utm IS 'utm_source, utm_medium, utm_campaign, utm_term, utm_content';

-- WEB · marketing_leads (platform)
CREATE TABLE IF NOT EXISTS marketing_leads (
  id uuid NOT NULL DEFAULT uuidv7(),
  email text NOT NULL,
  full_name text,
  company_name text,
  ruc char(11),
  phone text,
  sector text CHECK (sector IN ('construction', 'mining', 'agroindustry', 'manufacturing', 'retail', 'services', 'office', 'health', 'education', 'transport', 'energy', 'other')),
  workers_range text CHECK (workers_range IN ('1-10', '11-20', '21-50', '51-100', '101-250', '251-500', '501-1000', '1000+')),
  source text NOT NULL CHECK (source IN ('fine_calculator', 'self_assessment', 'resource', 'partner', 'newsletter', 'demo', 'contact', 'savings_calculator', 'webinar', 'campaign', 'popup')),
  last_source text CHECK (last_source IN ('fine_calculator', 'self_assessment', 'resource', 'partner', 'newsletter', 'demo', 'contact', 'savings_calculator', 'webinar', 'campaign', 'popup')),
  last_activity_at timestamptz NOT NULL DEFAULT now(),
  utm_source text,
  utm_medium text,
  utm_campaign text,
  privacy_consent boolean NOT NULL DEFAULT false,
  privacy_version_id uuid,
  marketing_consent boolean NOT NULL DEFAULT false,
  marketing_consent_at timestamptz,
  marketing_consent_withdrawn_at timestamptz,
  status text NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'contacted', 'qualified', 'converted', 'discarded')),
  assigned_to uuid,
  demo_request_id uuid,
  account_id uuid,
  discard_reason text,
  notes text,
  retain_until date,
  ip_hash bytea,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_marketing_leads_1 CHECK (email = lower(email) AND email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  CONSTRAINT ck_marketing_leads_2 CHECK (ruc IS NULL OR ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_marketing_leads_3 CHECK (NOT marketing_consent OR marketing_consent_at IS NOT NULL),
  CONSTRAINT ck_marketing_leads_4 CHECK (status <> 'converted' OR account_id IS NOT NULL OR demo_request_id IS NOT NULL),
  CONSTRAINT ck_marketing_leads_5 CHECK (status <> 'discarded' OR discard_reason IS NOT NULL)
);
COMMENT ON TABLE marketing_leads IS '[WEB] Lead de los formularios de captación (calculadora, autodiagnóstico, recursos, partners, boletín, demo, contacto) con origen, UTM, consentimiento comercial separado, estado y responsable';
COMMENT ON COLUMN marketing_leads.email IS 'correo normalizado en minúsculas; un lead por correo (se actualiza en cada formulario)';
COMMENT ON COLUMN marketing_leads.source IS 'primer origen (no cambia)';
COMMENT ON COLUMN marketing_leads.last_source IS 'origen de la última interacción';
COMMENT ON COLUMN marketing_leads.privacy_consent IS 'toma de conocimiento de la política de privacidad (obligatoria en todo formulario)';
COMMENT ON COLUMN marketing_leads.privacy_version_id IS 'versión de la política vigente al registrar';
COMMENT ON COLUMN marketing_leads.marketing_consent IS 'consentimiento de comunicaciones comerciales, separado del de privacidad (Ley 29733)';
COMMENT ON COLUMN marketing_leads.marketing_consent_at IS 'cuándo se otorgó; se registra aparte y no se presume';
COMMENT ON COLUMN marketing_leads.marketing_consent_withdrawn_at IS 'retiro (baja del boletín o pedido del titular)';
COMMENT ON COLUMN marketing_leads.demo_request_id IS 'solicitud de demo o contacto asociada (bandeja única)';
COMMENT ON COLUMN marketing_leads.account_id IS 'cuenta creada al convertirse';
COMMENT ON COLUMN marketing_leads.retain_until IS 'fin de conservación sin conversión (parámetro web.lead_retention_months)';

-- WEB · fine_calculations (platform)
CREATE TABLE IF NOT EXISTS fine_calculations (
  id uuid NOT NULL DEFAULT uuidv7(),
  lead_id uuid,
  company_size text NOT NULL CHECK (company_size IN ('micro', 'small', 'non_mype')),
  affected_workers integer NOT NULL,
  severity text NOT NULL CHECK (severity IN ('minor', 'serious', 'very_serious')),
  infraction_code text,
  uit_value numeric(12,2) NOT NULL,
  result_min_uit numeric(12,4) NOT NULL,
  result_max_uit numeric(12,4) NOT NULL,
  result_min_pen numeric(14,2) NOT NULL,
  result_max_pen numeric(14,2) NOT NULL,
  parameters_snapshot_json jsonb NOT NULL,
  source_page text,
  ip_hash bytea,
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_fine_calculations_1 CHECK (affected_workers >= 1),
  CONSTRAINT ck_fine_calculations_2 CHECK (uit_value > 0),
  CONSTRAINT ck_fine_calculations_3 CHECK (result_min_uit >= 0 AND result_max_uit >= result_min_uit),
  CONSTRAINT ck_fine_calculations_4 CHECK (result_min_pen >= 0 AND result_max_pen >= result_min_pen),
  CONSTRAINT ck_fine_calculations_5 CHECK (jsonb_typeof(parameters_snapshot_json) = 'object')
);
COMMENT ON TABLE fine_calculations IS '[WEB] Cálculo referencial de multa SUNAFIL hecho en la web, con copia de los parámetros legales vigentes usados (no es asesoría legal)';
COMMENT ON COLUMN fine_calculations.lead_id IS 'si el visitante pidió el resultado completo por correo';
COMMENT ON COLUMN fine_calculations.severity IS 'leve, grave, muy grave';
COMMENT ON COLUMN fine_calculations.infraction_code IS 'infracción concreta elegida (opcional, referencial)';
COMMENT ON COLUMN fine_calculations.uit_value IS 'UIT vigente al calcular (parámetro web.uit_value)';
COMMENT ON COLUMN fine_calculations.parameters_snapshot_json IS 'copia de web.uit_value, la tabla aplicada y el descuento por subsanación con su vigencia y to_confirm';

-- WEB · assessment_questionnaires (platform, noversion)
CREATE TABLE IF NOT EXISTS assessment_questionnaires (
  id uuid NOT NULL DEFAULT uuidv7(),
  title text NOT NULL,
  version integer NOT NULL DEFAULT 1,
  description text,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  to_validate boolean NOT NULL DEFAULT true,
  level_thresholds_json jsonb NOT NULL DEFAULT '{"low_max": 40, "medium_max": 70}'::jsonb,
  published_at timestamptz,
  published_by uuid,
  archived_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_assessment_questionnaires_1 CHECK (version >= 1),
  CONSTRAINT ck_assessment_questionnaires_2 CHECK (status <> 'published' OR published_at IS NOT NULL),
  CONSTRAINT ck_assessment_questionnaires_3 CHECK (jsonb_typeof(level_thresholds_json) = 'object')
);
COMMENT ON TABLE assessment_questionnaires IS '[WEB] Cuestionario del autodiagnóstico gratuito Ley 29783 (versionado; uno publicado a la vez)';
COMMENT ON COLUMN assessment_questionnaires.to_validate IS 'preguntas a validar por especialista SST; la web lo rotula mientras sea true';
COMMENT ON COLUMN assessment_questionnaires.level_thresholds_json IS '% de puntaje: ≤ low_max = bajo, ≤ medium_max = medio, mayor = alto (configurable, no legal)';

-- WEB · assessment_questions (platform)
CREATE TABLE IF NOT EXISTS assessment_questions (
  id uuid NOT NULL DEFAULT uuidv7(),
  questionnaire_id uuid NOT NULL,
  section text NOT NULL,
  question_text text NOT NULL,
  help_text text,
  weight numeric(6,2) NOT NULL DEFAULT 1,
  answer_type text NOT NULL DEFAULT 'yes_partial_no' CHECK (answer_type IN ('yes_no', 'yes_partial_no')),
  sort_order integer NOT NULL DEFAULT 0,
  legal_reference text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_assessment_questions_1 CHECK (weight > 0)
);
COMMENT ON TABLE assessment_questions IS '[WEB] Pregunta del autodiagnóstico por sección, con peso y referencia legal';
COMMENT ON COLUMN assessment_questions.section IS 'p. ej. Política y organización, IPERC, Capacitación, Registros, Salud ocupacional';
COMMENT ON COLUMN assessment_questions.answer_type IS 'sí = 100 %, parcial = 50 %, no = 0 % del peso';
COMMENT ON COLUMN assessment_questions.legal_reference IS 'artículo de la Ley 29783 o del D.S. 005-2012-TR (a validar)';

-- WEB · assessment_submissions (platform)
CREATE TABLE IF NOT EXISTS assessment_submissions (
  id uuid NOT NULL DEFAULT uuidv7(),
  questionnaire_id uuid NOT NULL,
  lead_id uuid,
  answers_json jsonb NOT NULL,
  score_total numeric(5,2) NOT NULL,
  score_by_section_json jsonb NOT NULL,
  level text NOT NULL CHECK (level IN ('low', 'medium', 'high')),
  report_file_id uuid,
  report_sent_at timestamptz,
  source_page text,
  ip_hash bytea,
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_assessment_submissions_1 CHECK (score_total BETWEEN 0 AND 100),
  CONSTRAINT ck_assessment_submissions_2 CHECK (jsonb_typeof(answers_json) = 'object' AND jsonb_typeof(score_by_section_json) = 'object')
);
COMMENT ON TABLE assessment_submissions IS '[WEB] Respuesta de un visitante al autodiagnóstico: puntaje total y por sección, nivel e informe PDF';
COMMENT ON COLUMN assessment_submissions.answers_json IS '{question_id: yes|partial|no}';
COMMENT ON COLUMN assessment_submissions.score_total IS '% de 0 a 100';
COMMENT ON COLUMN assessment_submissions.score_by_section_json IS '{sección: %}';
COMMENT ON COLUMN assessment_submissions.report_file_id IS 'PDF generado en B2 (bucket de plataforma), enviado por correo';

-- WEB · resource_items (platform)
CREATE TABLE IF NOT EXISTS resource_items (
  id uuid NOT NULL DEFAULT uuidv7(),
  title text NOT NULL,
  slug text NOT NULL,
  description text,
  resource_type text NOT NULL CHECK (resource_type IN ('template', 'guide', 'checklist', 'format')),
  sector text CHECK (sector IN ('construction', 'mining', 'agroindustry', 'manufacturing', 'retail', 'services', 'office', 'health', 'education', 'transport', 'energy', 'other')),
  file_id uuid,
  cover_file_id uuid,
  is_gated boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  published_at timestamptz,
  download_count integer NOT NULL DEFAULT 0,
  sort_order integer NOT NULL DEFAULT 0,
  seo_title text,
  seo_description text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_resource_items_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT ck_resource_items_2 CHECK (status <> 'published' OR (published_at IS NOT NULL AND file_id IS NOT NULL)),
  CONSTRAINT ck_resource_items_3 CHECK (download_count >= 0)
);
COMMENT ON TABLE resource_items IS '[WEB] Recurso descargable de la biblioteca (plantillas y formatos SST); libre o a cambio de datos (gated); archivo en B2 con URL firmada';
COMMENT ON COLUMN resource_items.file_id IS 'objeto en B2 (bucket de plataforma); la descarga sale por URL firmada de corta duración';
COMMENT ON COLUMN resource_items.is_gated IS 'exige datos (lead) para descargar';

-- WEB · resource_downloads (platform, imm)
CREATE TABLE IF NOT EXISTS resource_downloads (
  id uuid NOT NULL DEFAULT uuidv7(),
  resource_id uuid NOT NULL,
  lead_id uuid,
  ip_hash bytea,
  downloaded_at timestamptz NOT NULL DEFAULT now(),
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id)
);
COMMENT ON TABLE resource_downloads IS '[WEB] Descarga registrada de un recurso (inalterable) · INALTERABLE: solo INSERT.';

-- WEB · success_stories (platform)
CREATE TABLE IF NOT EXISTS success_stories (
  id uuid NOT NULL DEFAULT uuidv7(),
  slug text NOT NULL,
  title text,
  client_name text NOT NULL,
  sector text CHECK (sector IN ('construction', 'mining', 'agroindustry', 'manufacturing', 'retail', 'services', 'office', 'health', 'education', 'transport', 'energy', 'other')),
  logo_file_id uuid,
  challenge text,
  solution text,
  results_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  quote text,
  project_year smallint,
  modules_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  consent_file_id uuid,
  is_example boolean NOT NULL DEFAULT false,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'approved', 'published', 'hidden')),
  approved_by uuid,
  approved_at timestamptz,
  published_at timestamptz,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_success_stories_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT ck_success_stories_2 CHECK (jsonb_typeof(results_json) = 'array'),
  CONSTRAINT ck_success_stories_3 CHECK (status NOT IN ('approved', 'published') OR ((consent_file_id IS NOT NULL OR is_example) AND approved_by IS NOT NULL AND approved_at IS NOT NULL)),
  CONSTRAINT ck_success_stories_4 CHECK (status <> 'published' OR published_at IS NOT NULL),
  CONSTRAINT ck_success_stories_5 CHECK (project_year IS NULL OR project_year BETWEEN 2000 AND 2100),
  CONSTRAINT ck_success_stories_6 CHECK (jsonb_typeof(modules_json) = 'array')
);
COMMENT ON TABLE success_stories IS '[WEB] Caso de éxito con sector, reto, solución y resultados; solo con consentimiento escrito del cliente (archivo) y aprobación; «Ejemplo» mientras no haya reales';
COMMENT ON COLUMN success_stories.results_json IS '[{label, value}] resultados medibles declarados por el cliente';
COMMENT ON COLUMN success_stories.project_year IS 'año del proyecto (portafolio v1.5)';
COMMENT ON COLUMN success_stories.modules_json IS 'códigos de módulos o servicios usados, p. ej. ["IPR","CAP"]';
COMMENT ON COLUMN success_stories.consent_file_id IS 'consentimiento escrito del cliente (archivo en B2)';
COMMENT ON COLUMN success_stories.is_example IS 'caso de demostración: la web lo rotula «Ejemplo»';

-- WEB · help_categories (platform)
