  title text NOT NULL,
  slug text NOT NULL,
  body text NOT NULL,
  video_url text,
  screen_code text,
  related_article_ids uuid[] NOT NULL DEFAULT '{}'::uuid[],
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
