);
COMMENT ON TABLE help_articles IS '[WEB] Artículo del centro de ayuda (texto, video, relacionados) con ayuda contextual por pantalla (screen_code)';
COMMENT ON COLUMN help_articles.body IS 'Markdown';
COMMENT ON COLUMN help_articles.video_url IS 'YouTube o Vimeo';
COMMENT ON COLUMN help_articles.screen_code IS 'código de pantalla de la app para la ayuda contextual (GET /me/help?screen_code=)';

-- WEB · help_article_feedback (platform, imm)
CREATE TABLE IF NOT EXISTS help_article_feedback (
