COMMENT ON TABLE help_article_feedback IS '[WEB] Voto «¿Te sirvió?» de un artículo de ayuda (inalterable) · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN help_article_feedback.account_id IS 'si el voto viene desde la app con sesión';

-- WEB · partner_applications (platform)
CREATE TABLE IF NOT EXISTS partner_applications (
  id uuid NOT NULL DEFAULT uuidv7(),
  lead_id uuid NOT NULL,
  partner_type text NOT NULL CHECK (partner_type IN ('consultancy', 'independent', 'institute')),
  company_name text,
  ruc char(11),
  website text,
  message text,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  reviewed_by uuid,
  reviewed_at timestamptz,
  rejection_reason text,
  notes text,
  ip_hash bytea,
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_partner_applications_1 CHECK (ruc IS NULL OR ruc ~ '^(10|15|17|20)[0-9]{9}$'),
  CONSTRAINT ck_partner_applications_2 CHECK (website IS NULL OR website ~ '^https?://'),
  CONSTRAINT ck_partner_applications_3 CHECK (status = 'pending' OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CONSTRAINT ck_partner_applications_4 CHECK (status <> 'rejected' OR rejection_reason IS NOT NULL)
);
COMMENT ON TABLE partner_applications IS '[WEB] Solicitud al programa de partners (consultoras, independientes, institutos) con revisión';
COMMENT ON COLUMN partner_applications.lead_id IS 'datos de contacto del solicitante';

-- WEB · referral_codes (platform)
CREATE TABLE IF NOT EXISTS referral_codes (
  id uuid NOT NULL DEFAULT uuidv7(),
  partner_application_id uuid NOT NULL,
  code text NOT NULL,
  reward_rule_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  is_active boolean NOT NULL DEFAULT true,
  deactivated_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_referral_codes_1 CHECK (code ~ '^[A-Z0-9]+(-[A-Z0-9]+)*$' AND length(code) BETWEEN 4 AND 32),
  CONSTRAINT ck_referral_codes_2 CHECK (jsonb_typeof(reward_rule_json) = 'object')
);
COMMENT ON TABLE referral_codes IS '[WEB] Código de referido de un partner aprobado; la recompensa es una regla configurable (sin montos sembrados)';
COMMENT ON COLUMN referral_codes.code IS 'único en la plataforma (mayúsculas, dígitos y guiones)';
COMMENT ON COLUMN referral_codes.reward_rule_json IS '{type, value, conditions}: tipo y valor por definir por el dueño';

-- WEB · referrals (platform)
CREATE TABLE IF NOT EXISTS referrals (
  id uuid NOT NULL DEFAULT uuidv7(),
  referral_code_id uuid NOT NULL,
  lead_id uuid,
  account_id uuid,
  status text NOT NULL DEFAULT 'registered' CHECK (status IN ('registered', 'trial', 'customer', 'cancelled')),
  converted_at timestamptz,
  cancelled_reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_referrals_1 CHECK (lead_id IS NOT NULL OR account_id IS NOT NULL),
  CONSTRAINT ck_referrals_2 CHECK (status <> 'customer' OR (converted_at IS NOT NULL AND account_id IS NOT NULL))
);
COMMENT ON TABLE referrals IS '[WEB] Referido de un partner: registrado → en prueba → cliente (o cancelado)';

-- WEB · newsletter_subscribers (platform)
CREATE TABLE IF NOT EXISTS newsletter_subscribers (
  id uuid NOT NULL DEFAULT uuidv7(),
  email text NOT NULL,
  topics_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'confirmed', 'unsubscribed')),
  confirm_token_hash bytea,
  confirm_sent_at timestamptz,
  unsubscribe_token_hash bytea NOT NULL,
  confirmed_at timestamptz,
  unsubscribed_at timestamptz,
  lead_id uuid,
  consent_ip_hash bytea,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_newsletter_subscribers_1 CHECK (email = lower(email) AND email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  CONSTRAINT ck_newsletter_subscribers_2 CHECK (jsonb_typeof(topics_json) = 'array'),
  CONSTRAINT ck_newsletter_subscribers_3 CHECK (status <> 'confirmed' OR confirmed_at IS NOT NULL),
  CONSTRAINT ck_newsletter_subscribers_4 CHECK (status <> 'unsubscribed' OR unsubscribed_at IS NOT NULL)
);
COMMENT ON TABLE newsletter_subscribers IS '[WEB] Suscriptor del boletín normativo SST y de los avisos del estado del servicio (doble confirmación, baja con un clic; tokens solo como hash)';
COMMENT ON COLUMN newsletter_subscribers.email IS 'único; minúsculas';
COMMENT ON COLUMN newsletter_subscribers.topics_json IS '["regulations","sunafil","sectors","status"]';
COMMENT ON COLUMN newsletter_subscribers.confirm_token_hash IS 'sha256 del token del correo de confirmación (el token no se guarda)';
COMMENT ON COLUMN newsletter_subscribers.unsubscribe_token_hash IS 'sha256 del token de baja con un clic';

-- WEB · newsletter_issues (platform)
CREATE TABLE IF NOT EXISTS newsletter_issues (
  id uuid NOT NULL DEFAULT uuidv7(),
  subject text NOT NULL,
  slug text NOT NULL,
  preheader text,
  body text NOT NULL,
  topics_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'scheduled', 'sent')),
  scheduled_at timestamptz,
  sent_at timestamptz,
  sent_by uuid,
  provider_campaign_id text,
  recipients_count integer NOT NULL DEFAULT 0,
  opens_count integer NOT NULL DEFAULT 0,
  clicks_count integer NOT NULL DEFAULT 0,
  unsubscribes_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_newsletter_issues_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT ck_newsletter_issues_2 CHECK (jsonb_typeof(topics_json) = 'array'),
  CONSTRAINT ck_newsletter_issues_3 CHECK (status <> 'scheduled' OR scheduled_at IS NOT NULL),
  CONSTRAINT ck_newsletter_issues_4 CHECK (status <> 'sent' OR sent_at IS NOT NULL),
  CONSTRAINT ck_newsletter_issues_5 CHECK (recipients_count >= 0 AND opens_count >= 0 AND clicks_count >= 0 AND unsubscribes_count >= 0)
);
COMMENT ON TABLE newsletter_issues IS '[WEB] Edición del boletín redactada en el panel y enviada por Elastic Email (proveedor detrás de interfaz) con métricas básicas';
COMMENT ON COLUMN newsletter_issues.body IS 'Markdown/HTML seguro';
COMMENT ON COLUMN newsletter_issues.provider_campaign_id IS 'id de la campaña en el proveedor de correo';

-- WEB · subprocessors (platform)
CREATE TABLE IF NOT EXISTS subprocessors (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  purpose text NOT NULL,
  country char(2) NOT NULL,
  data_categories text NOT NULL,
  transfer_basis text,
  website text,
  to_validate boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'inactive')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_subprocessors_1 CHECK (country ~ '^[A-Z]{2}$'),
  CONSTRAINT ck_subprocessors_2 CHECK (website IS NULL OR website ~ '^https://')
);
COMMENT ON TABLE subprocessors IS '[WEB] Subencargado del tratamiento (Ley 29733): proveedor, finalidad, país y datos tratados; transferencia internacional';
COMMENT ON COLUMN subprocessors.country IS 'ISO 3166-1 alfa-2 donde se tratan los datos';
COMMENT ON COLUMN subprocessors.data_categories IS 'categorías de datos tratados';
COMMENT ON COLUMN subprocessors.transfer_basis IS 'base de la transferencia internacional (a validar con abogado)';
COMMENT ON COLUMN subprocessors.to_validate IS 'datos a validar (país, finalidad, contrato) antes de publicarlos como definitivos';

-- WEB · status_components (platform)
CREATE TABLE IF NOT EXISTS status_components (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  code text NOT NULL,
  description text,
  current_status text NOT NULL DEFAULT 'operational' CHECK (current_status IN ('operational', 'degraded', 'partial_outage', 'major_outage', 'maintenance')),
  sort_order integer NOT NULL DEFAULT 0,
  is_visible boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_status_components_1 CHECK (code ~ '^[a-z0-9]+(_[a-z0-9]+)*$')
);
COMMENT ON TABLE status_components IS '[WEB] Componente de la página de estado del servicio (app, API, base médica, correo, WhatsApp, pasarela)';

-- WEB · status_incidents (platform)
CREATE TABLE IF NOT EXISTS status_incidents (
  id uuid NOT NULL DEFAULT uuidv7(),
  title text NOT NULL,
  impact text NOT NULL CHECK (impact IN ('minor', 'major', 'critical', 'maintenance')),
  status text NOT NULL DEFAULT 'investigating' CHECK (status IN ('investigating', 'identified', 'monitoring', 'resolved')),
  started_at timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz,
  component_ids_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  published_at timestamptz,
  published_by uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_status_incidents_1 CHECK (jsonb_typeof(component_ids_json) = 'array'),
  CONSTRAINT ck_status_incidents_2 CHECK (status <> 'resolved' OR resolved_at IS NOT NULL),
  CONSTRAINT ck_status_incidents_3 CHECK (resolved_at IS NULL OR resolved_at >= started_at)
);
COMMENT ON TABLE status_incidents IS '[WEB] Incidente o mantenimiento del servicio con componentes afectados; sale en /estado solo al publicarse';
COMMENT ON COLUMN status_incidents.component_ids_json IS 'ids de status_components afectados';
COMMENT ON COLUMN status_incidents.published_at IS 'NULL = borrador interno (no sale en la página de estado)';

-- WEB · status_incident_updates (platform, imm)
CREATE TABLE IF NOT EXISTS status_incident_updates (
  id uuid NOT NULL DEFAULT uuidv7(),
  incident_id uuid NOT NULL,
  status text NOT NULL CHECK (status IN ('investigating', 'identified', 'monitoring', 'resolved')),
  message text NOT NULL,
  published_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id)
);
COMMENT ON TABLE status_incident_updates IS '[WEB] Actualización publicada de un incidente (inalterable) · INALTERABLE: solo INSERT.';

-- WEB · site_media (platform)
CREATE TABLE IF NOT EXISTS site_media (
  id uuid NOT NULL DEFAULT uuidv7(),
  file_id uuid NOT NULL,
  kind text NOT NULL CHECK (kind IN ('image', 'video', 'document', 'icon')),
  title text NOT NULL,
  alt_text text,
  width integer,
  height integer,
  size_bytes bigint,
  folder text,
  tags_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  is_example boolean NOT NULL DEFAULT false,
  usage_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_media_1 CHECK (kind <> 'image' OR nullif(trim(alt_text), '') IS NOT NULL),
  CONSTRAINT ck_site_media_2 CHECK (width IS NULL OR width > 0),
  CONSTRAINT ck_site_media_3 CHECK (height IS NULL OR height > 0),
  CONSTRAINT ck_site_media_4 CHECK (size_bytes IS NULL OR size_bytes >= 0),
  CONSTRAINT ck_site_media_5 CHECK (usage_count >= 0),
  CONSTRAINT ck_site_media_6 CHECK (jsonb_typeof(tags_json) = 'array')
);
COMMENT ON TABLE site_media IS '[WEB] Biblioteca de medios del sitio (imágenes, videos, documentos, íconos en B2): texto alternativo obligatorio en imágenes; reemplazar el archivo conserva el id (no rompe enlaces)';
COMMENT ON COLUMN site_media.file_id IS 'objeto en B2 (bucket de plataforma); reemplazar = cambiar file_id en la misma fila';
COMMENT ON COLUMN site_media.alt_text IS 'obligatorio en imágenes (accesibilidad)';
COMMENT ON COLUMN site_media.folder IS 'carpeta lógica (p. ej. portada/casos)';
COMMENT ON COLUMN site_media.is_example IS 'imagen o ilustración de ejemplo: la web la rotula «Ejemplo» si corresponde';
COMMENT ON COLUMN site_media.usage_count IS 'referencias conocidas (lo recalcula web_media_usages)';

-- WEB · site_analytics_daily (platform)
CREATE TABLE IF NOT EXISTS site_analytics_daily (
  id uuid NOT NULL DEFAULT uuidv7(),
  day date NOT NULL,
  path text NOT NULL,
  source text NOT NULL CHECK (source IN ('organic', 'direct', 'social', 'referral', 'campaign', 'email')),
  device text NOT NULL CHECK (device IN ('desktop', 'mobile', 'tablet')),
  visits integer NOT NULL DEFAULT 0,
  unique_visitors integer NOT NULL DEFAULT 0,
  avg_seconds integer,
  bounces integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_analytics_daily_1 CHECK (visits >= 0 AND unique_visitors >= 0 AND bounces >= 0 AND unique_visitors <= visits AND bounces <= visits),
  CONSTRAINT ck_site_analytics_daily_2 CHECK (avg_seconds IS NULL OR avg_seconds >= 0)
);
COMMENT ON TABLE site_analytics_daily IS '[WEB] Métricas propias agregadas por día, ruta, fuente y dispositivo (solo de visitantes con consentimiento analítico; sin IP ni huellas)';
COMMENT ON COLUMN site_analytics_daily.day IS 'día en America/Lima';
COMMENT ON COLUMN site_analytics_daily.unique_visitors IS 'sesiones distintas (session_hash rotado a diario)';
COMMENT ON COLUMN site_analytics_daily.avg_seconds IS 'tiempo medio en página (NULL si no se mide)';

-- WEB · site_events (platform, imm, partition)
CREATE TABLE IF NOT EXISTS site_events (
  id uuid NOT NULL DEFAULT uuidv7(),
  occurred_at timestamptz NOT NULL DEFAULT now(),
  event_type text NOT NULL CHECK (event_type IN ('page_view', 'cta_click', 'form_view', 'form_submit', 'whatsapp_click', 'phone_click', 'demo_booked', 'calculator_used', 'assessment_completed', 'resource_download', 'chatbot_open', 'chatbot_lead', 'popup_view', 'popup_click', 'popup_close', 'webinar_registered', 'savings_calculated', 'review_click', 'campaign_view')),
  path text,
  element_key text,
  utm_source text,
  utm_medium text,
  utm_campaign text,
  source text CHECK (source IN ('organic', 'direct', 'social', 'referral', 'campaign', 'email')),
  device text CHECK (device IN ('desktop', 'mobile', 'tablet')),
  session_hash text NOT NULL,
  lead_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id, occurred_at),
  CONSTRAINT ck_site_events_1 CHECK (session_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT ck_site_events_2 CHECK (path IS NULL OR (path ~ '^/' AND length(path) <= 300)),
  CONSTRAINT ck_site_events_3 CHECK (element_key IS NULL OR length(element_key) <= 80)
) PARTITION BY RANGE (occurred_at);
COMMENT ON TABLE site_events IS '[WEB] Evento analítico del sitio (vista, CTA, formulario, WhatsApp, demo, calculadoras, chatbot, popups, webinars, reseñas, campaña); solo con consentimiento analítico, sin IP ni datos personales; inalterable, particionado por mes (la conservación se aplica descartando particiones) · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN site_events.element_key IS 'CTA o formulario (p. ej. hero_demo, form_quote)';
COMMENT ON COLUMN site_events.source IS 'canal deducido por la API (UTM y dominio de referencia; no se guarda el referrer)';
COMMENT ON COLUMN site_events.device IS 'clase de dispositivo deducida por la API (no se guarda el user agent)';
COMMENT ON COLUMN site_events.session_hash IS 'hash de sesión rotado a diario (HMAC en la API); no identifica a la persona';
COMMENT ON COLUMN site_events.lead_id IS 'solo lo fijan funciones internas (nunca el visitante)';

-- WEB · demo_booking_settings (platform)
CREATE TABLE IF NOT EXISTS demo_booking_settings (
  id uuid NOT NULL DEFAULT uuidv7(),
  singleton boolean NOT NULL DEFAULT true,
  public_booking_enabled boolean NOT NULL DEFAULT false,
  duration_minutes smallint NOT NULL DEFAULT 30,
  buffer_minutes smallint NOT NULL DEFAULT 15,
  min_notice_hours smallint NOT NULL DEFAULT 24,
  max_days_ahead smallint NOT NULL DEFAULT 30,
  default_meeting_provider text NOT NULL DEFAULT 'meet' CHECK (default_meeting_provider IN ('meet', 'teams', 'phone')),
  reminder_24h boolean NOT NULL DEFAULT true,
  reminder_1h boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_demo_booking_settings_1 CHECK (singleton),
  CONSTRAINT ck_demo_booking_settings_2 CHECK (duration_minutes BETWEEN 10 AND 240),
  CONSTRAINT ck_demo_booking_settings_3 CHECK (buffer_minutes BETWEEN 0 AND 120),
  CONSTRAINT ck_demo_booking_settings_4 CHECK (min_notice_hours BETWEEN 0 AND 720),
  CONSTRAINT ck_demo_booking_settings_5 CHECK (max_days_ahead BETWEEN 1 AND 180)
);
COMMENT ON TABLE demo_booking_settings IS '[WEB] Ajustes únicos de la agenda pública de demos: activación, duración y margen configurables, aviso mínimo, horizonte, proveedor de reunión y recordatorios';
COMMENT ON COLUMN demo_booking_settings.duration_minutes IS 'configurable en el panel (la web no promete una duración fija)';
COMMENT ON COLUMN demo_booking_settings.buffer_minutes IS 'margen entre citas';

-- WEB · demo_hosts (platform)
CREATE TABLE IF NOT EXISTS demo_hosts (
  id uuid NOT NULL DEFAULT uuidv7(),
  user_id uuid NOT NULL,
  display_name text NOT NULL,
  email text NOT NULL,
  color text,
  timezone text NOT NULL DEFAULT 'America/Lima',
  calendar_provider text NOT NULL DEFAULT 'none' CHECK (calendar_provider IN ('google', 'microsoft', 'none')),
  calendar_secret_ref text,
  is_active boolean NOT NULL DEFAULT true,
  max_per_day smallint,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_demo_hosts_1 CHECK (color IS NULL OR color ~ '^#[0-9A-Fa-f]{6}$'),
  CONSTRAINT ck_demo_hosts_2 CHECK (email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  CONSTRAINT ck_demo_hosts_3 CHECK (calendar_secret_ref IS NULL OR calendar_secret_ref ~ '^[a-z][a-z0-9+.-]*://'),
  CONSTRAINT ck_demo_hosts_4 CHECK (calendar_provider = 'none' OR calendar_secret_ref IS NOT NULL),
  CONSTRAINT ck_demo_hosts_5 CHECK (max_per_day IS NULL OR max_per_day >= 1)
);
COMMENT ON TABLE demo_hosts IS '[WEB] Anfitrión de demos (asesor comercial o especialista SST) con zona horaria, calendario conectado por OAuth (secreto como referencia) y tope diario';
COMMENT ON COLUMN demo_hosts.color IS 'color en el calendario (#RRGGBB)';
COMMENT ON COLUMN demo_hosts.calendar_secret_ref IS 'referencia al token OAuth en el gestor de secretos (nunca el token)';
COMMENT ON COLUMN demo_hosts.max_per_day IS 'NULL = sin tope';

-- WEB · demo_availability_rules (platform, hard_delete)
CREATE TABLE IF NOT EXISTS demo_availability_rules (
  id uuid NOT NULL DEFAULT uuidv7(),
  host_id uuid NOT NULL,
  weekday smallint NOT NULL,
  start_time time NOT NULL,
  end_time time NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_demo_availability_rules_1 CHECK (weekday BETWEEN 1 AND 7),
  CONSTRAINT ck_demo_availability_rules_2 CHECK (end_time > start_time)
);
COMMENT ON TABLE demo_availability_rules IS '[WEB] Disponibilidad semanal de un anfitrión (día ISO 1 = lunes … 7 = domingo; horas en su zona horaria)';

-- WEB · demo_blackouts (platform, hard_delete)
CREATE TABLE IF NOT EXISTS demo_blackouts (
  id uuid NOT NULL DEFAULT uuidv7(),
  host_id uuid,
  starts_at timestamptz NOT NULL,
  ends_at timestamptz NOT NULL,
  reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_demo_blackouts_1 CHECK (ends_at > starts_at)
);
COMMENT ON TABLE demo_blackouts IS '[WEB] Bloqueo de agenda (vacaciones, evento interno); host_id NULL = todos los anfitriones. Los feriados nacionales salen de holidays';

-- WEB · demo_meetings (platform)
CREATE TABLE IF NOT EXISTS demo_meetings (
  id uuid NOT NULL DEFAULT uuidv7(),
  demo_request_id uuid NOT NULL,
  host_id uuid,
  starts_at timestamptz NOT NULL,
  ends_at timestamptz NOT NULL,
  status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'confirmed', 'rescheduled', 'cancelled', 'completed', 'no_show')),
  meeting_provider text NOT NULL DEFAULT 'meet' CHECK (meeting_provider IN ('meet', 'teams', 'phone')),
  meeting_url text,
  calendar_event_ref text,
  manage_token_hash bytea NOT NULL,
  confirmed_at timestamptz,
  reminder_24h_sent_at timestamptz,
  reminder_1h_sent_at timestamptz,
  cancel_reason text,
  outcome text CHECK (outcome IN ('interested', 'not_interested', 'follow_up', 'converted')),
  outcome_notes text,
  recording_consent boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_demo_meetings_1 CHECK (ends_at > starts_at),
  CONSTRAINT ck_demo_meetings_2 CHECK (length(manage_token_hash) = 32),
  CONSTRAINT ck_demo_meetings_3 CHECK (meeting_url IS NULL OR meeting_url ~ '^https://'),
  CONSTRAINT ck_demo_meetings_4 CHECK (status NOT IN ('confirmed', 'rescheduled', 'completed', 'no_show') OR host_id IS NOT NULL),
  CONSTRAINT ck_demo_meetings_5 CHECK (status <> 'confirmed' OR (confirmed_at IS NOT NULL AND (meeting_url IS NOT NULL OR meeting_provider = 'phone'))),
  CONSTRAINT ck_demo_meetings_6 CHECK (status <> 'cancelled' OR cancel_reason IS NOT NULL),
  CONSTRAINT ck_demo_meetings_7 CHECK (status <> 'completed' OR outcome IS NOT NULL)
);
COMMENT ON TABLE demo_meetings IS '[WEB] Reunión de demo agendada (propuesta → confirmada con enlace → completada / no asistió; reprogramar o cancelar con enlace seguro). Dos reuniones confirmadas del mismo anfitrión no se cruzan';
COMMENT ON COLUMN demo_meetings.host_id IS 'NULL = por asignar';
COMMENT ON COLUMN demo_meetings.meeting_url IS 'Google Meet o Microsoft Teams (https)';
COMMENT ON COLUMN demo_meetings.calendar_event_ref IS 'id del evento en el calendario del anfitrión';
COMMENT ON COLUMN demo_meetings.manage_token_hash IS 'sha256 del token del enlace «reprogramar o cancelar» (el token no se guarda)';
COMMENT ON COLUMN demo_meetings.recording_consent IS 'grabación solo con consentimiento expreso (parámetro web.demo_recording_requires_consent)';

-- WEB · chatbot_settings (platform)
CREATE TABLE IF NOT EXISTS chatbot_settings (
  id uuid NOT NULL DEFAULT uuidv7(),
  singleton boolean NOT NULL DEFAULT true,
  enabled boolean NOT NULL DEFAULT false,
  mode text NOT NULL DEFAULT 'guided' CHECK (mode IN ('guided', 'ai')),
  greeting text,
  avatar_media_id uuid,
  business_hours_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  offline_message text,
  handoff_whatsapp boolean NOT NULL DEFAULT true,
  ask_lead_after_messages smallint NOT NULL DEFAULT 3,
  ai_provider_secret_ref text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_chatbot_settings_1 CHECK (singleton),
  CONSTRAINT ck_chatbot_settings_2 CHECK (jsonb_typeof(business_hours_json) = 'object'),
  CONSTRAINT ck_chatbot_settings_3 CHECK (ask_lead_after_messages BETWEEN 1 AND 50),
  CONSTRAINT ck_chatbot_settings_4 CHECK (ai_provider_secret_ref IS NULL OR ai_provider_secret_ref ~ '^[a-z][a-z0-9+.-]*://'),
  CONSTRAINT ck_chatbot_settings_5 CHECK (mode <> 'ai' OR ai_provider_secret_ref IS NOT NULL)
);
COMMENT ON TABLE chatbot_settings IS '[WEB] Ajustes únicos del chatbot del sitio: activación, modo guiado o IA (solo contenido publicado), saludo, horario, derivación y pedido de datos';
COMMENT ON COLUMN chatbot_settings.business_hours_json IS '{"timezone": "America/Lima", "1": [["09:00", "18:00"]], …}; {} = siempre disponible';
COMMENT ON COLUMN chatbot_settings.handoff_whatsapp IS 'ofrece derivar a WhatsApp (número de site_settings)';
COMMENT ON COLUMN chatbot_settings.ask_lead_after_messages IS 'pide datos (con consentimiento) después de n mensajes del visitante';
COMMENT ON COLUMN chatbot_settings.ai_provider_secret_ref IS 'referencia a la llave del proveedor de IA (nunca la llave)';

-- WEB · chatbot_intents (platform)
CREATE TABLE IF NOT EXISTS chatbot_intents (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  trigger_phrases_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  answer text NOT NULL,
  cta_type text NOT NULL DEFAULT 'none' CHECK (cta_type IN ('none', 'demo', 'whatsapp', 'calculator', 'assessment', 'link')),
  cta_url text,
  faq_id uuid,
  help_article_id uuid,
  sort_order integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_chatbot_intents_1 CHECK (jsonb_typeof(trigger_phrases_json) = 'array'),
  CONSTRAINT ck_chatbot_intents_2 CHECK (cta_url IS NULL OR cta_url ~ '^(https://|/)'),
  CONSTRAINT ck_chatbot_intents_3 CHECK (cta_type <> 'link' OR cta_url IS NOT NULL)
);
COMMENT ON TABLE chatbot_intents IS '[WEB] Intención del chatbot guiado: frases disparadoras, respuesta y botón (demo, WhatsApp, calculadora, autodiagnóstico, enlace); borrador → publicada → archivada';
COMMENT ON COLUMN chatbot_intents.trigger_phrases_json IS '["precio", "demo", …] en minúsculas';

-- WEB · chatbot_conversations (platform)
CREATE TABLE IF NOT EXISTS chatbot_conversations (
  id uuid NOT NULL DEFAULT uuidv7(),
  session_hash text NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(),
  ended_at timestamptz,
  path text,
  lead_id uuid,
  handoff text NOT NULL DEFAULT 'none' CHECK (handoff IN ('none', 'whatsapp', 'form')),
  rating smallint,
  message_count integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_chatbot_conversations_1 CHECK (session_hash ~ '^[0-9a-f]{64}$'),
  CONSTRAINT ck_chatbot_conversations_2 CHECK (rating IS NULL OR rating BETWEEN 1 AND 5),
  CONSTRAINT ck_chatbot_conversations_3 CHECK (message_count >= 0),
  CONSTRAINT ck_chatbot_conversations_4 CHECK (ended_at IS NULL OR ended_at >= started_at)
);
COMMENT ON TABLE chatbot_conversations IS '[WEB] Conversación del chatbot (sin IP; session_hash rotado a diario); lead solo con consentimiento; conservación por parámetro';

-- WEB · chatbot_messages (platform, imm, partition)
CREATE TABLE IF NOT EXISTS chatbot_messages (
  id uuid NOT NULL DEFAULT uuidv7(),
  conversation_id uuid NOT NULL,
  sender text NOT NULL CHECK (sender IN ('visitor', 'bot')),
  body text NOT NULL,
  intent_id uuid,
  used_ai boolean NOT NULL DEFAULT false,
  occurred_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  PRIMARY KEY (id, occurred_at),
  CONSTRAINT ck_chatbot_messages_1 CHECK (length(body) BETWEEN 1 AND 2000),
  CONSTRAINT ck_chatbot_messages_2 CHECK (sender = 'bot' OR (NOT used_ai AND intent_id IS NULL))
) PARTITION BY RANGE (occurred_at);
COMMENT ON TABLE chatbot_messages IS '[WEB] Mensaje de una conversación del chatbot (visitante o bot; used_ai si lo redactó la IA con contenido publicado); inalterable, particionado por mes · INALTERABLE: solo INSERT.';
COMMENT ON COLUMN chatbot_messages.occurred_at IS 'clave de partición (conservación por web.chatbot_retention_months)';

-- WEB · crm_connections (platform)
CREATE TABLE IF NOT EXISTS crm_connections (
  id uuid NOT NULL DEFAULT uuidv7(),
  provider text NOT NULL CHECK (provider IN ('kallpa', 'generic_webhook')),
  name text NOT NULL,
  base_url text,
  secret_ref text,
  status text NOT NULL DEFAULT 'paused' CHECK (status IN ('active', 'paused', 'error')),
  entities_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  field_mapping_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  last_sync_at timestamptz,
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_crm_connections_1 CHECK (base_url IS NULL OR base_url ~ '^https://'),
  CONSTRAINT ck_crm_connections_2 CHECK (secret_ref IS NULL OR secret_ref ~ '^[a-z][a-z0-9+.-]*://'),
  CONSTRAINT ck_crm_connections_3 CHECK (status <> 'active' OR (base_url IS NOT NULL AND secret_ref IS NOT NULL)),
  CONSTRAINT ck_crm_connections_4 CHECK (jsonb_typeof(entities_json) = 'array' AND entities_json <@ '["marketing_lead","demo_request","demo_meeting","partner_application","newsletter_subscriber"]'::jsonb),
  CONSTRAINT ck_crm_connections_5 CHECK (jsonb_typeof(field_mapping_json) = 'object')
);
COMMENT ON TABLE crm_connections IS '[WEB] Conexión con el CRM («Kallpa CRM» propio o webhook genérico): URL, secreto como referencia, entidades a sincronizar y mapeo de campos. El Libro de Reclamaciones nunca se envía';
COMMENT ON COLUMN crm_connections.secret_ref IS 'referencia al secreto o token en el gestor de secretos';
COMMENT ON COLUMN crm_connections.entities_json IS 'subconjunto de ["marketing_lead","demo_request","demo_meeting","partner_application","newsletter_subscriber"]';

-- WEB · crm_sync_events (platform)
CREATE TABLE IF NOT EXISTS crm_sync_events (
  id uuid NOT NULL DEFAULT uuidv7(),
  connection_id uuid NOT NULL,
  entity_type text NOT NULL CHECK (entity_type IN ('marketing_lead', 'demo_request', 'demo_meeting', 'partner_application', 'newsletter_subscriber')),
  entity_id uuid NOT NULL,
  action text NOT NULL CHECK (action IN ('create', 'update')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'sent', 'failed', 'skipped')),
  attempts integer NOT NULL DEFAULT 0,
  next_attempt_at timestamptz DEFAULT now(),
  external_id text,
  response_code smallint,
  last_error text,
  idempotency_key text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_crm_sync_events_1 CHECK (attempts >= 0),
  CONSTRAINT ck_crm_sync_events_2 CHECK (status <> 'sent' OR attempts >= 1)
);
COMMENT ON TABLE crm_sync_events IS '[WEB] Cola de envíos al CRM con reintentos e idempotencia (una fila por entidad, acción y versión)';
COMMENT ON COLUMN crm_sync_events.external_id IS 'id en el CRM';
COMMENT ON COLUMN crm_sync_events.idempotency_key IS 'conexión:entidad:id:acción[:versión]; también se envía al CRM';

-- WEB · success_story_media (platform)
CREATE TABLE IF NOT EXISTS success_story_media (
  id uuid NOT NULL DEFAULT uuidv7(),
  success_story_id uuid NOT NULL,
  media_id uuid NOT NULL,
  caption text,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id)
);
COMMENT ON TABLE success_story_media IS '[WEB] Galería del caso de éxito (portafolio): imágenes de la biblioteca de medios con leyenda y orden';

-- WEB · campaigns (platform)
CREATE TABLE IF NOT EXISTS campaigns (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  channel text NOT NULL CHECK (channel IN ('google_ads', 'meta_ads', 'linkedin', 'email', 'other')),
  utm_source text,
  utm_medium text,
  utm_campaign text,
  landing_page_id uuid,
  form_type text CHECK (form_type IN ('demo', 'quote', 'contact', 'resource', 'assessment', 'calculator')),
  starts_on date,
  ends_on date,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'paused', 'finished')),
  goal text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_campaigns_1 CHECK (ends_on IS NULL OR starts_on IS NULL OR ends_on >= starts_on),
  CONSTRAINT ck_campaigns_2 CHECK (status <> 'active' OR landing_page_id IS NOT NULL),
  CONSTRAINT ck_campaigns_3 CHECK (utm_campaign IS NULL OR utm_campaign ~ '^[a-z0-9_-]{1,100}$')
);
COMMENT ON TABLE campaigns IS '[WEB] Campaña de anuncios (Google Ads, Meta Ads, LinkedIn, correo) con landing /l/{slug}, formulario, UTM por defecto y vigencia; métricas por utm_campaign';
COMMENT ON COLUMN campaigns.landing_page_id IS 'página page_type = campaign';
COMMENT ON COLUMN campaigns.goal IS 'objetivo interno (no se publica)';

-- WEB · site_popups (platform)
CREATE TABLE IF NOT EXISTS site_popups (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  trigger_type text NOT NULL CHECK (trigger_type IN ('exit_intent', 'scroll_percent', 'time_on_page')),
  trigger_value integer,
  pages_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  excluded_pages_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  devices text NOT NULL DEFAULT 'all' CHECK (devices IN ('all', 'desktop', 'mobile')),
  offer_type text NOT NULL CHECK (offer_type IN ('fine_calculator', 'savings_calculator', 'self_assessment', 'resource', 'demo', 'newsletter', 'webinar')),
  title text NOT NULL,
  body text,
  cta_label text,
  image_media_id uuid,
  frequency_days smallint NOT NULL DEFAULT 7,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'paused')),
  starts_at timestamptz,
  ends_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_popups_1 CHECK (jsonb_typeof(pages_json) = 'array' AND jsonb_typeof(excluded_pages_json) = 'array'),
  CONSTRAINT ck_site_popups_2 CHECK (trigger_type = 'exit_intent' OR trigger_value IS NOT NULL),
  CONSTRAINT ck_site_popups_3 CHECK (trigger_type <> 'scroll_percent' OR trigger_value BETWEEN 1 AND 100),
  CONSTRAINT ck_site_popups_4 CHECK (trigger_type <> 'time_on_page' OR trigger_value BETWEEN 1 AND 3600),
  CONSTRAINT ck_site_popups_5 CHECK (frequency_days BETWEEN 1 AND 365),
  CONSTRAINT ck_site_popups_6 CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at)
);
COMMENT ON TABLE site_popups IS '[WEB] Ventana emergente (intención de salida, % de scroll o tiempo en página) con oferta, páginas, dispositivo y frecuencia por visitante; nunca en Libro de Reclamaciones, políticas ni formularios';
COMMENT ON COLUMN site_popups.trigger_value IS '% de scroll (1-100) o segundos en página';
COMMENT ON COLUMN site_popups.pages_json IS 'rutas donde se muestra ([] = todas las permitidas; «/blog/*» = prefijo)';
COMMENT ON COLUMN site_popups.frequency_days IS 'se vuelve a mostrar al mismo visitante después de n días';

-- WEB · site_integrations (platform)
CREATE TABLE IF NOT EXISTS site_integrations (
  id uuid NOT NULL DEFAULT uuidv7(),
  name text NOT NULL,
  slug text NOT NULL,
  category text NOT NULL CHECK (category IN ('messaging', 'lms', 'payments', 'crm', 'calendar', 'email', 'storage', 'ai', 'analytics')),
  description text,
  logo_media_id uuid,
  availability text NOT NULL CHECK (availability IN ('available', 'beta', 'planned')),
  docs_url text,
  sort_order integer NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'hidden')),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_site_integrations_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT ck_site_integrations_2 CHECK (docs_url IS NULL OR docs_url ~ '^(https://|/)')
);
COMMENT ON TABLE site_integrations IS '[WEB] Integración mostrada en /integraciones con estado veraz (disponible, beta, planificada)';

-- WEB · product_updates (platform)
CREATE TABLE IF NOT EXISTS product_updates (
  id uuid NOT NULL DEFAULT uuidv7(),
  title text NOT NULL,
  slug text NOT NULL,
  body text NOT NULL,
  category text NOT NULL CHECK (category IN ('new', 'improvement', 'fix')),
  modules_json jsonb NOT NULL DEFAULT '[]'::jsonb,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'archived')),
  published_at timestamptz,
  notify_subscribers boolean NOT NULL DEFAULT false,
  show_in_app boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_product_updates_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT ck_product_updates_2 CHECK (jsonb_typeof(modules_json) = 'array'),
  CONSTRAINT ck_product_updates_3 CHECK (status <> 'published' OR published_at IS NOT NULL)
);
COMMENT ON TABLE product_updates IS '[WEB] Novedad del producto (nuevo, mejora, corrección) con módulos; se publica en /novedades, opcionalmente se avisa a suscriptores y se muestra en la app';
COMMENT ON COLUMN product_updates.body IS 'Markdown';
COMMENT ON COLUMN product_updates.modules_json IS 'códigos de módulo';

-- WEB · webinars (platform)
CREATE TABLE IF NOT EXISTS webinars (
  id uuid NOT NULL DEFAULT uuidv7(),
  title text NOT NULL,
  slug text NOT NULL,
  description text,
  speaker_name text NOT NULL,
  speaker_title text,
  starts_at timestamptz NOT NULL,
  duration_minutes smallint NOT NULL,
  meeting_provider text NOT NULL DEFAULT 'meet' CHECK (meeting_provider IN ('meet', 'teams', 'zoom', 'other')),
  meeting_url text,
  capacity integer,
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published', 'live', 'finished', 'cancelled')),
  recording_media_id uuid,
  recording_public boolean NOT NULL DEFAULT false,
  recording_informed boolean NOT NULL DEFAULT false,
  cover_media_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_webinars_1 CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  CONSTRAINT ck_webinars_2 CHECK (duration_minutes BETWEEN 10 AND 600),
  CONSTRAINT ck_webinars_3 CHECK (capacity IS NULL OR capacity >= 1),
  CONSTRAINT ck_webinars_4 CHECK (meeting_url IS NULL OR meeting_url ~ '^https://'),
  CONSTRAINT ck_webinars_5 CHECK (NOT recording_public OR (recording_informed AND recording_media_id IS NOT NULL))
);
COMMENT ON TABLE webinars IS '[WEB] Webinar (próximo o grabado) con ponente, cupos, enlace de reunión (solo para inscritos) y grabación publicada solo si se informó a ponente y asistentes';
COMMENT ON COLUMN webinars.meeting_url IS 'se envía a los inscritos; nunca sale en la web pública';
COMMENT ON COLUMN webinars.capacity IS 'NULL = sin cupo';
COMMENT ON COLUMN webinars.recording_informed IS 'ponente y asistentes fueron informados de la grabación (requisito para publicarla)';

-- WEB · webinar_registrations (platform)
CREATE TABLE IF NOT EXISTS webinar_registrations (
  id uuid NOT NULL DEFAULT uuidv7(),
  webinar_id uuid NOT NULL,
  lead_id uuid NOT NULL,
  status text NOT NULL DEFAULT 'registered' CHECK (status IN ('registered', 'cancelled', 'attended', 'no_show')),
  manage_token_hash bytea NOT NULL,
  reminder_24h_sent_at timestamptz,
  reminder_1h_sent_at timestamptz,
  registered_at timestamptz NOT NULL DEFAULT now(),
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_webinar_registrations_1 CHECK (length(manage_token_hash) = 32)
);
COMMENT ON TABLE webinar_registrations IS '[WEB] Inscripción a un webinar (con consentimiento vía lead), estado, asistencia y recordatorios; token de gestión solo como hash';
COMMENT ON COLUMN webinar_registrations.manage_token_hash IS 'sha256 del token del enlace para cancelar la inscripción';

-- WEB · review_sources (platform)
CREATE TABLE IF NOT EXISTS review_sources (
  id uuid NOT NULL DEFAULT uuidv7(),
  provider text NOT NULL DEFAULT 'google' CHECK (provider IN ('google')),
  place_id text NOT NULL,
  api_secret_ref text,
  min_rating smallint NOT NULL DEFAULT 1,
  max_to_show smallint NOT NULL DEFAULT 5,
  cache_ttl_hours integer NOT NULL DEFAULT 24,
  last_fetched_at timestamptz,
  status text NOT NULL DEFAULT 'paused' CHECK (status IN ('active', 'paused', 'error')),
  last_error text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_review_sources_1 CHECK (min_rating BETWEEN 1 AND 5),
  CONSTRAINT ck_review_sources_2 CHECK (max_to_show BETWEEN 1 AND 50),
  CONSTRAINT ck_review_sources_3 CHECK (cache_ttl_hours >= 1),
  CONSTRAINT ck_review_sources_4 CHECK (api_secret_ref IS NULL OR api_secret_ref ~ '^[a-z][a-z0-9+.-]*://'),
  CONSTRAINT ck_review_sources_5 CHECK (status <> 'active' OR api_secret_ref IS NOT NULL)
);
COMMENT ON TABLE review_sources IS '[WEB] Fuente de reseñas reales (perfil de Google Business por la API oficial): filtro solo por calificación mínima y cantidad; caché según el proveedor';
COMMENT ON COLUMN review_sources.api_secret_ref IS 'referencia a la llave de la API (nunca la llave)';
COMMENT ON COLUMN review_sources.cache_ttl_hours IS 'tope efectivo: web.review_cache_max_hours';

-- WEB · review_snapshots (platform, hard_delete)
CREATE TABLE IF NOT EXISTS review_snapshots (
  id uuid NOT NULL DEFAULT uuidv7(),
  review_source_id uuid NOT NULL,
  author_name text NOT NULL,
  author_photo_url text,
  rating smallint NOT NULL,
  body text,
  review_published_at timestamptz,
  provider_review_url text,
  fetched_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_review_snapshots_1 CHECK (rating BETWEEN 1 AND 5),
  CONSTRAINT ck_review_snapshots_2 CHECK (expires_at > fetched_at),
  CONSTRAINT ck_review_snapshots_3 CHECK (author_photo_url IS NULL OR author_photo_url ~ '^https://'),
  CONSTRAINT ck_review_snapshots_4 CHECK (provider_review_url IS NULL OR provider_review_url ~ '^https://')
);
COMMENT ON TABLE review_snapshots IS '[WEB] Copia en caché de una reseña tal como la entrega el proveedor (sin editar el texto), con atribución y expiración';
COMMENT ON COLUMN review_snapshots.body IS 'texto original (no se edita)';

-- WEB · savings_calculator_settings (platform)
CREATE TABLE IF NOT EXISTS savings_calculator_settings (
  id uuid NOT NULL DEFAULT uuidv7(),
  singleton boolean NOT NULL DEFAULT true,
  assumptions_json jsonb NOT NULL DEFAULT '{"minutes_saved_per_record": null, "manual_hours_reduction_pct": null, "hourly_cost_pen": null}'::jsonb,
  disclaimer text NOT NULL DEFAULT 'Estimación referencial, no garantizada. Los supuestos se muestran y pueden no aplicar a tu empresa.',
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
  to_validate boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_savings_calculator_settings_1 CHECK (singleton),
  CONSTRAINT ck_savings_calculator_settings_2 CHECK (jsonb_typeof(assumptions_json) = 'object')
);
COMMENT ON TABLE savings_calculator_settings IS '[WEB] Supuestos únicos de la calculadora de ahorro frente a Excel y papel, editables y visibles («estimación referencial, no garantizada»)';
COMMENT ON COLUMN savings_calculator_settings.assumptions_json IS 'supuestos visibles; null = por definir (costo hora vacío por defecto)';

-- WEB · savings_calculations (platform)
CREATE TABLE IF NOT EXISTS savings_calculations (
  id uuid NOT NULL DEFAULT uuidv7(),
  lead_id uuid,
  inputs_json jsonb NOT NULL,
  assumptions_snapshot_json jsonb NOT NULL,
  result_hours_month numeric(10,1) NOT NULL,
  result_cost_month numeric(14,2),
  idempotency_key text,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid,
  updated_at timestamptz NOT NULL DEFAULT now(),
  updated_by uuid,
  deleted_at timestamptz,
  PRIMARY KEY (id),
  CONSTRAINT ck_savings_calculations_1 CHECK (jsonb_typeof(inputs_json) = 'object' AND jsonb_typeof(assumptions_snapshot_json) = 'object'),
  CONSTRAINT ck_savings_calculations_2 CHECK (result_hours_month >= 0),
  CONSTRAINT ck_savings_calculations_3 CHECK (result_cost_month IS NULL OR result_cost_month >= 0)
);
COMMENT ON TABLE savings_calculations IS '[WEB] Cálculo de ahorro hecho en la web, con copia de los supuestos usados; resultado por correo a cambio de datos (lead)';
COMMENT ON COLUMN savings_calculations.inputs_json IS '{workers, sites, records_per_month, hours_per_month}';
COMMENT ON COLUMN savings_calculations.assumptions_snapshot_json IS 'copia de assumptions_json, disclaimer y to_validate al calcular';
COMMENT ON COLUMN savings_calculations.result_cost_month IS 'NULL si el costo hora no está definido';

-- Particiones mensuales de audit_logs: una por defecto + función para crear meses por adelantado (job mensual).
CREATE TABLE IF NOT EXISTS audit_logs_default PARTITION OF audit_logs DEFAULT;
ALTER TABLE audit_logs_default ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_logs_default FORCE ROW LEVEL SECURITY;
COMMENT ON TABLE audit_logs_default IS 'Partición por defecto de audit_logs. Acceso solo a través de la tabla padre.';
CREATE OR REPLACE FUNCTION public.audit_logs_ensure_partition(p_month date) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
  s date := date_trunc('month', p_month)::date;
  n text := format('audit_logs_%s', to_char(s, 'YYYYMM'));
BEGIN
  IF to_regclass(n) IS NULL THEN
    EXECUTE format('CREATE TABLE %I PARTITION OF audit_logs FOR VALUES FROM (%L) TO (%L)', n, s, (s + interval '1 month')::date);
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', n);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', n);
  END IF;
  RETURN n;
END $$;

