-- ---------- Funciones de dominio de escudo_main (escritas a mano; las incluye tools/db/generar.py) ----------

-- ¿El módulo está habilitado (o en solo lectura) para la empresa activa? Se usa en políticas de catálogos por complemento.
CREATE OR REPLACE FUNCTION public.app_module_enabled(p_module text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT EXISTS (
    SELECT 1 FROM feature_flags f
     WHERE f.company_id = app_company_id() AND f.module_code = p_module
       AND f.mode IN ('enabled', 'read_only') AND f.deleted_at IS NULL
       AND (f.valid_until IS NULL OR f.valid_until > now()))
$$;

-- Módulos que la empresa puede activar o desactivar dentro de su plan (feature_flags.company_enabled).
-- Si el plan los incluye y la empresa los desactivó: mode = 'disabled_by_company', source = 'company_setting'.
-- VTA viene desactivado por defecto; AUL activo. Desactivar no borra datos: el módulo deja de mostrarse y de operar.
CREATE OR REPLACE FUNCTION public.company_toggleable_modules() RETURNS text[]
LANGUAGE sql IMMUTABLE AS $$ SELECT ARRAY['AUL', 'VTA']::text[] $$;

-- La aplicación no puede cambiar mode/source/vigencia de un flag (los calcula refresh_feature_flags como escudo_definer
-- o los fija escudo_platform); solo puede activar o desactivar los módulos permitidos con set_company_module_enabled().
CREATE OR REPLACE FUNCTION public.trg_feature_flags_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF current_user = 'escudo_app' THEN
    IF TG_OP = 'INSERT' OR NEW.mode IS DISTINCT FROM OLD.mode OR NEW.source IS DISTINCT FROM OLD.source
       OR NEW.valid_until IS DISTINCT FROM OLD.valid_until OR NEW.module_code IS DISTINCT FROM OLD.module_code THEN
      RAISE EXCEPTION 'feature_flags: la aplicación solo puede activar o desactivar módulos permitidos'
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_feature_flags_guard BEFORE INSERT OR UPDATE ON feature_flags FOR EACH ROW EXECUTE FUNCTION trg_feature_flags_guard();

-- Activa o desactiva AUL/VTA en la empresa activa (la API exige el permiso sus.feature_flags.update del administrador).
CREATE OR REPLACE FUNCTION public.set_company_module_enabled(p_module text, p_enabled boolean) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE f feature_flags;
BEGIN
  IF app_company_id() IS NULL THEN
    RAISE EXCEPTION 'sin empresa activa' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT (p_module = ANY (company_toggleable_modules())) THEN
    RAISE EXCEPTION 'el módulo % no se puede activar o desactivar por empresa', p_module USING ERRCODE = 'check_violation';
  END IF;
  -- VTA exige AUL activo (M-SUS): no se activa VTA sin AUL ni se desactiva AUL con VTA activo.
  IF p_module = 'VTA' AND p_enabled AND NOT EXISTS (SELECT 1 FROM feature_flags a WHERE a.company_id = app_company_id()
       AND a.module_code = 'AUL' AND a.mode = 'enabled' AND a.company_enabled AND a.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'VTA requiere el aula virtual (AUL) activa' USING ERRCODE = 'check_violation';
  END IF;
  IF p_module = 'AUL' AND NOT p_enabled AND EXISTS (SELECT 1 FROM feature_flags v WHERE v.company_id = app_company_id()
       AND v.module_code = 'VTA' AND v.company_enabled AND v.deleted_at IS NULL) THEN
    RAISE EXCEPTION 'desactive primero la venta de cursos (VTA)' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE feature_flags SET company_enabled = p_enabled, toggled_by = app_user_id(), toggled_at = now(),
         mode = CASE WHEN NOT p_enabled AND mode = 'enabled' THEN 'disabled_by_company'
                     WHEN p_enabled AND mode = 'disabled_by_company' THEN 'enabled' ELSE mode END,   -- refresh_feature_flags ajusta el origen
         source = CASE WHEN NOT p_enabled AND mode = 'enabled' THEN 'company_setting'
                       WHEN p_enabled AND mode = 'disabled_by_company' THEN 'plan' ELSE source END
   WHERE company_id = app_company_id() AND module_code = p_module AND deleted_at IS NULL
  RETURNING * INTO f;
  IF f.id IS NULL THEN
    RAISE EXCEPTION 'la empresa no tiene flag para %', p_module USING ERRCODE = 'no_data_found';
  END IF;
  IF p_enabled THEN
    PERFORM refresh_feature_flags(f.company_id);   -- disabled_by_company → enabled si el plan lo incluye
    SELECT * INTO f FROM feature_flags WHERE id = f.id;
  END IF;
  INSERT INTO audit_logs (company_id, actor_user_id, action, module_code, entity_type, entity_id, changes)
  VALUES (f.company_id, app_user_id(), CASE WHEN p_enabled THEN 'module_enabled' ELSE 'module_disabled' END, 'SUS',
          'feature_flags', f.id, jsonb_build_object('module_code', p_module, 'company_enabled', p_enabled, 'mode', f.mode));
  RETURN jsonb_build_object('module_code', f.module_code, 'mode', f.mode, 'company_enabled', f.company_enabled,
                            'effective', f.mode = 'enabled');
END $$;

-- Valor vigente de un parámetro legal: primero el de la empresa activa, luego el de plataforma.
CREATE OR REPLACE FUNCTION public.legal_param(p_key text, p_on date DEFAULT current_date) RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT value FROM legal_parameters
   WHERE key = p_key AND deleted_at IS NULL
     AND valid_from <= p_on AND (valid_to IS NULL OR valid_to >= p_on)
     AND (company_id IS NULL OR company_id = app_company_id())
   ORDER BY (company_id IS NULL), valid_from DESC
   LIMIT 1
$$;

-- ------------------------------------------------------------------ Bitácora encadenada por hash
-- Cada fila guarda prev_hash (hash de la fila anterior de la misma empresa; NULL al inicio de la cadena)
-- y row_hash = sha256(prev_hash || contenido canónico). chain_seq es correlativo por empresa.
-- Un candado de asesoría por empresa serializa las inserciones de la misma cadena.
CREATE OR REPLACE FUNCTION public.audit_logs_canonical(r audit_logs) RETURNS text
LANGUAGE sql IMMUTABLE AS $$
  SELECT concat_ws('|', r.id::text, coalesce(r.company_id::text, '-'), r.chain_seq::text,
                   to_char(r.occurred_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
                   coalesce(r.actor_user_id::text, '-'), coalesce(r.actor_role, '-'), r.actor_type,
                   r.is_support_session::text, r.action, coalesce(r.module_code, '-'), r.entity_type,
                   coalesce(r.entity_id::text, '-'), coalesce(r.changes::text, '-'), coalesce(r.reason, '-'),
                   coalesce(host(r.ip), '-'), coalesce(r.request_id, '-'))
$$;

CREATE OR REPLACE FUNCTION public.trg_audit_logs_chain() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  last_seq bigint;
  last_hash bytea;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended('audit_logs:' || coalesce(NEW.company_id::text, 'platform'), 0));
  SELECT a.chain_seq, a.row_hash INTO last_seq, last_hash
    FROM audit_logs a
   WHERE a.company_id IS NOT DISTINCT FROM NEW.company_id
   ORDER BY a.chain_seq DESC
   LIMIT 1;
  NEW.chain_seq := coalesce(last_seq, 0) + 1;
  NEW.prev_hash := last_hash;
  IF NEW.occurred_at IS NULL THEN NEW.occurred_at := clock_timestamp(); END IF;
  NEW.row_hash := sha256(coalesce(last_hash, '\x'::bytea) || convert_to(audit_logs_canonical(NEW), 'UTF8'));
  RETURN NEW;
END $$;

-- Verifica la cadena de una empresa (NULL = cadena de plataforma). Devuelve las filas rotas; vacío = íntegra.
CREATE OR REPLACE FUNCTION public.audit_logs_verify_chain(p_company_id uuid)
RETURNS TABLE (chain_seq bigint, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  r audit_logs;
  expected_prev bytea := NULL;
  expected_seq bigint := 1;
BEGIN
  IF p_company_id IS DISTINCT FROM app_company_id() AND NOT pg_has_role(session_user, 'escudo_platform', 'MEMBER') THEN
    RAISE EXCEPTION 'solo se puede verificar la cadena de la empresa activa' USING ERRCODE = 'insufficient_privilege';
  END IF;
  FOR r IN SELECT * FROM audit_logs a WHERE a.company_id IS NOT DISTINCT FROM p_company_id ORDER BY a.chain_seq LOOP
    IF r.chain_seq <> expected_seq THEN
      chain_seq := r.chain_seq; problem := 'secuencia discontinua (se esperaba ' || expected_seq || ')'; RETURN NEXT;
    END IF;
    IF r.prev_hash IS DISTINCT FROM expected_prev THEN
      chain_seq := r.chain_seq; problem := 'prev_hash no coincide con la fila anterior'; RETURN NEXT;
    END IF;
    IF r.row_hash <> sha256(coalesce(r.prev_hash, '\x'::bytea) || convert_to(audit_logs_canonical(r), 'UTF8')) THEN
      chain_seq := r.chain_seq; problem := 'row_hash no corresponde al contenido'; RETURN NEXT;
    END IF;
    expected_prev := r.row_hash;
    expected_seq := r.chain_seq + 1;
  END LOOP;
END $$;

CREATE TRIGGER trg_audit_logs_chain BEFORE INSERT ON audit_logs FOR EACH ROW EXECUTE FUNCTION trg_audit_logs_chain();

-- ------------------------------------------------------------------ Feature flags
-- Recalcula feature_flags de una empresa desde su suscripción (plan acumulativo + complementos).
-- Regla: lo que deja de estar contratado pasa a read_only (nunca se borra); lo nunca contratado queda locked.
-- Las excepciones manuales (source = 'override') vigentes se respetan.
CREATE OR REPLACE FUNCTION public.refresh_feature_flags(p_company_id uuid) RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  sub subscriptions;
  m record;
  new_mode text;
  new_source text;
  n integer := 0;
  is_managed boolean;
BEGIN
  IF p_company_id IS DISTINCT FROM app_company_id()
     AND NOT EXISTS (SELECT 1 FROM companies c WHERE c.id = p_company_id AND c.account_id = app_account_id())
     AND NOT pg_has_role(session_user, 'escudo_platform', 'MEMBER') THEN
    RAISE EXCEPTION 'sin contexto para la empresa %', p_company_id USING ERRCODE = 'insufficient_privilege';
  END IF;
  SELECT * INTO sub FROM subscriptions s
   WHERE s.company_id = p_company_id AND s.deleted_at IS NULL AND s.status NOT IN ('cancelled', 'trial_expired')
   ORDER BY s.started_at DESC LIMIT 1;
  SELECT managed_by_account_id IS NOT NULL INTO is_managed FROM companies WHERE id = p_company_id;

  FOR m IN
    SELECT mo.code, mo.plan_code,
           EXISTS (SELECT 1 FROM plan_modules pm WHERE pm.plan_id = sub.plan_id AND pm.module_code = mo.code) AS in_plan,
           EXISTS (SELECT 1 FROM subscription_addons sa JOIN addons a ON a.id = sa.addon_id
                    WHERE sa.subscription_id = sub.id AND sa.status = 'active' AND sa.deleted_at IS NULL
                      AND (sa.company_id IS NULL OR sa.company_id = p_company_id)
                      AND a.module_code = mo.code) AS in_addon,
           f.mode AS old_mode, f.source AS old_source, f.valid_until AS old_until, f.company_enabled AS old_company_enabled
      FROM modules mo
      LEFT JOIN feature_flags f ON f.company_id = p_company_id AND f.module_code = mo.code AND f.deleted_at IS NULL
     WHERE mo.deleted_at IS NULL
  LOOP
    IF m.old_source = 'override' AND (m.old_until IS NULL OR m.old_until > now()) THEN
      CONTINUE;
    END IF;
    IF m.code = 'CON' AND is_managed THEN
      new_mode := 'enabled'; new_source := 'plan';
    ELSIF sub.id IS NOT NULL AND (m.in_plan OR m.in_addon) THEN
      new_mode := CASE WHEN sub.status IN ('read_only') THEN 'read_only' ELSE 'enabled' END;
      new_source := CASE WHEN m.in_plan THEN (CASE WHEN sub.status = 'trialing' THEN 'trial' ELSE 'plan' END) ELSE 'addon' END;
    ELSIF m.old_mode IN ('enabled', 'read_only', 'disabled_by_company') THEN
      new_mode := 'read_only'; new_source := 'downgrade';
    ELSE
      new_mode := 'locked'; new_source := 'plan';
    END IF;
    -- Activación por empresa (AUL, VTA): incluido en el plan pero desactivado por la empresa = disabled_by_company.
    -- VTA nace desactivado; VTA además exige AUL activo.
    IF new_mode = 'enabled' AND m.code = ANY (company_toggleable_modules())
       AND (NOT coalesce(m.old_company_enabled, m.code <> 'VTA')
            OR (m.code = 'VTA' AND EXISTS (SELECT 1 FROM feature_flags a WHERE a.company_id = p_company_id AND a.module_code = 'AUL'
                                             AND NOT a.company_enabled AND a.deleted_at IS NULL))) THEN
      new_mode := 'disabled_by_company'; new_source := 'company_setting';
    END IF;
    -- company_enabled solo se fija al crear el flag (VTA en falso); después lo decide la empresa.
    INSERT INTO feature_flags (company_id, module_code, mode, source, valid_from, company_enabled)
    VALUES (p_company_id, m.code, new_mode, new_source, now(), m.code <> 'VTA')
    ON CONFLICT (company_id, module_code) WHERE deleted_at IS NULL
    DO UPDATE SET mode = EXCLUDED.mode, source = EXCLUDED.source, valid_from = now(), valid_until = NULL
     WHERE feature_flags.mode IS DISTINCT FROM EXCLUDED.mode OR feature_flags.source IS DISTINCT FROM EXCLUDED.source;
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;

-- ------------------------------------------------------------------ Alta de empresa
-- seed_company_defaults(company_id): deja lista una empresa recién creada.
--  · sede principal y área «General» si no existen
--  · criterio de riesgo propio (copia del criterio por defecto de la plataforma, editable por la empresa)
--  · tipo de fotocheck «Fotocheck SST» con requisitos base (inducción, aptitud EMO vigente, SCTR)
--  · tableros por defecto por rol, con widgets de los KPI globales
--  · feature flags calculados desde la suscripción (todo locked si aún no tiene); AUL activo y VTA desactivado
--    por defecto dentro del plan (activación por empresa, feature_flags.company_enabled / mode disabled_by_company)
--  · evento en la bitácora
-- Idempotente: puede ejecutarse varias veces sin duplicar.
CREATE OR REPLACE FUNCTION public.seed_company_defaults(p_company_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  co companies;
  v_site uuid;
  v_area uuid;
  v_crit uuid;
  v_ctype uuid;
  v_dash uuid;
  v_user uuid := app_user_id();
  r record;
  pos integer;
  flags integer;
  res jsonb := '{}'::jsonb;
BEGIN
  SELECT * INTO co FROM companies WHERE id = p_company_id AND deleted_at IS NULL;
  IF co.id IS NULL THEN
    RAISE EXCEPTION 'empresa % no existe', p_company_id USING ERRCODE = 'no_data_found';
  END IF;
  IF p_company_id IS DISTINCT FROM app_company_id() AND co.account_id IS DISTINCT FROM app_account_id()
     AND NOT pg_has_role(session_user, 'escudo_platform', 'MEMBER') THEN
    RAISE EXCEPTION 'sin contexto para la empresa %', p_company_id USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Sede principal y área General
  SELECT id INTO v_site FROM sites WHERE company_id = p_company_id AND is_main AND deleted_at IS NULL;
  IF v_site IS NULL THEN
    INSERT INTO sites (company_id, code, name, site_type, address, ubigeo, is_main, created_by)
    VALUES (p_company_id, 'SEDE-01', 'Sede principal', 'office', co.fiscal_address, co.ubigeo, true, v_user)
    RETURNING id INTO v_site;
    res := res || jsonb_build_object('site_id', v_site);
  END IF;
  SELECT id INTO v_area FROM areas WHERE company_id = p_company_id AND site_id = v_site AND code = 'GEN' AND deleted_at IS NULL;
  IF v_area IS NULL THEN
    INSERT INTO areas (company_id, site_id, code, name, created_by)
    VALUES (p_company_id, v_site, 'GEN', 'General', v_user) RETURNING id INTO v_area;
  END IF;

  -- Criterio de evaluación de riesgos propio (copia del global por defecto)
  SELECT id INTO v_crit FROM risk_criteria WHERE company_id = p_company_id AND is_default AND deleted_at IS NULL;
  IF v_crit IS NULL THEN
    INSERT INTO risk_criteria (company_id, code, name, version_number, method, probability_scale, severity_scale,
                               probability_index_factors, level_bands, significant_from_level, is_default, status, created_by)
    SELECT p_company_id, g.code, g.name, 1, g.method, g.probability_scale, g.severity_scale,
           g.probability_index_factors, g.level_bands, g.significant_from_level, true, 'active', v_user
      FROM risk_criteria g
     WHERE g.company_id IS NULL AND g.is_default AND g.status = 'active' AND g.deleted_at IS NULL
     LIMIT 1
    RETURNING id INTO v_crit;
  END IF;

  -- Tipo de fotocheck base
  SELECT id INTO v_ctype FROM credential_types WHERE company_id = p_company_id AND code = 'FOTOCHECK-SST' AND deleted_at IS NULL;
  IF v_ctype IS NULL THEN
    INSERT INTO credential_types (company_id, code, name, description, validity_months, applies_to, created_by)
    VALUES (p_company_id, 'FOTOCHECK-SST', 'Fotocheck SST',
            'Credencial SST con QR verificable. Habilitada solo si cumple los requisitos configurados.', 12, 'both', v_user)
    RETURNING id INTO v_ctype;
    INSERT INTO credential_requirements (company_id, credential_type_id, requirement_type, description, is_blocking, created_by)
    VALUES (p_company_id, v_ctype, 'induction', 'Inducción SST vigente', true, v_user),
           (p_company_id, v_ctype, 'emo_fitness', 'Aptitud médica vigente (apto o apto con restricciones)', true, v_user),
           (p_company_id, v_ctype, 'sctr', 'SCTR salud y pensión vigente', true, v_user);
  END IF;

  -- Tableros por defecto
  FOR r IN SELECT * FROM (VALUES ('sst_manager', 'Panel SST'), ('management', 'Panel de gerencia'),
                                 ('committee_member', 'Panel del Comité SST'), ('area_lead', 'Panel de mi área')) v(role_code, title) LOOP
    SELECT id INTO v_dash FROM dashboards WHERE company_id = p_company_id AND audience_role = r.role_code AND is_default AND deleted_at IS NULL;
    IF v_dash IS NULL THEN
      INSERT INTO dashboards (company_id, name, audience_role, is_default, created_by)
      VALUES (p_company_id, r.title, r.role_code, true, v_user) RETURNING id INTO v_dash;
      pos := 0;
      INSERT INTO dashboard_widgets (company_id, dashboard_id, kpi_definition_id, widget_type, title, position, created_by)
      SELECT p_company_id, v_dash, k.id,
             CASE WHEN k.code IN ('frequency_index', 'severity_index', 'accident_rate') THEN 'line' ELSE 'traffic_light' END,
             k.name, row_number() OVER (ORDER BY k.code), v_user
        FROM kpi_definitions k
       WHERE k.company_id IS NULL AND k.is_active AND k.deleted_at IS NULL
         AND (r.role_code IN ('sst_manager', 'management')
              OR (r.role_code = 'committee_member' AND k.module_code IN ('PAS', 'PCA', 'ACC', 'EST', 'INS', 'ACR'))
              OR (r.role_code = 'area_lead' AND k.module_code IN ('INS', 'ACR', 'EPP', 'CAP')));
    END IF;
  END LOOP;

  flags := refresh_feature_flags(p_company_id);

  INSERT INTO audit_logs (company_id, actor_user_id, actor_type, action, module_code, entity_type, entity_id, changes)
  VALUES (p_company_id, v_user, CASE WHEN v_user IS NULL THEN 'system' ELSE 'user' END, 'seed_defaults', 'TEN',
          'companies', p_company_id, jsonb_build_object('feature_flags', flags));

  RETURN res || jsonb_build_object('company_id', p_company_id, 'main_site_id', v_site, 'general_area_id', v_area,
                                   'risk_criteria_id', v_crit, 'credential_type_id', v_ctype, 'feature_flags', flags);
END $$;

-- ------------------------------------------------------------------ Funciones para flujos sin empresa activa
-- Login: busca por correo sin exponer la tabla users (RLS solo deja ver al propio usuario y a los de la empresa activa).
CREATE OR REPLACE FUNCTION public.app_auth_lookup_user(p_email text)
RETURNS TABLE (id uuid, password_hash text, status text, mfa_enabled boolean, locked_until timestamptz, is_platform_staff boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT u.id, u.password_hash, u.status, u.mfa_enabled, u.locked_until, u.is_platform_staff
    FROM users u WHERE lower(u.email) = lower(p_email) AND u.deleted_at IS NULL
$$;

-- Login con DNI (SCR-USR-01): por el HMAC del documento del trabajador vinculado a la membresía o a la cuenta.
-- Devuelve todas las coincidencias: la aplicación solo acepta una.
CREATE OR REPLACE FUNCTION public.app_auth_lookup_user_by_document(p_hash bytea)
RETURNS TABLE (id uuid, password_hash text, status text, mfa_enabled boolean, locked_until timestamptz, is_platform_staff boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT u.id, u.password_hash, u.status, u.mfa_enabled, u.locked_until, u.is_platform_staff
    FROM users u
   WHERE u.deleted_at IS NULL
     AND u.id IN (
       SELECT m.user_id FROM memberships m JOIN workers w ON w.id = m.worker_id
        WHERE w.document_number_hash = p_hash AND w.deleted_at IS NULL AND m.deleted_at IS NULL AND m.status = 'active'
       UNION
       SELECT w.user_id FROM workers w
        WHERE w.document_number_hash = p_hash AND w.deleted_at IS NULL AND w.user_id IS NOT NULL)
$$;

-- Selector de empresa: membresías activas del usuario actual (app.user_id), en todas sus empresas.
CREATE OR REPLACE FUNCTION public.app_my_memberships()
RETURNS TABLE (membership_id uuid, company_id uuid, ruc char(11), company_name text, role_code text, expires_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT m.id, c.id, c.ruc, coalesce(c.trade_name, c.legal_name), r.code, m.expires_at
    FROM memberships m
    JOIN companies c ON c.id = m.company_id AND c.deleted_at IS NULL
    JOIN roles r ON r.id = m.role_id
   WHERE m.user_id = app_user_id() AND m.status = 'active' AND m.deleted_at IS NULL
     AND (m.expires_at IS NULL OR m.expires_at > now())
$$;

-- ------------------------------------------------------------------ Endpoints públicos (sin sesión)
-- Verificación pública de fotocheck por token del QR. Devuelve solo lo especificado en FOT (nunca datos médicos)
-- y registra la verificación (inalterable). Respuesta idéntica para token inexistente.
CREATE OR REPLACE FUNCTION public.public_verify_credential(p_token text, p_channel text DEFAULT 'public_qr',
                                                           p_ip_hash bytea DEFAULT NULL, p_user_agent text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  cr credentials;
  v_result text;
  v_name text;
  v_position text;
  v_company text;
  out jsonb;
BEGIN
  SELECT * INTO cr FROM credentials WHERE token_hash = sha256(convert_to(p_token, 'UTF8')) AND deleted_at IS NULL;
  IF cr.id IS NULL THEN
    RETURN jsonb_build_object('result', 'invalid');
  END IF;
  v_result := CASE cr.status WHEN 'active' THEN 'enabled' WHEN 'revoked' THEN 'revoked' WHEN 'expired' THEN 'expired'
                             ELSE 'not_enabled' END;
  IF v_result = 'enabled' AND cr.expires_on IS NOT NULL AND cr.expires_on < (now() AT TIME ZONE 'America/Lima')::date THEN
    v_result := 'expired';
  END IF;
  IF cr.worker_id IS NOT NULL THEN
    SELECT w.first_name || ' ' || w.paternal_last_name, p.name INTO v_name, v_position
      FROM workers w LEFT JOIN positions p ON p.id = w.current_position_id WHERE w.id = cr.worker_id;
  ELSE
    SELECT w.first_name || ' ' || w.paternal_last_name, w.position_text INTO v_name, v_position
      FROM contractor_workers w WHERE w.id = cr.contractor_worker_id;
  END IF;
  SELECT coalesce(trade_name, legal_name) INTO v_company FROM companies WHERE id = cr.company_id;
  out := jsonb_build_object('result', v_result, 'credential_number', cr.credential_number, 'name', v_name,
                            'position', v_position, 'company', v_company, 'expires_on', cr.expires_on,
                            'blocking_reasons', CASE WHEN v_result = 'not_enabled' THEN coalesce(cr.blocking_reasons, '[]'::jsonb) ELSE '[]'::jsonb END);
  INSERT INTO credential_verifications (company_id, credential_id, channel, result, response_snapshot, ip_hash, user_agent)
  VALUES (cr.company_id, cr.id, p_channel, v_result, out, p_ip_hash, p_user_agent);
  RETURN out;
END $$;

-- Reporte por QR: datos mínimos del punto (sede/área) para mostrar el formulario público.
CREATE OR REPLACE FUNCTION public.public_report_point(p_token text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('company', coalesce(c.trade_name, c.legal_name), 'site', s.name, 'area', a.name,
                            'location', rp.location_description, 'allow_anonymous', rp.allow_anonymous)
    FROM report_points rp
    JOIN companies c ON c.id = rp.company_id
    JOIN sites s ON s.id = rp.site_id
    LEFT JOIN areas a ON a.id = rp.area_id
   WHERE rp.token_hash = sha256(convert_to(p_token, 'UTF8')) AND rp.is_active AND rp.revoked_at IS NULL AND rp.deleted_at IS NULL
$$;

-- Reporte por QR: registra el acto/condición (idempotente por p_idempotency_key) y devuelve el código de seguimiento.
CREATE OR REPLACE FUNCTION public.public_submit_report(p_token text, p_report_type text, p_description text,
                                                       p_is_anonymous boolean, p_photo_file_id uuid DEFAULT NULL,
                                                       p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  rp report_points;
  v_id uuid;
  v_code text;
BEGIN
  SELECT * INTO rp FROM report_points
   WHERE token_hash = sha256(convert_to(p_token, 'UTF8')) AND is_active AND revoked_at IS NULL AND deleted_at IS NULL;
  IF rp.id IS NULL THEN
    RAISE EXCEPTION 'punto de reporte no válido' USING ERRCODE = 'no_data_found';
  END IF;
  IF p_is_anonymous AND NOT rp.allow_anonymous THEN
    RAISE EXCEPTION 'este punto no admite reportes anónimos' USING ERRCODE = 'check_violation';
  END IF;
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id, code INTO v_id, v_code FROM substandard_reports
     WHERE company_id = rp.company_id AND idempotency_key = p_idempotency_key;
    IF v_id IS NOT NULL THEN RETURN jsonb_build_object('id', v_id, 'code', v_code, 'replay', true); END IF;
  END IF;
  v_code := 'R-' || to_char(now() AT TIME ZONE 'America/Lima', 'YYMMDD') || '-' || upper(substr(md5(random()::text), 1, 5));
  INSERT INTO substandard_reports (company_id, code, report_type, origin, report_point_id, site_id, area_id, description,
                                   photo_file_id, is_anonymous, ip_hash, idempotency_key)
  VALUES (rp.company_id, v_code, p_report_type, 'qr', rp.id, rp.site_id, rp.area_id, p_description,
          p_photo_file_id, p_is_anonymous, p_ip_hash, p_idempotency_key)
  RETURNING id INTO v_id;
  UPDATE report_points SET report_count = report_count + 1, last_used_at = now() WHERE id = rp.id;
  RETURN jsonb_build_object('id', v_id, 'code', v_code, 'replay', false);
END $$;

-- Link compartido del expediente SUNAFIL: valida vencimiento, revocación y límite de vistas; cuenta la vista y la audita.
CREATE OR REPLACE FUNCTION public.public_open_dossier(p_token text, p_ip inet DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  l dossier_share_links;
  d inspection_dossiers;
BEGIN
  SELECT * INTO l FROM dossier_share_links WHERE token_hash = sha256(convert_to(p_token, 'UTF8')) AND deleted_at IS NULL FOR UPDATE;
  IF l.id IS NULL OR l.status <> 'active' THEN
    RETURN jsonb_build_object('result', 'invalid');
  END IF;
  IF l.expires_at <= now() THEN
    UPDATE dossier_share_links SET status = 'expired' WHERE id = l.id;
    RETURN jsonb_build_object('result', 'invalid');
  END IF;
  IF l.max_views IS NOT NULL AND l.view_count >= l.max_views THEN
    UPDATE dossier_share_links SET status = 'exhausted' WHERE id = l.id;
    RETURN jsonb_build_object('result', 'invalid');
  END IF;
  UPDATE dossier_share_links SET view_count = view_count + 1, last_accessed_at = now(),
         status = CASE WHEN max_views IS NOT NULL AND view_count + 1 >= max_views THEN 'exhausted' ELSE status END
   WHERE id = l.id;
  SELECT * INTO d FROM inspection_dossiers WHERE id = l.dossier_id;
  INSERT INTO audit_logs (company_id, actor_type, action, module_code, entity_type, entity_id, ip, changes)
  VALUES (l.company_id, 'public', 'share_link_view', 'SUN', 'dossier_share_links', l.id, p_ip,
          jsonb_build_object('view', l.view_count + 1));
  RETURN jsonb_build_object('result', 'ok', 'dossier_id', d.id, 'title', d.title, 'period_from', d.period_from,
                            'period_to', d.period_to, 'status', d.status, 'allow_download', l.allow_download,
                            'items', (SELECT coalesce(jsonb_agg(jsonb_build_object('section', i.section_code, 'title', i.title,
                                                       'status', i.status, 'file_id', CASE WHEN l.allow_download THEN i.file_id END)
                                                       ORDER BY i.sort_order), '[]'::jsonb)
                                        FROM dossier_items i WHERE i.dossier_id = d.id AND i.deleted_at IS NULL));
END $$;

-- ------------------------------------------------------------------ CAP · verificación pública de certificados
-- Consulta por verification_code (aleatorio, no secuencial). Devuelve solo nombre, documento enmascarado, curso, horas,
-- fechas, empresa emisora y estado; nunca correo, teléfono ni nota si el curso no la muestra. Registra la consulta (inalterable).
-- Código inexistente: respuesta idéntica 'invalid' y sin registro (no hay empresa a la que imputarlo; lo cubre el límite de uso).
CREATE OR REPLACE FUNCTION public.public_verify_certificate(p_code text, p_channel text DEFAULT 'public_web',
                                                            p_ip_hash bytea DEFAULT NULL, p_user_agent text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  c training_certificates;
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  v_result text;
  v_company text;
  out jsonb;
BEGIN
  IF length(v_code) < 12 OR length(v_code) > 32 THEN
    RETURN jsonb_build_object('result', 'invalid');
  END IF;
  SELECT * INTO c FROM training_certificates WHERE verification_code = v_code AND deleted_at IS NULL;
  IF c.id IS NULL THEN
    RETURN jsonb_build_object('result', 'invalid');
  END IF;
  v_result := CASE
    WHEN NOT c.public_verification_enabled THEN 'not_public'
    WHEN c.status = 'voided' THEN 'voided'
    WHEN c.status = 'pending_validation' THEN 'pending_validation'
    WHEN c.status = 'expired' OR (c.expires_on IS NOT NULL AND c.expires_on < (now() AT TIME ZONE 'America/Lima')::date) THEN 'expired'
    ELSE 'valid' END;
  SELECT coalesce(trade_name, legal_name) INTO v_company FROM companies WHERE id = c.company_id;
  IF v_result = 'not_public' THEN
    out := jsonb_build_object('result', 'not_public', 'company', v_company);
  ELSE
    out := jsonb_build_object('result', v_result, 'certificate_code', c.certificate_code, 'holder_name', c.holder_name,
                              'holder_document_masked', c.holder_document_masked, 'course_title', c.course_title,
                              'hours', c.hours, 'issued_on', c.issued_on, 'expires_on', c.expires_on, 'company', v_company);
  END IF;
  INSERT INTO certificate_verifications (company_id, certificate_id, queried_code, channel, result, response_snapshot, ip_hash, user_agent)
  VALUES (c.company_id, c.id, v_code, p_channel, v_result, out, p_ip_hash, left(p_user_agent, 300));
  RETURN out;
END $$;

-- ------------------------------------------------------------------ VTA · catálogo público y webhook de pasarela
-- Catálogo público de cursos a la venta de una empresa (por su catalog_slug). Solo ofertas publicadas, visibles y vigentes,
-- de cursos publicados, y solo si la empresa tiene VTA habilitado y activo. Sin datos personales.
CREATE OR REPLACE FUNCTION public.public_course_catalog(p_company_slug text) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  co companies;
BEGIN
  SELECT * INTO co FROM companies WHERE catalog_slug = lower(p_company_slug) AND status = 'active' AND deleted_at IS NULL;
  IF co.id IS NULL OR NOT EXISTS (SELECT 1 FROM feature_flags f WHERE f.company_id = co.id AND f.module_code = 'VTA'
                                     AND f.mode = 'enabled' AND f.deleted_at IS NULL) THEN
    RETURN jsonb_build_object('result', 'not_found');
  END IF;
  RETURN jsonb_build_object('result', 'ok', 'company', coalesce(co.trade_name, co.legal_name),
    'offers', (SELECT coalesce(jsonb_agg(jsonb_build_object(
                  'slug', o.slug, 'title', o.title, 'short_description', o.short_description, 'currency', o.currency,
                  'list_price', o.list_price, 'sale_price', o.sale_price, 'access_days', o.access_days,
                  'seats_available', CASE WHEN o.seats_total IS NULL THEN NULL ELSE o.seats_total - o.seats_sold END,
                  'allows_company_purchase', o.allows_company_purchase, 'hours', c.hours, 'modality', c.delivery_mode,
                  'cover_file_id', c.cover_file_id, 'promo_video_id', c.promo_video_id) ORDER BY o.title), '[]'::jsonb)
                 FROM course_offers o JOIN courses c ON c.id = o.course_id AND c.status = 'published' AND c.deleted_at IS NULL
                WHERE o.company_id = co.id AND o.status = 'published' AND o.is_public AND o.deleted_at IS NULL
                  AND (o.sale_starts_at IS NULL OR o.sale_starts_at <= now()) AND (o.sale_ends_at IS NULL OR o.sale_ends_at > now())));
END $$;

-- Contexto de un webhook de pasarela: con el id de la pasarela de la URL, devuelve la empresa y la referencia al secreto
-- de firma para que la aplicación verifique la firma y luego fije app.company_id. Nunca devuelve secretos en claro.
CREATE OR REPLACE FUNCTION public.payment_gateway_webhook_context(p_gateway_id uuid, p_provider text)
RETURNS TABLE (company_id uuid, payment_gateway_id uuid, provider text, mode text, webhook_secret_ref text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT g.company_id, g.id, g.provider, g.mode, g.webhook_secret_ref
    FROM payment_gateways g
   WHERE g.id = p_gateway_id AND g.provider = p_provider AND g.is_active AND g.deleted_at IS NULL
$$;

-- ------------------------------------------------------------------ WEB · sitio público y CMS (módulo interno)
-- Las 14 tablas WEB son de plataforma (sin company_id): solo escudo_platform las lee y escribe (RLS forzado) y la app de
-- empresa no tiene privilegios sobre ellas. Lo público sale por las funciones public_* (SECURITY DEFINER), que devuelven
-- únicamente contenido publicado (nunca borradores) o insertan registros acotados (cookies, aceptaciones, reclamos, demos).
-- El límite de uso por IP, el captcha y el cifrado de datos personales ($) los aplica la API antes de llamar a estas funciones.

-- Parámetro legal de plataforma (company_id NULL) vigente en una fecha; no depende del contexto de empresa.
CREATE OR REPLACE FUNCTION public.platform_legal_param(p_key text, p_on date DEFAULT current_date) RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT value FROM legal_parameters
   WHERE key = p_key AND company_id IS NULL AND deleted_at IS NULL
     AND valid_from <= p_on AND (valid_to IS NULL OR valid_to >= p_on)
   ORDER BY valid_from DESC
   LIMIT 1
$$;

-- Suma días hábiles (lunes a viernes, sin feriados nacionales de `holidays`) a una fecha.
CREATE OR REPLACE FUNCTION public.add_business_days(p_from date, p_days integer) RETURNS date
LANGUAGE plpgsql STABLE AS $$
DECLARE
  d date := p_from;
  n integer := 0;
BEGIN
  IF p_days IS NULL OR p_days < 0 THEN
    RAISE EXCEPTION 'días hábiles inválidos: %', p_days USING ERRCODE = 'invalid_parameter_value';
  END IF;
  WHILE n < p_days LOOP
    d := d + 1;
    IF extract(isodow FROM d) < 6 AND NOT EXISTS (
         SELECT 1 FROM holidays h WHERE h.holiday_on = d AND h.scope = 'national' AND h.is_non_working AND h.deleted_at IS NULL) THEN
      n := n + 1;
    END IF;
  END LOOP;
  RETURN d;
END $$;

-- Versión de documento legal publicada o reemplazada: no se edita. Solo se permite published → superseded.
CREATE OR REPLACE FUNCTION public.trg_legal_document_versions_lock() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  free text[] := ARRAY['status', 'superseded_at', 'updated_at', 'updated_by'];
BEGIN
  IF OLD.status IN ('published', 'superseded') THEN
    IF (to_jsonb(NEW) - free) IS DISTINCT FROM (to_jsonb(OLD) - free)
       OR NOT (NEW.status = OLD.status OR (OLD.status = 'published' AND NEW.status = 'superseded')) THEN
      RAISE EXCEPTION 'La versión % del documento legal ya fue publicada y no se edita: cree una nueva versión', OLD.version_label
        USING ERRCODE = 'insufficient_privilege';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_legal_document_versions_lock BEFORE UPDATE ON legal_document_versions
  FOR EACH ROW EXECUTE FUNCTION trg_legal_document_versions_lock();

-- Hoja de reclamación: los datos registrados (proveedor, consumidor, bien, detalle, pedido, plazos calculados) no cambian;
-- solo avanzan el estado, la prórroga, la asignación y la respuesta, con transiciones válidas. Una hoja cerrada no cambia.
CREATE OR REPLACE FUNCTION public.trg_consumer_complaints_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  free text[] := ARRAY['status', 'extended_until', 'extension_reason', 'assigned_to', 'response_text', 'response_channel',
                       'answered_at', 'answered_by', 'closed_at', 'closed_by', 'acknowledgment_sent_at', 'related_account_id',
                       'updated_at', 'updated_by'];
BEGIN
  IF (to_jsonb(NEW) - free) IS DISTINCT FROM (to_jsonb(OLD) - free) THEN
    RAISE EXCEPTION 'La hoja % no se modifica: solo cambian estado, prórroga, asignación y respuesta', OLD.complaint_code
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF OLD.status = 'closed' THEN
    RAISE EXCEPTION 'La hoja % está cerrada', OLD.complaint_code USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NEW.status <> OLD.status AND NOT (
       (OLD.status = 'received' AND NEW.status IN ('in_progress', 'extended', 'answered')) OR
       (OLD.status = 'in_progress' AND NEW.status IN ('extended', 'answered')) OR
       (OLD.status = 'extended' AND NEW.status = 'answered') OR
       (OLD.status = 'answered' AND NEW.status = 'closed')) THEN
    RAISE EXCEPTION 'Transición no permitida en la hoja %: % → %', OLD.complaint_code, OLD.status, NEW.status
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.answered_at IS NOT NULL AND (NEW.response_text IS DISTINCT FROM OLD.response_text OR NEW.answered_at IS DISTINCT FROM OLD.answered_at) THEN
    RAISE EXCEPTION 'La respuesta de la hoja % ya fue emitida', OLD.complaint_code USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF OLD.extended_until IS NOT NULL AND NEW.extended_until IS DISTINCT FROM OLD.extended_until THEN
    RAISE EXCEPTION 'La hoja % ya fue prorrogada una vez', OLD.complaint_code USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_consumer_complaints_guard BEFORE UPDATE ON consumer_complaints
  FOR EACH ROW EXECUTE FUNCTION trg_consumer_complaints_guard();

-- ---------- Lectura pública (solo publicado) ----------
-- Datos públicos del titular y del sitio (pie de página, Libro de Reclamaciones, Organization en JSON-LD).
CREATE OR REPLACE FUNCTION public.public_site_settings() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((SELECT jsonb_build_object(
           'legal_name', s.legal_name, 'trade_name', s.trade_name, 'ruc', s.ruc, 'legal_address', s.legal_address,
           'primary_domain', s.primary_domain, 'contact_email', s.contact_email, 'sales_email', s.sales_email,
           'support_email', s.support_email, 'privacy_email', s.privacy_email, 'contact_phone', s.contact_phone,
           'whatsapp_number', s.whatsapp_number, 'whatsapp_default_message', s.whatsapp_default_message, 'blog_url', s.blog_url,
           'show_latest_blog_posts', s.show_latest_blog_posts, 'latest_blog_posts_count', s.latest_blog_posts_count,
           'hero_video_urls', s.hero_video_urls, 'announcement_bar', s.announcement_bar,
           'trust_badges', s.trust_badges_json, 'interactive_demo_url', s.interactive_demo_url,
           'complaints_officer_name', s.complaints_officer_name,
           'social_links', s.social_links, 'analytics_ids', s.analytics_ids,
           'search_console_verification', s.search_console_verification, 'logo_file_id', s.logo_file_id,
           'logo_dark_file_id', s.logo_dark_file_id, 'favicon_file_id', s.favicon_file_id,
           'default_og_image_file_id', s.default_og_image_file_id, 'brand_colors', s.brand_colors,
           'default_locale', s.default_locale, 'maintenance_mode', s.maintenance_mode)
         FROM site_settings s WHERE s.singleton AND s.deleted_at IS NULL), '{}'::jsonb)
$$;

-- Página publicada por slug (NULL o '' = portada). Devuelve solo la copia publicada; borrador o archivada = not_found.
CREATE OR REPLACE FUNCTION public.public_site_page(p_slug text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('result', 'ok', 'slug', p.slug, 'page_type', p.page_type, 'sector_code', p.sector_code,
                              'whatsapp_message', coalesce(p.whatsapp_message, (SELECT s.whatsapp_default_message FROM site_settings s WHERE s.singleton)),
                              'published_at', p.published_at) || p.published_snapshot
      FROM site_pages p
     WHERE p.status = 'published' AND p.deleted_at IS NULL AND p.published_snapshot IS NOT NULL
       AND p.page_type <> 'campaign'  -- las landings de campaña solo salen por public_campaign_page (vigencia)
       AND (CASE WHEN coalesce(p_slug, '') = '' THEN p.page_type = 'home' ELSE p.slug = lower(p_slug) END)
     LIMIT 1), jsonb_build_object('result', 'not_found'))
$$;

-- Menú activo por ubicación. Los ítems que apuntan a una página solo se devuelven si esa página está publicada.
CREATE OR REPLACE FUNCTION public.public_site_menu(p_location text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('result', 'ok', 'location', m.location,
             'items', coalesce((SELECT jsonb_agg(i ORDER BY o)
                                  FROM jsonb_array_elements(m.items) WITH ORDINALITY AS x(i, o)
                                 WHERE NOT (i ? 'page_slug') OR EXISTS (
                                       SELECT 1 FROM site_pages p WHERE p.slug = i ->> 'page_slug' AND p.status = 'published' AND p.deleted_at IS NULL)),
                               '[]'::jsonb))
      FROM site_menus m WHERE m.location = p_location AND m.is_active AND m.deleted_at IS NULL LIMIT 1),
    jsonb_build_object('result', 'not_found'))
$$;

-- Planes públicos con precio (price_reference; NULL = «Solicitar cotización»), complementos y comparativa por módulo.
-- Cambiar un plan en el panel lo cambia en la web. Los módulos internos (SUS, WEB) no se listan.
CREATE OR REPLACE FUNCTION public.public_pricing() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  WITH pl AS (
    SELECT * FROM plans WHERE is_public AND is_active AND deleted_at IS NULL AND code <> 'I')
  SELECT jsonb_build_object(
    'plans', coalesce((SELECT jsonb_agg(jsonb_build_object(
               'code', pl.code, 'name', pl.name, 'description', pl.description, 'includes_plan_codes', pl.includes_plan_codes,
               'price', CASE WHEN pl.price_reference IS NULL THEN NULL ELSE pl.price_reference::text END,
               'price_label', CASE WHEN pl.price_reference IS NULL THEN 'Solicitar cotización' END,
               'currency', pl.currency, 'billing_periods', pl.billing_periods,
               'limits', jsonb_build_object('max_companies', pl.max_companies, 'max_workers', pl.max_workers, 'max_sites', pl.max_sites,
                                            'max_management_users', pl.max_management_users, 'storage_gb', pl.storage_gb,
                                            'qr_report_points', pl.qr_report_points),
               'modules_count', (SELECT count(*) FROM plan_modules pm WHERE pm.plan_id = pl.id))
               ORDER BY pl.sort_order) FROM pl), '[]'::jsonb),
    'addons', coalesce((SELECT jsonb_agg(jsonb_build_object(
               'code', a.code, 'name', a.name, 'description', a.description, 'per_sector', a.is_per_sector,
               'available', a.available_in_v1,
               'price', CASE WHEN a.price_reference IS NULL THEN NULL ELSE a.price_reference::text END,
               'price_label', CASE WHEN a.price_reference IS NULL THEN 'Solicitar cotización' END, 'currency', a.currency)
               ORDER BY a.code) FROM addons a WHERE a.is_active AND a.deleted_at IS NULL), '[]'::jsonb),
    'comparison', coalesce((SELECT jsonb_agg(jsonb_build_object(
               'module_code', m.code, 'number', m.number, 'name', m.name, 'group_number', m.group_number, 'is_addon', m.is_addon,
               'plans', (SELECT coalesce(jsonb_object_agg(pl.code, EXISTS (SELECT 1 FROM plan_modules pm WHERE pm.plan_id = pl.id AND pm.module_code = m.code)), '{}'::jsonb) FROM pl))
               ORDER BY m.group_number, m.number) FROM modules m WHERE m.plan_code NOT IN ('I') AND m.deleted_at IS NULL), '[]'::jsonb))
$$;

-- Otros productos de GRUPO DE SOLUCIONES CREATIVAS visibles en la web.
CREATE OR REPLACE FUNCTION public.public_site_products() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'products', coalesce(jsonb_agg(jsonb_build_object(
           'name', p.name, 'description', p.description, 'logo_file_id', p.logo_file_id, 'url', p.url) ORDER BY p.sort_order, p.name), '[]'::jsonb))
    FROM site_products p WHERE p.is_visible AND p.deleted_at IS NULL
$$;

-- Testimonios aprobados (con consentimiento de publicación, o de ejemplo rotulados como tales). Pendientes y ocultos no salen.
CREATE OR REPLACE FUNCTION public.public_site_testimonials() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'testimonials', coalesce(jsonb_agg(jsonb_build_object(
           'author_name', t.author_name, 'author_role', t.author_role, 'company_name', t.company_name, 'quote', t.quote,
           'rating', t.rating, 'photo_file_id', t.photo_file_id, 'is_example', t.is_example) ORDER BY t.sort_order, t.created_at), '[]'::jsonb))
    FROM site_testimonials t
   WHERE t.status = 'approved' AND t.deleted_at IS NULL AND (t.publication_consent OR t.is_example)
$$;

-- Preguntas frecuentes publicadas (por tema o de una página publicada).
CREATE OR REPLACE FUNCTION public.public_site_faqs(p_topic text DEFAULT NULL, p_page_slug text DEFAULT NULL) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'faqs', coalesce(jsonb_agg(jsonb_build_object(
           'topic', f.topic, 'question', f.question, 'answer', f.answer) ORDER BY f.topic, f.sort_order), '[]'::jsonb))
    FROM site_faqs f LEFT JOIN site_pages p ON p.id = f.page_id
   WHERE f.status = 'published' AND f.deleted_at IS NULL
     AND (p_topic IS NULL OR f.topic = p_topic)
     AND (p_page_slug IS NULL OR (p.slug = p_page_slug AND p.status = 'published' AND p.deleted_at IS NULL))
     AND (f.page_id IS NULL OR (p.status = 'published' AND p.deleted_at IS NULL))
$$;

-- Entradas de sitemap.xml: páginas publicadas e indexables y documentos legales vigentes. La API arma el XML con el dominio
-- de site_settings (el blog en WordPress publica su propio sitemap; robots.txt lo enlaza).
CREATE OR REPLACE FUNCTION public.public_sitemap()
RETURNS TABLE (path text, kind text, last_modified timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT CASE WHEN p.page_type = 'home' THEN '/' ELSE '/' || p.slug END, 'page', greatest(p.published_at, p.updated_at)
    FROM site_pages p WHERE p.status = 'published' AND NOT p.noindex AND p.deleted_at IS NULL AND p.page_type <> 'campaign'
  UNION ALL
  SELECT '/legal/' || d.slug, 'legal', v.published_at
    FROM legal_documents d JOIN legal_document_versions v ON v.id = d.current_version_id AND v.status = 'published'
   WHERE d.is_active AND d.deleted_at IS NULL
$$;

-- Rutas con noindex (para robots.txt y la cabecera X-Robots-Tag).
CREATE OR REPLACE FUNCTION public.public_noindex_paths() RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce(array_agg(x ORDER BY x), '{}') FROM (
    SELECT CASE WHEN page_type = 'campaign' THEN '/l/' ELSE '/' END || slug AS x FROM site_pages
     WHERE status = 'published' AND noindex AND deleted_at IS NULL AND page_type <> 'home') s
$$;

-- Redirección activa de una ruta (301/302); cuenta el uso.
CREATE OR REPLACE FUNCTION public.public_resolve_redirect(p_path text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  r site_redirects;
BEGIN
  UPDATE site_redirects SET hit_count = hit_count + 1, last_hit_at = now()
   WHERE source_path = p_path AND is_active AND deleted_at IS NULL
  RETURNING * INTO r;
  IF r.id IS NULL THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  RETURN jsonb_build_object('result', 'ok', 'target_url', r.target_url, 'status_code', r.status_code);
END $$;

-- Documento legal vigente (versión publicada actual). Sin versión publicada: not_published (nunca el borrador).
CREATE OR REPLACE FUNCTION public.public_legal_document(p_doc_type text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT CASE WHEN v.id IS NULL THEN jsonb_build_object('result', 'not_published', 'doc_type', d.doc_type, 'title', d.title)
           ELSE jsonb_build_object('result', 'ok', 'doc_type', d.doc_type, 'title', d.title, 'slug', d.slug,
                                   'version_id', v.id, 'version_label', v.version_label, 'effective_from', v.effective_from,
                                   'content', v.content, 'summary_of_changes', v.summary_of_changes) END
      FROM legal_documents d
      LEFT JOIN legal_document_versions v ON v.id = d.current_version_id AND v.status = 'published' AND v.deleted_at IS NULL
     WHERE d.doc_type = p_doc_type AND d.is_active AND d.deleted_at IS NULL),
    jsonb_build_object('result', 'not_found'))
$$;

-- ---------- Escritura pública acotada ----------
-- Consentimiento de cookies del visitante (inalterable; cada cambio es una fila). «Necesarias» siempre activas.
CREATE OR REPLACE FUNCTION public.public_record_cookie_consent(p_visitor_id uuid, p_categories jsonb, p_action text,
                                                               p_user_id uuid DEFAULT NULL, p_ip_hash bytea DEFAULT NULL,
                                                               p_user_agent text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v legal_document_versions;
  cats jsonb;
  v_id uuid;
BEGIN
  IF p_visitor_id IS NULL OR jsonb_typeof(p_categories) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'consentimiento de cookies inválido' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT x.* INTO v FROM legal_documents d JOIN legal_document_versions x ON x.id = d.current_version_id AND x.status = 'published'
   WHERE d.doc_type = 'cookies' AND d.deleted_at IS NULL;
  cats := jsonb_build_object('necessary', true,
                             'preferences', coalesce((p_categories ->> 'preferences')::boolean, false) AND p_action NOT IN ('reject_all', 'withdraw'),
                             'analytics', coalesce((p_categories ->> 'analytics')::boolean, false) AND p_action NOT IN ('reject_all', 'withdraw'),
                             'marketing', coalesce((p_categories ->> 'marketing')::boolean, false) AND p_action NOT IN ('reject_all', 'withdraw'));
  IF p_action = 'accept_all' THEN
    cats := jsonb_build_object('necessary', true, 'preferences', true, 'analytics', true, 'marketing', true);
  END IF;
  INSERT INTO cookie_consents (visitor_id, categories, action, policy_version_id, policy_version_label, user_id, ip_hash, user_agent)
  VALUES (p_visitor_id, cats, p_action, v.id, coalesce(v.version_label, 'sin publicar'), p_user_id, p_ip_hash, left(p_user_agent, 300))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'categories', cats, 'policy_version', coalesce(v.version_label, 'sin publicar'));
END $$;

-- Aceptación de la versión vigente de un documento legal (registro autoservicio, re-aceptación o checkout). Idempotente.
-- Solo se acepta la versión publicada actual; una versión vieja o un borrador se rechaza.
CREATE OR REPLACE FUNCTION public.public_record_legal_acceptance(p_version_id uuid, p_context text, p_user_id uuid DEFAULT NULL,
                                                                 p_email text DEFAULT NULL, p_email_hash bytea DEFAULT NULL,
                                                                 p_account_id uuid DEFAULT NULL, p_company_id uuid DEFAULT NULL,
                                                                 p_ip_hash bytea DEFAULT NULL, p_user_agent text DEFAULT NULL,
                                                                 p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v legal_document_versions;
  d legal_documents;
  v_id uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_id FROM legal_acceptances WHERE idempotency_key = p_idempotency_key;
    IF v_id IS NOT NULL THEN RETURN jsonb_build_object('id', v_id, 'replay', true); END IF;
  END IF;
  SELECT * INTO v FROM legal_document_versions WHERE id = p_version_id AND deleted_at IS NULL;
  SELECT * INTO d FROM legal_documents WHERE id = v.legal_document_id AND deleted_at IS NULL;
  IF v.id IS NULL OR v.status <> 'published' OR d.current_version_id IS DISTINCT FROM v.id THEN
    RAISE EXCEPTION 'solo se acepta la versión vigente publicada del documento' USING ERRCODE = 'check_violation';
  END IF;
  INSERT INTO legal_acceptances (legal_document_version_id, legal_document_id, doc_type, version_label, user_id, email, email_hash,
                                 account_id, company_id, context, ip_hash, user_agent, idempotency_key)
  VALUES (v.id, d.id, d.doc_type, v.version_label, p_user_id, p_email, p_email_hash, p_account_id, p_company_id, p_context,
          p_ip_hash, left(p_user_agent, 300), p_idempotency_key)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'doc_type', d.doc_type, 'version_label', v.version_label, 'replay', false);
END $$;

-- Documentos que el usuario de la sesión (app.user_id) debe aceptar o volver a aceptar antes de seguir.
CREATE OR REPLACE FUNCTION public.app_pending_legal_acceptances()
RETURNS TABLE (doc_type text, title text, version_id uuid, version_label text, effective_from timestamptz, is_reacceptance boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT d.doc_type, d.title, v.id, v.version_label, v.effective_from,
         EXISTS (SELECT 1 FROM legal_acceptances a WHERE a.user_id = app_user_id() AND a.legal_document_id = d.id)
    FROM legal_documents d
    JOIN legal_document_versions v ON v.id = d.current_version_id AND v.status = 'published'
   WHERE d.requires_acceptance_on_signup AND d.is_active AND d.deleted_at IS NULL AND app_user_id() IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM legal_acceptances a WHERE a.user_id = app_user_id() AND a.legal_document_version_id = v.id)
     AND (v.requires_reacceptance OR NOT EXISTS (SELECT 1 FROM legal_acceptances a WHERE a.user_id = app_user_id() AND a.legal_document_id = d.id))
$$;

-- Registro de una hoja del Libro de Reclamaciones (idempotente por p_idempotency_key). Los datos personales llegan ya
-- cifrados por la API (Laravel encrypted casts). Copia los datos del proveedor de site_settings, asigna el correlativo
-- anual (candado por año), calcula la fecha límite (días hábiles del parámetro) y la conservación, y registra el evento.
CREATE OR REPLACE FUNCTION public.public_submit_complaint(p_data jsonb, p_tracking_key text, p_ip_hash bytea DEFAULT NULL,
                                                          p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  s site_settings;
  c consumer_complaints;
  v_now timestamptz := now();
  v_day date := (now() AT TIME ZONE 'America/Lima')::date;
  v_year smallint := extract(year FROM (now() AT TIME ZONE 'America/Lima'))::smallint;
  v_seq integer;
  v_days integer;
  v_years integer;
  v_due date;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO c FROM consumer_complaints WHERE idempotency_key = p_idempotency_key;
    IF c.id IS NOT NULL THEN
      RETURN jsonb_build_object('complaint_code', c.complaint_code, 'filed_at', c.filed_at, 'response_due_on', c.response_due_on, 'replay', true);
    END IF;
  END IF;
  IF p_tracking_key IS NULL OR length(p_tracking_key) < 16 THEN
    RAISE EXCEPTION 'clave de seguimiento inválida' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  SELECT * INTO s FROM site_settings WHERE singleton AND deleted_at IS NULL;
  IF s.id IS NULL THEN
    RAISE EXCEPTION 'faltan los datos del proveedor (site_settings)' USING ERRCODE = 'no_data_found';
  END IF;
  v_days := platform_legal_param('web.complaint_response_days', v_day)::integer;
  v_years := platform_legal_param('web.complaint_retention_years', v_day)::integer;
  IF v_days IS NULL OR v_years IS NULL THEN
    RAISE EXCEPTION 'faltan los parámetros legales del Libro de Reclamaciones' USING ERRCODE = 'no_data_found';
  END IF;
  v_due := add_business_days(v_day, v_days);
  PERFORM pg_advisory_xact_lock(hashtext('consumer_complaints'), v_year);
  SELECT coalesce(max(sequence_number), 0) + 1 INTO v_seq FROM consumer_complaints WHERE complaint_year = v_year;
  INSERT INTO consumer_complaints (
      complaint_code, complaint_year, sequence_number, filed_at, tracking_key_hash,
      provider_legal_name, provider_ruc, provider_address, provider_snapshot,
      consumer_full_name, consumer_document_type, consumer_document_number, consumer_address, consumer_email, consumer_phone,
      is_minor, guardian_full_name, guardian_document_type, guardian_document_number, guardian_email, guardian_phone,
      item_type, item_description, amount_claimed, complaint_type, detail, consumer_request,
      response_business_days, response_due_on, retention_years, retain_until, consumer_ip_hash, idempotency_key)
  VALUES (
      format('LR-%s-%s', v_year, lpad(v_seq::text, 6, '0')), v_year, v_seq, v_now, sha256(convert_to(p_tracking_key, 'UTF8')),
      s.legal_name, s.ruc, s.legal_address,
      jsonb_build_object('legal_name', s.legal_name, 'trade_name', s.trade_name, 'ruc', s.ruc, 'legal_address', s.legal_address,
                         'primary_domain', s.primary_domain, 'complaints_officer_name', s.complaints_officer_name,
                         'complaints_officer_email', s.complaints_officer_email),
      p_data ->> 'consumer_full_name', p_data ->> 'consumer_document_type', p_data ->> 'consumer_document_number',
      p_data ->> 'consumer_address', p_data ->> 'consumer_email', p_data ->> 'consumer_phone',
      coalesce((p_data ->> 'is_minor')::boolean, false), p_data ->> 'guardian_full_name', p_data ->> 'guardian_document_type',
      p_data ->> 'guardian_document_number', p_data ->> 'guardian_email', p_data ->> 'guardian_phone',
      p_data ->> 'item_type', p_data ->> 'item_description', (p_data ->> 'amount_claimed')::numeric(14,2),
      p_data ->> 'complaint_type', p_data ->> 'detail', p_data ->> 'consumer_request',
      v_days, v_due, v_years, (v_day + make_interval(years => v_years))::date, p_ip_hash, p_idempotency_key)
  RETURNING * INTO c;
  INSERT INTO complaint_events (consumer_complaint_id, event_type, to_status, actor_type, details)
  VALUES (c.id, 'registered', 'received', 'consumer',
          jsonb_build_object('response_due_on', c.response_due_on, 'response_business_days', v_days, 'retain_until', c.retain_until));
  RETURN jsonb_build_object('complaint_code', c.complaint_code, 'filed_at', c.filed_at, 'response_due_on', c.response_due_on, 'replay', false);
END $$;

-- Estado de una hoja por código + clave de seguimiento (de la constancia). Sin datos personales; respuesta idéntica si
-- el código no existe o la clave no coincide.
CREATE OR REPLACE FUNCTION public.public_complaint_status(p_code text, p_tracking_key text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('result', 'ok', 'complaint_code', c.complaint_code, 'complaint_type', c.complaint_type,
                              'filed_at', c.filed_at, 'status', c.status, 'response_due_on', c.response_due_on,
                              'extended_until', c.extended_until, 'answered_at', c.answered_at, 'closed_at', c.closed_at)
      FROM consumer_complaints c
     WHERE c.complaint_code = upper(p_code) AND c.tracking_key_hash = sha256(convert_to(coalesce(p_tracking_key, ''), 'UTF8'))),
    jsonb_build_object('result', 'invalid'))
$$;

-- Solicitud desde los formularios de la web (demo, contacto o cotización; idempotente). Exige consentimiento de privacidad.
CREATE OR REPLACE FUNCTION public.public_create_demo_request(p_data jsonb, p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_id uuid;
  v_priv uuid;
  v_lead uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_id FROM demo_requests WHERE idempotency_key = p_idempotency_key;
    IF v_id IS NOT NULL THEN RETURN jsonb_build_object('id', v_id, 'replay', true); END IF;
  END IF;
  SELECT d.current_version_id INTO v_priv FROM legal_documents d WHERE d.doc_type = 'privacy' AND d.deleted_at IS NULL;
  INSERT INTO demo_requests (request_type, full_name, company_name, ruc, job_title, email, phone, headcount, economic_sector, interest_plan_code,
                             message, privacy_consent, privacy_version_id, marketing_consent, source_page, utm, referrer, ip_hash, idempotency_key)
  VALUES (coalesce(p_data ->> 'request_type', 'demo'), p_data ->> 'full_name', p_data ->> 'company_name', p_data ->> 'ruc', p_data ->> 'job_title', lower(p_data ->> 'email'),
          p_data ->> 'phone', (p_data ->> 'headcount')::integer, p_data ->> 'economic_sector', p_data ->> 'interest_plan_code',
          left(p_data ->> 'message', 4000), coalesce((p_data ->> 'privacy_consent')::boolean, false), v_priv,
          coalesce((p_data ->> 'marketing_consent')::boolean, false), left(p_data ->> 'source_page', 300),
          coalesce(p_data -> 'utm', '{}'::jsonb), left(p_data ->> 'referrer', 500), p_ip_hash, p_idempotency_key)
  RETURNING id INTO v_id;
  -- Bandeja única de leads: la solicitud crea o actualiza el lead (origen demo o contact) y queda enlazada.
  v_lead := web_upsert_lead(p_data || jsonb_build_object('sector', p_data ->> 'economic_sector'),
                            CASE WHEN coalesce(p_data ->> 'request_type', 'demo') = 'demo' THEN 'demo' ELSE 'contact' END, p_ip_hash);
  UPDATE marketing_leads SET demo_request_id = v_id WHERE id = v_lead;
  RETURN jsonb_build_object('id', v_id, 'replay', false, 'lead_id', v_lead);
END $$;

-- ---------- Acciones del panel del Dueño de la plataforma (corren como escudo_platform) ----------
-- Publicar página: copia título, bloques y SEO a published_snapshot (lo único que sale a la web).
-- Término bloqueado presente en un texto (sin distinguir mayúsculas), o NULL.
CREATE OR REPLACE FUNCTION public.web_blocked_term(p_text text, p_terms jsonb) RETURNS text
LANGUAGE sql IMMUTABLE AS $$
  SELECT x FROM jsonb_array_elements_text(coalesce(p_terms, '[]'::jsonb)) x
   WHERE length(trim(x)) > 0 AND strpos(lower(coalesce(p_text, '')), lower(trim(x))) > 0 LIMIT 1
$$;

CREATE OR REPLACE FUNCTION public.web_publish_page(p_page_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  p site_pages;
  s site_settings;
  v_term text;
BEGIN
  -- Lineamientos de contenido (RN-WEB-58 y RN-WEB-42): no se publica con expresiones no veraces o prohibidas.
  SELECT * INTO s FROM site_settings WHERE singleton AND deleted_at IS NULL;
  SELECT * INTO p FROM site_pages WHERE id = p_page_id AND deleted_at IS NULL;
  IF p.id IS NOT NULL THEN
    v_term := web_blocked_term(concat_ws(' ', p.title, p.summary, p.blocks::text, p.meta_title, p.meta_description),
                               coalesce(s.content_blocked_terms, '[]'::jsonb)
                               || CASE WHEN p.page_type = 'comparison' THEN coalesce(s.comparison_blocked_terms, '[]'::jsonb) ELSE '[]'::jsonb END);
    IF v_term IS NOT NULL THEN
      RAISE EXCEPTION 'la página contiene el término bloqueado «%»', v_term USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  p := NULL;
  UPDATE site_pages SET status = 'published', published_at = now(), published_by = app_user_id(), archived_at = NULL,
         published_snapshot = jsonb_build_object('title', title, 'summary', summary, 'blocks', blocks,
           'seo', jsonb_build_object('meta_title', coalesce(meta_title, title), 'meta_description', meta_description,
                                     'canonical_url', canonical_url, 'og_image_file_id', og_image_file_id, 'noindex', noindex,
                                     'structured_data', structured_data))
   WHERE id = p_page_id AND deleted_at IS NULL AND status IN ('draft', 'published', 'archived')
  RETURNING * INTO p;
  IF p.id IS NULL THEN RAISE EXCEPTION 'página no encontrada' USING ERRCODE = 'no_data_found'; END IF;
  RETURN jsonb_build_object('id', p.id, 'status', p.status, 'published_at', p.published_at, 'version', p.version);
END $$;

CREATE OR REPLACE FUNCTION public.web_archive_page(p_page_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  p site_pages;
BEGIN
  UPDATE site_pages SET status = 'archived', archived_at = now() WHERE id = p_page_id AND deleted_at IS NULL AND status = 'published'
  RETURNING * INTO p;
  IF p.id IS NULL THEN RAISE EXCEPTION 'solo se archiva una página publicada' USING ERRCODE = 'check_violation'; END IF;
  RETURN jsonb_build_object('id', p.id, 'status', p.status);
END $$;

-- Publicar una versión aprobada de un documento legal: la anterior pasa a superseded y la nueva queda vigente.
-- Si requires_reacceptance, app_pending_legal_acceptances() la exige a todos los usuarios en su próximo ingreso.
CREATE OR REPLACE FUNCTION public.web_publish_legal_version(p_version_id uuid, p_effective_from timestamptz DEFAULT now()) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  v legal_document_versions;
  d legal_documents;
BEGIN
  SELECT * INTO v FROM legal_document_versions WHERE id = p_version_id AND deleted_at IS NULL FOR UPDATE;
  IF v.id IS NULL OR v.status <> 'approved' THEN
    RAISE EXCEPTION 'solo se publica una versión aprobada' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO d FROM legal_documents WHERE id = v.legal_document_id FOR UPDATE;
  UPDATE legal_document_versions SET status = 'superseded', superseded_at = now()
   WHERE legal_document_id = d.id AND status = 'published';
  UPDATE legal_document_versions SET status = 'published', published_at = now(), published_by = app_user_id(),
         effective_from = coalesce(p_effective_from, now()), content_sha256 = sha256(convert_to(content, 'UTF8'))
   WHERE id = v.id RETURNING * INTO v;
  UPDATE legal_documents SET current_version_id = v.id WHERE id = d.id;
  RETURN jsonb_build_object('legal_document_id', d.id, 'doc_type', d.doc_type, 'version_id', v.id, 'version_label', v.version_label,
                            'effective_from', v.effective_from, 'requires_reacceptance', v.requires_reacceptance);
END $$;

-- Transiciones de una hoja de reclamación con su evento inalterable: start (en atención), extend (prórroga con motivo,
-- tope según parámetro), answer (respuesta), close (cierre), acknowledge (constancia enviada), assign (responsable), note.
CREATE OR REPLACE FUNCTION public.web_complaint_action(p_complaint_id uuid, p_action text, p_text text DEFAULT NULL,
                                                       p_until date DEFAULT NULL, p_channel text DEFAULT NULL,
                                                       p_assignee uuid DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  c consumer_complaints;
  v_from text;
  v_max integer;
  v_event text;
BEGIN
  SELECT * INTO c FROM consumer_complaints WHERE id = p_complaint_id FOR UPDATE;
  IF c.id IS NULL THEN RAISE EXCEPTION 'hoja no encontrada' USING ERRCODE = 'no_data_found'; END IF;
  v_from := c.status;
  IF p_action = 'start' THEN
    UPDATE consumer_complaints SET status = 'in_progress' WHERE id = c.id RETURNING * INTO c; v_event := 'in_progress';
  ELSIF p_action = 'extend' THEN
    IF p_text IS NULL OR p_until IS NULL THEN
      RAISE EXCEPTION 'la prórroga exige motivo y nueva fecha' USING ERRCODE = 'check_violation';
    END IF;
    v_max := platform_legal_param('web.complaint_extension_days', c.filed_at::date)::integer;
    IF v_max IS NULL OR v_max <= 0 OR p_until > add_business_days(c.response_due_on, v_max) THEN
      RAISE EXCEPTION 'la prórroga excede el máximo del parámetro legal o no está permitida' USING ERRCODE = 'check_violation';
    END IF;
    UPDATE consumer_complaints SET status = 'extended', extended_until = p_until, extension_reason = p_text WHERE id = c.id RETURNING * INTO c;
    v_event := 'extended';
  ELSIF p_action = 'answer' THEN
    UPDATE consumer_complaints SET status = 'answered', response_text = p_text, response_channel = coalesce(p_channel, 'email'),
           answered_at = now(), answered_by = app_user_id() WHERE id = c.id RETURNING * INTO c;
    v_event := 'answered';
  ELSIF p_action = 'close' THEN
    UPDATE consumer_complaints SET status = 'closed', closed_at = now(), closed_by = app_user_id() WHERE id = c.id RETURNING * INTO c;
    v_event := 'closed';
  ELSIF p_action = 'acknowledge' THEN
    UPDATE consumer_complaints SET acknowledgment_sent_at = now() WHERE id = c.id RETURNING * INTO c; v_event := 'acknowledgment_sent';
  ELSIF p_action = 'assign' THEN
    UPDATE consumer_complaints SET assigned_to = p_assignee WHERE id = c.id RETURNING * INTO c; v_event := 'assigned';
  ELSIF p_action = 'note' THEN
    v_event := 'note';
  ELSE
    RAISE EXCEPTION 'acción desconocida %', p_action USING ERRCODE = 'invalid_parameter_value';
  END IF;
  INSERT INTO complaint_events (consumer_complaint_id, event_type, from_status, to_status, reason, details, actor_type, actor_user_id)
  VALUES (c.id, v_event, v_from, c.status, CASE WHEN p_action IN ('extend', 'note') THEN p_text END,
          jsonb_strip_nulls(jsonb_build_object('extended_until', p_until, 'channel', p_channel, 'assigned_to', p_assignee)),
          CASE WHEN app_user_id() IS NULL THEN 'system' ELSE 'user' END, app_user_id());
  RETURN jsonb_build_object('id', c.id, 'complaint_code', c.complaint_code, 'status', c.status,
                            'response_due_on', c.response_due_on, 'extended_until', c.extended_until);
END $$;

REVOKE ALL ON FUNCTION public.web_publish_page(uuid), public.web_archive_page(uuid),
  public.web_publish_legal_version(uuid, timestamptz),
  public.web_complaint_action(uuid, text, text, date, text, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.web_publish_page(uuid), public.web_archive_page(uuid),
  public.web_publish_legal_version(uuid, timestamptz),
  public.web_complaint_action(uuid, text, text, date, text, uuid) TO escudo_platform;

-- ------------------------------------------------------------------ WEB · herramientas de captación (spec/brief-web-extras.md)
-- 20 tablas de plataforma más: leads, calculadora de multas, autodiagnóstico, recursos, casos de éxito, centro de ayuda,
-- partners y referidos, boletín, subencargados y estado del servicio. Lo público sale por funciones public_* SECURITY
-- DEFINER (solo lo publicado; inserciones acotadas). Las acciones del panel (web_*) corren como escudo_platform.
-- Los ayudantes web_* sin SECURITY DEFINER no se otorgan a escudo_app: solo los usan las funciones públicas y el panel.

-- Búsqueda del centro de ayuda (español).
CREATE INDEX IF NOT EXISTS idx_help_articles_fts ON help_articles USING gin (to_tsvector('spanish', title || ' ' || body));

-- Parámetro legal de plataforma vigente con su metadato (para la copia que guarda la calculadora).
CREATE OR REPLACE FUNCTION public.platform_legal_param_info(p_key text, p_on date DEFAULT current_date) RETURNS jsonb
LANGUAGE sql STABLE AS $$
  SELECT jsonb_build_object('key', key, 'value', value, 'value_type', value_type, 'unit', unit, 'valid_from', valid_from,
                            'valid_to', valid_to, 'to_confirm', to_confirm, 'legal_reference', legal_reference)
    FROM legal_parameters
   WHERE key = p_key AND company_id IS NULL AND deleted_at IS NULL
     AND valid_from <= p_on AND (valid_to IS NULL OR valid_to >= p_on)
   ORDER BY valid_from DESC
   LIMIT 1
$$;

CREATE OR REPLACE FUNCTION public.web_try_numeric(p text) RETURNS numeric
LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  RETURN nullif(trim(p), '')::numeric;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION public.web_try_jsonb(p text) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  RETURN nullif(trim(p), '')::jsonb;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END $$;

-- Crea o actualiza el lead por correo (un lead por correo). Exige la toma de conocimiento de la política de privacidad;
-- el consentimiento comercial es separado: se registra con fecha cuando se otorga y nunca se presume ni se apaga aquí
-- (el retiro se registra en marketing_consent_withdrawn_at desde la baja o el panel).
CREATE OR REPLACE FUNCTION public.web_upsert_lead(p_data jsonb, p_source text, p_ip_hash bytea DEFAULT NULL) RETURNS uuid
LANGUAGE plpgsql AS $$
DECLARE
  v_email text := lower(trim(p_data ->> 'email'));
  v_mkt boolean := coalesce((p_data ->> 'marketing_consent')::boolean, false);
  v_priv uuid;
  v_months integer;
  v_until date;
  v_id uuid;
BEGIN
  IF v_email IS NULL OR v_email = '' THEN
    RAISE EXCEPTION 'el correo es obligatorio' USING ERRCODE = 'not_null_violation';
  END IF;
  IF NOT coalesce((p_data ->> 'privacy_consent')::boolean, false) THEN
    RAISE EXCEPTION 'se requiere la toma de conocimiento de la política de privacidad' USING ERRCODE = 'check_violation';
  END IF;
  SELECT d.current_version_id INTO v_priv FROM legal_documents d WHERE d.doc_type = 'privacy' AND d.deleted_at IS NULL;
  v_months := web_try_numeric(platform_legal_param('web.lead_retention_months'))::integer;
  v_until := CASE WHEN v_months > 0 THEN (current_date + make_interval(months => v_months))::date END;
  SELECT id INTO v_id FROM marketing_leads WHERE email = v_email AND deleted_at IS NULL FOR UPDATE;
  IF v_id IS NULL THEN
    INSERT INTO marketing_leads (email, full_name, company_name, ruc, phone, sector, workers_range, source, last_source,
                                 utm_source, utm_medium, utm_campaign, privacy_consent, privacy_version_id,
                                 marketing_consent, marketing_consent_at, retain_until, ip_hash)
    VALUES (v_email, left(nullif(p_data ->> 'full_name', ''), 200), left(nullif(p_data ->> 'company_name', ''), 200),
            nullif(p_data ->> 'ruc', ''), left(nullif(p_data ->> 'phone', ''), 20), nullif(p_data ->> 'sector', ''),
            nullif(p_data ->> 'workers_range', ''), p_source, p_source,
            left(coalesce(p_data ->> 'utm_source', p_data -> 'utm' ->> 'utm_source'), 100),
            left(coalesce(p_data ->> 'utm_medium', p_data -> 'utm' ->> 'utm_medium'), 100),
            left(coalesce(p_data ->> 'utm_campaign', p_data -> 'utm' ->> 'utm_campaign'), 100),
            true, v_priv, v_mkt, CASE WHEN v_mkt THEN now() END, v_until, p_ip_hash)
    RETURNING id INTO v_id;
  ELSE
    UPDATE marketing_leads SET
           full_name = coalesce(left(nullif(p_data ->> 'full_name', ''), 200), full_name),
           company_name = coalesce(left(nullif(p_data ->> 'company_name', ''), 200), company_name),
           ruc = coalesce(nullif(p_data ->> 'ruc', ''), ruc),
           phone = coalesce(left(nullif(p_data ->> 'phone', ''), 20), phone),
           sector = coalesce(nullif(p_data ->> 'sector', ''), sector),
           workers_range = coalesce(nullif(p_data ->> 'workers_range', ''), workers_range),
           last_source = p_source, last_activity_at = now(),
           utm_source = coalesce(left(coalesce(p_data ->> 'utm_source', p_data -> 'utm' ->> 'utm_source'), 100), utm_source),
           utm_medium = coalesce(left(coalesce(p_data ->> 'utm_medium', p_data -> 'utm' ->> 'utm_medium'), 100), utm_medium),
           utm_campaign = coalesce(left(coalesce(p_data ->> 'utm_campaign', p_data -> 'utm' ->> 'utm_campaign'), 100), utm_campaign),
           privacy_consent = true, privacy_version_id = coalesce(v_priv, privacy_version_id),
           marketing_consent_at = CASE WHEN v_mkt AND NOT marketing_consent THEN now() ELSE marketing_consent_at END,
           marketing_consent_withdrawn_at = CASE WHEN v_mkt AND NOT marketing_consent THEN NULL ELSE marketing_consent_withdrawn_at END,
           marketing_consent = marketing_consent OR v_mkt,
           retain_until = CASE WHEN status <> 'converted' THEN coalesce(v_until, retain_until) ELSE retain_until END,
           ip_hash = coalesce(p_ip_hash, ip_hash)
     WHERE id = v_id;
  END IF;
  RETURN v_id;
END $$;

-- ---------- Calculadora de multas SUNAFIL (referencial) ----------
-- Tablas web.fine_table_* (JSON): {"unit": "UIT", "rows": [{"workers_from": 1, "workers_to": 10,
--   "minor": {"min": n, "max": n}, "serious": {...}, "very_serious": {...}}]} (workers_to nulo = en adelante).
-- Con la UIT o la celda sin valor confirmado devuelve parameters_pending y no calcula.
CREATE OR REPLACE FUNCTION public.web_fine_parameters(p_on date DEFAULT current_date) RETURNS jsonb
LANGUAGE sql STABLE AS $$
  SELECT jsonb_build_object(
    'uit', platform_legal_param_info('web.uit_value', p_on),
    'tables', jsonb_build_object('micro', platform_legal_param_info('web.fine_table_micro', p_on),
                                 'small', platform_legal_param_info('web.fine_table_small', p_on),
                                 'non_mype', platform_legal_param_info('web.fine_table_non_mype', p_on)),
    'correction_discount', platform_legal_param_info('web.fine_correction_discount_pct', p_on))
$$;

CREATE OR REPLACE FUNCTION public.public_fine_calculator_parameters() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  p jsonb := web_fine_parameters();
  v_uit numeric := web_try_numeric(p -> 'uit' ->> 'value');
  v_tables jsonb := '{}'::jsonb;
  k text;
  t jsonb;
BEGIN
  FOREACH k IN ARRAY ARRAY['micro', 'small', 'non_mype'] LOOP
    t := web_try_jsonb(p -> 'tables' -> k ->> 'value');
    v_tables := v_tables || jsonb_build_object(k, jsonb_build_object(
      'rows', coalesce(t -> 'rows', '[]'::jsonb), 'valid_from', p -> 'tables' -> k -> 'valid_from',
      'to_confirm', coalesce((p -> 'tables' -> k ->> 'to_confirm')::boolean, true)));
  END LOOP;
  RETURN jsonb_build_object(
    'result', 'ok', 'currency', 'PEN',
    'uit_value', v_uit, 'uit_valid_from', p -> 'uit' -> 'valid_from',
    'tables', v_tables,
    'correction_discount_pct', web_try_numeric(p -> 'correction_discount' ->> 'value'),
    'company_sizes', jsonb_build_array('micro', 'small', 'non_mype'),
    'severities', jsonb_build_array('minor', 'serious', 'very_serious'),
    'to_confirm', coalesce((p -> 'uit' ->> 'to_confirm')::boolean, true)
                  OR EXISTS (SELECT 1 FROM jsonb_each(v_tables) x WHERE (x.value ->> 'to_confirm')::boolean),
    'available', v_uit IS NOT NULL AND EXISTS (SELECT 1 FROM jsonb_each(v_tables) x WHERE jsonb_array_length(x.value -> 'rows') > 0),
    'disclaimer', 'Resultado referencial calculado con parámetros legales por confirmar; no es asesoría legal.');
END $$;

-- Calcula el rango con los parámetros vigentes y guarda la copia usada. Si trae correo, crea o actualiza el lead
-- (origen fine_calculator) para enviar el resultado completo. Idempotente por clave.
CREATE OR REPLACE FUNCTION public.public_calculate_fine(p_data jsonb, p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_size text := p_data ->> 'company_size';
  v_sev text := p_data ->> 'severity';
  v_aw integer := (p_data ->> 'affected_workers')::integer;
  p jsonb := web_fine_parameters();
  v_uit numeric;
  v_table jsonb;
  v_row jsonb;
  v_min numeric;
  v_max numeric;
  v_disc numeric;
  v_lead uuid;
  f fine_calculations;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO f FROM fine_calculations WHERE idempotency_key = p_idempotency_key;
    IF f.id IS NOT NULL THEN
      RETURN jsonb_build_object('result', 'ok', 'id', f.id, 'replay', true, 'uit_value', f.uit_value,
                                'result_min_uit', f.result_min_uit, 'result_max_uit', f.result_max_uit,
                                'result_min_pen', f.result_min_pen, 'result_max_pen', f.result_max_pen);
    END IF;
  END IF;
  IF v_size IS NULL OR v_size NOT IN ('micro', 'small', 'non_mype') OR v_sev IS NULL OR v_sev NOT IN ('minor', 'serious', 'very_serious')
     OR v_aw IS NULL OR v_aw < 1 OR v_aw > 100000 THEN
    RAISE EXCEPTION 'datos de cálculo inválidos' USING ERRCODE = 'check_violation';
  END IF;
  v_uit := web_try_numeric(p -> 'uit' ->> 'value');
  v_table := web_try_jsonb(p -> 'tables' -> v_size ->> 'value');
  SELECT r INTO v_row FROM jsonb_array_elements(coalesce(v_table -> 'rows', '[]'::jsonb)) r
   WHERE (r ->> 'workers_from')::integer <= v_aw AND (r ->> 'workers_to' IS NULL OR (r ->> 'workers_to')::integer >= v_aw)
   ORDER BY (r ->> 'workers_from')::integer DESC LIMIT 1;
  v_min := web_try_numeric(v_row -> v_sev ->> 'min');
  v_max := web_try_numeric(v_row -> v_sev ->> 'max');
  IF v_uit IS NULL OR v_uit <= 0 OR v_min IS NULL OR v_max IS NULL OR v_max < v_min THEN
    RETURN jsonb_build_object('result', 'parameters_pending',
                              'message', 'Los valores de la UIT o de la tabla de multas aún no están cargados o confirmados.');
  END IF;
  IF nullif(p_data ->> 'email', '') IS NOT NULL THEN
    v_lead := web_upsert_lead(p_data, 'fine_calculator', p_ip_hash);
  END IF;
  v_disc := web_try_numeric(p -> 'correction_discount' ->> 'value');
  INSERT INTO fine_calculations (lead_id, company_size, affected_workers, severity, infraction_code, uit_value,
                                 result_min_uit, result_max_uit, result_min_pen, result_max_pen, parameters_snapshot_json,
                                 source_page, ip_hash, idempotency_key)
  VALUES (v_lead, v_size, v_aw, v_sev, left(p_data ->> 'infraction_code', 60), v_uit, v_min, v_max,
          round(v_min * v_uit, 2), round(v_max * v_uit, 2),
          jsonb_build_object('calculated_on', current_date, 'uit', p -> 'uit', 'table', (p -> 'tables' -> v_size) - 'value',
                             'row', v_row, 'correction_discount', p -> 'correction_discount'),
          left(p_data ->> 'source_page', 300), p_ip_hash, p_idempotency_key)
  RETURNING * INTO f;
  RETURN jsonb_build_object('result', 'ok', 'id', f.id, 'replay', false, 'uit_value', f.uit_value,
           'result_min_uit', f.result_min_uit, 'result_max_uit', f.result_max_uit,
           'result_min_pen', f.result_min_pen, 'result_max_pen', f.result_max_pen,
           'with_correction_discount', CASE WHEN v_disc > 0 AND v_disc < 100 THEN jsonb_build_object(
             'pct', v_disc, 'min_pen', round(f.result_min_pen * (1 - v_disc / 100), 2), 'max_pen', round(f.result_max_pen * (1 - v_disc / 100), 2)) END,
           'lead_registered', v_lead IS NOT NULL, 'to_confirm', true,
           'disclaimer', 'Resultado referencial calculado con parámetros legales por confirmar; no es asesoría legal.');
END $$;

-- ---------- Autodiagnóstico Ley 29783 ----------
CREATE OR REPLACE FUNCTION public.public_self_assessment() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('result', 'ok', 'id', q.id, 'title', q.title, 'version', q.version, 'description', q.description,
             'to_validate', q.to_validate,
             'sections', coalesce((
               SELECT jsonb_agg(jsonb_build_object('section', s.section, 'questions', s.questions) ORDER BY s.first_order)
                 FROM (SELECT a.section, min(a.sort_order) AS first_order,
                              jsonb_agg(jsonb_build_object('id', a.id, 'question_text', a.question_text, 'help_text', a.help_text,
                                                           'answer_type', a.answer_type, 'legal_reference', a.legal_reference)
                                        ORDER BY a.sort_order, a.id) AS questions
                         FROM assessment_questions a WHERE a.questionnaire_id = q.id AND a.deleted_at IS NULL GROUP BY a.section) s), '[]'::jsonb))
      FROM assessment_questionnaires q WHERE q.status = 'published' AND q.deleted_at IS NULL LIMIT 1),
    jsonb_build_object('result', 'not_found'))
$$;

-- Califica las respuestas (sí = 100 %, parcial = 50 %, no o sin respuesta = 0 % del peso), puntaje total y por sección,
-- nivel según level_thresholds_json; exige correo (el informe PDF se envía por correo) y crea o actualiza el lead.
CREATE OR REPLACE FUNCTION public.public_submit_self_assessment(p_data jsonb, p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  q assessment_questionnaires;
  s assessment_submissions;
  v_answers jsonb := coalesce(p_data -> 'answers', '{}'::jsonb);
  v_total numeric;
  v_by jsonb;
  v_level text;
  v_lead uuid;
  v_bad integer;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO s FROM assessment_submissions WHERE idempotency_key = p_idempotency_key;
    IF s.id IS NOT NULL THEN
      RETURN jsonb_build_object('id', s.id, 'replay', true, 'score_total', s.score_total, 'score_by_section', s.score_by_section_json, 'level', s.level);
    END IF;
  END IF;
  SELECT * INTO q FROM assessment_questionnaires
   WHERE status = 'published' AND deleted_at IS NULL AND (p_data ->> 'questionnaire_id' IS NULL OR id = (p_data ->> 'questionnaire_id')::uuid);
  IF q.id IS NULL THEN RAISE EXCEPTION 'cuestionario no publicado' USING ERRCODE = 'no_data_found'; END IF;
  IF jsonb_typeof(v_answers) <> 'object' THEN RAISE EXCEPTION 'respuestas inválidas' USING ERRCODE = 'check_violation'; END IF;
  SELECT count(*) INTO v_bad FROM jsonb_each_text(v_answers) x
   WHERE x.value NOT IN ('yes', 'partial', 'no')
      OR NOT EXISTS (SELECT 1 FROM assessment_questions a WHERE a.questionnaire_id = q.id AND a.deleted_at IS NULL AND a.id::text = x.key
                       AND (x.value <> 'partial' OR a.answer_type = 'yes_partial_no'));
  IF v_bad > 0 THEN RAISE EXCEPTION 'respuestas inválidas' USING ERRCODE = 'check_violation'; END IF;
  WITH sc AS (
    SELECT a.section, a.weight,
           a.weight * CASE v_answers ->> a.id::text WHEN 'yes' THEN 1 WHEN 'partial' THEN 0.5 ELSE 0 END AS got
      FROM assessment_questions a WHERE a.questionnaire_id = q.id AND a.deleted_at IS NULL)
  SELECT round(100 * sum(got) / nullif(sum(weight), 0), 2),
         (SELECT jsonb_object_agg(section, pct) FROM (SELECT section, round(100 * sum(got) / nullif(sum(weight), 0), 2) AS pct FROM sc GROUP BY section) z)
    INTO v_total, v_by FROM sc;
  IF v_total IS NULL THEN RAISE EXCEPTION 'cuestionario sin preguntas' USING ERRCODE = 'no_data_found'; END IF;
  v_level := CASE WHEN v_total <= coalesce((q.level_thresholds_json ->> 'low_max')::numeric, 40) THEN 'low'
                  WHEN v_total <= coalesce((q.level_thresholds_json ->> 'medium_max')::numeric, 70) THEN 'medium'
                  ELSE 'high' END;
  v_lead := web_upsert_lead(p_data, 'self_assessment', p_ip_hash);
  INSERT INTO assessment_submissions (questionnaire_id, lead_id, answers_json, score_total, score_by_section_json, level, source_page, ip_hash, idempotency_key)
  VALUES (q.id, v_lead, v_answers, v_total, v_by, v_level, left(p_data ->> 'source_page', 300), p_ip_hash, p_idempotency_key)
  RETURNING * INTO s;
  RETURN jsonb_build_object('id', s.id, 'replay', false, 'score_total', s.score_total, 'score_by_section', s.score_by_section_json,
                            'level', s.level, 'to_validate', q.to_validate);
END $$;

-- ---------- Biblioteca de recursos ----------
CREATE OR REPLACE FUNCTION public.public_resources(p_type text DEFAULT NULL, p_sector text DEFAULT NULL) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'resources', coalesce(jsonb_agg(jsonb_build_object(
           'slug', r.slug, 'title', r.title, 'description', r.description, 'resource_type', r.resource_type, 'sector', r.sector,
           'is_gated', r.is_gated, 'cover_file_id', r.cover_file_id, 'published_at', r.published_at,
           'seo_title', r.seo_title, 'seo_description', r.seo_description) ORDER BY r.sort_order, r.published_at DESC), '[]'::jsonb))
    FROM resource_items r
   WHERE r.status = 'published' AND r.deleted_at IS NULL
     AND (p_type IS NULL OR r.resource_type = p_type) AND (p_sector IS NULL OR r.sector = p_sector)
$$;

-- Registra la descarga (inalterable) y devuelve el file_id para que la API firme una URL de corta duración.
-- Recurso gated: exige correo y crea o actualiza el lead (origen resource).
CREATE OR REPLACE FUNCTION public.public_download_resource(p_slug text, p_data jsonb DEFAULT '{}'::jsonb, p_ip_hash bytea DEFAULT NULL,
                                                           p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  r resource_items;
  d resource_downloads;
  v_lead uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO d FROM resource_downloads WHERE idempotency_key = p_idempotency_key;
    IF d.id IS NOT NULL THEN
      SELECT * INTO r FROM resource_items WHERE id = d.resource_id;
      RETURN jsonb_build_object('result', 'ok', 'replay', true, 'title', r.title, 'file_id', r.file_id);
    END IF;
  END IF;
  SELECT * INTO r FROM resource_items WHERE slug = lower(p_slug) AND status = 'published' AND deleted_at IS NULL;
  IF r.id IS NULL THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  IF r.is_gated AND nullif(p_data ->> 'email', '') IS NULL THEN
    RETURN jsonb_build_object('result', 'lead_required');
  END IF;
  IF nullif(p_data ->> 'email', '') IS NOT NULL THEN
    v_lead := web_upsert_lead(p_data, 'resource', p_ip_hash);
  END IF;
  INSERT INTO resource_downloads (resource_id, lead_id, ip_hash, idempotency_key) VALUES (r.id, v_lead, p_ip_hash, p_idempotency_key);
  UPDATE resource_items SET download_count = download_count + 1 WHERE id = r.id;
  RETURN jsonb_build_object('result', 'ok', 'replay', false, 'title', r.title, 'file_id', r.file_id);
END $$;

-- ---------- Casos de éxito (solo publicados; nunca el archivo de consentimiento) ----------
CREATE OR REPLACE FUNCTION public.public_success_stories(p_sector text DEFAULT NULL) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'stories', coalesce(jsonb_agg(jsonb_build_object(
           'slug', s.slug, 'title', s.title, 'client_name', s.client_name, 'sector', s.sector, 'logo_file_id', s.logo_file_id,
           'challenge', s.challenge, 'solution', s.solution, 'results', s.results_json, 'quote', s.quote,
           'project_year', s.project_year, 'modules', s.modules_json,
           'gallery', coalesce((SELECT jsonb_agg(jsonb_build_object('file_id', m.file_id, 'alt_text', m.alt_text, 'caption', g.caption,
                                                                    'width', m.width, 'height', m.height) ORDER BY g.sort_order, m.title)
                                  FROM success_story_media g JOIN site_media m ON m.id = g.media_id AND m.deleted_at IS NULL AND m.kind = 'image'
                                 WHERE g.success_story_id = s.id AND g.deleted_at IS NULL), '[]'::jsonb),
           'is_example', s.is_example, 'published_at', s.published_at) ORDER BY s.sort_order, s.published_at DESC), '[]'::jsonb))
    FROM success_stories s
   WHERE s.status = 'published' AND s.deleted_at IS NULL AND (s.consent_file_id IS NOT NULL OR s.is_example)
     AND (p_sector IS NULL OR s.sector = p_sector)
$$;

-- ---------- Centro de ayuda (solo publicado) ----------
CREATE OR REPLACE FUNCTION public.public_help_categories() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'categories', coalesce(jsonb_agg(jsonb_build_object(
           'slug', c.slug, 'name', c.name, 'icon', c.icon, 'description', c.description,
           'articles_count', (SELECT count(*) FROM help_articles a WHERE a.category_id = c.id AND a.status = 'published' AND a.deleted_at IS NULL))
           ORDER BY c.sort_order, c.name), '[]'::jsonb))
    FROM help_categories c WHERE c.status = 'active' AND c.deleted_at IS NULL
$$;

-- Lista de artículos publicados por categoría, búsqueda (texto completo en español) o código de pantalla (ayuda contextual).
CREATE OR REPLACE FUNCTION public.public_help_articles(p_category_slug text DEFAULT NULL, p_q text DEFAULT NULL,
                                                       p_screen_code text DEFAULT NULL, p_limit integer DEFAULT 50) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'articles', coalesce(jsonb_agg(x.j ORDER BY x.o1, x.o2), '[]'::jsonb))
    FROM (SELECT jsonb_build_object('slug', a.slug, 'title', a.title, 'category_slug', c.slug, 'excerpt', left(a.body, 240),
                                    'video_url', a.video_url, 'screen_code', a.screen_code, 'published_at', a.published_at) AS j,
                 c.sort_order AS o1, a.sort_order AS o2
            FROM help_articles a JOIN help_categories c ON c.id = a.category_id AND c.status = 'active' AND c.deleted_at IS NULL
           WHERE a.status = 'published' AND a.deleted_at IS NULL
             AND (p_category_slug IS NULL OR c.slug = p_category_slug)
             AND (p_screen_code IS NULL OR a.screen_code = p_screen_code)
             AND (nullif(trim(p_q), '') IS NULL
                  OR to_tsvector('spanish', a.title || ' ' || a.body) @@ websearch_to_tsquery('spanish', p_q)
                  OR a.title ILIKE '%' || replace(replace(p_q, '%', ''), '_', '') || '%')
           LIMIT least(greatest(coalesce(p_limit, 50), 1), 100)) x
$$;

CREATE OR REPLACE FUNCTION public.public_help_article(p_slug text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('result', 'ok', 'slug', a.slug, 'title', a.title, 'body', a.body, 'video_url', a.video_url,
             'screen_code', a.screen_code, 'published_at', a.published_at, 'updated_at', a.updated_at,
             'seo_title', coalesce(a.seo_title, a.title), 'seo_description', a.seo_description,
             'category', jsonb_build_object('slug', c.slug, 'name', c.name),
             'related', coalesce((SELECT jsonb_agg(jsonb_build_object('slug', r.slug, 'title', r.title) ORDER BY r.sort_order, r.title)
                                    FROM help_articles r JOIN help_categories rc ON rc.id = r.category_id AND rc.status = 'active' AND rc.deleted_at IS NULL
                                   WHERE r.id = ANY (a.related_article_ids) AND r.id <> a.id AND r.status = 'published' AND r.deleted_at IS NULL), '[]'::jsonb))
      FROM help_articles a JOIN help_categories c ON c.id = a.category_id AND c.status = 'active' AND c.deleted_at IS NULL
     WHERE a.slug = lower(p_slug) AND a.status = 'published' AND a.deleted_at IS NULL),
    jsonb_build_object('result', 'not_found'))
$$;

-- «¿Te sirvió?»: voto inalterable e idempotente; actualiza los contadores del artículo.
CREATE OR REPLACE FUNCTION public.public_help_feedback(p_slug text, p_was_helpful boolean, p_comment text DEFAULT NULL,
                                                       p_account_id uuid DEFAULT NULL, p_user_id uuid DEFAULT NULL,
                                                       p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_article uuid;
  v_id uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_id FROM help_article_feedback WHERE idempotency_key = p_idempotency_key;
    IF v_id IS NOT NULL THEN RETURN jsonb_build_object('result', 'ok', 'id', v_id, 'replay', true); END IF;
  END IF;
  IF p_was_helpful IS NULL THEN RAISE EXCEPTION 'voto obligatorio' USING ERRCODE = 'not_null_violation'; END IF;
  SELECT id INTO v_article FROM help_articles WHERE slug = lower(p_slug) AND status = 'published' AND deleted_at IS NULL;
  IF v_article IS NULL THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  INSERT INTO help_article_feedback (article_id, was_helpful, comment, account_id, user_id, ip_hash, idempotency_key)
  VALUES (v_article, p_was_helpful, left(nullif(trim(p_comment), ''), 1000), p_account_id, p_user_id, p_ip_hash, p_idempotency_key)
  RETURNING id INTO v_id;
  UPDATE help_articles SET helpful_count = helpful_count + (CASE WHEN p_was_helpful THEN 1 ELSE 0 END),
                           not_helpful_count = not_helpful_count + (CASE WHEN p_was_helpful THEN 0 ELSE 1 END)
   WHERE id = v_article;
  RETURN jsonb_build_object('result', 'ok', 'id', v_id, 'replay', false);
END $$;

-- ---------- Partners y referidos ----------
CREATE OR REPLACE FUNCTION public.public_apply_partner(p_data jsonb, p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_id uuid;
  v_lead uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_id FROM partner_applications WHERE idempotency_key = p_idempotency_key;
    IF v_id IS NOT NULL THEN RETURN jsonb_build_object('id', v_id, 'status', 'pending', 'replay', true); END IF;
  END IF;
  v_lead := web_upsert_lead(p_data, 'partner', p_ip_hash);
  SELECT id INTO v_id FROM partner_applications WHERE lead_id = v_lead AND status = 'pending' AND deleted_at IS NULL;
  IF v_id IS NOT NULL THEN RETURN jsonb_build_object('id', v_id, 'status', 'pending', 'replay', true); END IF;
  INSERT INTO partner_applications (lead_id, partner_type, company_name, ruc, website, message, ip_hash, idempotency_key)
  VALUES (v_lead, p_data ->> 'partner_type', left(nullif(p_data ->> 'company_name', ''), 200), nullif(p_data ->> 'ruc', ''),
          left(nullif(p_data ->> 'website', ''), 300), left(p_data ->> 'message', 4000), p_ip_hash, p_idempotency_key)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'status', 'pending', 'replay', false);
END $$;

-- Un código de referido solo existe para una solicitud aprobada.
CREATE OR REPLACE FUNCTION public.trg_referral_codes_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM partner_applications a WHERE a.id = NEW.partner_application_id AND a.status = 'approved') THEN
    RAISE EXCEPTION 'el código de referido exige una solicitud de partner aprobada' USING ERRCODE = 'check_violation';
  END IF;
  NEW.code := upper(NEW.code);
  RETURN NEW;
END $$;
CREATE TRIGGER trg_referral_codes_guard BEFORE INSERT OR UPDATE OF partner_application_id, code ON referral_codes
  FOR EACH ROW EXECUTE FUNCTION trg_referral_codes_guard();

-- ---------- Boletín y avisos del estado del servicio (doble confirmación; tokens solo como sha256) ----------
-- La API genera los tokens aleatorios, los envía por correo y pasa aquí el texto: en la base solo queda su hash.
-- La respuesta pública es siempre la misma (no revela si el correo ya estaba suscrito).
CREATE OR REPLACE FUNCTION public.web_subscribe(p_email text, p_topics jsonb, p_confirm_token text, p_unsubscribe_token text,
                                                p_lead_id uuid DEFAULT NULL, p_ip_hash bytea DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  v_email text := lower(trim(p_email));
  v_topics jsonb := coalesce(p_topics, '[]'::jsonb);
  n newsletter_subscribers;
BEGIN
  IF v_email IS NULL OR v_email = '' THEN RAISE EXCEPTION 'el correo es obligatorio' USING ERRCODE = 'not_null_violation'; END IF;
  IF jsonb_typeof(v_topics) <> 'array' OR jsonb_array_length(v_topics) = 0
     OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(v_topics) x WHERE x NOT IN ('regulations', 'sunafil', 'sectors', 'status')) THEN
    RAISE EXCEPTION 'temas inválidos' USING ERRCODE = 'check_violation';
  END IF;
  IF length(coalesce(p_confirm_token, '')) < 32 OR length(coalesce(p_unsubscribe_token, '')) < 32 THEN
    RAISE EXCEPTION 'tokens demasiado cortos' USING ERRCODE = 'check_violation';
  END IF;
  SELECT * INTO n FROM newsletter_subscribers WHERE email = v_email AND deleted_at IS NULL FOR UPDATE;
  IF n.id IS NULL THEN
    INSERT INTO newsletter_subscribers (email, topics_json, status, confirm_token_hash, confirm_sent_at, unsubscribe_token_hash, lead_id, consent_ip_hash)
    VALUES (v_email, v_topics, 'pending', sha256(convert_to(p_confirm_token, 'UTF8')), now(), sha256(convert_to(p_unsubscribe_token, 'UTF8')), p_lead_id, p_ip_hash);
    RETURN jsonb_build_object('result', 'accepted', 'send_confirmation', true);
  END IF;
  IF n.status = 'confirmed' THEN
    UPDATE newsletter_subscribers SET topics_json = (SELECT jsonb_agg(DISTINCT x) FROM jsonb_array_elements(n.topics_json || v_topics) x),
           lead_id = coalesce(lead_id, p_lead_id)
     WHERE id = n.id;
    RETURN jsonb_build_object('result', 'accepted', 'send_confirmation', false);
  END IF;
  UPDATE newsletter_subscribers SET status = 'pending', unsubscribed_at = NULL,
         topics_json = CASE WHEN n.status = 'pending' THEN (SELECT jsonb_agg(DISTINCT x) FROM jsonb_array_elements(n.topics_json || v_topics) x) ELSE v_topics END,
         confirm_token_hash = sha256(convert_to(p_confirm_token, 'UTF8')), confirm_sent_at = now(),
         unsubscribe_token_hash = sha256(convert_to(p_unsubscribe_token, 'UTF8')), lead_id = coalesce(lead_id, p_lead_id),
         consent_ip_hash = coalesce(p_ip_hash, consent_ip_hash)
   WHERE id = n.id;
  RETURN jsonb_build_object('result', 'accepted', 'send_confirmation', true);
END $$;

CREATE OR REPLACE FUNCTION public.public_newsletter_subscribe(p_data jsonb, p_confirm_token text, p_unsubscribe_token text,
                                                              p_ip_hash bytea DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_lead uuid := web_upsert_lead(p_data, 'newsletter', p_ip_hash);
BEGIN
  RETURN web_subscribe(p_data ->> 'email', coalesce(p_data -> 'topics', '["regulations"]'::jsonb), p_confirm_token, p_unsubscribe_token, v_lead, p_ip_hash);
END $$;

-- Avisos del estado del servicio: suscripción con el tema status (sin lead: no es un formulario de captación).
CREATE OR REPLACE FUNCTION public.public_status_subscribe(p_email text, p_confirm_token text, p_unsubscribe_token text,
                                                          p_privacy_consent boolean DEFAULT false, p_ip_hash bytea DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT coalesce(p_privacy_consent, false) THEN
    RAISE EXCEPTION 'se requiere la toma de conocimiento de la política de privacidad' USING ERRCODE = 'check_violation';
  END IF;
  RETURN web_subscribe(p_email, '["status"]'::jsonb, p_confirm_token, p_unsubscribe_token, NULL, p_ip_hash);
END $$;

CREATE OR REPLACE FUNCTION public.public_newsletter_confirm(p_token text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_id uuid;
BEGIN
  UPDATE newsletter_subscribers SET status = 'confirmed', confirmed_at = now(), confirm_token_hash = NULL
   WHERE confirm_token_hash = sha256(convert_to(coalesce(p_token, ''), 'UTF8')) AND status = 'pending' AND deleted_at IS NULL
     AND confirm_sent_at > now() - make_interval(hours => coalesce((SELECT st.newsletter_confirm_token_validity FROM site_settings st
                                                                     WHERE st.singleton AND st.deleted_at IS NULL), 72))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('result', CASE WHEN v_id IS NULL THEN 'invalid' ELSE 'confirmed' END);
END $$;

-- Baja con un clic: idempotente (repetir con el mismo token sigue respondiendo unsubscribed).
CREATE OR REPLACE FUNCTION public.public_newsletter_unsubscribe(p_token text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  n newsletter_subscribers;
BEGIN
  SELECT * INTO n FROM newsletter_subscribers
   WHERE unsubscribe_token_hash = sha256(convert_to(coalesce(p_token, ''), 'UTF8')) AND deleted_at IS NULL FOR UPDATE;
  IF n.id IS NULL THEN RETURN jsonb_build_object('result', 'invalid'); END IF;
  IF n.status <> 'unsubscribed' THEN
    UPDATE newsletter_subscribers SET status = 'unsubscribed', unsubscribed_at = now(), confirm_token_hash = NULL WHERE id = n.id;
  END IF;
  RETURN jsonb_build_object('result', 'unsubscribed');
END $$;

-- ---------- Centro de confianza y estado del servicio ----------
CREATE OR REPLACE FUNCTION public.public_subprocessors() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'subprocessors', coalesce(jsonb_agg(jsonb_build_object(
           'name', s.name, 'purpose', s.purpose, 'country', s.country, 'data_categories', s.data_categories,
           'transfer_basis', s.transfer_basis, 'website', s.website, 'to_validate', s.to_validate) ORDER BY s.sort_order, s.name), '[]'::jsonb))
    FROM subprocessors s WHERE s.status = 'active' AND s.deleted_at IS NULL
$$;

-- Componentes visibles con su estado, estado general (el peor) e incidentes publicados (abiertos y resueltos en los
-- últimos 90 días) con sus actualizaciones. Un incidente sin publicar no sale.
CREATE OR REPLACE FUNCTION public.public_service_status() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  WITH comp AS (
    SELECT * FROM status_components WHERE is_visible AND deleted_at IS NULL),
  rank AS (
    SELECT c.*, array_position(ARRAY['operational', 'maintenance', 'degraded', 'partial_outage', 'major_outage'], c.current_status) AS sev FROM comp c)
  SELECT jsonb_build_object('result', 'ok',
    'overall_status', coalesce((SELECT current_status FROM rank ORDER BY sev DESC LIMIT 1), 'operational'),
    'components', coalesce((SELECT jsonb_agg(jsonb_build_object('code', code, 'name', name, 'description', description,
                                                                'current_status', current_status) ORDER BY sort_order, name) FROM comp), '[]'::jsonb),
    'incidents', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id', i.id, 'title', i.title, 'impact', i.impact, 'status', i.status, 'started_at', i.started_at, 'resolved_at', i.resolved_at,
        'published_at', i.published_at,
        'components', coalesce((SELECT jsonb_agg(c.code ORDER BY c.sort_order) FROM status_components c
                                 WHERE c.id::text IN (SELECT jsonb_array_elements_text(i.component_ids_json)) AND c.is_visible AND c.deleted_at IS NULL), '[]'::jsonb),
        'updates', coalesce((SELECT jsonb_agg(jsonb_build_object('status', u.status, 'message', u.message, 'published_at', u.published_at)
                                              ORDER BY u.published_at DESC) FROM status_incident_updates u WHERE u.incident_id = i.id), '[]'::jsonb))
        ORDER BY i.started_at DESC)
        FROM status_incidents i
       WHERE i.published_at IS NOT NULL AND i.deleted_at IS NULL
         AND (i.status <> 'resolved' OR i.resolved_at >= now() - make_interval(days => coalesce((SELECT st.status_history_days FROM site_settings st
                                                                                                    WHERE st.singleton AND st.deleted_at IS NULL), 90)))), '[]'::jsonb))
$$;

-- ---------- Acciones del panel (corren como escudo_platform; no son SECURITY DEFINER) ----------
-- Preguntas de un cuestionario publicado o archivado no cambian (las respuestas ya calificadas dependen de ellas).
CREATE OR REPLACE FUNCTION public.trg_assessment_questions_lock() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_status text;
BEGIN
  SELECT status INTO v_status FROM assessment_questionnaires
   WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.questionnaire_id ELSE NEW.questionnaire_id END;
  IF v_status IS DISTINCT FROM 'draft' OR (TG_OP = 'UPDATE' AND NEW.questionnaire_id <> OLD.questionnaire_id) THEN
    RAISE EXCEPTION 'las preguntas de un cuestionario publicado o archivado no se editan: cree una nueva versión'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;
CREATE TRIGGER trg_assessment_questions_lock BEFORE INSERT OR UPDATE OR DELETE ON assessment_questions
  FOR EACH ROW EXECUTE FUNCTION trg_assessment_questions_lock();

-- Publicar cuestionario: exige preguntas; el publicado anterior pasa a archivado.
CREATE OR REPLACE FUNCTION public.web_publish_questionnaire(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  q assessment_questionnaires;
BEGIN
  SELECT * INTO q FROM assessment_questionnaires WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF q.id IS NULL OR q.status <> 'draft' THEN
    RAISE EXCEPTION 'solo se publica un cuestionario en borrador' USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM assessment_questions WHERE questionnaire_id = q.id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'el cuestionario no tiene preguntas' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE assessment_questionnaires SET status = 'archived', archived_at = now() WHERE status = 'published' AND id <> q.id;
  UPDATE assessment_questionnaires SET status = 'published', published_at = now(), published_by = app_user_id() WHERE id = q.id RETURNING * INTO q;
  RETURN jsonb_build_object('id', q.id, 'status', q.status, 'version', q.version, 'to_validate', q.to_validate, 'published_at', q.published_at);
END $$;

-- Caso de éxito: aprobar (exige consentimiento escrito o marcarlo como ejemplo), publicar (exige aprobación) u ocultar.
CREATE OR REPLACE FUNCTION public.web_success_story_action(p_id uuid, p_action text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  s success_stories;
BEGIN
  SELECT * INTO s FROM success_stories WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'caso no encontrado' USING ERRCODE = 'no_data_found'; END IF;
  IF p_action = 'approve' AND s.status IN ('draft', 'hidden') THEN
    UPDATE success_stories SET status = 'approved', approved_by = app_user_id(), approved_at = now() WHERE id = s.id RETURNING * INTO s;
  ELSIF p_action = 'publish' AND s.status IN ('approved', 'hidden') AND s.approved_at IS NOT NULL THEN
    UPDATE success_stories SET status = 'published', published_at = now() WHERE id = s.id RETURNING * INTO s;
  ELSIF p_action = 'hide' AND s.status IN ('approved', 'published') THEN
    UPDATE success_stories SET status = 'hidden' WHERE id = s.id RETURNING * INTO s;
  ELSE
    RAISE EXCEPTION 'transición inválida % desde %', p_action, s.status USING ERRCODE = 'check_violation';
  END IF;
  RETURN jsonb_build_object('id', s.id, 'status', s.status, 'is_example', s.is_example);
END $$;

CREATE OR REPLACE FUNCTION public.web_publish_help_article(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  a help_articles;
BEGIN
  UPDATE help_articles SET status = 'published', published_at = now(), published_by = app_user_id()
   WHERE id = p_id AND deleted_at IS NULL AND status IN ('draft', 'archived', 'published')
  RETURNING * INTO a;
  IF a.id IS NULL THEN RAISE EXCEPTION 'artículo no encontrado' USING ERRCODE = 'no_data_found'; END IF;
  RETURN jsonb_build_object('id', a.id, 'status', a.status, 'published_at', a.published_at);
END $$;

-- Revisión de una solicitud de partner. Aprobar crea su código de referido (el indicado o uno aleatorio) con la regla de
-- recompensa por definir; rechazar exige motivo.
CREATE OR REPLACE FUNCTION public.web_review_partner(p_id uuid, p_approve boolean, p_code text DEFAULT NULL, p_reason text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  a partner_applications;
  v_code text;
BEGIN
  SELECT * INTO a FROM partner_applications WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF a.id IS NULL OR a.status <> 'pending' THEN
    RAISE EXCEPTION 'solo se revisa una solicitud pendiente' USING ERRCODE = 'check_violation';
  END IF;
  IF p_approve THEN
    UPDATE partner_applications SET status = 'approved', reviewed_by = app_user_id(), reviewed_at = now() WHERE id = a.id RETURNING * INTO a;
    v_code := upper(coalesce(nullif(trim(p_code), ''), 'ESC-' || upper(substr(encode(uuid_send(gen_random_uuid()), 'hex'), 1, 8))));
    INSERT INTO referral_codes (partner_application_id, code) VALUES (a.id, v_code);
  ELSE
    UPDATE partner_applications SET status = 'rejected', reviewed_by = app_user_id(), reviewed_at = now(), rejection_reason = p_reason
     WHERE id = a.id RETURNING * INTO a;
  END IF;
  RETURN jsonb_build_object('id', a.id, 'status', a.status, 'referral_code', v_code);
END $$;

-- Registra un referido por código (lo usa el alta autoservicio o el panel); un lead o cuenta solo se refiere una vez.
CREATE OR REPLACE FUNCTION public.web_register_referral(p_code text, p_lead_id uuid DEFAULT NULL, p_account_id uuid DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  v_code uuid;
  v_id uuid;
BEGIN
  SELECT id INTO v_code FROM referral_codes WHERE code = upper(p_code) AND is_active AND deleted_at IS NULL;
  IF v_code IS NULL THEN RETURN jsonb_build_object('result', 'invalid_code'); END IF;
  INSERT INTO referrals (referral_code_id, lead_id, account_id) VALUES (v_code, p_lead_id, p_account_id)
  ON CONFLICT DO NOTHING RETURNING id INTO v_id;
  RETURN jsonb_build_object('result', CASE WHEN v_id IS NULL THEN 'already_referred' ELSE 'ok' END, 'id', v_id);
END $$;

-- Edición enviada: el contenido no cambia; solo las métricas (aperturas, clics, bajas).
CREATE OR REPLACE FUNCTION public.trg_newsletter_issues_lock() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  free text[] := ARRAY['opens_count', 'clicks_count', 'unsubscribes_count', 'updated_at', 'updated_by'];
BEGIN
  IF OLD.status = 'sent' AND (to_jsonb(NEW) - free) IS DISTINCT FROM (to_jsonb(OLD) - free) THEN
    RAISE EXCEPTION 'la edición % ya fue enviada y no se edita', OLD.slug USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_newsletter_issues_lock BEFORE UPDATE ON newsletter_issues FOR EACH ROW EXECUTE FUNCTION trg_newsletter_issues_lock();

-- Programar el envío (ahora o en una fecha): fija los destinatarios confirmados con algún tema en común (o todos si la
-- edición no tiene temas). El job de envío lo pasa a sent con web_newsletter_issue_sent().
CREATE OR REPLACE FUNCTION public.web_send_newsletter_issue(p_id uuid, p_at timestamptz DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  i newsletter_issues;
BEGIN
  SELECT * INTO i FROM newsletter_issues WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF i.id IS NULL OR i.status NOT IN ('draft', 'scheduled') THEN
    RAISE EXCEPTION 'solo se programa una edición en borrador o programada' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE newsletter_issues SET status = 'scheduled', scheduled_at = coalesce(p_at, now()), sent_by = app_user_id(),
         recipients_count = (SELECT count(*) FROM newsletter_subscribers n
                              WHERE n.status = 'confirmed' AND n.deleted_at IS NULL
                                AND (jsonb_array_length(i.topics_json) = 0 OR EXISTS (
                                     SELECT 1 FROM jsonb_array_elements_text(i.topics_json) t WHERE n.topics_json ? t)))
   WHERE id = i.id RETURNING * INTO i;
  RETURN jsonb_build_object('id', i.id, 'status', i.status, 'scheduled_at', i.scheduled_at, 'recipients_count', i.recipients_count);
END $$;

CREATE OR REPLACE FUNCTION public.web_newsletter_issue_sent(p_id uuid, p_provider_campaign_id text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  i newsletter_issues;
BEGIN
  UPDATE newsletter_issues SET status = 'sent', sent_at = now(), provider_campaign_id = p_provider_campaign_id
   WHERE id = p_id AND status = 'scheduled' RETURNING * INTO i;
  IF i.id IS NULL THEN RAISE EXCEPTION 'solo se marca enviada una edición programada' USING ERRCODE = 'check_violation'; END IF;
  RETURN jsonb_build_object('id', i.id, 'status', i.status, 'sent_at', i.sent_at);
END $$;

-- Publicar un incidente en /estado con su primera actualización (inalterable).
CREATE OR REPLACE FUNCTION public.web_publish_incident(p_id uuid, p_message text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  i status_incidents;
BEGIN
  IF nullif(trim(p_message), '') IS NULL THEN RAISE EXCEPTION 'mensaje obligatorio' USING ERRCODE = 'check_violation'; END IF;
  UPDATE status_incidents SET published_at = coalesce(published_at, now()), published_by = coalesce(published_by, app_user_id())
   WHERE id = p_id AND deleted_at IS NULL RETURNING * INTO i;
  IF i.id IS NULL THEN RAISE EXCEPTION 'incidente no encontrado' USING ERRCODE = 'no_data_found'; END IF;
  INSERT INTO status_incident_updates (incident_id, status, message) VALUES (i.id, i.status, p_message);
  RETURN jsonb_build_object('id', i.id, 'status', i.status, 'published_at', i.published_at);
END $$;

-- Nueva actualización: cambia el estado del incidente (resolved fija resolved_at) y deja la actualización inalterable.
CREATE OR REPLACE FUNCTION public.web_add_incident_update(p_id uuid, p_status text, p_message text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  i status_incidents;
BEGIN
  IF nullif(trim(p_message), '') IS NULL THEN RAISE EXCEPTION 'mensaje obligatorio' USING ERRCODE = 'check_violation'; END IF;
  UPDATE status_incidents SET status = p_status,
         resolved_at = CASE WHEN p_status = 'resolved' THEN coalesce(resolved_at, now()) ELSE NULL END
   WHERE id = p_id AND deleted_at IS NULL RETURNING * INTO i;
  IF i.id IS NULL THEN RAISE EXCEPTION 'incidente no encontrado' USING ERRCODE = 'no_data_found'; END IF;
  INSERT INTO status_incident_updates (incident_id, status, message) VALUES (i.id, i.status, p_message);
  RETURN jsonb_build_object('id', i.id, 'status', i.status, 'resolved_at', i.resolved_at);
END $$;

REVOKE ALL ON FUNCTION public.web_upsert_lead(jsonb, text, bytea), public.web_subscribe(text, jsonb, text, text, uuid, bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.web_upsert_lead(jsonb, text, bytea), public.web_subscribe(text, jsonb, text, text, uuid, bytea) TO escudo_definer;
REVOKE ALL ON FUNCTION public.web_publish_questionnaire(uuid), public.web_success_story_action(uuid, text), public.web_publish_help_article(uuid),
  public.web_review_partner(uuid, boolean, text, text), public.web_register_referral(text, uuid, uuid),
  public.web_send_newsletter_issue(uuid, timestamptz), public.web_newsletter_issue_sent(uuid, text),
  public.web_publish_incident(uuid, text), public.web_add_incident_update(uuid, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.web_publish_questionnaire(uuid), public.web_success_story_action(uuid, text), public.web_publish_help_article(uuid),
  public.web_review_partner(uuid, boolean, text, text), public.web_register_referral(text, uuid, uuid),
  public.web_send_newsletter_issue(uuid, timestamptz), public.web_newsletter_issue_sent(uuid, text),
  public.web_publish_incident(uuid, text), public.web_add_incident_update(uuid, text, text) TO escudo_platform;

-- ------------------------------------------------------------------ WEB v1.5 (spec/brief-web-v15.md)
-- 15 tablas de plataforma más: medios, métricas propias, calendario de demos, chatbot, CRM y galería del portafolio.
-- Lo público sale por funciones public_* SECURITY DEFINER; las acciones del panel (web_*) corren como escudo_platform
-- y no se otorgan a escudo_app. Tokens solo como sha256; eventos analíticos solo con consentimiento y sin IP.

-- ---------- Ayudantes ----------
CREATE OR REPLACE FUNCTION public.web_token_hash(p_token text) RETURNS bytea
LANGUAGE sql IMMUTABLE AS $$ SELECT sha256(convert_to(coalesce(p_token, ''), 'UTF8')) $$;

-- Descarta particiones mensuales anteriores a la conservación (site_events, chatbot_messages). Lo ejecuta el job de
-- mantenimiento como escudo_owner (dueño de las particiones): las tablas siguen siendo inalterables fila a fila.
CREATE OR REPLACE FUNCTION public.web_drop_expired_partitions(p_table text, p_retention_months integer) RETURNS text[]
LANGUAGE plpgsql AS $$
DECLARE
  r record;
  v_limit date;
  out text[] := '{}';
BEGIN
  IF p_table NOT IN ('site_events', 'chatbot_messages') OR p_retention_months IS NULL OR p_retention_months < 1 THEN
    RAISE EXCEPTION 'tabla o conservación inválida' USING ERRCODE = 'invalid_parameter_value';
  END IF;
  v_limit := (date_trunc('month', current_date) - make_interval(months => p_retention_months))::date;
  FOR r IN SELECT c.relname FROM pg_inherits i JOIN pg_class c ON c.oid = i.inhrelid JOIN pg_class p ON p.oid = i.inhparent
            WHERE p.relname = p_table AND c.relname ~ ('^' || p_table || '_[0-9]{6}$')
              AND to_date(right(c.relname, 6), 'YYYYMM') < v_limit LOOP
    EXECUTE format('DROP TABLE %I', r.relname);
    out := out || r.relname::text;
  END LOOP;
  RETURN out;
END $$;

-- ---------- Calendario de demos ----------
-- Dos reuniones confirmadas (o reprogramadas) del mismo anfitrión no se cruzan. Se usa un trigger con candado por
-- anfitrión en lugar de EXCLUDE USING gist porque la exclusión con uuid exige la extensión btree_gist (el kit no usa extensiones).
CREATE OR REPLACE FUNCTION public.trg_demo_meetings_no_overlap() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.host_id IS NULL OR NEW.status NOT IN ('confirmed', 'rescheduled') OR NEW.deleted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('demo_meetings'), hashtext(NEW.host_id::text));
  IF EXISTS (SELECT 1 FROM demo_meetings m
              WHERE m.host_id = NEW.host_id AND m.id <> NEW.id AND m.deleted_at IS NULL
                AND m.status IN ('confirmed', 'rescheduled')
                AND tstzrange(m.starts_at, m.ends_at) && tstzrange(NEW.starts_at, NEW.ends_at)) THEN
    RAISE EXCEPTION 'el anfitrión ya tiene una reunión confirmada que se cruza con %', NEW.starts_at
      USING ERRCODE = 'exclusion_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_demo_meetings_no_overlap BEFORE INSERT OR UPDATE OF host_id, starts_at, ends_at, status, deleted_at ON demo_meetings
  FOR EACH ROW EXECUTE FUNCTION trg_demo_meetings_no_overlap();

-- Horarios libres por anfitrión: reglas semanales (zona horaria del anfitrión) en pasos de duración + margen, sin feriados
-- nacionales, sin bloqueos (del anfitrión o generales), sin reuniones propuestas/confirmadas/reprogramadas (con margen),
-- respetando el tope diario, el aviso mínimo y el horizonte de demo_booking_settings.
CREATE OR REPLACE FUNCTION public.web_demo_free_slots(p_from date, p_to date, p_exclude_meeting uuid DEFAULT NULL)
RETURNS TABLE (host_id uuid, starts_at timestamptz, ends_at timestamptz)
LANGUAGE sql STABLE AS $$
  WITH s AS (SELECT * FROM demo_booking_settings WHERE singleton AND deleted_at IS NULL),
  days AS (
    SELECT d::date AS day
      FROM s, generate_series(greatest(p_from, (now() AT TIME ZONE 'America/Lima')::date)::timestamp,
                              least(p_to, (now() AT TIME ZONE 'America/Lima')::date + s.max_days_ahead)::timestamp, interval '1 day') d
     WHERE NOT EXISTS (SELECT 1 FROM holidays h WHERE h.holiday_on = d::date AND h.scope = 'national' AND h.is_non_working AND h.deleted_at IS NULL)),
  cand AS (
    SELECT h.id AS host_id, h.max_per_day, h.timezone, days.day, g AS st, g + make_interval(mins => s.duration_minutes) AS en
      FROM s CROSS JOIN days
      JOIN demo_availability_rules r ON r.weekday = extract(isodow FROM days.day) AND r.deleted_at IS NULL
      JOIN demo_hosts h ON h.id = r.host_id AND h.is_active AND h.deleted_at IS NULL
      CROSS JOIN LATERAL generate_series((days.day + r.start_time) AT TIME ZONE h.timezone,
                                         ((days.day + r.end_time) AT TIME ZONE h.timezone) - make_interval(mins => s.duration_minutes),
                                         make_interval(mins => s.duration_minutes + s.buffer_minutes)) g)
  SELECT c.host_id, c.st, c.en
    FROM cand c CROSS JOIN s
   WHERE c.st >= now() + make_interval(hours => s.min_notice_hours)
     AND NOT EXISTS (SELECT 1 FROM demo_blackouts b
                      WHERE b.deleted_at IS NULL AND (b.host_id IS NULL OR b.host_id = c.host_id)
                        AND tstzrange(b.starts_at, b.ends_at) && tstzrange(c.st, c.en))
     AND NOT EXISTS (SELECT 1 FROM demo_meetings m
                      WHERE m.host_id = c.host_id AND m.deleted_at IS NULL AND m.status IN ('proposed', 'confirmed', 'rescheduled')
                        AND m.id IS DISTINCT FROM p_exclude_meeting
                        AND tstzrange(m.starts_at - make_interval(mins => s.buffer_minutes), m.ends_at + make_interval(mins => s.buffer_minutes))
                            && tstzrange(c.st, c.en))
     AND (c.max_per_day IS NULL OR (SELECT count(*) FROM demo_meetings m
                                     WHERE m.host_id = c.host_id AND m.deleted_at IS NULL AND m.status IN ('proposed', 'confirmed', 'rescheduled')
                                       AND m.id IS DISTINCT FROM p_exclude_meeting
                                       AND (m.starts_at AT TIME ZONE c.timezone)::date = c.day) < c.max_per_day)
$$;

-- Público: horarios libres (sin anfitrión ni datos personales). Agenda pública desactivada: disabled.
CREATE OR REPLACE FUNCTION public.public_demo_slots(p_from date DEFAULT NULL, p_to date DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  s demo_booking_settings;
  v_from date := coalesce(p_from, (now() AT TIME ZONE 'America/Lima')::date);
  v_to date;
BEGIN
  SELECT * INTO s FROM demo_booking_settings WHERE singleton AND deleted_at IS NULL;
  IF s.id IS NULL OR NOT s.public_booking_enabled THEN
    RETURN jsonb_build_object('result', 'disabled', 'slots', '[]'::jsonb);
  END IF;
  v_to := least(coalesce(p_to, v_from + 14), v_from + 31);
  RETURN jsonb_build_object('result', 'ok', 'duration_minutes', s.duration_minutes, 'timezone', 'America/Lima',
    'slots', coalesce((SELECT jsonb_agg(jsonb_build_object('starts_at', x.starts_at, 'ends_at', x.ends_at) ORDER BY x.starts_at)
                         FROM (SELECT DISTINCT f.starts_at, f.ends_at FROM web_demo_free_slots(v_from, v_to) f) x), '[]'::jsonb));
END $$;

-- Reserva pública: crea la solicitud de demo (y con ella el lead), elige un anfitrión libre y deja la reunión propuesta
-- con el hash del token de gestión. Idempotente por Idempotency-Key (la de demo_requests).
CREATE OR REPLACE FUNCTION public.public_demo_book(p_data jsonb, p_starts_at timestamptz, p_manage_token text,
                                                   p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  s demo_booking_settings;
  m demo_meetings;
  v_req uuid;
  v_host uuid;
  v_day date := (p_starts_at AT TIME ZONE 'America/Lima')::date;
  r jsonb;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT x.* INTO m FROM demo_meetings x JOIN demo_requests d ON d.id = x.demo_request_id
     WHERE d.idempotency_key = p_idempotency_key ORDER BY x.created_at DESC LIMIT 1;
    IF m.id IS NOT NULL THEN
      RETURN jsonb_build_object('result', 'ok', 'replay', true, 'demo_request_id', m.demo_request_id, 'meeting_id', m.id,
                                'starts_at', m.starts_at, 'ends_at', m.ends_at, 'status', m.status);
    END IF;
  END IF;
  SELECT * INTO s FROM demo_booking_settings WHERE singleton AND deleted_at IS NULL;
  IF s.id IS NULL OR NOT s.public_booking_enabled THEN RETURN jsonb_build_object('result', 'disabled'); END IF;
  IF length(coalesce(p_manage_token, '')) < 32 THEN
    RAISE EXCEPTION 'token de gestión demasiado corto' USING ERRCODE = 'check_violation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('demo_booking'));
  SELECT f.host_id INTO v_host FROM web_demo_free_slots(v_day - 1, v_day + 1) f
   WHERE f.starts_at = p_starts_at
   ORDER BY (SELECT count(*) FROM demo_meetings x WHERE x.host_id = f.host_id AND x.status IN ('proposed', 'confirmed', 'rescheduled')
                AND x.deleted_at IS NULL AND (x.starts_at AT TIME ZONE 'America/Lima')::date = v_day), f.host_id
   LIMIT 1;
  IF v_host IS NULL THEN RETURN jsonb_build_object('result', 'slot_unavailable'); END IF;
  r := public_create_demo_request(p_data || jsonb_build_object('request_type', 'demo'), p_ip_hash, p_idempotency_key);
  v_req := (r ->> 'id')::uuid;
  UPDATE demo_requests SET status = 'demo_scheduled', demo_scheduled_at = p_starts_at WHERE id = v_req AND status IN ('new', 'contacted');
  INSERT INTO demo_meetings (demo_request_id, host_id, starts_at, ends_at, status, meeting_provider, manage_token_hash, recording_consent)
  VALUES (v_req, v_host, p_starts_at, p_starts_at + make_interval(mins => s.duration_minutes), 'proposed', s.default_meeting_provider,
          web_token_hash(p_manage_token), coalesce((p_data ->> 'recording_consent')::boolean, false))
  RETURNING * INTO m;
  RETURN jsonb_build_object('result', 'ok', 'replay', false, 'demo_request_id', v_req, 'meeting_id', m.id, 'lead_id', r -> 'lead_id',
                            'starts_at', m.starts_at, 'ends_at', m.ends_at, 'status', m.status);
END $$;

-- Gestión de la cita por token (solo se compara el hash). Sin correo, teléfono ni empresa del visitante.
CREATE OR REPLACE FUNCTION public.public_demo_manage(p_token text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('result', 'ok', 'status', m.status, 'starts_at', m.starts_at, 'ends_at', m.ends_at,
             'meeting_provider', m.meeting_provider,
             'meeting_url', CASE WHEN m.status IN ('confirmed', 'rescheduled') THEN m.meeting_url END,
             'host_name', h.display_name, 'recording_consent', m.recording_consent,
             'can_change', m.status IN ('proposed', 'confirmed', 'rescheduled') AND m.starts_at > now())
      FROM demo_meetings m LEFT JOIN demo_hosts h ON h.id = m.host_id
     WHERE m.manage_token_hash = web_token_hash(p_token) AND m.deleted_at IS NULL),
    jsonb_build_object('result', 'invalid'))
$$;

CREATE OR REPLACE FUNCTION public.public_demo_reschedule(p_token text, p_starts_at timestamptz) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  m demo_meetings;
  s demo_booking_settings;
  v_host uuid;
  v_day date := (p_starts_at AT TIME ZONE 'America/Lima')::date;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('demo_booking'));
  SELECT * INTO m FROM demo_meetings WHERE manage_token_hash = web_token_hash(p_token) AND deleted_at IS NULL FOR UPDATE;
  IF m.id IS NULL THEN RETURN jsonb_build_object('result', 'invalid'); END IF;
  IF m.status NOT IN ('proposed', 'confirmed', 'rescheduled') OR m.starts_at <= now() THEN
    RETURN jsonb_build_object('result', 'not_allowed', 'status', m.status);
  END IF;
  SELECT * INTO s FROM demo_booking_settings WHERE singleton AND deleted_at IS NULL;
  SELECT f.host_id INTO v_host FROM web_demo_free_slots(v_day - 1, v_day + 1, m.id) f
   WHERE f.starts_at = p_starts_at ORDER BY (f.host_id = m.host_id) DESC, f.host_id LIMIT 1;
  IF v_host IS NULL THEN RETURN jsonb_build_object('result', 'slot_unavailable'); END IF;
  UPDATE demo_meetings SET starts_at = p_starts_at, ends_at = p_starts_at + make_interval(mins => s.duration_minutes),
         host_id = v_host,
         status = CASE WHEN m.status = 'proposed' OR v_host IS DISTINCT FROM m.host_id THEN 'proposed' ELSE 'rescheduled' END,
         meeting_url = CASE WHEN v_host IS DISTINCT FROM m.host_id THEN NULL ELSE meeting_url END,
         calendar_event_ref = CASE WHEN v_host IS DISTINCT FROM m.host_id THEN NULL ELSE calendar_event_ref END,
         confirmed_at = CASE WHEN v_host IS DISTINCT FROM m.host_id THEN NULL ELSE confirmed_at END,
         reminder_24h_sent_at = NULL, reminder_1h_sent_at = NULL
   WHERE id = m.id RETURNING * INTO m;
  UPDATE demo_requests SET demo_scheduled_at = p_starts_at WHERE id = m.demo_request_id AND status = 'demo_scheduled';
  RETURN jsonb_build_object('result', 'ok', 'status', m.status, 'starts_at', m.starts_at, 'ends_at', m.ends_at);
END $$;

CREATE OR REPLACE FUNCTION public.public_demo_cancel(p_token text, p_reason text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  m demo_meetings;
BEGIN
  SELECT * INTO m FROM demo_meetings WHERE manage_token_hash = web_token_hash(p_token) AND deleted_at IS NULL FOR UPDATE;
  IF m.id IS NULL THEN RETURN jsonb_build_object('result', 'invalid'); END IF;
  IF m.status = 'cancelled' THEN RETURN jsonb_build_object('result', 'cancelled', 'replay', true); END IF;
  IF m.status NOT IN ('proposed', 'confirmed', 'rescheduled') THEN RETURN jsonb_build_object('result', 'not_allowed', 'status', m.status); END IF;
  UPDATE demo_meetings SET status = 'cancelled', cancel_reason = coalesce(left(nullif(trim(p_reason), ''), 1000), 'Cancelada por el visitante')
   WHERE id = m.id;
  RETURN jsonb_build_object('result', 'cancelled', 'replay', false);
END $$;

-- Panel: asignar, confirmar (con enlace) y cerrar una reunión.
CREATE OR REPLACE FUNCTION public.web_demo_meeting_assign(p_id uuid, p_host_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  m demo_meetings;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM demo_hosts WHERE id = p_host_id AND is_active AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'anfitrión inactivo o inexistente' USING ERRCODE = 'check_violation';
  END IF;
  UPDATE demo_meetings SET host_id = p_host_id,
         meeting_url = CASE WHEN host_id IS DISTINCT FROM p_host_id THEN NULL ELSE meeting_url END,
         calendar_event_ref = CASE WHEN host_id IS DISTINCT FROM p_host_id THEN NULL ELSE calendar_event_ref END
   WHERE id = p_id AND deleted_at IS NULL AND status IN ('proposed', 'confirmed', 'rescheduled') RETURNING * INTO m;
  IF m.id IS NULL THEN RAISE EXCEPTION 'solo se asigna una reunión vigente' USING ERRCODE = 'check_violation'; END IF;
  RETURN jsonb_build_object('id', m.id, 'host_id', m.host_id, 'status', m.status);
END $$;

CREATE OR REPLACE FUNCTION public.web_demo_meeting_confirm(p_id uuid, p_meeting_url text DEFAULT NULL, p_provider text DEFAULT NULL,
                                                           p_calendar_event_ref text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  m demo_meetings;
BEGIN
  UPDATE demo_meetings SET status = 'confirmed', confirmed_at = now(), meeting_provider = coalesce(p_provider, meeting_provider),
         meeting_url = coalesce(p_meeting_url, meeting_url), calendar_event_ref = coalesce(p_calendar_event_ref, calendar_event_ref)
   WHERE id = p_id AND deleted_at IS NULL AND status IN ('proposed', 'rescheduled', 'confirmed') RETURNING * INTO m;
  IF m.id IS NULL THEN RAISE EXCEPTION 'solo se confirma una reunión propuesta o reprogramada' USING ERRCODE = 'check_violation'; END IF;
  RETURN jsonb_build_object('id', m.id, 'status', m.status, 'meeting_url', m.meeting_url, 'confirmed_at', m.confirmed_at);
END $$;

CREATE OR REPLACE FUNCTION public.web_demo_meeting_complete(p_id uuid, p_outcome text DEFAULT NULL, p_notes text DEFAULT NULL,
                                                            p_no_show boolean DEFAULT false) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  m demo_meetings;
BEGIN
  UPDATE demo_meetings SET status = CASE WHEN p_no_show THEN 'no_show' ELSE 'completed' END,
         outcome = CASE WHEN p_no_show THEN outcome ELSE p_outcome END, outcome_notes = coalesce(p_notes, outcome_notes)
   WHERE id = p_id AND deleted_at IS NULL AND status IN ('confirmed', 'rescheduled') RETURNING * INTO m;
  IF m.id IS NULL THEN RAISE EXCEPTION 'solo se cierra una reunión confirmada' USING ERRCODE = 'check_violation'; END IF;
  RETURN jsonb_build_object('id', m.id, 'status', m.status, 'outcome', m.outcome);
END $$;

-- ---------- Métricas propias (solo con consentimiento analítico; sin IP ni datos personales) ----------
CREATE OR REPLACE FUNCTION public.public_record_event(p_visitor_id uuid, p_event jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_ok boolean;
  v_id uuid;
BEGIN
  SELECT coalesce((c.categories ->> 'analytics')::boolean, false) INTO v_ok
    FROM cookie_consents c WHERE c.visitor_id = p_visitor_id ORDER BY c.consented_at DESC, c.created_at DESC LIMIT 1;
  IF p_visitor_id IS NULL OR NOT coalesce(v_ok, false) THEN
    RAISE EXCEPTION 'evento rechazado: sin consentimiento de cookies analíticas' USING ERRCODE = 'insufficient_privilege';
  END IF;
  INSERT INTO site_events (event_type, path, element_key, utm_source, utm_medium, utm_campaign, source, device, session_hash)
  VALUES (p_event ->> 'event_type', left(p_event ->> 'path', 300), left(p_event ->> 'element_key', 80),
          left(p_event ->> 'utm_source', 100), left(p_event ->> 'utm_medium', 100), left(lower(p_event ->> 'utm_campaign'), 100),
          p_event ->> 'source', p_event ->> 'device', p_event ->> 'session_hash')
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('result', 'recorded');
END $$;

-- Job diario: agrega las vistas de un día (America/Lima) en site_analytics_daily (idempotente: recalcula el día).
CREATE OR REPLACE FUNCTION public.web_rollup_site_analytics(p_day date) RETURNS integer
LANGUAGE plpgsql AS $$
DECLARE
  n integer;
BEGIN
  WITH ev AS (
    SELECT coalesce(path, '/') AS path, coalesce(source, 'direct') AS source, coalesce(device, 'desktop') AS device, session_hash
      FROM site_events
     WHERE event_type IN ('page_view', 'campaign_view')
       AND occurred_at >= (p_day::timestamp AT TIME ZONE 'America/Lima') AND occurred_at < ((p_day + 1)::timestamp AT TIME ZONE 'America/Lima')),
  single AS (SELECT session_hash FROM ev GROUP BY session_hash HAVING count(*) = 1),
  agg AS (
    SELECT path, source, device, count(*)::integer AS visits, count(DISTINCT session_hash)::integer AS uv,
           count(*) FILTER (WHERE session_hash IN (SELECT session_hash FROM single))::integer AS bounces
      FROM ev GROUP BY path, source, device)
  INSERT INTO site_analytics_daily (day, path, source, device, visits, unique_visitors, bounces)
  SELECT p_day, path, source, device, visits, uv, bounces FROM agg
  ON CONFLICT (day, path, source, device) DO UPDATE SET visits = EXCLUDED.visits, unique_visitors = EXCLUDED.unique_visitors,
         bounces = EXCLUDED.bounces;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- Resumen del panel (#m-web/resumen): tráfico, fuentes, páginas, conversiones por formulario y CTA, tasa de conversión,
-- leads, demos pendientes, reclamos por vencer y campañas. Solo agregados; corre como escudo_platform.
CREATE OR REPLACE FUNCTION public.web_site_metrics(p_from date, p_to date) RETURNS jsonb
LANGUAGE sql STABLE AS $$
  WITH d AS (SELECT * FROM site_analytics_daily WHERE day BETWEEN p_from AND p_to AND deleted_at IS NULL),
  e AS (SELECT * FROM site_events WHERE occurred_at >= (p_from::timestamp AT TIME ZONE 'America/Lima')
                                    AND occurred_at < ((p_to + 1)::timestamp AT TIME ZONE 'America/Lima')),
  conv AS (SELECT * FROM e WHERE event_type IN ('form_submit', 'demo_booked', 'calculator_used', 'assessment_completed', 'whatsapp_click',
                                               'chatbot_lead', 'webinar_registered', 'savings_calculated', 'resource_download'))
  SELECT jsonb_build_object(
    'from', p_from, 'to', p_to,
    'visits', coalesce((SELECT sum(visits) FROM d), 0),
    'unique_visitors', coalesce((SELECT sum(unique_visitors) FROM d), 0),
    'bounces', coalesce((SELECT sum(bounces) FROM d), 0),
    'by_source', coalesce((SELECT jsonb_object_agg(source, v) FROM (SELECT source, sum(visits) AS v FROM d GROUP BY source) x), '{}'::jsonb),
    'by_device', coalesce((SELECT jsonb_object_agg(device, v) FROM (SELECT device, sum(visits) AS v FROM d GROUP BY device) x), '{}'::jsonb),
    'top_pages', coalesce((SELECT jsonb_agg(jsonb_build_object('path', path, 'visits', v) ORDER BY v DESC, path)
                             FROM (SELECT path, sum(visits) AS v FROM d GROUP BY path ORDER BY v DESC, path LIMIT 10) x), '[]'::jsonb),
    'conversions', coalesce((SELECT jsonb_object_agg(event_type, n) FROM (SELECT event_type, count(*) AS n FROM conv GROUP BY event_type) x), '{}'::jsonb),
    'cta_clicks', coalesce((SELECT jsonb_object_agg(k, n) FROM (SELECT coalesce(element_key, 'other') AS k, count(*) AS n FROM e
                                                                 WHERE event_type = 'cta_click' GROUP BY 1) x), '{}'::jsonb),
    'conversion_rate', CASE WHEN coalesce((SELECT sum(visits) FROM d), 0) = 0 THEN NULL
                            ELSE round(100.0 * (SELECT count(*) FROM conv WHERE event_type <> 'whatsapp_click') / (SELECT sum(visits) FROM d), 2) END,
    'leads', (SELECT count(*) FROM marketing_leads WHERE deleted_at IS NULL
                AND created_at >= (p_from::timestamp AT TIME ZONE 'America/Lima') AND created_at < ((p_to + 1)::timestamp AT TIME ZONE 'America/Lima')),
    'demos_pending', (SELECT count(*) FROM demo_meetings WHERE status = 'proposed' AND deleted_at IS NULL),
    'demo_requests_new', (SELECT count(*) FROM demo_requests WHERE status = 'new' AND deleted_at IS NULL),
    'complaints_due_soon', (SELECT count(*) FROM consumer_complaints c
                             WHERE c.status IN ('received', 'in_progress', 'extended')
                               AND coalesce(c.extended_until, c.response_due_on)
                                   <= add_business_days(current_date, coalesce(web_try_numeric(platform_legal_param('web.complaint_warning_days'))::integer, 0))),
    'campaigns', coalesce((SELECT jsonb_agg(jsonb_build_object('utm_campaign', x.utm_campaign, 'name', c.name, 'views', x.views, 'conversions', x.conv)
                                            ORDER BY x.views DESC)
                             FROM (SELECT utm_campaign, count(*) FILTER (WHERE event_type IN ('page_view', 'campaign_view')) AS views,
                                          count(*) FILTER (WHERE event_type IN ('form_submit', 'demo_booked', 'chatbot_lead', 'webinar_registered',
                                                                                'calculator_used', 'savings_calculated', 'assessment_completed')) AS conv
                                     FROM e WHERE utm_campaign IS NOT NULL GROUP BY utm_campaign) x
                             LEFT JOIN campaigns c ON c.utm_campaign = x.utm_campaign AND c.deleted_at IS NULL), '[]'::jsonb))
$$;

-- ---------- Biblioteca de medios: dónde se usa cada archivo ----------
CREATE OR REPLACE FUNCTION public.web_media_usages(p_media_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  m site_media;
  u jsonb;
BEGIN
  SELECT * INTO m FROM site_media WHERE id = p_media_id AND deleted_at IS NULL;
  IF m.id IS NULL THEN RAISE EXCEPTION 'medio no encontrado' USING ERRCODE = 'no_data_found'; END IF;
  SELECT coalesce(jsonb_agg(x), '[]'::jsonb) INTO u FROM (
    SELECT jsonb_build_object('table', 'success_story_media', 'id', success_story_id) x FROM success_story_media WHERE media_id = m.id AND deleted_at IS NULL
    UNION ALL SELECT jsonb_build_object('table', 'chatbot_settings', 'id', id) FROM chatbot_settings WHERE avatar_media_id = m.id
    UNION ALL SELECT jsonb_build_object('table', 'site_popups', 'id', id) FROM site_popups WHERE image_media_id = m.id AND deleted_at IS NULL
    UNION ALL SELECT jsonb_build_object('table', 'site_integrations', 'id', id) FROM site_integrations WHERE logo_media_id = m.id AND deleted_at IS NULL
    UNION ALL SELECT jsonb_build_object('table', 'webinars', 'id', id) FROM webinars WHERE m.id IN (recording_media_id, cover_media_id) AND deleted_at IS NULL
    UNION ALL SELECT jsonb_build_object('table', 'site_settings', 'id', id) FROM site_settings
               WHERE m.file_id IN (logo_file_id, logo_dark_file_id, favicon_file_id, default_og_image_file_id)
    UNION ALL SELECT jsonb_build_object('table', 'site_pages', 'id', id, 'slug', slug) FROM site_pages
               WHERE deleted_at IS NULL AND (og_image_file_id = m.file_id OR blocks::text LIKE '%' || m.file_id::text || '%' OR blocks::text LIKE '%' || m.id::text || '%')
    UNION ALL SELECT jsonb_build_object('table', 'resource_items', 'id', id) FROM resource_items WHERE m.file_id IN (file_id, cover_file_id) AND deleted_at IS NULL
    UNION ALL SELECT jsonb_build_object('table', 'success_stories', 'id', id) FROM success_stories WHERE logo_file_id = m.file_id AND deleted_at IS NULL
    UNION ALL SELECT jsonb_build_object('table', 'site_products', 'id', id) FROM site_products WHERE logo_file_id = m.file_id AND deleted_at IS NULL
    UNION ALL SELECT jsonb_build_object('table', 'site_testimonials', 'id', id) FROM site_testimonials WHERE photo_file_id = m.file_id AND deleted_at IS NULL) s;
  UPDATE site_media SET usage_count = jsonb_array_length(u) WHERE id = m.id;
  RETURN jsonb_build_object('id', m.id, 'usage_count', jsonb_array_length(u), 'usages', u);
END $$;

-- ---------- Chatbot ----------
-- Horario de atención: {} = siempre; {"timezone": "...", "1": [["09:00","18:00"]], …} por día ISO.
CREATE OR REPLACE FUNCTION public.web_chatbot_is_open(p_hours jsonb, p_at timestamptz DEFAULT now()) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT CASE WHEN p_hours IS NULL OR p_hours = '{}'::jsonb THEN true
         ELSE EXISTS (SELECT 1 FROM jsonb_array_elements(p_hours -> extract(isodow FROM (p_at AT TIME ZONE coalesce(p_hours ->> 'timezone', 'America/Lima')))::int::text) r
                       WHERE (p_at AT TIME ZONE coalesce(p_hours ->> 'timezone', 'America/Lima'))::time >= (r ->> 0)::time
                         AND (p_at AT TIME ZONE coalesce(p_hours ->> 'timezone', 'America/Lima'))::time < (r ->> 1)::time) END
$$;

-- Configuración pública del widget e intenciones publicadas. Nunca la referencia al secreto del proveedor de IA.
CREATE OR REPLACE FUNCTION public.public_chatbot_config() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT CASE WHEN NOT c.enabled THEN jsonb_build_object('result', 'disabled') ELSE jsonb_build_object(
             'result', 'ok', 'mode', c.mode, 'greeting', c.greeting,
             'avatar_file_id', (SELECT m.file_id FROM site_media m WHERE m.id = c.avatar_media_id AND m.deleted_at IS NULL),
             'avatar_alt_text', (SELECT m.alt_text FROM site_media m WHERE m.id = c.avatar_media_id AND m.deleted_at IS NULL),
             'is_open', web_chatbot_is_open(c.business_hours_json), 'business_hours', c.business_hours_json,
             'offline_message', c.offline_message, 'ask_lead_after_messages', c.ask_lead_after_messages,
             'handoff_whatsapp', c.handoff_whatsapp AND s.whatsapp_number IS NOT NULL,
             'whatsapp_number', CASE WHEN c.handoff_whatsapp THEN s.whatsapp_number END,
             'intents', coalesce((SELECT jsonb_agg(jsonb_build_object('id', i.id, 'name', i.name, 'answer', i.answer, 'cta_type', i.cta_type,
                                                                      'cta_url', i.cta_url) ORDER BY i.sort_order, i.name)
                                    FROM chatbot_intents i WHERE i.status = 'published' AND i.deleted_at IS NULL), '[]'::jsonb)) END
      FROM chatbot_settings c LEFT JOIN site_settings s ON s.singleton AND s.deleted_at IS NULL
     WHERE c.singleton AND c.deleted_at IS NULL),
    jsonb_build_object('result', 'disabled'))
$$;

CREATE OR REPLACE FUNCTION public.public_chatbot_start(p_session_hash text, p_path text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  c chatbot_settings;
  v_id uuid;
BEGIN
  SELECT * INTO c FROM chatbot_settings WHERE singleton AND deleted_at IS NULL;
  IF c.id IS NULL OR NOT c.enabled THEN RETURN jsonb_build_object('result', 'disabled'); END IF;
  INSERT INTO chatbot_conversations (session_hash, path) VALUES (p_session_hash, left(p_path, 300)) RETURNING id INTO v_id;
  RETURN jsonb_build_object('result', 'ok', 'conversation_id', v_id, 'greeting', c.greeting,
                            'is_open', web_chatbot_is_open(c.business_hours_json), 'offline_message', c.offline_message);
END $$;

-- Mensaje del visitante: responde con la intención publicada (botón o frase) o, en modo IA, pide a la API que redacte
-- con contenido publicado (needs_ai). Solo la sesión que abrió la conversación puede escribir en ella.
CREATE OR REPLACE FUNCTION public.public_chatbot_message(p_conversation_id uuid, p_session_hash text, p_body text,
                                                         p_intent_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  c chatbot_settings;
  v chatbot_conversations;
  i chatbot_intents;
  v_visitor integer;
  v_reply text;
BEGIN
  SELECT * INTO c FROM chatbot_settings WHERE singleton AND deleted_at IS NULL;
  IF c.id IS NULL OR NOT c.enabled THEN RETURN jsonb_build_object('result', 'disabled'); END IF;
  SELECT * INTO v FROM chatbot_conversations WHERE id = p_conversation_id AND session_hash = p_session_hash AND ended_at IS NULL AND deleted_at IS NULL FOR UPDATE;
  IF v.id IS NULL THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  IF v.message_count >= 200 THEN RETURN jsonb_build_object('result', 'limit_reached'); END IF;
  INSERT INTO chatbot_messages (conversation_id, sender, body) VALUES (v.id, 'visitor', left(p_body, 2000));
  IF p_intent_id IS NOT NULL THEN
    SELECT * INTO i FROM chatbot_intents WHERE id = p_intent_id AND status = 'published' AND deleted_at IS NULL;
  ELSE
    SELECT x.* INTO i FROM chatbot_intents x
     WHERE x.status = 'published' AND x.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM jsonb_array_elements_text(x.trigger_phrases_json) ph
                    WHERE length(trim(ph)) > 0 AND lower(p_body) LIKE '%' || lower(trim(ph)) || '%')
     ORDER BY x.sort_order, x.name LIMIT 1;
  END IF;
  SELECT count(*) + 1 INTO v_visitor FROM chatbot_messages WHERE conversation_id = v.id AND sender = 'visitor';
  IF i.id IS NULL AND c.mode = 'ai' THEN
    UPDATE chatbot_conversations SET message_count = message_count + 1 WHERE id = v.id;
    RETURN jsonb_build_object('result', 'needs_ai', 'ask_lead', v.lead_id IS NULL AND v_visitor - 1 >= c.ask_lead_after_messages);
  END IF;
  v_reply := coalesce(i.answer, CASE WHEN web_chatbot_is_open(c.business_hours_json) THEN
               'No tengo una respuesta para eso. Puedes dejarnos tus datos o escribirnos por WhatsApp.'
             ELSE coalesce(c.offline_message, 'Estamos fuera de horario. Déjanos tus datos y te contactamos.') END);
  INSERT INTO chatbot_messages (conversation_id, sender, body, intent_id) VALUES (v.id, 'bot', left(v_reply, 2000), i.id);
  UPDATE chatbot_conversations SET message_count = message_count + 2 WHERE id = v.id;
  RETURN jsonb_build_object('result', CASE WHEN i.id IS NULL THEN 'no_match' ELSE 'ok' END, 'reply', v_reply,
                            'intent_id', i.id, 'cta_type', coalesce(i.cta_type, 'none'), 'cta_url', i.cta_url,
                            'ask_lead', v.lead_id IS NULL AND v_visitor - 1 >= c.ask_lead_after_messages,
                            'handoff_whatsapp', c.handoff_whatsapp);
END $$;

-- Respuesta redactada por la IA (la llama la API tras el proveedor, con solo contenido publicado; no es una ruta pública).
CREATE OR REPLACE FUNCTION public.public_chatbot_record_ai_reply(p_conversation_id uuid, p_session_hash text, p_body text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v chatbot_conversations;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM chatbot_settings WHERE singleton AND enabled AND mode = 'ai' AND deleted_at IS NULL) THEN
    RETURN jsonb_build_object('result', 'disabled');
  END IF;
  SELECT * INTO v FROM chatbot_conversations WHERE id = p_conversation_id AND session_hash = p_session_hash AND ended_at IS NULL AND deleted_at IS NULL FOR UPDATE;
  IF v.id IS NULL THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  INSERT INTO chatbot_messages (conversation_id, sender, body, used_ai) VALUES (v.id, 'bot', left(p_body, 2000), true);
  UPDATE chatbot_conversations SET message_count = message_count + 1 WHERE id = v.id;
  RETURN jsonb_build_object('result', 'ok');
END $$;

-- Datos del visitante desde el chatbot: exige privacidad; el consentimiento comercial va aparte (lead con origen contact).
CREATE OR REPLACE FUNCTION public.public_chatbot_lead(p_conversation_id uuid, p_session_hash text, p_data jsonb, p_ip_hash bytea DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v chatbot_conversations;
  v_lead uuid;
BEGIN
  SELECT * INTO v FROM chatbot_conversations WHERE id = p_conversation_id AND session_hash = p_session_hash AND deleted_at IS NULL FOR UPDATE;
  IF v.id IS NULL THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  v_lead := web_upsert_lead(p_data, 'contact', p_ip_hash);
  UPDATE chatbot_conversations SET lead_id = v_lead, handoff = CASE WHEN handoff = 'none' THEN 'form' ELSE handoff END WHERE id = v.id;
  RETURN jsonb_build_object('result', 'ok', 'lead_registered', true, 'replay', v.lead_id IS NOT DISTINCT FROM v_lead);
END $$;

CREATE OR REPLACE FUNCTION public.web_publish_chatbot_intent(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  i chatbot_intents;
BEGIN
  UPDATE chatbot_intents SET status = 'published' WHERE id = p_id AND deleted_at IS NULL AND status IN ('draft', 'archived', 'published')
  RETURNING * INTO i;
  IF i.id IS NULL THEN RAISE EXCEPTION 'intención no encontrada' USING ERRCODE = 'no_data_found'; END IF;
  IF jsonb_array_length(i.trigger_phrases_json) = 0 THEN
    RAISE EXCEPTION 'la intención necesita al menos una frase disparadora' USING ERRCODE = 'check_violation';
  END IF;
  RETURN jsonb_build_object('id', i.id, 'status', i.status);
END $$;

-- ---------- Conexión con el CRM ----------
-- Encola un envío por cada conexión activa que sincroniza la entidad. El Libro de Reclamaciones no tiene este trigger
-- (nunca se envía). Idempotente: create una vez por entidad; update una vez por versión (updated_at).
CREATE OR REPLACE FUNCTION public.trg_crm_enqueue() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_entity text := TG_ARGV[0];
  v_action text := CASE WHEN TG_OP = 'INSERT' THEN 'create' ELSE 'update' END;
BEGIN
  IF TG_OP = 'UPDATE' AND to_jsonb(NEW) - 'updated_at' - 'updated_by' = to_jsonb(OLD) - 'updated_at' - 'updated_by' THEN
    RETURN NULL;
  END IF;
  INSERT INTO crm_sync_events (connection_id, entity_type, entity_id, action, idempotency_key)
  SELECT c.id, v_entity, NEW.id, v_action,
         c.id || ':' || v_entity || ':' || NEW.id || ':' || v_action ||
         CASE WHEN v_action = 'update' THEN ':' || (extract(epoch FROM NEW.updated_at) * 1000000)::bigint ELSE '' END
    FROM crm_connections c
   WHERE c.status = 'active' AND c.deleted_at IS NULL AND c.entities_json ? v_entity
  ON CONFLICT (idempotency_key) DO NOTHING;
  RETURN NULL;
END $$;
CREATE TRIGGER trg_marketing_leads_crm AFTER INSERT OR UPDATE ON marketing_leads FOR EACH ROW EXECUTE FUNCTION trg_crm_enqueue('marketing_lead');
CREATE TRIGGER trg_demo_requests_crm AFTER INSERT OR UPDATE ON demo_requests FOR EACH ROW EXECUTE FUNCTION trg_crm_enqueue('demo_request');
CREATE TRIGGER trg_demo_meetings_crm AFTER INSERT OR UPDATE ON demo_meetings FOR EACH ROW EXECUTE FUNCTION trg_crm_enqueue('demo_meeting');
CREATE TRIGGER trg_partner_applications_crm AFTER INSERT OR UPDATE ON partner_applications FOR EACH ROW EXECUTE FUNCTION trg_crm_enqueue('partner_application');
CREATE TRIGGER trg_newsletter_subscribers_crm AFTER INSERT OR UPDATE ON newsletter_subscribers FOR EACH ROW EXECUTE FUNCTION trg_crm_enqueue('newsletter_subscriber');

-- Resultado de un envío (lo registra el worker): sent con id externo o failed con reintento exponencial (tope 6 h).
CREATE OR REPLACE FUNCTION public.web_crm_event_result(p_id uuid, p_ok boolean, p_response_code integer DEFAULT NULL,
                                                       p_external_id text DEFAULT NULL, p_error text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  e crm_sync_events;
BEGIN
  UPDATE crm_sync_events SET attempts = attempts + 1, response_code = p_response_code,
         status = CASE WHEN p_ok THEN 'sent' ELSE 'failed' END,
         external_id = coalesce(p_external_id, external_id), last_error = CASE WHEN p_ok THEN NULL ELSE left(p_error, 2000) END,
         next_attempt_at = CASE WHEN p_ok THEN NULL ELSE now() + least(interval '6 hours', interval '1 minute' * power(2, attempts)) END
   WHERE id = p_id AND status IN ('pending', 'failed') RETURNING * INTO e;
  IF e.id IS NULL THEN RAISE EXCEPTION 'envío no encontrado o ya enviado' USING ERRCODE = 'check_violation'; END IF;
  UPDATE crm_connections SET last_sync_at = CASE WHEN p_ok THEN now() ELSE last_sync_at END,
         last_error = CASE WHEN p_ok THEN last_error ELSE left(p_error, 2000) END WHERE id = e.connection_id;
  RETURN jsonb_build_object('id', e.id, 'status', e.status, 'attempts', e.attempts, 'next_attempt_at', e.next_attempt_at);
END $$;

CREATE OR REPLACE FUNCTION public.web_crm_retry_event(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  e crm_sync_events;
BEGIN
  UPDATE crm_sync_events SET status = 'pending', next_attempt_at = now() WHERE id = p_id AND status IN ('failed', 'skipped') RETURNING * INTO e;
  IF e.id IS NULL THEN RAISE EXCEPTION 'solo se reintenta un envío fallido u omitido' USING ERRCODE = 'check_violation'; END IF;
  RETURN jsonb_build_object('id', e.id, 'status', e.status, 'next_attempt_at', e.next_attempt_at);
END $$;

-- Resultado de «probar conexión» (la prueba la hace la API con el proveedor; aquí se registra). Nunca activa sola una conexión.
CREATE OR REPLACE FUNCTION public.web_crm_connection_tested(p_id uuid, p_ok boolean, p_error text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  c crm_connections;
BEGIN
  UPDATE crm_connections SET last_error = CASE WHEN p_ok THEN NULL ELSE left(coalesce(p_error, 'error'), 2000) END,
         status = CASE WHEN NOT p_ok AND status = 'active' THEN 'error' WHEN p_ok AND status = 'error' THEN 'active' ELSE status END
   WHERE id = p_id AND deleted_at IS NULL RETURNING * INTO c;
  IF c.id IS NULL THEN RAISE EXCEPTION 'conexión no encontrada' USING ERRCODE = 'no_data_found'; END IF;
  RETURN jsonb_build_object('id', c.id, 'status', c.status, 'ok', p_ok, 'last_error', c.last_error);
END $$;

-- ------------------------------------------------------------------ WEB v1.5-b (spec/brief-web-v15.md, ampliación)
-- Landings de campaña: noindex por defecto al crearse.
CREATE OR REPLACE FUNCTION public.trg_site_pages_campaign_noindex() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.page_type = 'campaign' THEN NEW.noindex := true; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_site_pages_campaign_noindex BEFORE INSERT ON site_pages FOR EACH ROW EXECUTE FUNCTION trg_site_pages_campaign_noindex();

-- Página de campaña publicada y vigente (campaña activa dentro de sus fechas en America/Lima).
CREATE OR REPLACE FUNCTION public.public_campaign_page(p_slug text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('result', 'ok', 'slug', p.slug, 'page_type', p.page_type, 'published_at', p.published_at,
             'whatsapp_message', coalesce(p.whatsapp_message, (SELECT s.whatsapp_default_message FROM site_settings s WHERE s.singleton)),
             'campaign', jsonb_build_object('channel', c.channel, 'form_type', c.form_type, 'utm_source', c.utm_source,
                                            'utm_medium', c.utm_medium, 'utm_campaign', c.utm_campaign, 'ends_on', c.ends_on)) || p.published_snapshot
      FROM site_pages p JOIN campaigns c ON c.landing_page_id = p.id AND c.status = 'active' AND c.deleted_at IS NULL
     WHERE p.slug = lower(p_slug) AND p.page_type = 'campaign' AND p.status = 'published' AND p.deleted_at IS NULL AND p.published_snapshot IS NOT NULL
       AND (c.starts_on IS NULL OR c.starts_on <= (now() AT TIME ZONE 'America/Lima')::date)
       AND (c.ends_on IS NULL OR c.ends_on >= (now() AT TIME ZONE 'America/Lima')::date)
     ORDER BY c.starts_on DESC NULLS LAST LIMIT 1),
    jsonb_build_object('result', 'not_found'))
$$;

CREATE OR REPLACE FUNCTION public.web_campaign_action(p_id uuid, p_action text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  c campaigns;
BEGIN
  SELECT * INTO c FROM campaigns WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF c.id IS NULL THEN RAISE EXCEPTION 'campaña no encontrada' USING ERRCODE = 'no_data_found'; END IF;
  IF p_action = 'activate' AND c.status IN ('draft', 'paused') THEN
    IF NOT EXISTS (SELECT 1 FROM site_pages p WHERE p.id = c.landing_page_id AND p.page_type = 'campaign' AND p.status = 'published' AND p.deleted_at IS NULL) THEN
      RAISE EXCEPTION 'la campaña necesita una landing de campaña publicada' USING ERRCODE = 'check_violation';
    END IF;
    UPDATE campaigns SET status = 'active' WHERE id = c.id RETURNING * INTO c;
  ELSIF p_action = 'pause' AND c.status = 'active' THEN
    UPDATE campaigns SET status = 'paused' WHERE id = c.id RETURNING * INTO c;
  ELSIF p_action = 'finish' AND c.status IN ('active', 'paused') THEN
    UPDATE campaigns SET status = 'finished' WHERE id = c.id RETURNING * INTO c;
  ELSE
    RAISE EXCEPTION 'transición inválida % desde %', p_action, c.status USING ERRCODE = 'check_violation';
  END IF;
  RETURN jsonb_build_object('id', c.id, 'status', c.status);
END $$;

-- Ruta donde nunca se muestra una ventana emergente: Libro de Reclamaciones, políticas y formularios.
CREATE OR REPLACE FUNCTION public.web_popup_forbidden_path(p_path text) RETURNS boolean
LANGUAGE sql STABLE AS $$
  SELECT p_path IS NULL
      OR p_path ~ '^/(libro-de-reclamaciones|reclamaciones|legal|politicas|demo|contacto|cotizacion)(/|$)'
      OR EXISTS (SELECT 1 FROM legal_documents d WHERE d.deleted_at IS NULL AND p_path IN ('/' || d.slug, '/legal/' || d.slug))
      OR EXISTS (SELECT 1 FROM site_pages p WHERE p.deleted_at IS NULL AND p.page_type IN ('legal', 'contact') AND p_path = '/' || p.slug)
$$;

CREATE OR REPLACE FUNCTION public.web_path_matches(p_path text, p_patterns jsonb) RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT EXISTS (SELECT 1 FROM jsonb_array_elements_text(p_patterns) x
                  WHERE p_path = x OR (right(x, 1) = '*' AND left(p_path, length(x) - 1) = left(x, length(x) - 1)))
$$;

-- Ventanas emergentes activas para una ruta y dispositivo, con el tope por visita (parámetro web.popup_max_per_visit).
CREATE OR REPLACE FUNCTION public.public_site_popups(p_path text, p_device text DEFAULT 'desktop') RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok',
    'max_per_visit', coalesce(web_try_numeric(platform_legal_param('web.popup_max_per_visit'))::integer, 1),
    'popups', CASE WHEN web_popup_forbidden_path(p_path) THEN '[]'::jsonb ELSE coalesce((
      SELECT jsonb_agg(jsonb_build_object('id', w.id, 'trigger_type', w.trigger_type, 'trigger_value', w.trigger_value,
               'offer_type', w.offer_type, 'title', w.title, 'body', w.body, 'cta_label', w.cta_label,
               'image_file_id', m.file_id, 'image_alt_text', m.alt_text, 'frequency_days', w.frequency_days) ORDER BY w.created_at)
        FROM site_popups w LEFT JOIN site_media m ON m.id = w.image_media_id AND m.deleted_at IS NULL
       WHERE w.status = 'active' AND w.deleted_at IS NULL
         AND (w.starts_at IS NULL OR w.starts_at <= now()) AND (w.ends_at IS NULL OR w.ends_at > now())
         AND (w.devices = 'all' OR w.devices = CASE WHEN p_device = 'tablet' THEN 'mobile' ELSE p_device END)
         AND (jsonb_array_length(w.pages_json) = 0 OR web_path_matches(p_path, w.pages_json))
         AND NOT web_path_matches(p_path, w.excluded_pages_json)), '[]'::jsonb) END)
$$;

CREATE OR REPLACE FUNCTION public.web_popup_action(p_id uuid, p_action text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  w site_popups;
BEGIN
  UPDATE site_popups SET status = CASE p_action WHEN 'activate' THEN 'active' WHEN 'pause' THEN 'paused' END
   WHERE id = p_id AND deleted_at IS NULL AND ((p_action = 'activate' AND status IN ('draft', 'paused')) OR (p_action = 'pause' AND status = 'active'))
  RETURNING * INTO w;
  IF w.id IS NULL THEN RAISE EXCEPTION 'transición inválida de la ventana emergente' USING ERRCODE = 'check_violation'; END IF;
  RETURN jsonb_build_object('id', w.id, 'status', w.status);
END $$;

-- Integraciones publicadas con su estado veraz.
CREATE OR REPLACE FUNCTION public.public_site_integrations() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'integrations', coalesce(jsonb_agg(jsonb_build_object(
           'name', i.name, 'slug', i.slug, 'category', i.category, 'description', i.description, 'availability', i.availability,
           'docs_url', i.docs_url, 'logo_file_id', m.file_id, 'logo_alt_text', m.alt_text) ORDER BY i.category, i.sort_order, i.name), '[]'::jsonb))
    FROM site_integrations i LEFT JOIN site_media m ON m.id = i.logo_media_id AND m.deleted_at IS NULL
   WHERE i.status = 'published' AND i.deleted_at IS NULL
$$;

-- Novedades del producto (web y app).
CREATE OR REPLACE FUNCTION public.public_product_updates(p_limit integer DEFAULT 20, p_in_app boolean DEFAULT false) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'updates', coalesce(jsonb_agg(x.j ORDER BY x.published_at DESC), '[]'::jsonb))
    FROM (SELECT jsonb_build_object('slug', u.slug, 'title', u.title, 'category', u.category, 'modules', u.modules_json,
                                    'excerpt', left(u.body, 240), 'published_at', u.published_at) AS j, u.published_at
            FROM product_updates u
           WHERE u.status = 'published' AND u.deleted_at IS NULL AND (NOT p_in_app OR u.show_in_app)
           ORDER BY u.published_at DESC LIMIT least(greatest(coalesce(p_limit, 20), 1), 100)) x
$$;

CREATE OR REPLACE FUNCTION public.public_product_update(p_slug text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((SELECT jsonb_build_object('result', 'ok', 'slug', u.slug, 'title', u.title, 'body', u.body, 'category', u.category,
                                             'modules', u.modules_json, 'published_at', u.published_at)
                     FROM product_updates u WHERE u.slug = lower(p_slug) AND u.status = 'published' AND u.deleted_at IS NULL),
                  jsonb_build_object('result', 'not_found'))
$$;

CREATE OR REPLACE FUNCTION public.web_publish_product_update(p_id uuid) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  u product_updates;
BEGIN
  UPDATE product_updates SET status = 'published', published_at = coalesce(published_at, now())
   WHERE id = p_id AND deleted_at IS NULL AND status IN ('draft', 'archived', 'published') RETURNING * INTO u;
  IF u.id IS NULL THEN RAISE EXCEPTION 'novedad no encontrada' USING ERRCODE = 'no_data_found'; END IF;
  RETURN jsonb_build_object('id', u.id, 'status', u.status, 'published_at', u.published_at, 'notify_subscribers', u.notify_subscribers);
END $$;

-- ---------- Webinars ----------
CREATE OR REPLACE FUNCTION public.web_webinar_public_json(w webinars) RETURNS jsonb
LANGUAGE sql STABLE AS $$
  SELECT jsonb_build_object('slug', w.slug, 'title', w.title, 'description', w.description, 'speaker_name', w.speaker_name,
           'speaker_title', w.speaker_title, 'starts_at', w.starts_at, 'duration_minutes', w.duration_minutes,
           'meeting_provider', w.meeting_provider, 'status', w.status,
           'cover_file_id', (SELECT m.file_id FROM site_media m WHERE m.id = w.cover_media_id AND m.deleted_at IS NULL),
           'recording_file_id', CASE WHEN w.recording_public AND w.recording_informed
                                     THEN (SELECT m.file_id FROM site_media m WHERE m.id = w.recording_media_id AND m.deleted_at IS NULL) END,
           'capacity', w.capacity,
           'seats_left', CASE WHEN w.capacity IS NULL THEN NULL ELSE greatest(w.capacity - (SELECT count(*) FROM webinar_registrations r
                               WHERE r.webinar_id = w.id AND r.status IN ('registered', 'attended') AND r.deleted_at IS NULL), 0) END,
           'registration_open', w.status = 'published' AND w.starts_at > now())
$$;

-- Próximos y grabados (publicados, en vivo o finalizados). Nunca el enlace de reunión ni datos de inscritos.
CREATE OR REPLACE FUNCTION public.public_webinars() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok',
    'upcoming', coalesce((SELECT jsonb_agg(web_webinar_public_json(w) ORDER BY w.starts_at) FROM webinars w
                           WHERE w.status IN ('published', 'live') AND w.deleted_at IS NULL), '[]'::jsonb),
    'recorded', coalesce((SELECT jsonb_agg(web_webinar_public_json(w) ORDER BY w.starts_at DESC) FROM webinars w
                           WHERE w.status = 'finished' AND w.recording_public AND w.recording_informed AND w.deleted_at IS NULL), '[]'::jsonb))
$$;

CREATE OR REPLACE FUNCTION public.public_webinar(p_slug text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((SELECT jsonb_build_object('result', 'ok') || web_webinar_public_json(w) FROM webinars w
                    WHERE w.slug = lower(p_slug) AND w.status IN ('published', 'live', 'finished') AND w.deleted_at IS NULL),
                  jsonb_build_object('result', 'not_found'))
$$;

-- Inscripción: lead con consentimiento (origen webinar), una por persona y webinar (idempotente), con cupo bajo candado.
CREATE OR REPLACE FUNCTION public.public_webinar_register(p_slug text, p_data jsonb, p_manage_token text, p_ip_hash bytea DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  w webinars;
  r webinar_registrations;
  v_lead uuid;
  v_used integer;
BEGIN
  SELECT * INTO w FROM webinars WHERE slug = lower(p_slug) AND deleted_at IS NULL FOR UPDATE;
  IF w.id IS NULL OR w.status NOT IN ('published', 'live', 'finished') THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  IF w.status <> 'published' OR w.starts_at <= now() THEN RETURN jsonb_build_object('result', 'closed'); END IF;
  IF length(coalesce(p_manage_token, '')) < 32 THEN RAISE EXCEPTION 'token de gestión demasiado corto' USING ERRCODE = 'check_violation'; END IF;
  v_lead := web_upsert_lead(p_data, 'webinar', p_ip_hash);
  SELECT * INTO r FROM webinar_registrations WHERE webinar_id = w.id AND lead_id = v_lead AND deleted_at IS NULL FOR UPDATE;
  IF r.id IS NOT NULL AND r.status IN ('registered', 'attended') THEN
    RETURN jsonb_build_object('result', 'registered', 'replay', true, 'registration_id', r.id);
  END IF;
  SELECT count(*) INTO v_used FROM webinar_registrations WHERE webinar_id = w.id AND status IN ('registered', 'attended') AND deleted_at IS NULL;
  IF w.capacity IS NOT NULL AND v_used >= w.capacity THEN RETURN jsonb_build_object('result', 'full'); END IF;
  IF r.id IS NOT NULL THEN
    UPDATE webinar_registrations SET status = 'registered', manage_token_hash = web_token_hash(p_manage_token), registered_at = now(),
           reminder_24h_sent_at = NULL, reminder_1h_sent_at = NULL WHERE id = r.id RETURNING * INTO r;
  ELSE
    INSERT INTO webinar_registrations (webinar_id, lead_id, manage_token_hash) VALUES (w.id, v_lead, web_token_hash(p_manage_token)) RETURNING * INTO r;
  END IF;
  RETURN jsonb_build_object('result', 'registered', 'replay', false, 'registration_id', r.id);
END $$;

CREATE OR REPLACE FUNCTION public.public_webinar_cancel(p_token text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  r webinar_registrations;
BEGIN
  SELECT * INTO r FROM webinar_registrations WHERE manage_token_hash = web_token_hash(p_token) AND deleted_at IS NULL FOR UPDATE;
  IF r.id IS NULL THEN RETURN jsonb_build_object('result', 'invalid'); END IF;
  IF r.status = 'cancelled' THEN RETURN jsonb_build_object('result', 'cancelled', 'replay', true); END IF;
  IF r.status <> 'registered' THEN RETURN jsonb_build_object('result', 'not_allowed'); END IF;
  UPDATE webinar_registrations SET status = 'cancelled' WHERE id = r.id;
  RETURN jsonb_build_object('result', 'cancelled', 'replay', false);
END $$;

CREATE OR REPLACE FUNCTION public.web_webinar_action(p_id uuid, p_action text) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  w webinars;
BEGIN
  SELECT * INTO w FROM webinars WHERE id = p_id AND deleted_at IS NULL FOR UPDATE;
  IF w.id IS NULL THEN RAISE EXCEPTION 'webinar no encontrado' USING ERRCODE = 'no_data_found'; END IF;
  IF p_action = 'publish' AND w.status = 'draft' THEN
    UPDATE webinars SET status = 'published' WHERE id = w.id RETURNING * INTO w;
  ELSIF p_action = 'start' AND w.status = 'published' THEN
    UPDATE webinars SET status = 'live' WHERE id = w.id RETURNING * INTO w;
  ELSIF p_action = 'finish' AND w.status IN ('published', 'live') THEN
    UPDATE webinars SET status = 'finished' WHERE id = w.id RETURNING * INTO w;
    UPDATE webinar_registrations SET status = 'no_show' WHERE webinar_id = w.id AND status = 'registered';
  ELSIF p_action = 'cancel' AND w.status IN ('draft', 'published') THEN
    UPDATE webinars SET status = 'cancelled' WHERE id = w.id RETURNING * INTO w;
  ELSE
    RAISE EXCEPTION 'transición inválida % desde %', p_action, w.status USING ERRCODE = 'check_violation';
  END IF;
  RETURN jsonb_build_object('id', w.id, 'status', w.status);
END $$;

-- ---------- Reseñas de Google (reales, por la API oficial; caché con expiración) ----------
-- Reemplaza la caché de una fuente con lo que entregó el proveedor (texto sin editar). Expira según cache_ttl_hours, con
-- el tope del parámetro web.review_cache_max_hours (términos del proveedor).
CREATE OR REPLACE FUNCTION public.web_store_review_snapshots(p_source_id uuid, p_reviews jsonb) RETURNS jsonb
LANGUAGE plpgsql AS $$
DECLARE
  s review_sources;
  v_hours integer;
  n integer;
BEGIN
  SELECT * INTO s FROM review_sources WHERE id = p_source_id AND deleted_at IS NULL FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'fuente de reseñas no encontrada' USING ERRCODE = 'no_data_found'; END IF;
  IF jsonb_typeof(p_reviews) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'reseñas inválidas' USING ERRCODE = 'invalid_parameter_value'; END IF;
  v_hours := least(s.cache_ttl_hours, coalesce(web_try_numeric(platform_legal_param('web.review_cache_max_hours'))::integer, s.cache_ttl_hours));
  DELETE FROM review_snapshots WHERE review_source_id = s.id;
  INSERT INTO review_snapshots (review_source_id, author_name, author_photo_url, rating, body, review_published_at, provider_review_url, fetched_at, expires_at)
  SELECT s.id, x ->> 'author_name', x ->> 'author_photo_url', (x ->> 'rating')::smallint, x ->> 'body',
         (x ->> 'review_published_at')::timestamptz, x ->> 'provider_review_url', now(), now() + make_interval(hours => v_hours)
    FROM jsonb_array_elements(p_reviews) x;
  GET DIAGNOSTICS n = ROW_COUNT;
  UPDATE review_sources SET last_fetched_at = now(), last_error = NULL, status = CASE WHEN status = 'error' THEN 'active' ELSE status END WHERE id = s.id;
  RETURN jsonb_build_object('source_id', s.id, 'stored', n, 'expires_in_hours', v_hours);
END $$;

-- Público: solo reseñas vigentes (no vencidas) de fuentes activas, con calificación mínima y cantidad de la fuente, más
-- recientes primero (no se eligen a mano). Atribución obligatoria.
CREATE OR REPLACE FUNCTION public.public_reviews() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('result', 'ok', 'attribution', 'Reseñas de Google', 'provider', 'google',
    'reviews', coalesce((
      SELECT jsonb_agg(x.j ORDER BY x.o DESC) FROM (
        SELECT jsonb_build_object('author_name', r.author_name, 'author_photo_url', r.author_photo_url, 'rating', r.rating, 'body', r.body,
                                  'review_published_at', r.review_published_at, 'provider_review_url', r.provider_review_url) AS j,
               r.review_published_at AS o,
               row_number() OVER (PARTITION BY s.id ORDER BY r.review_published_at DESC NULLS LAST, r.id) AS rn, s.max_to_show
          FROM review_sources s JOIN review_snapshots r ON r.review_source_id = s.id AND r.expires_at > now() AND r.deleted_at IS NULL
         WHERE s.status = 'active' AND s.deleted_at IS NULL AND r.rating >= s.min_rating) x
       WHERE x.rn <= x.max_to_show), '[]'::jsonb))
$$;

-- ---------- Calculadora de ahorro frente a Excel y papel ----------
CREATE OR REPLACE FUNCTION public.public_savings_calculator() RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT coalesce((SELECT jsonb_build_object('result', 'ok', 'assumptions', s.assumptions_json, 'disclaimer', s.disclaimer,
                                             'to_validate', s.to_validate,
                                             'available', web_try_numeric(s.assumptions_json ->> 'minutes_saved_per_record') IS NOT NULL
                                                          AND web_try_numeric(s.assumptions_json ->> 'manual_hours_reduction_pct') IS NOT NULL)
                     FROM savings_calculator_settings s WHERE s.singleton AND s.status = 'published' AND s.deleted_at IS NULL),
                  jsonb_build_object('result', 'not_found'))
$$;

-- horas/mes = registros × minutos ahorrados / 60 + horas dedicadas × % de reducción (tope: horas dedicadas si se informan);
-- costo/mes = horas × costo hora (solo si el supuesto está definido). Guarda la copia de supuestos. Idempotente.
CREATE OR REPLACE FUNCTION public.public_calculate_savings(p_data jsonb, p_ip_hash bytea DEFAULT NULL, p_idempotency_key text DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  s savings_calculator_settings;
  c savings_calculations;
  v_workers numeric := web_try_numeric(p_data ->> 'workers');
  v_sites numeric := web_try_numeric(p_data ->> 'sites');
  v_records numeric := web_try_numeric(p_data ->> 'records_per_month');
  v_hours numeric := web_try_numeric(p_data ->> 'hours_per_month');
  v_min numeric;
  v_pct numeric;
  v_cost numeric;
  v_res numeric;
  v_lead uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO c FROM savings_calculations WHERE idempotency_key = p_idempotency_key;
    IF c.id IS NOT NULL THEN
      RETURN jsonb_build_object('result', 'ok', 'id', c.id, 'replay', true, 'result_hours_month', c.result_hours_month,
                                'result_cost_month', c.result_cost_month, 'assumptions', c.assumptions_snapshot_json);
    END IF;
  END IF;
  SELECT * INTO s FROM savings_calculator_settings WHERE singleton AND status = 'published' AND deleted_at IS NULL;
  IF s.id IS NULL THEN RETURN jsonb_build_object('result', 'not_found'); END IF;
  IF v_workers IS NULL OR v_workers < 1 OR v_workers > 100000 OR coalesce(v_sites, 1) < 1 OR v_records IS NULL OR v_records < 0
     OR v_records > 1000000 OR coalesce(v_hours, 0) < 0 OR coalesce(v_hours, 0) > 10000 THEN
    RAISE EXCEPTION 'datos de cálculo inválidos' USING ERRCODE = 'check_violation';
  END IF;
  v_min := web_try_numeric(s.assumptions_json ->> 'minutes_saved_per_record');
  v_pct := web_try_numeric(s.assumptions_json ->> 'manual_hours_reduction_pct');
  v_cost := web_try_numeric(s.assumptions_json ->> 'hourly_cost_pen');
  IF v_min IS NULL OR v_pct IS NULL THEN
    RETURN jsonb_build_object('result', 'assumptions_pending', 'message', 'Los supuestos de la calculadora aún no están definidos.');
  END IF;
  v_res := v_records * v_min / 60 + coalesce(v_hours, 0) * v_pct / 100;
  IF v_hours IS NOT NULL AND v_hours > 0 THEN v_res := least(v_res, v_hours); END IF;
  IF nullif(p_data ->> 'email', '') IS NOT NULL THEN
    v_lead := web_upsert_lead(p_data, 'savings_calculator', p_ip_hash);
  END IF;
  INSERT INTO savings_calculations (lead_id, inputs_json, assumptions_snapshot_json, result_hours_month, result_cost_month, idempotency_key)
  VALUES (v_lead, jsonb_build_object('workers', v_workers, 'sites', coalesce(v_sites, 1), 'records_per_month', v_records, 'hours_per_month', v_hours),
          jsonb_build_object('assumptions', s.assumptions_json, 'disclaimer', s.disclaimer, 'to_validate', s.to_validate, 'calculated_on', current_date),
          round(v_res, 1), CASE WHEN v_cost IS NOT NULL AND v_cost >= 0 THEN round(round(v_res, 1) * v_cost, 2) END, p_idempotency_key)
  RETURNING * INTO c;
  RETURN jsonb_build_object('result', 'ok', 'id', c.id, 'replay', false, 'result_hours_month', c.result_hours_month,
                            'result_cost_month', c.result_cost_month, 'assumptions', s.assumptions_json, 'disclaimer', s.disclaimer,
                            'to_validate', s.to_validate, 'lead_registered', v_lead IS NOT NULL);
END $$;

REVOKE ALL ON FUNCTION public.web_drop_expired_partitions(text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.web_drop_expired_partitions(text, integer) TO escudo_owner;
REVOKE ALL ON FUNCTION public.web_demo_free_slots(date, date, uuid), public.web_token_hash(text), public.web_chatbot_is_open(jsonb, timestamptz),
  public.web_popup_forbidden_path(text), public.web_path_matches(text, jsonb), public.web_webinar_public_json(webinars) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.web_demo_free_slots(date, date, uuid), public.web_token_hash(text), public.web_chatbot_is_open(jsonb, timestamptz),
  public.web_popup_forbidden_path(text), public.web_path_matches(text, jsonb), public.web_webinar_public_json(webinars) TO escudo_definer, escudo_platform;
REVOKE ALL ON FUNCTION public.web_demo_meeting_assign(uuid, uuid), public.web_demo_meeting_confirm(uuid, text, text, text),
  public.web_demo_meeting_complete(uuid, text, text, boolean), public.web_rollup_site_analytics(date), public.web_site_metrics(date, date),
  public.web_media_usages(uuid), public.web_publish_chatbot_intent(uuid), public.web_crm_event_result(uuid, boolean, integer, text, text),
  public.web_crm_retry_event(uuid), public.web_crm_connection_tested(uuid, boolean, text), public.web_campaign_action(uuid, text),
  public.web_popup_action(uuid, text), public.web_publish_product_update(uuid), public.web_webinar_action(uuid, text),
  public.web_store_review_snapshots(uuid, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.web_demo_meeting_assign(uuid, uuid), public.web_demo_meeting_confirm(uuid, text, text, text),
  public.web_demo_meeting_complete(uuid, text, text, boolean), public.web_rollup_site_analytics(date), public.web_site_metrics(date, date),
  public.web_media_usages(uuid), public.web_publish_chatbot_intent(uuid), public.web_crm_event_result(uuid, boolean, integer, text, text),
  public.web_crm_retry_event(uuid), public.web_crm_connection_tested(uuid, boolean, text), public.web_campaign_action(uuid, text),
  public.web_popup_action(uuid, text), public.web_publish_product_update(uuid), public.web_webinar_action(uuid, text),
  public.web_store_review_snapshots(uuid, jsonb) TO escudo_platform;

-- ---------- Seguridad a nivel de fila (RLS forzado) y privilegios ------------------
-- Política tipo: rls_<tabla>_company USING/WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid).
-- Sin app.company_id fijado la expresión es NULL y no pasa ninguna fila (no hay valor por defecto permisivo).
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounts FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_accounts_account ON accounts TO escudo_app USING (id = app_account_id() OR id IN (SELECT c.account_id FROM companies c WHERE c.id = app_company_id())) WITH CHECK (id = app_account_id());
CREATE POLICY rls_accounts_platform ON accounts TO escudo_platform USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE ON accounts TO escudo_platform;
GRANT SELECT, INSERT, UPDATE ON accounts TO escudo_app;

ALTER TABLE companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE companies FORCE ROW LEVEL SECURITY;
-- companies: la empresa activa, las empresas de la cuenta activa y las que gestiona la consultora activa.
CREATE POLICY rls_companies_company ON companies FOR SELECT TO escudo_app USING (id = app_company_id() OR account_id = app_account_id() OR managed_by_account_id = app_account_id());
CREATE POLICY rls_companies_insert ON companies FOR INSERT TO escudo_app WITH CHECK (account_id = app_account_id());
CREATE POLICY rls_companies_update ON companies FOR UPDATE TO escudo_app USING (id = app_company_id() OR account_id = app_account_id()) WITH CHECK (id = app_company_id() OR account_id = app_account_id());
CREATE POLICY rls_companies_platform ON companies TO escudo_platform USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE ON companies TO escudo_platform;
GRANT SELECT, INSERT, UPDATE ON companies TO escudo_app;

ALTER TABLE sites ENABLE ROW LEVEL SECURITY;
ALTER TABLE sites FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_sites_company ON sites TO escudo_app USING (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON sites TO escudo_app;

ALTER TABLE areas ENABLE ROW LEVEL SECURITY;
ALTER TABLE areas FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_areas_company ON areas TO escudo_app USING (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON areas TO escudo_app;

ALTER TABLE positions ENABLE ROW LEVEL SECURITY;
ALTER TABLE positions FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_positions_company ON positions TO escudo_app USING (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON positions TO escudo_app;

ALTER TABLE work_shifts ENABLE ROW LEVEL SECURITY;
ALTER TABLE work_shifts FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_work_shifts_company ON work_shifts TO escudo_app USING (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);
GRANT SELECT, INSERT, UPDATE ON work_shifts TO escudo_app;

ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE users FORCE ROW LEVEL SECURITY;
-- users: identidad global. Se ve a sí mismo y a los miembros de la empresa activa. El login usa app_auth_lookup_user().
CREATE POLICY rls_users_read ON users FOR SELECT TO escudo_app USING (id = app_user_id() OR EXISTS (SELECT 1 FROM memberships m WHERE m.user_id = users.id AND m.company_id = app_company_id()));
CREATE POLICY rls_users_insert ON users FOR INSERT TO escudo_app WITH CHECK (NOT is_platform_staff);
CREATE POLICY rls_users_update ON users FOR UPDATE TO escudo_app USING (id = app_user_id() OR EXISTS (SELECT 1 FROM memberships m WHERE m.user_id = users.id AND m.company_id = app_company_id())) WITH CHECK (NOT is_platform_staff OR id = app_user_id());
CREATE POLICY rls_users_platform ON users TO escudo_platform USING (true) WITH CHECK (true);
GRANT SELECT, INSERT, UPDATE ON users TO escudo_platform;
GRANT SELECT, INSERT, UPDATE ON users TO escudo_app;

ALTER TABLE roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE roles FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_roles_read ON roles FOR SELECT TO escudo_app USING (account_id IS NULL OR account_id = app_account_id() OR account_id IN (SELECT c.account_id FROM companies c WHERE c.id = app_company_id()));
CREATE POLICY rls_roles_write ON roles FOR INSERT TO escudo_app WITH CHECK (account_id = app_account_id() AND NOT is_system);
CREATE POLICY rls_roles_update ON roles FOR UPDATE TO escudo_app USING (account_id = app_account_id() AND NOT is_system) WITH CHECK (account_id = app_account_id() AND NOT is_system);
CREATE POLICY rls_roles_platform ON roles TO escudo_platform USING (account_id IS NULL) WITH CHECK (account_id IS NULL);
GRANT SELECT, INSERT, UPDATE ON roles TO escudo_platform;
GRANT SELECT, INSERT, UPDATE ON roles TO escudo_app;

-- modules: catálogo global sin company_id. Lectura para la app; escritura solo escudo_platform.
GRANT SELECT ON modules TO escudo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON modules TO escudo_platform;
-- permissions: catálogo global sin company_id. Lectura para la app; escritura solo escudo_platform.
GRANT SELECT ON permissions TO escudo_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON permissions TO escudo_platform;
ALTER TABLE role_permissions ENABLE ROW LEVEL SECURITY;
ALTER TABLE role_permissions FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_role_permissions_read ON role_permissions FOR SELECT TO escudo_app USING (account_id IS NULL OR account_id = app_account_id() OR account_id IN (SELECT c.account_id FROM companies c WHERE c.id = app_company_id()));
CREATE POLICY rls_role_permissions_insert ON role_permissions FOR INSERT TO escudo_app WITH CHECK (account_id = app_account_id());
CREATE POLICY rls_role_permissions_delete ON role_permissions FOR DELETE TO escudo_app USING (account_id = app_account_id());
CREATE POLICY rls_role_permissions_platform ON role_permissions TO escudo_platform USING (account_id IS NULL) WITH CHECK (account_id IS NULL);
GRANT SELECT, INSERT, UPDATE, DELETE ON role_permissions TO escudo_platform;
GRANT SELECT, INSERT, UPDATE, DELETE ON role_permissions TO escudo_app;

ALTER TABLE memberships ENABLE ROW LEVEL SECURITY;
ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY rls_memberships_company ON memberships TO escudo_app USING (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid) WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);
