-- ---------- Propiedad de los objetos -------------------------------------------
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
           WHERE n.nspname = 'public' AND c.relkind IN ('r','p') LOOP
    EXECUTE format('ALTER TABLE %I OWNER TO escudo_owner', r.relname);
  END LOOP;
END $$;
-- Las funciones SECURITY DEFINER pertenecen a escudo_definer (BYPASSRLS, NOLOGIN) y necesitan privilegios de tabla.
GRANT SELECT, INSERT, UPDATE ON ALL TABLES IN SCHEMA public TO escudo_definer;
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT p.oid::regprocedure AS f FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
           WHERE n.nspname = 'public' AND p.prosecdef LOOP
    EXECUTE format('ALTER FUNCTION %s OWNER TO escudo_definer', r.f);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', r.f);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO escudo_app, escudo_platform', r.f);
  END LOOP;
END $$;
-- Fin del esquema.
